# === Catálogo de módulos (sistema Multi-Proyecto Modular) ===================
# Cada plantilla puede encenderse independientemente en cualquiera de las 3
# categorías de informe (Diario/Semanal/Mensual) — un módulo NO vive bajo una
# única cadencia fija. El Coordinador decide, por informe, si el recuento de
# actividades de esa plantilla debe aparecer ahí (ver `_ensure_modulo_activo`
# para el gate de captura/menú — OR entre las 3 categorías — y
# `_modulos_categoria_para_export` para qué categoría manda al exportar). Si
# una clave no aparece aquí, se ignora al guardar `modulos` (evita que un
# payload arbitrario cree módulos "fantasma" que ninguna pantalla sabe
# renderizar).
MODULOS_KEYS = {
    "seguridad_higiene", "forestal_arbolado",
    "gestion_riesgos", "estudios_proyecto", "impacto_ambiental",
    "tabla_resumen", "estado_tiempo", "control_obra",
    "fotos_lidar", "tapial", "pruebas_calidad", "control_calidad",
    "avance_obra", "estimaciones", "pendientes_generales", "aspectos_sociales",
    "indicadores_seguridad", "juntas_trabajo", "supervision_ambiental",
    "actividades_particulares", "electromecanica",
}
MODULOS_DIARIOS = MODULOS_KEYS
MODULOS_SEMANALES = MODULOS_KEYS
MODULOS_MENSUALES = MODULOS_KEYS
MODULOS_CATALOG = {
    "reportes_diarios": MODULOS_DIARIOS,
    "reportes_semanales": MODULOS_SEMANALES,
    "reportes_mensuales": MODULOS_MENSUALES,
}

# Jerarquía por REGISTRO en los módulos de captura (misma regla que los
# reportes de actividad, ver `_severity_set_for_period_type`): cada registro
# lleva a qué informe llega, de forma excluyente —
#   "diario" → solo el informe Diario, "semanal" → solo el Semanal,
#   "mensual" → solo el Mensual, "informativo" → a ninguno.
# El interruptor por informe del módulo (MODULOS_CATALOG) sigue siendo la
# primera puerta; la jerarquía decide, dentro de un módulo encendido, qué
# registros se imprimen. Un registro SIN jerarquía (capturado antes de esta
# regla) sigue imprimiéndose en todos los informes donde el módulo esté
# encendido, para no esconder datos históricos.
JERARQUIAS_MODULO = ("informativo", "diario", "semanal", "mensual")
_CATEGORIA_A_JERARQUIA = {
    "reportes_diarios": "diario",
    "reportes_semanales": "semanal",
    "reportes_mensuales": "mensual",
}


def _jerarquia_modulo(value: Optional[str], default: Optional[str] = "diario") -> Optional[str]:
    """Valida la jerarquía de un registro de módulo (400 si no es válida);
    vacío → `default` (los registros nuevos nacen como "diario")."""
    v = (value or "").strip().lower()
    if not v:
        return default
    if v not in JERARQUIAS_MODULO:
        raise HTTPException(400, "jerarquia debe ser informativo, diario, semanal o mensual")
    return v


def _jerarquia_q(categoria: str) -> dict:
    """Filtro Mongo: registros que corresponden al informe `categoria`
    (jerarquía igual a la del informe, o sin jerarquía = legado)."""
    return {"jerarquia": {"$in": [None, _CATEGORIA_A_JERARQUIA.get(categoria, "diario")]}}


def _sanitize_modulos(value: Optional[dict]) -> dict:
    """Normaliza el objeto `modulos`: sólo conserva claves conocidas por
    categoría (ver MODULOS_CATALOG) con valor bool; el resto (categorías o
    módulos desconocidos) se descarta en silencio. Los módulos no
    mencionados explícitamente en `value` quedan apagados por default —
    nunca se asume "encendido" para un módulo nuevo sin confirmación
    explícita del Coordinador."""
    out: dict = {}
    value = value or {}
    for categoria, claves_validas in MODULOS_CATALOG.items():
        cat_in = value.get(categoria) if isinstance(value, dict) else None
        cat_out = {}
        for clave in claves_validas:
            v = cat_in.get(clave) if isinstance(cat_in, dict) else None
            cat_out[clave] = bool(v) if isinstance(v, bool) else False
        out[categoria] = cat_out
    return out


_DATOS_CONTRATO_BLOQUES = ("obra", "supervision")
_DATOS_CONTRATO_CAMPOS = (
    "objeto", "empresa", "contrato", "ubicacion", "inicio", "fin",
    "monto", "iva", "monto_con_iva", "anticipo_label", "anticipo",
    "superintendente",  # solo se usa en SUPERVISIÓN: firma de la hoja final del informe
)


def _sanitize_datos_contrato(value) -> dict:
    """Normaliza `datos_contrato` (slide "DATOS DE CONTRATO" del informe
    PPTX): dos bloques, `obra` y `supervision`, cada uno con campos de
    texto libre (los montos se capturan ya formateados, ej. "$117,352,207.05").
    Se descartan claves desconocidas y se recorta cada valor."""
    out: dict = {}
    if not isinstance(value, dict):
        return out
    for bloque in _DATOS_CONTRATO_BLOQUES:
        src = value.get(bloque)
        if not isinstance(src, dict):
            continue
        clean = {}
        for campo in _DATOS_CONTRATO_CAMPOS:
            v = src.get(campo)
            if isinstance(v, str) and v.strip():
                clean[campo] = v.strip()[:1000]
        if clean:
            out[bloque] = clean
    return out


def _contrato_bloques(proj: dict) -> list:
    """Bloques de la hoja "DATOS DE CONTRATO" de los informes (PPTX/PDF/DOCX):
    OBRA y, si tiene algún dato, SUPERVISIÓN. Cada bloque:
    {"etiqueta", "lineas": [(rótulo, valor)], "filas": [(rótulo, valor1,
    valor2, unida)]} — `filas` es la tabla Periodo/Monto/IVA/Monto con IVA/
    Anticipo (`unida`=True: el valor ocupa las dos columnas Inicio+Fin).
    Lo que falte en OBRA cae a los datos base del proyecto (objeto,
    constructora, número de contrato, fechas). [] si no hay nada que imprimir."""
    dc = _sanitize_datos_contrato((proj or {}).get("datos_contrato"))
    obra = dict(dc.get("obra") or {})
    sup = dict(dc.get("supervision") or {})
    obra.setdefault("objeto", ((proj or {}).get("objeto_contrato") or (proj or {}).get("name") or "").strip())
    if not obra.get("empresa") and (proj or {}).get("constructora"):
        obra["empresa"] = proj["constructora"]
    if not obra.get("contrato") and (proj or {}).get("contract_number"):
        obra["contrato"] = proj["contract_number"]
    if not obra.get("inicio") and (proj or {}).get("start_date"):
        obra["inicio"] = _fmt_iso_dmy(proj["start_date"])
    if not obra.get("fin") and (proj or {}).get("end_date"):
        obra["fin"] = _fmt_iso_dmy(proj["end_date"])
    bloques = []
    for etq, d in (("OBRA", obra), ("SUPERVISIÓN", sup)):
        if not any(v for k, v in d.items() if k != "superintendente"):
            continue
        lineas = []
        if d.get("objeto"):
            lineas.append((etq + ":", f"\u201c{d['objeto']}\u201d."))
        if d.get("empresa"):
            lineas.append(("EMPRESA:", d["empresa"].upper()))
        if d.get("contrato"):
            lineas.append(("CONTRATO:", d["contrato"]))
        if d.get("ubicacion"):
            lineas.append(("UBICACIÓN:", d["ubicacion"].upper()))
        filas = []
        if d.get("inicio") or d.get("fin"):
            filas.append(("Periodo de ejecución", d.get("inicio") or "", d.get("fin") or "", False))
        if d.get("monto"):
            filas.append(("Monto", d["monto"], "", True))
        if d.get("iva"):
            filas.append(("IVA", d["iva"], "", True))
        if d.get("monto_con_iva"):
            filas.append(("Monto con IVA", d["monto_con_iva"], "", True))
        if d.get("anticipo"):
            filas.append((d.get("anticipo_label") or "Anticipo", d["anticipo"], "", True))
        bloques.append({"etiqueta": etq, "lineas": lineas, "filas": filas})
    return bloques


def _sanitize_reference_files(items) -> list:
    """Valida y limpia la lista de archivos de referencia.
    Espera una lista de dicts con 'name' y 'url'.
    Descarta entradas vacías o malformadas. Máximo 50 elementos."""
    if not items or not isinstance(items, list):
        return []
    cleaned = []
    for it in items[:50]:
        if not isinstance(it, dict):
            continue
        name = (it.get("name") or "").strip()
        url = (it.get("url") or "").strip()
        if not name or not url:
            continue
        # Limitar tamaños para evitar payloads abusivos
        cleaned.append({"name": name[:200], "url": url[:1000]})
    return cleaned

