_VALID_SEVERIDADES = ("informativo", "diario", "importante", "urgente")

# Semáforo de GRAVEDAD del reporte (distinto del semáforo de periodo `severidad`):
# verde = solo informativo, amarillo = algo relevante, rojo = algo grave.
_VALID_GRAVEDADES = ("verde", "amarillo", "rojo")
_GRAVEDAD_EMOJI = {"verde": "🟢", "amarillo": "🟡", "rojo": "🔴"}


def _normalize_gravedad(raw: Any) -> str:
    v = str(raw or "").strip().lower()
    return v if v in _VALID_GRAVEDADES else "verde"


def _normalize_severidad_list(raw: Any) -> List[str]:
    """Normaliza la severidad de un reporte a una lista de valores válidos.

    Acepta tanto un string único (compatibilidad con clientes/datos viejos,
    donde `severidad` era escalar) como una lista (selección múltiple de
    jerarquías, p.ej. ["diario", "urgente"] para que el mismo reporte
    aparezca en el informe Diario Y en el Mensual). "informativo" es
    excluyente: si aparece junto con otras, se descartan las demás, porque
    un reporte informativo no debe entrar a ningún informe categorizado.
    """
    if raw is None:
        items = []
    elif isinstance(raw, str):
        items = [raw]
    elif isinstance(raw, (list, tuple, set)):
        items = list(raw)
    else:
        items = []
    out: List[str] = []
    for v in items:
        v = (v or "").strip().lower()
        if v in _VALID_SEVERIDADES and v not in out:
            out.append(v)
    if not out:
        return ["informativo"]
    if "informativo" in out and len(out) > 1:
        out = [v for v in out if v != "informativo"]
    return out


class ReportIn(BaseModel):
    project_id: str
    node_id: str  # debe ser hoja
    # Valor de medición (formato depende del measurement_type del nodo)
    measurement_value: dict  # ej: {"lat": 19.43, "lon": -99.13} | {"cadenamiento": "5+100"} | {"eje": "A"} | {"nivel": 12.45}
    # Título/nombre del reporte (opcional). Si viene vacío, en el frontend
    # se muestra un fallback tipo "Reporte del <fecha>". Se indexa para búsqueda.
    title: Optional[str] = None
    area_id: Optional[str] = None
    actividades: Optional[str] = None
    notes: Optional[str] = None
    avance: Optional[str] = None
    observaciones: Optional[str] = None
    incidencias: Optional[str] = None  # Notas sobre eventos/desviaciones del día
    # Acepta un string único (legacy) o una lista (selección múltiple de
    # jerarquías: p.ej. ["diario", "urgente"]). Se normaliza con
    # `_normalize_severidad_list` antes de guardar.
    severidad: Optional[Any] = "informativo"
    # Semáforo de gravedad (verde / amarillo / rojo). Independiente de `severidad`.
    gravedad: Optional[str] = "verde"
    contratista: Optional[str] = None
    personnel: List[str] = Field(default_factory=list)
    equipment: List[str] = Field(default_factory=list)
    images: List[str] = Field(default_factory=list)  # base64
    # Descripciones individuales por foto (foto 1 → captions[0], foto 2 → captions[1]).
    # Fallback al campo `observaciones` general si no se rellena.
    photo_captions: List[str] = Field(default_factory=list)
    files: List[dict] = Field(default_factory=list)  # [{filename, mime, data_base64}]
    # Lecturas numéricas (P/U) – específicas del flujo Especialista v2.
    primera_lectura: Optional[float] = None
    ultima_lectura: Optional[float] = None
    # Unidad de las lecturas (km | m | cm). Default = "m".
    unidad: Optional[str] = "m"
    # [OFFLINE 2026-08-07] Id de idempotencia generado en el cliente al
    # encolar un reporte sin conexion. Permite deduplicar si el mismo
    # reporte se reintenta (ver db.reports índice único sparse sobre esto).
    client_id: Optional[str] = None
    # [OFFLINE 2026-09-09] Hora real de captura en el dispositivo (antes de
    # encolar sin conexion). Si el reporte tarda en sincronizarse, evita que
    # se le asigne la hora de sincronizacion como `created_at` -- ver uso en
    # el endpoint de creación.
    captured_at: Optional[datetime] = None
    # Reporte estructurado (opcional): id de la plantilla elegida (ver
    # ReportTemplate) y los valores capturados para sus campos dinámicos.
    template_id: Optional[str] = None
    dynamic_data: dict = Field(default_factory=dict)
    # Captura rápida de Fuerza de Trabajo: reporte mínimo con solo personal y/o
    # equipo. No exige valor de medición del nodo (no aplica) pero sí al menos
    # una categoría de personal o de equipo.
    solo_fuerza_trabajo: bool = False
    # Valores de los campos libres que el Área define (p. ej. banderilleros):
    # {id_del_campo: valor}. Solo se guardan los que el Área tiene configurados.
    campos_extra: Dict[str, Any] = Field(default_factory=dict)


class ReportOut(BaseModel):
    id: str
    project_id: str
    node_id: str
    node_path_names: List[str]
    node_path_ids: List[str] = Field(default_factory=list)  # ids ancestrales para filtros
    measurement_type: str
    measurement_value: dict
    title: Optional[str] = None
    area_id: Optional[str] = None
    area_name: Optional[str] = None
    actividades: Optional[str] = None
    observaciones: Optional[str] = None
    incidencias: Optional[str] = None
    severidad: List[str] = Field(default_factory=lambda: ["informativo"])
    gravedad: str = "verde"

    @field_validator("gravedad", mode="before")
    @classmethod
    def _v_gravedad(cls, v: Any) -> str:
        return _normalize_gravedad(v)

    @field_validator("severidad", mode="before")
    @classmethod
    def _v_severidad(cls, v: Any) -> List[str]:
        # Normaliza datos legacy: reportes viejos guardaron `severidad` como
        # string único en Mongo; esto lo convierte a lista en la respuesta
        # sin necesidad de migrar la colección completa.
        return _normalize_severidad_list(v)
    contratista: Optional[str] = None
    personnel: List[str] = Field(default_factory=list)
    equipment: List[str] = Field(default_factory=list)
    images: List[str] = Field(default_factory=list)
    photo_captions: List[str] = Field(default_factory=list)
    files: List[dict] = Field(default_factory=list)
    primera_lectura: Optional[float] = None
    ultima_lectura: Optional[float] = None
    unidad: Optional[str] = "m"
    captured_by: str
    captured_by_name: str
    created_at: datetime
    template_id: Optional[str] = None
    dynamic_data: dict = Field(default_factory=dict)
    # Campos libres del Área con su valor, tal como se capturaron:
    # [{id, nombre, tipo, unidad, valor}] (copia del nombre, no se pierde si
    # luego el Coordinador renombra o quita el campo).
    campos_extra: List[dict] = Field(default_factory=list)
    # False cuando el Área del reporte no captura Personal / Equipo (el texto y
    # los informes omiten esa sección en vez de mostrar "-").
    captura_personal: bool = True
    captura_equipo: bool = True


def _campos_extra_para_reporte(area: Optional[dict], valores: Dict[str, Any]) -> List[dict]:
    """Cruza los valores enviados con los campos que el Área tiene definidos.
    Ignora ids desconocidos y valores vacíos; los numéricos deben ser >= 0."""
    if not area or not valores:
        return []
    out: List[dict] = []
    for c in area.get("campos_extra") or []:
        v = valores.get(c["id"])
        if v is None or (isinstance(v, str) and not v.strip()):
            continue
        if c.get("tipo") == "numero":
            try:
                num = float(str(v).replace(",", "."))
            except ValueError:
                raise HTTPException(400, f"«{c['nombre']}» debe ser un número")
            if num < 0 or num != num or num in (float("inf"), float("-inf")):
                raise HTTPException(400, f"«{c['nombre']}» debe ser un número mayor o igual a 0")
            v = int(num) if num == int(num) else num
        else:
            v = str(v).strip()[:500]
        out.append({**{k: c.get(k) for k in ("id", "nombre", "tipo", "unidad")}, "valor": v})
    return out


def _campo_extra_texto(c: dict) -> str:
    unidad = f" {c['unidad']}" if c.get("unidad") else ""
    return f"{c.get('nombre')}: {c.get('valor')}{unidad}"


# === Plantillas de reporte estructurado (formularios dinámicos) ============
class ReportTemplateField(BaseModel):
    key: str
    label: str
    type: Literal["string", "number", "boolean", "select", "multiselect"]
    required: bool = False
    options: List[str] = Field(default_factory=list)


class ReportTemplate(BaseModel):
    id: str
    code: str
    name: str
    category: str
    fields: List[ReportTemplateField] = Field(default_factory=list)


class ReportTemplateIn(BaseModel):
    code: str
    name: str
    category: str
    fields: List[ReportTemplateField] = Field(default_factory=list)


class ReportTemplatePatch(BaseModel):
    name: Optional[str] = None
    category: Optional[str] = None
    fields: Optional[List[ReportTemplateField]] = None


def _tf(key: str, label: str, type: str, required: bool = False, options: Optional[List[str]] = None) -> dict:
    return {"key": key, "label": label, "type": type, "required": required, "options": options or []}


