@api.post("/auth/login", response_model=Token)
async def login(body: LoginIn):
    u = await db.users.find_one({"email": body.email.lower()})
    if not u or u.get("deleted_at") or not verify_pw(body.password, u["password"]):
        raise HTTPException(401, "Credenciales inválidas")
    return {"token": make_token(u["id"]), "user": user_to_out(u)}


@api.get("/auth/me")
async def me(user: dict = Depends(current_user)):
    return user_to_out(user)


@api.post("/auth/change_password")
async def change_password(body: ChangePasswordIn, user: dict = Depends(current_user)):
    """Auto-servicio: cualquier usuario autenticado cambia su propia
    contraseña sin necesidad de dar la actual (basta con estar autenticado).
    Distinto de POST .../reset_password (que genera una temporal y solo
    puede ejecutarlo un Coordinador sobre un Sub-coordinador/Especialista)."""
    new_pw = (body.new_password or "").strip()
    if len(new_pw) < 6:
        raise HTTPException(400, "La nueva contraseña debe tener mínimo 6 caracteres")
    await db.users.update_one({"id": user["id"]}, {"$set": {"password": hash_pw(new_pw)}})
    return {"ok": True}


# === ELIMINACIÓN DE CUENTA (T-01) ===========================================
# Google Play y la App Store exigen poder borrar la cuenta desde la app y desde
# una página web pública. La cuenta se ANONIMIZA (no se borra la fila): los
# reportes, avances y minutas que firmó se conservan porque son registro de obra
# del proyecto, pero con el autor "Usuario eliminado". Se eliminan los datos
# personales: correo, nombre, teléfono, contraseña, tokens de notificación y
# solicitudes de contraseña.
USUARIO_ELIMINADO = "Usuario eliminado"

# Colecciones que NO se anonimizan por autoría: `users` se trata aparte y las
# otras solo guardan datos personales del propio usuario (se borran o se omiten).
_COLECCIONES_SIN_AUTORIA = {"users", "password_reset_requests", "password_reset_tokens", "channel_reads", "deletion_requests"}

# (campo con el id del usuario, {campo hermano con su nombre/correo: valor}).
CAMPOS_AUTORIA: List[Tuple[str, Dict[str, Any]]] = [
    ("created_by", {"created_by_name": USUARIO_ELIMINADO}),
    ("updated_by", {"updated_by_name": USUARIO_ELIMINADO}),
    ("captured_by", {"captured_by_name": USUARIO_ELIMINADO}),
    ("author_id", {"author_name": USUARIO_ELIMINADO}),
    ("user_id", {"user_name": USUARIO_ELIMINADO, "user_email": None}),
    ("capturado_por", {"capturado_por_nombre": USUARIO_ELIMINADO}),
    ("creado_por", {"creado_por_nombre": USUARIO_ELIMINADO}),
    ("uploaded_by", {"uploaded_by_name": USUARIO_ELIMINADO}),
    ("pdf_uploaded_by", {"pdf_uploaded_by_name": USUARIO_ELIMINADO}),
    ("completed_by", {"completed_by_name": USUARIO_ELIMINADO}),
    ("resolved_by", {"resolved_by_name": USUARIO_ELIMINADO}),
    ("responsable_id", {"responsable_name": USUARIO_ELIMINADO}),
]


# Arreglos paralelos ids/nombres (minutas.involved_*, events.attendee_*): el nombre
# de cada persona vive en la misma posición que su id.
ARREGLOS_PARALELOS: List[Tuple[str, str]] = [
    ("involved_ids", "involved_names"),
    ("attendee_ids", "attendee_names"),
]


def nombres_sin_usuario(ids: List[str], nombres: List[str], uid: str) -> List[str]:
    """Copia de `nombres` con USUARIO_ELIMINADO en las posiciones donde `ids` == uid."""
    salida = list(nombres or [])
    for i, x in enumerate(ids or []):
        if x == uid and i < len(salida):
            salida[i] = USUARIO_ELIMINADO
    return salida


def correo_eliminado(uid: str) -> str:
    """Correo de relleno único (la colección exige `email` único) y no enviable."""
    return f"eliminado-{uid}@eliminado.example.com"


def campos_usuario_anonimizado(uid: str, ahora: datetime) -> Dict[str, Any]:
    """`$set` que deja el documento de usuario sin datos personales ni acceso."""
    return {
        "name": USUARIO_ELIMINADO,
        "email": correo_eliminado(uid),
        "password": hash_pw(secrets.token_urlsafe(32)),  # nadie la conoce: no puede entrar
        "expo_push_tokens": [],
        "project_ids": [],
        "scope_node_id": None,
        "scope_node_ids": [],
        "area": None,
        "area_id": None,
        "puesto": None,
        "no_control": None,
        "phone": None,
        "deleted_at": ahora,
    }


async def anonimizar_usuario(uid: str) -> Dict[str, int]:
    """Anonimiza a `uid` en toda la base. Idempotente. Devuelve conteos por tipo."""
    ahora = datetime.now(timezone.utc)
    u = await db.users.find_one({"id": uid})
    if not u:
        raise HTTPException(404, "Usuario no existe")
    email_original = (u.get("email") or "").lower()
    conteo = {"documentos_anonimizados": 0, "documentos_borrados": 0}

    # 1) Datos personales propios: se borran.
    r = await db.password_reset_requests.delete_many({"user_id": uid})
    conteo["documentos_borrados"] += r.deleted_count
    r = await db.channel_reads.delete_many({"user_id": uid})
    conteo["documentos_borrados"] += r.deleted_count
    r = await db.password_reset_tokens.delete_many({"user_id": uid})
    conteo["documentos_borrados"] += r.deleted_count

    # 2) Autoría en el resto de colecciones: se conserva el registro, se quita el nombre.
    for cname in await db.list_collection_names():
        if cname in _COLECCIONES_SIN_AUTORIA or cname.startswith("system."):
            continue
        col = db[cname]
        for campo_id, hermanos in CAMPOS_AUTORIA:
            for campo, valor in hermanos.items():
                res = await col.update_many({campo_id: uid, campo: {"$exists": True}}, {"$set": {campo: valor}})
                conteo["documentos_anonimizados"] += res.modified_count
    # Arreglos paralelos ids/nombres (participantes de minutas y eventos).
        for ids_f, names_f in ARREGLOS_PARALELOS:
            for d in await col.find({ids_f: uid, names_f: {"$exists": True}}).to_list(length=10000):
                nuevos = nombres_sin_usuario(d.get(ids_f) or [], d.get(names_f) or [], uid)
                await col.update_one({"_id": d["_id"]}, {"$set": {names_f: nuevos}})
                conteo["documentos_anonimizados"] += 1
    # Minutas: el responsable de cada acuerdo va dentro de un arreglo.
    res = await db.minutas.update_many(
        {"acuerdos.responsable_id": uid},
        {"$set": {"acuerdos.$[a].responsable_name": USUARIO_ELIMINADO}},
        array_filters=[{"a.responsable_id": uid}],
    )
    conteo["documentos_anonimizados"] += res.modified_count

    # 3) Invitaciones: quita nombre y correo; las pendientes ya no se pueden canjear.
    filtro_inv: Dict[str, Any] = {"accepted_user_id": uid}
    if email_original:
        filtro_inv = {"$or": [{"accepted_user_id": uid}, {"email": email_original}]}
    await db.invitations.update_many({**filtro_inv, "status": "pending"}, {"$set": {"status": "revoked"}})
    res = await db.invitations.update_many(
        filtro_inv,
        {"$set": {"name": USUARIO_ELIMINADO, "email": correo_eliminado(uid), "phone": None}},
    )
    conteo["documentos_anonimizados"] += res.modified_count

    # 4) El usuario en sí (al final: si algo falla antes, se puede reintentar).
    await db.users.update_one({"id": uid}, {"$set": campos_usuario_anonimizado(uid, ahora)})
    conteo["documentos_anonimizados"] += 1
    log.info(f"[cuenta] Usuario {uid} anonimizado: {conteo}")
    return conteo


async def _validar_puede_eliminarse(u: dict) -> None:
    """No se permite dejar el sistema sin ningún Coordinador General."""
    if u.get("role") == ROLE_COORD:
        otros = await db.users.count_documents(
            {"role": ROLE_COORD, "id": {"$ne": u["id"]}, "deleted_at": {"$exists": False}}
        )
        if otros == 0:
            raise HTTPException(
                409,
                "Eres el único Coordinador General. Crea o promueve a otro antes de eliminar tu cuenta.",
            )


class DeleteAccountIn(BaseModel):
    password: str


@api.post("/auth/delete_account")
async def delete_account(body: DeleteAccountIn, user: dict = Depends(current_user)):
    """Eliminación de cuenta iniciada por la persona (exige su contraseña)."""
    completo = await db.users.find_one({"id": user["id"]})
    if not completo or not verify_pw(body.password or "", completo.get("password", "")):
        raise HTTPException(403, "La contraseña no es correcta")
    await _validar_puede_eliminarse(completo)
    await anonimizar_usuario(user["id"])
    return {"ok": True}


class DeletionRequestIn(BaseModel):
    email: EmailStr
    note: Optional[str] = None


@api.post("/public/deletion_request")
async def public_deletion_request(body: DeletionRequestIn):
    """Formulario público de la página /eliminar-cuenta (sin sesión). Responde
    siempre lo mismo, exista o no la cuenta, para no revelar quién es usuario."""
    email = body.email.lower()
    u = await db.users.find_one({"email": email, "deleted_at": {"$exists": False}})
    ya = await db.deletion_requests.find_one({"email": email, "status": "pending"})
    if not ya:
        await db.deletion_requests.insert_one({
            "id": str(uuid.uuid4()),
            "email": email,
            "user_id": u["id"] if u else None,
            "note": (body.note or "").strip()[:500] or None,
            "status": "pending",
            "created_at": datetime.now(timezone.utc),
        })
    return {"ok": True, "message": "Recibimos tu solicitud. Si el correo corresponde a una cuenta, la eliminaremos y te lo confirmaremos."}


@api.get("/admin/deletion_requests")
async def list_deletion_requests(user: dict = Depends(require_role(ROLE_COORD))):
    items = await db.deletion_requests.find({"status": "pending"}).sort("created_at", 1).to_list(length=500)
    for it in items:
        it.pop("_id", None)
    return items


class ExecuteDeletionIn(BaseModel):
    confirm: bool = False


@api.post("/admin/deletion_requests/{rid}/execute")
async def execute_deletion_request(rid: str, body: ExecuteDeletionIn, user: dict = Depends(require_role(ROLE_COORD))):
    """El Coordinador General atiende una solicitud pública. Requiere confirm=true."""
    if not body.confirm:
        raise HTTPException(400, "Falta confirmar la eliminación (confirm=true)")
    req = await db.deletion_requests.find_one({"id": rid})
    if not req:
        raise HTTPException(404, "Solicitud no existe")
    if req["status"] != "pending":
        raise HTTPException(410, "Solicitud ya atendida")
    conteo = None
    if req.get("user_id"):
        target = await db.users.find_one({"id": req["user_id"]})
        if target and not target.get("deleted_at"):
            await _validar_puede_eliminarse(target)
            conteo = await anonimizar_usuario(target["id"])
    # La solicitud conserva el correo solo mientras está pendiente.
    await db.deletion_requests.update_one(
        {"id": rid},
        {"$set": {"status": "done", "resolved_at": datetime.now(timezone.utc), "resolved_by": user["id"],
                  "email": correo_eliminado(req.get("user_id") or rid), "note": None}},
    )
    return {"ok": True, "resultado": conteo}


# === PUSH NOTIFICATIONS (Expo) ==============================================
import httpx  # local import is safe — module-level top imports remain authoritative

EXPO_PUSH_API_URL = "https://exp.host/--/api/v2/push/send"


def _is_valid_expo_token(token: str) -> bool:
    """
    Valida el formato de un Expo push token.
    Formato oficial: 'ExponentPushToken[xxxxxxxxxxxxxxxxxxxxxx]' o 'ExpoPushToken[...]'.
    """
    if not token or not isinstance(token, str):
        return False
    t = token.strip()
    if not (t.startswith("ExponentPushToken[") or t.startswith("ExpoPushToken[")):
        return False
    if not t.endswith("]"):
        return False
    if len(t) > 200:  # defensive cap
        return False
    return True


@api.post("/users/push-token")
async def register_push_token(
    body: PushTokenIn,
    user: dict = Depends(current_user),
):
    """
    Registra un Expo Push Token en el perfil del usuario autenticado.
    - Usa $addToSet para evitar duplicados.
    - Limita el array a 10 tokens (FIFO) para no acumular dispositivos viejos.
    """
    token = (body.token or "").strip()
    if not _is_valid_expo_token(token):
        raise HTTPException(400, "Token de Expo inválido")

    # Add to set (no duplicates).
    await db.users.update_one(
        {"id": user["id"]},
        {"$addToSet": {"expo_push_tokens": token}},
    )

    # FIFO cap @ 10 tokens — keep only the most recent ones.
    fresh = await db.users.find_one(
        {"id": user["id"]}, {"_id": 0, "expo_push_tokens": 1}
    )
    tokens_list = (fresh or {}).get("expo_push_tokens") or []
    if len(tokens_list) > 10:
        trimmed = tokens_list[-10:]
        await db.users.update_one(
            {"id": user["id"]},
            {"$set": {"expo_push_tokens": trimmed}},
        )
        tokens_list = trimmed

    logger_count = len(tokens_list)
    log.info(
        "[push] token registered user=%s platform=%s total_tokens=%d",
        user.get("email"),
        body.platform or "unknown",
        logger_count,
    )
    return {"ok": True, "count": logger_count}


@api.delete("/users/push-token")
async def unregister_push_token(
    body: PushTokenIn,
    user: dict = Depends(current_user),
):
    """Elimina un Expo push token del perfil del usuario (logout / device removal)."""
    token = (body.token or "").strip()
    if not token:
        raise HTTPException(400, "Token vacío")
    await db.users.update_one(
        {"id": user["id"]},
        {"$pull": {"expo_push_tokens": token}},
    )
    return {"ok": True}


async def send_push_notification(
    user_id: str,
    title: str,
    body: str,
    data: Optional[dict] = None,
    sound: Optional[str] = "default",
    priority: str = "high",
) -> dict:
    """
    Envía una notificación push a TODOS los Expo push tokens registrados del usuario.

    Esta función está **definida y lista para usarse**, pero NO se vincula a ningún
    evento todavía. Es responsabilidad del feature que la consuma (e.g. nuevo reporte,
    mensaje en chat, asignación de tarea) llamarla.

    Args:
        user_id: ID del usuario destinatario.
        title:   Título de la notificación.
        body:    Cuerpo / mensaje principal.
        data:    Payload opcional para deep-linking (e.g. {"report_id": "..."}).
        sound:   'default' o None.
        priority: 'default' | 'normal' | 'high'.

    Returns:
        dict con shape:
        {
          "ok": bool,
          "sent": int,            # cuántos mensajes se intentaron enviar
          "failed_tokens": [str], # tokens que Expo reportó como inválidos
          "response": <expo raw json or error string>,
        }
    """
    u = await db.users.find_one({"id": user_id}, {"_id": 0, "expo_push_tokens": 1})
    tokens: list = (u or {}).get("expo_push_tokens") or []
    if not tokens:
        return {"ok": False, "sent": 0, "failed_tokens": [], "response": "no tokens"}

    # Build the Expo push message batch (Expo accepts a JSON array).
    messages = []
    for t in tokens:
        if not _is_valid_expo_token(t):
            continue
        msg = {
            "to": t,
            "title": title,
            "body": body,
            "priority": priority,
        }
        if sound:
            msg["sound"] = sound
        if data:
            msg["data"] = data
        messages.append(msg)

    if not messages:
        return {"ok": False, "sent": 0, "failed_tokens": tokens, "response": "no valid tokens"}

    headers = {
        "Accept": "application/json",
        "Accept-Encoding": "gzip, deflate",
        "Content-Type": "application/json",
    }

    failed_tokens: list = []
    try:
        async with httpx.AsyncClient(timeout=10.0) as client:
            r = await client.post(EXPO_PUSH_API_URL, json=messages, headers=headers)
            try:
                payload = r.json()
            except Exception:
                payload = {"raw": r.text}

            # Expo returns {"data": [{"status":"ok"|"error","id":"...","message":"...","details":{"error":"DeviceNotRegistered"}}, ...]}
            results = (payload or {}).get("data") or []
            for idx, item in enumerate(results):
                if isinstance(item, dict) and item.get("status") == "error":
                    err = (item.get("details") or {}).get("error", "")
                    if err in ("DeviceNotRegistered", "InvalidCredentials"):
                        if idx < len(messages):
                            failed_tokens.append(messages[idx]["to"])

            # Auto-clean: remove invalid tokens from user's profile.
            if failed_tokens:
                await db.users.update_one(
                    {"id": user_id},
                    {"$pull": {"expo_push_tokens": {"$in": failed_tokens}}},
                )

            return {
                "ok": r.status_code < 400,
                "sent": len(messages),
                "failed_tokens": failed_tokens,
                "response": payload,
            }
    except Exception as exc:  # pragma: no cover - defensive
        log.exception("[push] send_push_notification failed: %s", exc)
        return {
            "ok": False,
            "sent": 0,
            "failed_tokens": [],
            "response": f"exception: {exc}",
        }


# === PROJECTS ===============================================================
GENERO_NIVELES_MAX = 20
GENERO_NIVELES_CLAVE_MAX = 60


def sanitizar_genero_niveles(valor) -> dict:
    """Valida `genero_niveles` (nombre de nivel → 'm' | 'f'): claves de texto no vacías de hasta
    60 caracteres, máximo 20 entradas. Devuelve un dict limpio; lanza 400 con mensaje es-MX."""
    if not valor:
        return {}
    if not isinstance(valor, dict):
        raise HTTPException(400, "El género de los niveles debe ser una lista de pares nombre y género.")
    if len(valor) > GENERO_NIVELES_MAX:
        raise HTTPException(400, f"Solo se puede indicar el género de hasta {GENERO_NIVELES_MAX} niveles.")
    limpio: dict = {}
    for clave, genero in valor.items():
        nombre = clave.strip() if isinstance(clave, str) else ""
        if not nombre:
            raise HTTPException(400, "El nombre de un nivel con género indicado no puede estar vacío.")
        if len(nombre) > GENERO_NIVELES_CLAVE_MAX:
            raise HTTPException(400, f"El nombre de un nivel admite hasta {GENERO_NIVELES_CLAVE_MAX} caracteres.")
        if genero not in ("m", "f"):
            raise HTTPException(400, "El género de un nivel debe ser masculino o femenino.")
        limpio[nombre] = genero
    return limpio


def _sanitize_str_list(items, max_items: int = 200, max_len: int = 200) -> list:
    """Limpia listas de strings (contratistas / contratos). Dedup case-insensitive."""
    if not items or not isinstance(items, list):
        return []
    out: list = []
    seen: set = set()
    for it in items:
        if not isinstance(it, str):
            continue
        s = it.strip()
        if not s:
            continue
        if len(s) > max_len:
            s = s[:max_len]
        key = s.lower()
        if key in seen:
            continue
        seen.add(key)
        out.append(s)
        if len(out) >= max_items:
            break
    return out


def _zona_o_400(nombre: Optional[str]) -> str:
    try:
        return validar_zona_horaria(nombre) or ZONA_POR_DEFECTO
    except ValueError as e:
        raise HTTPException(400, str(e))


def _hora_hhmm_o_400(valor: Optional[str]) -> Optional[str]:
    """"HH:MM" normalizado (24 h); vacío -> None; formato inválido -> 400."""
    try:
        return normalizar_hora_hhmm(valor)
    except ValueError as e:
        raise HTTPException(400, str(e))


COLOR_HEX_ESTRICTO = re.compile(r"^#[0-9A-Fa-f]{6}$")


def validar_color_hex(valor: Optional[str], etiqueta: str) -> Optional[str]:
    """P-02: al GUARDAR un color se exige #RRGGBB exacto y NUNCA se sustituye en silencio un
    valor inválido por el color por defecto: se responde 400 con un mensaje claro.
    Vacío/None = "no configurado" (devuelve None; quien llama decide el color por defecto)."""
    if valor is None:
        return None
    if not isinstance(valor, str):
        raise HTTPException(400, f"{etiqueta}: el color debe ser texto con el formato #RRGGBB (por ejemplo #1E40AF).")
    v = valor.strip()
    if v == "":
        return None
    if not COLOR_HEX_ESTRICTO.match(v):
        raise HTTPException(400, f"{etiqueta}: el color debe tener el formato #RRGGBB (por ejemplo #1E40AF). Escribiste «{valor}».")
    return v.upper()


def _sanitize_color_hex(value: Optional[str]) -> Optional[str]:
    """Valida un color hex `#RRGGBB` o `#RGB`. Devuelve `#RRGGBB` en mayúsculas o None."""
    if not value or not isinstance(value, str):
        return None
    s = value.strip().lstrip("#")
    if len(s) == 3 and all(ch in "0123456789abcdefABCDEF" for ch in s):
        s = "".join(ch * 2 for ch in s)
    if len(s) != 6 or any(ch not in "0123456789abcdefABCDEF" for ch in s):
        return None
    return "#" + s.upper()


_WHATSAPP_GROUP_RE = re.compile(r"^\d+(-\d+)*@g\.us$")


def _whatsapp_group_ids(value: Optional[str]) -> List[str]:
    """Lista de IDs de grupo guardados en `whatsapp_group_id` (varios separados
    por coma, punto y coma, espacio o salto de línea). Sin repetidos, en orden."""
    out: List[str] = []
    for g in re.split(r"[,;\s]+", value or ""):
        if g and g not in out:
            out.append(g)
    return out


def _sanitize_whatsapp_group_id(value: Optional[str]) -> Optional[str]:
    """Normaliza el/los ID(s) de grupo de WhatsApp. Vacío => None (desactiva el
    envío). Lanza 400 si algún ID no tiene el formato `<dígitos>@g.us` de Whapi.
    Se guarda como texto "id1, id2" (compatible con proyectos de un solo ID)."""
    ids = _whatsapp_group_ids(value)
    if not ids:
        return None
    for g in ids:
        if not _WHATSAPP_GROUP_RE.match(g):
            raise HTTPException(400, f"whatsapp_group_id inválido: {g!r} debe tener el formato 1203634...@g.us")
    return ", ".join(ids)


@api.get("/projects")
async def list_projects(user: dict = Depends(current_user)):
    # La lista solo pinta nombre/constructora/contrato — excluir binarios
    # pesados (logo y galería de datos generales, hasta 30 imágenes de 5MB
    # c/u por proyecto) que solo hacen falta en el detalle de un proyecto.
    projection = {"constructora_logo": 0, "general_data_images": 0}
    if user["role"] in (ROLE_COORD, ROLE_JEFE):
        # Coordinador General y Jefe de Proyecto: acceso global a todos los proyectos.
        cursor = db.projects.find({"archived": {"$ne": True}}, projection).sort("created_at", -1)
    else:
        pids = user.get("project_ids") or []
        cursor = db.projects.find({"id": {"$in": pids}, "archived": {"$ne": True}}, projection).sort("created_at", -1)
    items = await cursor.to_list(length=500)
    for it in items:
        it.pop("_id", None)
        it.setdefault("contratistas_list", [])
        it.setdefault("contratos_list", [])
        it.setdefault("minuta_code_prefix", None)
        it["tipo_obra"] = tipo_obra_de(it)
        it["modulos"] = _sanitize_modulos(it.get("modulos"))
        it["modulos_areas"] = _sanitize_modulos_areas(it.get("modulos_areas"))
    return items


@api.post("/projects")
async def create_project(body: ProjectIn, user: dict = Depends(require_role(ROLE_COORD))):
    pid = str(uuid.uuid4())
    doc = {
        "id": pid,
        "name": body.name.strip(),
        "constructora": body.constructora.strip(),
        "contract_number": body.contract_number.strip(),
        "objeto_contrato": (body.objeto_contrato or "").strip() or None,
        "datos_contrato": _sanitize_datos_contrato(body.datos_contrato),
        "cliente_principal": (body.cliente_principal or "").strip() or None,
        "color_tema": validar_color_hex(body.color_tema, "Color del título de portada") or "#003366",
        "color_institucional": validar_color_hex(body.color_institucional, "Color institucional") or "#003366",
        "report_text_color": validar_color_hex(body.report_text_color, "Color del texto de reportes") or "#0F172A",
        "start_date": body.start_date,
        "end_date": body.end_date,
        "description": (body.description or "").strip() or None,
        "reference_files": _sanitize_reference_files(body.reference_files),
        "contratistas_list": _sanitize_str_list(body.contratistas_list),
        "contratos_list": _sanitize_str_list(body.contratos_list),
        "categorias_personal": _sanitize_str_list(body.categorias_personal),
        "categorias_equipo": _sanitize_str_list(body.categorias_equipo),
        "tipo_contrato": body.tipo_contrato,
        "modo_avance": body.modo_avance,
        "nombres_niveles_partida": _sanitize_str_list(body.nombres_niveles_partida),
        "nombre_nivel_concepto": (body.nombre_nivel_concepto or "").strip(),
        "genero_niveles": sanitizar_genero_niveles(body.genero_niveles),
        "unidades_personalizadas": _sanitize_str_list(body.unidades_personalizadas),
        "tipo_obra": body.tipo_obra,
        "etapas_poste": [e.model_dump() for e in body.etapas_poste],
        "titulo_modulo_catalogo": (body.titulo_modulo_catalogo or "").strip(),
        "cadencia_reporte": body.cadencia_reporte,
        "dia_inicio_semana": body.dia_inicio_semana,
        "whatsapp_group_id": _sanitize_whatsapp_group_id(body.whatsapp_group_id),
        "zona_horaria": _zona_o_400(body.zona_horaria),
        "separador_decimal": body.separador_decimal,
        # Sin `modulos` explícitos, el tipo de obra decide cuáles quedan encendidos.
        "modulos": _sanitize_modulos(body.modulos) if body.modulos is not None else modulos_por_defecto_de_tipo(body.tipo_obra),
        "created_by": user["id"],
        "created_at": datetime.now(timezone.utc),
        "archived": False,
    }
    await db.projects.insert_one(doc)
    doc.pop("_id", None)
    return doc


@api.get("/projects/{pid}")
async def get_project(pid: str, user: dict = Depends(current_user)):
    p = await ensure_project_access(user, pid)
    p.pop("_id", None)
    p.setdefault("reference_files", [])
    p.setdefault("contratistas_list", [])
    p.setdefault("contratos_list", [])
    p.setdefault("categorias_personal", [])
    p.setdefault("categorias_equipo", [])
    p.setdefault("objeto_contrato", None)
    p.setdefault("datos_contrato", {})
    p.setdefault("cliente_principal", None)
    p.setdefault("color_tema", "#003366")
    p.setdefault("color_institucional", "#003366")
    p.setdefault("report_text_color", "#0F172A")
    # `general_data_images` NO se incluye aquí a propósito (ver
    # ensure_project_access): puede pesar hasta 30 imágenes de 5MB. Solo se
    # manda el conteo (vía $size, sin transferir el array) para el badge de
    # la UI; el contenido real se pide bajo demanda en
    # GET /projects/{pid}/general-data-images cuando se abre ese modal.
    p["general_data_images"] = []
    count_doc = await db.projects.aggregate([
        {"$match": {"id": pid}},
        {"$project": {"_id": 0, "n": {"$size": {"$ifNull": ["$general_data_images", []]}}}},
    ]).to_list(length=1)
    p["general_data_images_count"] = count_doc[0]["n"] if count_doc else 0
    p.setdefault("minuta_code_prefix", None)
    p.setdefault("whatsapp_group_id", None)
    p.setdefault("tipo_contrato", "PRECIOS_UNITARIOS")
    p.setdefault("modo_avance", "CANTIDAD")
    p.setdefault("nombres_niveles_partida", [])
    p.setdefault("nombre_nivel_concepto", "")
    p.setdefault("genero_niveles", {})
    p.setdefault("unidades_personalizadas", [])
    if "etapas_poste" not in p:
        p["etapas_poste"] = list(etapas_poste_de(p))
    p["tipo_obra"] = tipo_obra_de(p)
    p.setdefault("titulo_modulo_catalogo", "")
    p.setdefault("cadencia_reporte", "MENSUAL")
    p.setdefault("dia_inicio_semana", "LUNES")
    p["zona_horaria"] = p.get("zona_horaria") or ZONA_POR_DEFECTO
    p.setdefault("separador_decimal", ".")
    p.setdefault("turno_nocturno_inicio", None)
    p.setdefault("turno_nocturno_fin", None)
    p["hoy"] = hoy_proyecto(p).isoformat()
    p["tz_offset_min"] = offset_min_proyecto(p)
    p["modulos"] = _sanitize_modulos(p.get("modulos"))
    p["modulos_areas"] = _sanitize_modulos_areas(p.get("modulos_areas"))
    return p


@api.put("/projects/{pid}")
async def update_project(pid: str, body: ProjectPatch, user: dict = Depends(require_role(ROLE_COORD))):
    """PATCH parcial: sólo actualiza los campos enviados.

    Permite, por ejemplo, actualizar únicamente `objeto_contrato` o catálogos
    sin tener que reenviar name/constructora/contract_number.
    """
    existing = await db.projects.find_one({"id": pid})
    if not existing:
        raise HTTPException(404, "Proyecto no existe")

    upd: dict = {}
    if body.name is not None:
        n = body.name.strip()
        if n:
            upd["name"] = n
    if body.constructora is not None:
        upd["constructora"] = body.constructora.strip()
    if body.contract_number is not None:
        upd["contract_number"] = body.contract_number.strip()
    if body.objeto_contrato is not None:
        upd["objeto_contrato"] = body.objeto_contrato.strip() or None
    if body.datos_contrato is not None:
        upd["datos_contrato"] = _sanitize_datos_contrato(body.datos_contrato)
    if body.cliente_principal is not None:
        upd["cliente_principal"] = body.cliente_principal.strip() or None
    if body.color_tema is not None:
        upd["color_tema"] = validar_color_hex(body.color_tema, "Color del título de portada") or "#003366"
    if body.color_institucional is not None:
        upd["color_institucional"] = validar_color_hex(body.color_institucional, "Color institucional") or "#003366"
    if body.report_text_color is not None:
        upd["report_text_color"] = validar_color_hex(body.report_text_color, "Color del texto de reportes") or "#0F172A"
    if body.start_date is not None:
        upd["start_date"] = body.start_date
    if body.end_date is not None:
        upd["end_date"] = body.end_date
    if body.description is not None:
        upd["description"] = body.description.strip() or None
    if body.reference_files is not None:
        upd["reference_files"] = _sanitize_reference_files(body.reference_files)
    if body.contratistas_list is not None:
        upd["contratistas_list"] = _sanitize_str_list(body.contratistas_list)
    if body.contratos_list is not None:
        upd["contratos_list"] = _sanitize_str_list(body.contratos_list)
    if body.categorias_personal is not None:
        upd["categorias_personal"] = _sanitize_str_list(body.categorias_personal)
    if body.categorias_equipo is not None:
        upd["categorias_equipo"] = _sanitize_str_list(body.categorias_equipo)
    if body.constructora_logo is not None:
        # Aceptamos cadena vacía para "limpiar" el logo
        upd["constructora_logo"] = body.constructora_logo or None
    if body.minuta_code_prefix is not None:
        upd["minuta_code_prefix"] = body.minuta_code_prefix.strip() or None
    if body.whatsapp_group_id is not None:
        upd["whatsapp_group_id"] = _sanitize_whatsapp_group_id(body.whatsapp_group_id)

    # modo_avance y tipo_contrato: ejes independientes, cada uno con su
    # propia bandera de confirmación — cambiarlos con datos ya capturados
    # reinterpreta cómo se lee ese dato, así que NUNCA se convierte en
    # silencio (ver diagnóstico de Etapa 1).
    if body.modo_avance is not None and body.modo_avance != existing.get("modo_avance", "CANTIDAD"):
        tiene_avances = await db.registros_avance.find_one({"project_id": pid})
        if tiene_avances and not body.confirmar_cambio_modo_avance:
            raise HTTPException(
                400,
                "Este proyecto ya tiene registros de avance capturados. Cambiar "
                "modo_avance reinterpreta cómo se calcula el % de avance de cada "
                "concepto y partida — reenvía la solicitud con "
                "confirmar_cambio_modo_avance=true para confirmar el cambio.",
            )
        upd["modo_avance"] = body.modo_avance
    if body.tipo_contrato is not None and body.tipo_contrato != existing.get("tipo_contrato", "PRECIOS_UNITARIOS"):
        tiene_conceptos = await db.conceptos.find_one({"project_id": pid})
        if tiene_conceptos and not body.confirmar_cambio_tipo_contrato:
            raise HTTPException(
                400,
                "Este proyecto ya tiene conceptos capturados en su catálogo. "
                "Cambiar tipo_contrato reinterpreta cómo se leen cantidad y "
                "precio unitario — reenvía la solicitud con "
                "confirmar_cambio_tipo_contrato=true para confirmar el cambio.",
            )
        upd["tipo_contrato"] = body.tipo_contrato
    if body.nombres_niveles_partida is not None:
        upd["nombres_niveles_partida"] = _sanitize_str_list(body.nombres_niveles_partida)
    if body.nombre_nivel_concepto is not None:
        upd["nombre_nivel_concepto"] = body.nombre_nivel_concepto.strip()
    if body.genero_niveles is not None:
        upd["genero_niveles"] = sanitizar_genero_niveles(body.genero_niveles)
    if body.unidades_personalizadas is not None:
        upd["unidades_personalizadas"] = _sanitize_str_list(body.unidades_personalizadas)
    if body.etapas_poste is not None:
        upd["etapas_poste"] = [e.model_dump() for e in body.etapas_poste]
    if body.tipo_obra is not None and body.tipo_obra != existing.get("tipo_obra"):
        # Cambiar el tipo solo cambia lo que se ofrece a futuro: NO reescribe módulos
        # ni etapas ya configurados. Un proyecto anterior al campo que nunca guardó sus
        # etapas conserva las que usaba implícitamente (para no perderlas al dejar de
        # ser "legado").
        if not existing.get("tipo_obra") and "etapas_poste" not in existing and "etapas_poste" not in upd:
            upd["etapas_poste"] = [dict(e) for e in PLANTILLA_ETAPAS_CIMENTACION_POSTES]
        upd["tipo_obra"] = body.tipo_obra
    if body.titulo_modulo_catalogo is not None:
        upd["titulo_modulo_catalogo"] = body.titulo_modulo_catalogo.strip()
    if body.cadencia_reporte is not None:
        upd["cadencia_reporte"] = body.cadencia_reporte
    if body.dia_inicio_semana is not None:
        upd["dia_inicio_semana"] = body.dia_inicio_semana
    if body.zona_horaria is not None:
        upd["zona_horaria"] = _zona_o_400(body.zona_horaria)
    if body.turno_nocturno_inicio is not None or body.turno_nocturno_fin is not None:
        ini = _hora_hhmm_o_400(body.turno_nocturno_inicio if body.turno_nocturno_inicio is not None
                               else existing.get("turno_nocturno_inicio"))
        fin = _hora_hhmm_o_400(body.turno_nocturno_fin if body.turno_nocturno_fin is not None
                               else existing.get("turno_nocturno_fin"))
        if bool(ini) != bool(fin):
            raise HTTPException(400, "El turno nocturno necesita hora de inicio y hora de fin")
        if ini and ini == fin:
            raise HTTPException(400, "La hora de inicio y la de fin del turno nocturno no pueden ser iguales")
        upd["turno_nocturno_inicio"] = ini
        upd["turno_nocturno_fin"] = fin
    if body.separador_decimal is not None:
        upd["separador_decimal"] = body.separador_decimal

    if upd:
        await db.projects.update_one({"id": pid}, {"$set": upd})

    p = await db.projects.find_one({"id": pid})
    return _project_public(p)


def _project_public(p: dict) -> dict:
    """Serializa un doc de proyecto para exponer al frontend con defaults."""
    if not p:
        return p
    p = dict(p)  # copia superficial para no mutar el original
    p.pop("_id", None)
    # Config/estructura del índice editable: se sirven por /indice/{periodo}.
    p.pop("indice_config", None)
    p.pop("indice_estructura", None)
    p.setdefault("reference_files", [])
    p.setdefault("contratistas_list", [])
    p.setdefault("contratos_list", [])
    p.setdefault("categorias_personal", [])
    p.setdefault("categorias_equipo", [])
    p.setdefault("objeto_contrato", None)
    p.setdefault("datos_contrato", {})
    p.setdefault("cliente_principal", None)
    p.setdefault("color_tema", "#003366")
    p.setdefault("color_institucional", "#003366")
    p.setdefault("report_text_color", "#0F172A")
    p.setdefault("general_data_images", [])
    p.setdefault("general_data_names", [])
    p.setdefault("template_pdf", None)
    p.setdefault("template_docx", None)
    p.setdefault("template_pptx", None)
    p.setdefault("template_map", None)
    p.setdefault("minuta_code_prefix", None)
    p.setdefault("whatsapp_group_id", None)
    p.setdefault("tipo_contrato", "PRECIOS_UNITARIOS")
    p.setdefault("modo_avance", "CANTIDAD")
    p.setdefault("nombres_niveles_partida", [])
    p.setdefault("nombre_nivel_concepto", "")
    p.setdefault("genero_niveles", {})
    p.setdefault("unidades_personalizadas", [])
    if "etapas_poste" not in p:
        p["etapas_poste"] = list(etapas_poste_de(p))
    p["tipo_obra"] = tipo_obra_de(p)
    p.setdefault("titulo_modulo_catalogo", "")
    p.setdefault("cadencia_reporte", "MENSUAL")
    p.setdefault("dia_inicio_semana", "LUNES")
    p["zona_horaria"] = p.get("zona_horaria") or ZONA_POR_DEFECTO
    p.setdefault("separador_decimal", ".")
    p.setdefault("turno_nocturno_inicio", None)
    p.setdefault("turno_nocturno_fin", None)
    p["hoy"] = hoy_proyecto(p).isoformat()
    p["tz_offset_min"] = offset_min_proyecto(p)
    p["modulos"] = _sanitize_modulos(p.get("modulos"))
    p["modulos_areas"] = _sanitize_modulos_areas(p.get("modulos_areas"))
    return p


@api.put("/projects/{pid}/catalogos")
async def set_project_catalogos(
    pid: str,
    body: dict,
    user: dict = Depends(require_role(ROLE_COORD)),
):
    """Actualiza catálogos dinámicos del proyecto:
    contratistas_list, contratos_list, categorias_personal y categorias_equipo.
    Sólo Coordinador General puede modificarlos."""
    upd: dict = {}
    if isinstance(body.get("contratistas_list"), list):
        upd["contratistas_list"] = _sanitize_str_list(body.get("contratistas_list"))
    if isinstance(body.get("contratos_list"), list):
        upd["contratos_list"] = _sanitize_str_list(body.get("contratos_list"))
    if isinstance(body.get("categorias_personal"), list):
        upd["categorias_personal"] = _sanitize_str_list(body.get("categorias_personal"))
    if isinstance(body.get("categorias_equipo"), list):
        upd["categorias_equipo"] = _sanitize_str_list(body.get("categorias_equipo"))
    if not upd:
        raise HTTPException(400, "Nada para actualizar")
    r = await db.projects.update_one({"id": pid}, {"$set": upd})
    if r.matched_count == 0:
        raise HTTPException(404, "Proyecto no existe")
    p = await db.projects.find_one({"id": pid})
    return _project_public(p)


@api.put("/projects/{pid}/modulos")
async def set_project_modulos(
    pid: str,
    body: dict,
    user: dict = Depends(require_role(ROLE_COORD)),
):
    """Enciende/apaga módulos (plantillas) del proyecto, por categoría de
    informe — Diario/Semanal/Mensual (ver MODULOS_CATALOG). Un mismo módulo
    puede estar encendido en varias categorías a la vez. Sólo Coordinador
    General.

    Actualización PARCIAL por diseño: sólo se tocan las claves de módulo que
    vienen explícitamente en el body — las demás conservan su valor actual.
    Togglear "forestal_arbolado" nunca debe apagar de rebote
    "seguridad_higiene" sólo porque el cliente no lo mandó en el payload.
    """
    existing = await db.projects.find_one({"id": pid})
    if not existing:
        raise HTTPException(404, "Proyecto no existe")
    merged = _sanitize_modulos(existing.get("modulos"))
    for categoria, claves_validas in MODULOS_CATALOG.items():
        incoming = body.get(categoria) if isinstance(body, dict) else None
        if not isinstance(incoming, dict):
            continue
        for clave, valor in incoming.items():
            if clave in claves_validas and isinstance(valor, bool):
                merged[categoria][clave] = valor
    await db.projects.update_one({"id": pid}, {"$set": {"modulos": merged}})
    p = await db.projects.find_one({"id": pid})
    return _project_public(p)


def _sanitize_modulos_areas(value, claves_validas=None) -> dict:
    """{clave_de_módulo: area_id} — solo claves de módulo conocidas con un id de
    texto no vacío. El id apunta a una Área del proyecto (`/projects/{pid}/areas`)."""
    claves = set(claves_validas) if claves_validas is not None else set(MODULOS_KEYS)
    out: dict = {}
    if isinstance(value, dict):
        for k, v in value.items():
            if k in claves and isinstance(v, str) and v.strip():
                out[k] = v.strip()
    return out


@api.put("/projects/{pid}/modulos-areas")
async def set_project_modulos_areas(
    pid: str,
    body: dict,
    user: dict = Depends(require_role(ROLE_COORD)),
):
    """Asigna (o quita) el Área a la que pertenece cada módulo. El hub de
    módulos de Sub-Coordinador/Especialista agrupa por estas Áreas: primero
    ven las áreas y, adentro, las herramientas (módulos) de cada una.

    Actualización PARCIAL: solo se tocan las claves que vienen en el body;
    `null` o "" quita la asignación (el módulo cae en "General")."""
    existing = await db.projects.find_one({"id": pid})
    if not existing:
        raise HTTPException(404, "Proyecto no existe")
    if not isinstance(body, dict):
        raise HTTPException(400, "Cuerpo inválido")
    areas_ids = {a["id"] async for a in db.areas.find({"project_id": pid}, {"id": 1})}
    merged = _sanitize_modulos_areas(existing.get("modulos_areas"))
    for clave, area_id in body.items():
        if clave not in MODULOS_KEYS:
            raise HTTPException(400, f"Módulo desconocido: {clave}")
        if area_id in (None, ""):
            merged.pop(clave, None)
            continue
        if not isinstance(area_id, str) or area_id not in areas_ids:
            raise HTTPException(400, "El área no existe en este proyecto")
        merged[clave] = area_id
    await db.projects.update_one({"id": pid}, {"$set": {"modulos_areas": merged}})
    p = await db.projects.find_one({"id": pid})
    return _project_public(p)


