async def delete_tabla_resumen_columna(
    pid: str, cid: str, user: dict = Depends(require_role(ROLE_COORD, ROLE_SUB)),
):
    await ensure_project_access(user, pid)
    await db.tabla_resumen_columnas.delete_one({"id": cid, "project_id": pid})
    await db.tabla_resumen_celdas.delete_many({"project_id": pid, "columna_id": cid})
    return {"ok": True}


@api.put("/projects/{pid}/tabla-resumen/celdas")
async def upsert_tabla_resumen_celda(pid: str, body: TablaResumenCeldaIn, user: dict = Depends(current_user)):
    """Captura ABIERTA a cualquier rol con acceso al proyecto (incluido
    Especialista) — a diferencia de actividades/columnas (estructura de la
    tabla, solo Coordinador/Sub-Coord), el VALOR de cada celda es dato de
    avance como cualquier otro módulo de campo. Un doc por (actividad,
    columna) — cada llamada actualiza ese valor en su lugar, mismo criterio
    que `estudio_disciplina_avance`."""
    _assert_write_allowed(user)
    project = await ensure_project_access(user, pid)
    _ensure_modulo_activo(project, "tabla_resumen")
    if body.valor is not None and not (0 <= body.valor <= 100):
        raise HTTPException(400, "valor debe estar entre 0 y 100")
    actividad = await db.tabla_resumen_actividades.find_one({"id": body.actividad_id, "project_id": pid})
    if not actividad:
        raise HTTPException(404, "Actividad no existe en este proyecto")
    columna = await db.tabla_resumen_columnas.find_one({"id": body.columna_id, "project_id": pid})
    if not columna:
        raise HTTPException(404, "Columna no existe en este proyecto")
    key = {"project_id": pid, "actividad_id": body.actividad_id, "columna_id": body.columna_id}
    now = datetime.now(timezone.utc)
    existing = await db.tabla_resumen_celdas.find_one(key)
    upd = {
        **key,
        "valor": body.valor,
        "no_aplica": body.no_aplica,
        "updated_by": user["id"],
        "updated_by_name": user["name"],
        "updated_at": now,
    }
    if existing:
        await db.tabla_resumen_celdas.update_one({"id": existing["id"]}, {"$set": upd})
        upd["id"] = existing["id"]
    else:
        upd["id"] = str(uuid.uuid4())
        await db.tabla_resumen_celdas.insert_one(upd)
    upd.pop("_id", None)
    return upd


# --- Módulo "Estado del Tiempo" ---------------------------------------------
# Captura MANUAL de Temperatura/Viento/Precipitación/Calidad del aire por
# nodo Estación + día (fecha CDMX) — hasta ahora esa sección del resumen
# impreso (ver "ESTADO DEL TIEMPO" en `draw_subtramo_summary_page`/`_slide`)
# se llenaba 100% automático vía Open-Meteo (`_fetch_weather_for_export`).
# Esta captura tiene PRIORIDAD sobre esa consulta automática cuando existe
# (ver el prefetch en `export_reports_pdf`/`export_reports_pptx`, más abajo);
# si no hay captura de hoy para un nodo, se sigue usando el fetch automático
# sin cambios — es la red de seguridad para estaciones que no usan este
# módulo. Nombres de campo IDÉNTICOS a los que ya devuelve
# `_fetch_weather_for_export` (`temperature_c`/`wind_kmh`/`precipitation_mm`/
# `us_aqi`) para que el renderer no necesite saber de dónde salió el dato.
# Solo aplica a nodos tipo "Estación" (ver `tipo_nodo` en LocationNode) que
# ya estén habilitados en Acceso al Predio (`_acceso_predio_efectivo`) — un
# Intertramo no tiene sección de clima en su formato impreso.
class WeatherLogIn(BaseModel):
    node_id: str
    temperature_c: Optional[float] = None
    wind_kmh: Optional[float] = None
    precipitation_mm: Optional[float] = None
    us_aqi: Optional[float] = None


def _node_es_estacion_habilitada(node: dict) -> bool:
    return bool(node) and _acceso_predio_efectivo(node) and (node.get("tipo_nodo") or "estacion") == "estacion"


@api.get("/projects/{pid}/weather-logs")
async def list_weather_logs(pid: str, date: Optional[str] = None, user: dict = Depends(current_user)):
    """Capturas de una fecha CDMX dada (default: hoy) — una sola llamada
    para que la pantalla de captura indexe por `node_id` en vez de pedir
    nodo por nodo."""
    await ensure_project_access(user, pid)
    fecha_cdmx = date or (await hoy_de(pid)).isoformat()
    docs = await db.weather_logs.find(
        {"project_id": pid, "fecha_cdmx": fecha_cdmx}, {"_id": 0},
    ).sort([("node_id", 1), ("hora_cdmx", 1)]).to_list(length=2000)
    return {"logs": docs}


def _latest_weather_log_by_node(docs: list) -> dict:
    """Una captura por nodo para los exports: la MÁS RECIENTE del día
    (mayor `hora_cdmx`; las capturas antiguas sin hora cuentan como la más
    vieja) que tenga al menos un valor — así una hora capturada en blanco no
    tapa la última con datos."""
    best: dict = {}
    for wl in docs:
        if not any(wl.get(k) is not None for k in ("temperature_c", "wind_kmh", "precipitation_mm", "us_aqi")):
            continue
        rank = (wl.get("hora_cdmx") or "", wl.get("updated_at") or datetime.min.replace(tzinfo=timezone.utc))
        cur = best.get(wl["node_id"])
        if cur is None or rank >= cur[0]:
            best[wl["node_id"]] = (rank, wl)
    return {nid: wl for nid, (_, wl) in best.items()}


@api.put("/projects/{pid}/weather-logs")
async def upsert_weather_log(pid: str, body: WeatherLogIn, user: dict = Depends(current_user)):
    """Captura ABIERTA a cualquier rol con acceso al proyecto (incluido
    Especialista, presente en sitio) — mismo criterio que
    `upsert_tabla_resumen_celda`. Un doc por (nodo, día CDMX, hora CDMX): el
    clima se captura cada hora; capturar de nuevo en la misma hora
    sobrescribe, nunca duplica."""
    _assert_write_allowed(user)
    project = await ensure_project_access(user, pid)
    _ensure_modulo_activo(project, "estado_tiempo")
    node = await db.location_nodes.find_one({"id": body.node_id, "project_id": pid})
    if not node:
        raise HTTPException(404, "Nodo no existe en este proyecto")
    if not _node_es_estacion_habilitada(node):
        raise HTTPException(400, "Este nodo no es una Estación habilitada en Acceso al Predio")

    now = datetime.now(timezone.utc)
    fecha_cdmx = (await hoy_de(pid)).isoformat()
    hora_cdmx = f"{now.astimezone(MX_TZ).hour:02d}"
    key = {"project_id": pid, "node_id": body.node_id, "fecha_cdmx": fecha_cdmx, "hora_cdmx": hora_cdmx}
    upd = {
        **key,
        "node_name": node.get("name") or "",
        "temperature_c": body.temperature_c,
        "wind_kmh": body.wind_kmh,
        "precipitation_mm": body.precipitation_mm,
        "us_aqi": body.us_aqi,
        "captured_by": user["id"],
        "captured_by_name": user["name"],
        "updated_at": now,
    }
    existing = await db.weather_logs.find_one(key)
    if existing:
        await db.weather_logs.update_one({"id": existing["id"]}, {"$set": upd})
        upd["id"] = existing["id"]
        upd["created_at"] = existing.get("created_at", now)
    else:
        upd["id"] = str(uuid.uuid4())
        upd["created_at"] = now
        await db.weather_logs.insert_one(dict(upd))
    upd.pop("_id", None)
    return upd


