# --- Puente app → panel externo: exportar en el MISMO formato de 3 hojas --
# (POSTES/CIMENTACION/PERFORADORAS) que ya sabe leer el panel HTML de obra
# que el usuario usaba antes de este módulo (ver stateToWorkbook() en ese
# panel — layout replicado aquí celda por celda). Puente unidireccional y de
# solo lectura: quien siga abriendo ese panel (para compartirlo sin la app,
# o mostrarlo en una pantalla de obra) puede refrescarlo con lo capturado
# aquí importando este archivo, sin volver a capturar nada a mano. No
# gateado por _ensure_modulo_activo (a diferencia de los endpoints de
# escritura arriba) — mismo criterio que list_cimentacion_elementos/
# list_perforadoras, que tampoco lo gatean: es lectura, no captura.
_CONTROL_OBRA_ESTATUS_CODE = {"cambio_trayectoria": 0, "sin_iniciar": 1, "en_proceso": 2, "concluido": 3}


@api.get("/projects/{pid}/control-obra/export.xlsx")
async def export_control_obra_xlsx(pid: str, user: dict = Depends(current_user)):
    await ensure_project_access(user, pid)
    from openpyxl import Workbook

    nodes = await db.location_nodes.find({"project_id": pid}).to_list(length=10000)

    wb = Workbook()

    # --- Hoja POSTES ---
    ws1 = wb.active
    ws1.title = "POSTES"
    ws1.append([])
    ws1.append([None, None, 0, "En proceso cambio de trayectoria", None, None, 2, "En proceso", "SEMÁFORO DE AVANCE DE POSTES"])
    ws1.append([None, None, 1, "Sin iniciar", None, None, 3, "Concluido"])
    ws1.append([])
    campos = ["pilas", "cabezal", "fuste", "poste"]
    ws1.append([None, "POSTE", "Pilas", "Cabezal", "Fuste", "Poste"])
    ws1.append([None, None, "Estatus", "Estatus", "Estatus", "Estatus"])
    intertramos = sorted(
        (n for n in nodes if n.get("tipo_nodo") == "intertramo" and _acceso_predio_efectivo(n)),
        key=lambda n: (n.get("order", 0), n.get("name", "")),
    )
    for it in intertramos:
        ws1.append([None, it.get("name") or ""])
        postes = sorted(
            (n for n in nodes if n.get("parent_id") == it["id"]),
            key=lambda n: (n.get("order", 0), n.get("name", "")),
        )
        for p in postes:
            row = [None, p.get("name") or ""]
            for campo in campos:
                row.append(_CONTROL_OBRA_ESTATUS_CODE.get(p.get(f"estatus_{campo}"), 1))
            ws1.append(row)
    ws1.column_dimensions["A"].width = 2
    ws1.column_dimensions["B"].width = 22
    for col_letter in ("C", "D", "E", "F"):
        ws1.column_dimensions[col_letter].width = 11

    # --- Hoja CIMENTACION ---
    ws2 = wb.create_sheet("CIMENTACION")
    elementos = await db.cimentacion_elementos.find({"project_id": pid}).to_list(length=2000)
    elementos_by_node: dict = {}
    for e in elementos:
        elementos_by_node.setdefault(e["node_id"], []).append(e)
    estaciones = sorted(
        (n for n in nodes if _node_es_estacion_habilitada(n)),
        key=lambda n: (n.get("order", 0), n.get("name", "")),
    )
    for est in estaciones:
        els = elementos_by_node.get(est["id"]) or []
        if not els:
            continue
        ws2.append([None, None, None, est.get("name") or ""])
        ws2.append([None, None, None, "Elemento", "Total", "Acumulado Total", "En proceso", "% colado", "% por colar"])
        for el in els:
            total = el.get("total") or 0
            acum = el.get("acumulado_total") or 0
            pct = (acum / total) if total > 0 else 0
            ws2.append([None, None, None, el.get("elemento") or "", total, acum, el.get("en_proceso") or 0, pct, 1 - pct])
        ws2.append([])
    for col_letter, w in zip(("A", "B", "C", "D", "E", "F", "G", "H", "I"), (2, 2, 2, 16, 8, 16, 11, 10, 12)):
        ws2.column_dimensions[col_letter].width = w

    # --- Hoja PERFORADORAS ---
    ws3 = wb.create_sheet("PERFORADORAS")
    ws3.append([None, "RELACIÓN DE PERFORADORAS"])
    ws3.append([])
    ws3.append([None, "PERFORADORA", "SERIE", "UBICACIÓN", "ESTATUS"])
    perforadoras = await db.perforadoras.find({"project_id": pid}).to_list(length=500)
    for p in perforadoras:
        ws3.append([None, p.get("nombre") or "", p.get("serie") or "", p.get("ubicacion") or "", p.get("estatus") or ""])
    for col_letter, w in zip(("A", "B", "C", "D", "E"), (2, 26, 22, 16, 12)):
        ws3.column_dimensions[col_letter].width = w

    buf = io.BytesIO()
    wb.save(buf)
    buf.seek(0)
    stamp = datetime.now(timezone.utc).astimezone(MX_TZ).strftime("%Y-%m-%d_%H%M")
    return StreamingResponse(
        buf,
        media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        headers={"Content-Disposition": f'attachment; filename="control_obra_{stamp}.xlsx"'},
    )


# Registro de accidentes (módulo Seguridad e Higiene). Una fila = un renglón
# de la bitácora impresa: Fecha, Mes, Nombre del trabajador, Contratista,
# Registro (tipo), Ubicación, Descripción, Foto y Seguimiento.
SEGURIDAD_TIPOS = ("sin_accidentes", "dano_propiedad", "incidente", "accidente_leve", "incapacitante", "grave")
SEGURIDAD_TIPO_LABEL = {
    "sin_accidentes": "Sin accidentes",
    "dano_propiedad": "Daño a la propiedad",
    "incidente": "Incidente",
    "accidente_leve": "Accidente leve / primeros auxilios",
    "incapacitante": "Incapacitante",
    "grave": "Grave",
}
# `severidad` (leve/moderado/grave) es el campo ANTERIOR a este formato: se
# sigue guardando derivado del tipo para no romper consumidores viejos.
_SEGURIDAD_TIPO_A_SEVERIDAD = {
    "sin_accidentes": "leve", "dano_propiedad": "leve", "incidente": "leve",
    "accidente_leve": "leve", "incapacitante": "moderado", "grave": "grave",
}
_SEGURIDAD_MESES = ["Enero", "Febrero", "Marzo", "Abril", "Mayo", "Junio", "Julio", "Agosto",
                    "Septiembre", "Octubre", "Noviembre", "Diciembre"]


def _seguridad_mes(fecha: Optional[str]) -> str:
    """Nombre del mes (español) de una fecha ISO 'YYYY-MM-DD'; "" si no parsea."""
    try:
        return _SEGURIDAD_MESES[date.fromisoformat((fecha or "")[:10]).month - 1]
    except (ValueError, TypeError):
        return ""


def _seguridad_registro_label(doc: dict) -> str:
    """Etiqueta del tipo de registro. Los reportes anteriores a este formato
    solo tienen `severidad` (leve/moderado/grave): se muestra tal cual."""
    tipo = doc.get("tipo_registro")
    if tipo in SEGURIDAD_TIPO_LABEL:
        return SEGURIDAD_TIPO_LABEL[tipo]
    return (doc.get("severidad") or "").capitalize()


def _seguridad_clean(v: Optional[str], maxlen: int) -> Optional[str]:
    v = " ".join(str(v or "").split())[:maxlen]
    return v or None


def _seguridad_out(doc: dict) -> dict:
    """Documento listo para el cliente: agrega `mes` y `registro_label`
    (derivados, no se guardan)."""
    out = {k: v for k, v in doc.items() if k != "_id"}
    out["mes"] = _seguridad_mes(out.get("fecha"))
    out["registro_label"] = _seguridad_registro_label(out)
    return out


def _seguridad_validar_fecha(fecha: Optional[str]) -> str:
    if not fecha:
        return datetime.now(MX_TZ).date().isoformat()
    try:
        return _fecha_flexible(fecha).isoformat()
    except ValueError:
        raise HTTPException(400, "Fecha inválida: usa AAAA-MM-DD o DD/MM/AAAA")


class SeguridadReporteIn(BaseModel):
    node_id: Optional[str] = None
    fecha: Optional[str] = None  # ISO date; default = hoy
    trabajador: Optional[str] = None
    contratista: Optional[str] = None
    tipo_registro: Optional[Literal["sin_accidentes", "dano_propiedad", "incidente",
                                      "accidente_leve", "incapacitante", "grave"]] = None
    ubicacion: Optional[str] = None  # texto libre; si hay node_id se imprime la ruta del nodo
    descripcion: str = ""
    seguimiento: Optional[str] = None
    acciones_tomadas: Optional[str] = None  # legacy (formato anterior)
    severidad: Optional[Literal["leve", "moderado", "grave"]] = None  # legacy: se deriva del tipo
    images: List[str] = Field(default_factory=list)  # base64
    jerarquia: Optional[str] = None  # informe al que llega (ver JERARQUIAS_MODULO)


class SeguridadReportePatch(BaseModel):
    """Edición parcial — típicamente para ir agregando el Seguimiento."""
    fecha: Optional[str] = None
    trabajador: Optional[str] = None
    contratista: Optional[str] = None
    tipo_registro: Optional[Literal["sin_accidentes", "dano_propiedad", "incidente",
                                      "accidente_leve", "incapacitante", "grave"]] = None
    ubicacion: Optional[str] = None
    descripcion: Optional[str] = None
    seguimiento: Optional[str] = None
    images: Optional[List[str]] = None
    jerarquia: Optional[str] = None


@api.get("/projects/{pid}/seguridad-reportes")
async def list_seguridad_reportes(pid: str, user: dict = Depends(current_user)):
    await ensure_project_access(user, pid)
    cursor = db.seguridad_reportes.find({"project_id": pid}).sort("created_at", -1)
    items = await cursor.to_list(length=1000)
    return [_seguridad_out(it) for it in items]


@api.post("/projects/{pid}/seguridad-reportes")
async def create_seguridad_reporte(pid: str, body: SeguridadReporteIn, user: dict = Depends(current_user)):
    _assert_write_allowed(user)
    project = await ensure_project_access(user, pid)
    _ensure_modulo_activo(project, "seguridad_higiene")
    descripcion = body.descripcion.strip()
    # "Sin accidentes" es un renglón válido sin descripción (el día sin novedad).
    if not descripcion and body.tipo_registro != "sin_accidentes":
        raise HTTPException(400, "Descripción requerida")
    doc = {
        "id": str(uuid.uuid4()),
        "project_id": pid,
        "node_id": body.node_id,
        "fecha": _seguridad_validar_fecha(body.fecha) if body.fecha else (await hoy_de(pid)).isoformat(),
        "trabajador": _seguridad_clean(body.trabajador, 120),
        "contratista": _seguridad_clean(body.contratista, 120),
        "tipo_registro": body.tipo_registro,
        "ubicacion": _seguridad_clean(body.ubicacion, 200),
        "descripcion": descripcion,
        "seguimiento": _seguridad_clean(body.seguimiento, 2000),
        "acciones_tomadas": (body.acciones_tomadas or "").strip() or None,
        "severidad": (_SEGURIDAD_TIPO_A_SEVERIDAD[body.tipo_registro] if body.tipo_registro
                      else (body.severidad or "leve")),
        "jerarquia": _jerarquia_modulo(body.jerarquia),
        "images": await asyncio.to_thread(_normalize_images_b64, body.images[:10]),
        "captured_by": user["id"],
        "captured_by_name": user["name"],
        "created_at": datetime.now(timezone.utc),
    }
    await db.seguridad_reportes.insert_one(doc)
    return _seguridad_out(doc)


@api.patch("/projects/{pid}/seguridad-reportes/{rid}")
async def update_seguridad_reporte(pid: str, rid: str, body: SeguridadReportePatch,
                                   user: dict = Depends(current_user)):
    _assert_write_allowed(user)
    project = await ensure_project_access(user, pid)
    _ensure_modulo_activo(project, "seguridad_higiene")
    row = await db.seguridad_reportes.find_one({"id": rid, "project_id": pid})
    if not row:
        raise HTTPException(404, "Reporte no existe")
    upd: dict = {}
    if body.fecha is not None:
        upd["fecha"] = _seguridad_validar_fecha(body.fecha)
    for campo, maxlen in (("trabajador", 120), ("contratista", 120), ("ubicacion", 200), ("seguimiento", 2000)):
        valor = getattr(body, campo)
        if valor is not None:
            upd[campo] = _seguridad_clean(valor, maxlen)
    if body.tipo_registro is not None:
        upd["tipo_registro"] = body.tipo_registro
        upd["severidad"] = _SEGURIDAD_TIPO_A_SEVERIDAD[body.tipo_registro]
    if body.descripcion is not None:
        upd["descripcion"] = body.descripcion.strip()
    if body.images is not None:
        upd["images"] = await asyncio.to_thread(_normalize_images_b64, body.images[:10])
    if body.jerarquia is not None:
        upd["jerarquia"] = _jerarquia_modulo(body.jerarquia)
    tipo_final = upd.get("tipo_registro", row.get("tipo_registro"))
    if "descripcion" in upd and not upd["descripcion"] and tipo_final != "sin_accidentes":
        raise HTTPException(400, "Descripción requerida")
    if not upd:
        raise HTTPException(400, "Nada para actualizar")
    await db.seguridad_reportes.update_one({"id": rid}, {"$set": upd})
    return _seguridad_out({**row, **upd})


# === CRUZ DE SEGURIDAD =====================================================
# Tablero visual del mes: cada día es una casilla de una cruz (30 casillas) y
# se pinta según lo peor que pasó ese día — verde si no hubo accidentes, gris
# los días que aún no ocurren. Junto a la cruz van el resumen por tipo de
# accidente, la fuerza de trabajo promedio y la bitácora del año por mes.
CRUZ_TIPOS_ORDEN = ["sin_accidentes", "dano_propiedad", "incidente", "accidente_leve", "incapacitante", "grave"]
CRUZ_ABREV = {"sin_accidentes": "SA", "dano_propiedad": "DP", "incidente": "I",
              "accidente_leve": "PA", "incapacitante": "INCA", "grave": "GR"}
# Colores de la hoja de referencia (hex RRGGBB, sin #).
CRUZ_COLOR = {"sin_accidentes": "008040", "dano_propiedad": "6DC8E8", "incidente": "7030A0",
              "accidente_leve": "FFC000", "incapacitante": "ED7D31", "grave": "E0104A"}
CRUZ_COLOR_FUTURO = "A6A6A6"
# Etiqueta de la hoja de referencia por tipo (en mayúsculas, como se imprime).
CRUZ_LABEL = {"sin_accidentes": "SIN ACCIDENTES", "dano_propiedad": "DAÑO A LA PROPIEDAD",
              "incidente": "INCIDENTE", "accidente_leve": "ACCIDENTE LEVE / PRIMEROS AUXILIO",
              "incapacitante": "INCAPACITANTE", "grave": "GRAVE"}
_CRUZ_GRAVEDAD = {t: i for i, t in enumerate(CRUZ_TIPOS_ORDEN)}
_CRUZ_LEGACY = {"leve": "accidente_leve", "moderado": "incapacitante", "grave": "grave"}


def _seguridad_tipo_efectivo(doc: dict) -> str:
    """Tipo del registro; los reportes anteriores al formato solo traen
    `severidad` y se mapean (leve → accidente leve, moderado → incapacitante)."""
    tipo = doc.get("tipo_registro")
    if tipo in _CRUZ_GRAVEDAD:
        return tipo
    return _CRUZ_LEGACY.get(doc.get("severidad"), "accidente_leve")


def _cruz_layout(n_dias: int) -> List[tuple]:
    """Posición (día, fila, columna) de cada casilla de la cruz, en una
    cuadrícula de 9 columnas: brazo superior 3×2 (días 1-6), cuerpo 9×2
    (7-24) y brazo inferior de 3 de ancho (25-30, y el 31 debajo)."""
    bandas = [(range(1, 4), 3), (range(4, 7), 3), (range(7, 16), 0), (range(16, 25), 0),
              (range(25, 28), 3), (range(28, 31), 3), (range(31, 32), 3)]
    out: List[tuple] = []
    for fila, (dias, col0) in enumerate(bandas):
        for i, d in enumerate(dias):
            if d <= n_dias:
                out.append((d, fila, col0 + i))
    return out


def _cruz_calcular(registros: list, anio: int, mes: int, hoy: date, fuerza_trabajo: Optional[int] = None,
                   parametros: Optional[list] = None, fuerza_heredada: bool = False) -> dict:
    """Datos de la Cruz de Seguridad de un mes. Pura — sin Mongo.

    `registros`: documentos de `seguridad_reportes` (cualquier fecha; aquí se
    filtran). Cada día transcurrido es el peor tipo registrado ese día, o
    "sin_accidentes" si no hay nada; los días futuros quedan sin tipo (gris).
    El resumen cuenta REGISTROS por tipo (y, para "Sin accidentes", días
    laborables) y el porcentaje es sobre los DÍAS LABORABLES transcurridos del
    mes (lunes a sábado; no se descuentan festivos). `fuerza_trabajo` es el
    número de personal que se captura A MANO para el mes (incluye contratistas
    y demás frentes, no solo la plantilla dada de alta). La bitácora es el
    acumulado del AÑO, sin los renglones "Sin accidentes"."""
    import calendar
    n_dias = calendar.monthrange(anio, mes)[1]
    if (anio, mes) < (hoy.year, hoy.month):
        transcurridos = n_dias
    elif (anio, mes) == (hoy.year, hoy.month):
        transcurridos = hoy.day
    else:
        transcurridos = 0

    por_dia: Dict[int, str] = {}
    conteo = {t: 0 for t in CRUZ_TIPOS_ORDEN}
    bitacora = []
    for r in sorted(registros, key=lambda r: (r.get("fecha") or "", r.get("created_at") or "")):
        try:
            f = date.fromisoformat((r.get("fecha") or "")[:10])
        except ValueError:
            continue
        tipo = _seguridad_tipo_efectivo(r)
        if f.year == anio and tipo != "sin_accidentes":
            bitacora.append({
                "mes": _SEGURIDAD_MESES[f.month - 1], "mes_num": f.month,
                "trabajador": r.get("trabajador") or "", "contratista": r.get("contratista") or "",
                "tipo": tipo, "abrev": CRUZ_ABREV[tipo], "ubicacion": r.get("ubicacion") or "",
                "fecha": f.isoformat(), "descripcion": r.get("descripcion") or "",
            })
        if (f.year, f.month) == (anio, mes):
            if tipo != "sin_accidentes":
                conteo[tipo] += 1
            actual = por_dia.get(f.day)
            if actual is None or _CRUZ_GRAVEDAD[tipo] > _CRUZ_GRAVEDAD[actual]:
                por_dia[f.day] = tipo
    for i, b in enumerate(bitacora, 1):
        b["n"] = i

    dias = []
    for d, fila, col in _cruz_layout(n_dias):
        tipo = None if d > transcurridos else por_dia.get(d, "sin_accidentes")
        dias.append({"dia": d, "fila": fila, "col": col, "tipo": tipo})
    es_laborable = lambda d: date(anio, mes, d).weekday() != 6  # noqa: E731  (domingo no cuenta)
    laborables = sum(1 for d in range(1, transcurridos + 1) if es_laborable(d))
    conteo["sin_accidentes"] = sum(1 for x in dias if x["tipo"] == "sin_accidentes" and es_laborable(x["dia"]))

    def _pct(n):
        return round(100 * n / laborables) if laborables else 0

    return {
        "mes": f"{anio:04d}-{mes:02d}",
        "mes_label": f"{_SEGURIDAD_MESES[mes - 1]} {anio}",
        "dias_transcurridos": transcurridos,
        "dias_laborables": laborables,
        "dias": dias,
        "resumen": [{"tipo": t, "label": CRUZ_LABEL[t], "abrev": CRUZ_ABREV[t], "color": CRUZ_COLOR[t],
                     "cantidad": conteo[t], "porcentaje": _pct(conteo[t])} for t in CRUZ_TIPOS_ORDEN],
        "fuerza_trabajo": {"personal": fuerza_trabajo, **({"heredado": True} if fuerza_heredada else {})},
        "parametros": parametros or [],
        "registros": bitacora,
    }


def _cruz_parse_mes(mes: Optional[str]) -> tuple:
    """'YYYY-MM' → (año, mes); por omisión el mes actual (CDMX)."""
    if not mes:
        hoy = datetime.now(MX_TZ).date()
        return hoy.year, hoy.month
    try:
        anio, m = mes.split("-")
        anio, m = int(anio), int(m)
        if not (1 <= m <= 12 and 2000 <= anio <= 2200):
            raise ValueError
        return anio, m
    except ValueError:
        raise HTTPException(400, "mes debe tener el formato AAAA-MM")


SEGURIDAD_PARAMETROS_DEFAULT = [{"id": "banderilleros", "nombre": "Banderilleros"}]


async def _seguridad_parametros_def(pid: str) -> List[dict]:
    """Parámetros numéricos que Seguridad reporta cada mes (por omisión,
    banderilleros); los define el Coordinador General por proyecto."""
    proj = await db.projects.find_one({"id": pid}, {"seguridad_parametros": 1})
    lista = (proj or {}).get("seguridad_parametros")
    return lista if isinstance(lista, list) else [dict(p) for p in SEGURIDAD_PARAMETROS_DEFAULT]


async def _cruz_fetch(pid: str, mes: Optional[str]) -> dict:
    anio, m = _cruz_parse_mes(mes)
    mes_key = f"{anio:04d}-{m:02d}"
    registros = await db.seguridad_reportes.find({"project_id": pid}).to_list(length=20000)
    ft = await db.seguridad_fuerza_trabajo.find_one({"project_id": pid, "mes": mes_key})
    personal = (ft or {}).get("personal")
    heredado = False
    if personal is None:
        # Sin dato este mes: se muestra el último capturado (no hay que
        # volver a escribirlo cada mes); al editarlo se guarda para el mes.
        previo = await db.seguridad_fuerza_trabajo.find_one(
            {"project_id": pid, "mes": {"$lt": mes_key}, "personal": {"$ne": None}}, sort=[("mes", -1)])
        if previo:
            personal, heredado = previo.get("personal"), True
    valores = (ft or {}).get("parametros") or {}
    parametros = [{"id": p["id"], "nombre": p["nombre"], "valor": valores.get(p["id"])}
                  for p in await _seguridad_parametros_def(pid)]
    return _cruz_calcular(registros, anio, m, datetime.now(MX_TZ).date(), personal, parametros, heredado)


def _cruz_xlsx_bytes(data: dict, proyecto: str) -> bytes:
    """Hoja "CRUZ DE SEGURIDAD" con el formato de la referencia: banda de
    título, fuerza de trabajo y resumen por tipo a la izquierda, la cruz de
    casillas a la derecha y, debajo, la bitácora agrupada por mes."""
    from openpyxl import Workbook
    from openpyxl.styles import Alignment, Border, Font, PatternFill, Side
    from openpyxl.utils import get_column_letter

    wb = Workbook()
    ws = wb.active
    ws.title = "CRUZ DE SEGURIDAD"
    ws.sheet_view.showGridLines = False

    def fill(hex_):
        return PatternFill("solid", fgColor=hex_)

    thin = Side(style="thin", color="000000")
    box = Border(left=thin, right=thin, top=thin, bottom=thin)
    center = Alignment(horizontal="center", vertical="center", wrap_text=True)
    NAVY, MAROON, GRAY_HEAD, GRAY_ROW = "0A2342", "9B1D45", "595959", "BFBFBF"
    CLARO = {"dano_propiedad", "accidente_leve"}  # fondos claros → texto oscuro

    # Columnas: A..H bitácora/resumen · I separador · J..R cuadrícula de la cruz.
    for col, w in zip("ABCDEFGH", (5, 12, 32, 14, 9, 24, 13, 66)):
        ws.column_dimensions[col].width = w
    ws.column_dimensions["I"].width = 3
    for i in range(10, 19):
        ws.column_dimensions[get_column_letter(i)].width = 4.6

    ws.merge_cells("A1:R1")
    c = ws["A1"]
    c.value = "CRUZ DE SEGURIDAD"
    c.font = Font(bold=True, size=20, color="FFFFFF")
    c.fill = fill(NAVY)
    c.alignment = center
    ws.row_dimensions[1].height = 32
    ws.merge_cells("A2:R2")
    ws["A2"].value = f"{proyecto} · {data['mes_label']}"
    ws["A2"].alignment = center
    ws["A2"].font = Font(italic=True, size=11, color="595959")

    # Fuerza de trabajo promedio.
    ft = data["fuerza_trabajo"]
    ws["C4"].value = "Fuerza de Trabajo PROMEDIO"
    ws["C4"].font = Font(bold=True)
    ws["D4"].value = ft["personal"]
    ws["E4"].value = "personal"
    ws["E4"].font = Font(italic=True, size=9, color="595959")
    for ref in ("C4", "D4"):
        ws[ref].border = box
        ws[ref].alignment = center
    ws["D4"].font = Font(bold=True)

    ws.merge_cells("C5:F5")
    ws["C5"].value = "REGISTRO DE ACCIDENTES"
    ws["C5"].fill = fill(MAROON)
    ws["C5"].font = Font(color="FFFFFF")
    ws["C5"].alignment = center

    resumen = {r["tipo"]: r for r in data["resumen"]}
    sa = resumen["sin_accidentes"]
    ws["C6"].value = f"SIN ACCIDENTES ({sa['cantidad']} días laborables)"
    ws["C6"].fill = fill(CRUZ_COLOR["sin_accidentes"])
    ws["C6"].font = Font(color="FFFFFF")
    for ref, txt in (("D6", "TIPO ACCIDENTE"), ("E6", "CANTIDAD"), ("F6", "PORCENTAJE")):
        ws[ref].value = txt
        ws[ref].fill = fill(GRAY_HEAD)
        ws[ref].font = Font(bold=True, color="FFFFFF", size=9)
    for ref in ("C6", "D6", "E6", "F6"):
        ws[ref].alignment = center
        ws[ref].border = box
    ws.row_dimensions[6].height = 28
    for i, t in enumerate(CRUZ_TIPOS_ORDEN[1:]):
        row = 7 + i
        r = resumen[t]
        ws.cell(row, 3, r["label"]).fill = fill(CRUZ_COLOR[t])
        ws.cell(row, 3).font = Font(color="000000" if t in CLARO else "FFFFFF", size=10)
        ws.cell(row, 4, r["abrev"])
        ws.cell(row, 5, r["cantidad"])
        ws.cell(row, 6, f"{r['porcentaje']}%")
        for col in (3, 4, 5, 6):
            ws.cell(row, col).alignment = center
            ws.cell(row, col).border = box
        ws.row_dimensions[row].height = 26

    # La cruz.
    for d in data["dias"]:
        cell = ws.cell(4 + d["fila"], 10 + d["col"], d["dia"])
        color = CRUZ_COLOR_FUTURO if d["tipo"] is None else CRUZ_COLOR[d["tipo"]]
        cell.fill = fill(color)
        cell.font = Font(size=9, bold=True, color="000000" if d["tipo"] in CLARO or d["tipo"] is None else "FFFFFF")
        cell.alignment = center
        cell.border = Border(left=Side(style="thin", color="FFFFFF"), right=Side(style="thin", color="FFFFFF"),
                             top=Side(style="thin", color="FFFFFF"), bottom=Side(style="thin", color="FFFFFF"))

    # Bitácora del año, agrupada por mes.
    fila = 14
    for i, h in enumerate(("Nº", "Mes", "Nombre de trabajador", "Contratista", "Tipo", "Ubicación", "Fecha", "Descripción"), 1):
        c = ws.cell(fila, i, h)
        c.fill = fill(MAROON)
        c.font = Font(bold=True, color="FFFFFF")
        c.alignment = center
        c.border = box
    fila += 1
    mes_actual = None
    for b in data["registros"]:
        if b["mes_num"] != mes_actual:
            mes_actual = b["mes_num"]
            if b["mes_num"] != data["registros"][0]["mes_num"]:
                ws.merge_cells(start_row=fila, start_column=1, end_row=fila, end_column=8)
                ws.cell(fila, 1, b["mes"].upper()).alignment = center
                ws.cell(fila, 1).font = Font(bold=True)
                ws.cell(fila, 1).fill = fill(GRAY_ROW)
                fila += 1
        f = date.fromisoformat(b["fecha"])
        valores = (b["n"], b["mes"], b["trabajador"], b["contratista"], b["abrev"], b["ubicacion"],
                   f.strftime("%d/%m/%Y"), b["descripcion"])
        for i, v in enumerate(valores, 1):
            c = ws.cell(fila, i, v)
            c.alignment = center
            c.border = box
        fila += 1

    ws.page_setup.orientation = "landscape"
    ws.page_setup.fitToWidth = 1
    ws.page_setup.fitToHeight = 0
    ws.sheet_properties.pageSetUpPr.fitToPage = True
    if data.get("parametros"):
        wp = wb.create_sheet("PARÁMETROS")
        wp.append([f"Parámetros de Seguridad · {data['mes_label']}"])
        wp["A1"].font = Font(bold=True, size=12)
        wp.append(["Parámetro", "Valor"])
        for c in wp[2]:
            c.font = Font(bold=True)
        for p in data["parametros"]:
            wp.append([p["nombre"], p["valor"]])
        wp.column_dimensions["A"].width = 32
        wp.column_dimensions["B"].width = 12
    buf = io.BytesIO()
    wb.save(buf)
    return buf.getvalue()


@api.get("/projects/{pid}/seguridad-cruz")
async def get_seguridad_cruz(pid: str, mes: Optional[str] = Query(None, description="AAAA-MM; por omisión el mes actual"),
                             user: dict = Depends(current_user)):
    """Datos de la Cruz de Seguridad del mes (cruz, resumen por tipo, fuerza de
    trabajo promedio y bitácora del año)."""
    await ensure_project_access(user, pid)
    return await _cruz_fetch(pid, mes)


class SeguridadFuerzaTrabajoIn(BaseModel):
    mes: str  # AAAA-MM
    personal: Optional[int] = Field(None, ge=0, le=100000)  # None = sin dato


@api.put("/projects/{pid}/seguridad-cruz/fuerza-trabajo")
async def set_seguridad_fuerza_trabajo(pid: str, body: SeguridadFuerzaTrabajoIn,
                                       user: dict = Depends(current_user)):
    """Fuerza de trabajo PROMEDIO del mes (personal de todos los frentes y
    contratistas): un número que se captura directo, editable por cualquier
    rol con permiso de escritura. Devuelve la Cruz del mes ya recalculada."""
    _assert_write_allowed(user)
    project = await ensure_project_access(user, pid)
    _ensure_modulo_activo(project, "seguridad_higiene")
    anio, m = _cruz_parse_mes(body.mes)
    mes = f"{anio:04d}-{m:02d}"
    await db.seguridad_fuerza_trabajo.update_one(
        {"project_id": pid, "mes": mes},
        {"$set": {"personal": body.personal, "updated_by": user["id"], "updated_by_name": user["name"],
                  "updated_at": datetime.now(timezone.utc)},
         "$setOnInsert": {"id": str(uuid.uuid4())}},
        upsert=True,
    )
    return await _cruz_fetch(pid, mes)


class SeguridadParametroIn(BaseModel):
    id: Optional[str] = None
    nombre: str


class SeguridadParametrosIn(BaseModel):
    parametros: List[SeguridadParametroIn]


@api.get("/projects/{pid}/seguridad-parametros")
async def get_seguridad_parametros(pid: str, user: dict = Depends(current_user)):
    await ensure_project_access(user, pid)
    return {"parametros": await _seguridad_parametros_def(pid)}


@api.put("/projects/{pid}/seguridad-parametros")
async def put_seguridad_parametros(pid: str, body: SeguridadParametrosIn,
                                   user: dict = Depends(require_role(ROLE_COORD))):
    """El Coordinador General define qué parámetros reporta Seguridad (p. ej.
    banderilleros) y puede añadir más. Quitar uno solo lo oculta: los valores
    ya capturados se conservan en la base."""
    _assert_write_allowed(user)
    await ensure_project_access(user, pid)
    vistos, out = set(), []
    for p in body.parametros:
        nombre = (p.nombre or "").strip()
        if not nombre:
            continue
        if len(nombre) > 60:
            raise HTTPException(400, "Nombre máximo 60 caracteres")
        if nombre.lower() in vistos:
            raise HTTPException(400, f"Parámetro repetido: {nombre}")
        vistos.add(nombre.lower())
        out.append({"id": (p.id or "").strip() or uuid.uuid4().hex[:12], "nombre": nombre})
    if len(out) > 30:
        raise HTTPException(400, "Máximo 30 parámetros")
    await db.projects.update_one({"id": pid}, {"$set": {"seguridad_parametros": out}})
    return {"parametros": out}


class SeguridadParametrosValoresIn(BaseModel):
    mes: str  # AAAA-MM
    valores: Dict[str, Optional[int]]


@api.put("/projects/{pid}/seguridad-cruz/parametros")
async def set_seguridad_parametros_valores(pid: str, body: SeguridadParametrosValoresIn,
                                           user: dict = Depends(current_user)):
    """Valores del mes de los parámetros de Seguridad (p. ej. banderilleros)."""
    _assert_write_allowed(user)
    project = await ensure_project_access(user, pid)
    _ensure_modulo_activo(project, "seguridad_higiene")
    anio, m = _cruz_parse_mes(body.mes)
    validos = {p["id"] for p in await _seguridad_parametros_def(pid)}
    sets = {"updated_by": user["id"], "updated_by_name": user["name"], "updated_at": datetime.now(timezone.utc)}
    for pid_param, v in body.valores.items():
        if pid_param not in validos:
            raise HTTPException(400, "Parámetro desconocido")
        if v is not None and not (0 <= v <= 100000):
            raise HTTPException(400, "Valor fuera de rango")
        sets[f"parametros.{pid_param}"] = v
    await db.seguridad_fuerza_trabajo.update_one(
        {"project_id": pid, "mes": f"{anio:04d}-{m:02d}"},
        {"$set": sets, "$setOnInsert": {"id": str(uuid.uuid4())}},
        upsert=True,
    )
    return await _cruz_fetch(pid, f"{anio:04d}-{m:02d}")


@api.get("/projects/{pid}/seguridad-cruz.xlsx")
async def export_seguridad_cruz_xlsx(pid: str, mes: Optional[str] = Query(None, description="AAAA-MM"),
                                     user: dict = Depends(current_user)):
    """Exporta la Cruz de Seguridad a Excel, con el formato de la hoja de referencia."""
    project = await ensure_project_access(user, pid)
    data = await _cruz_fetch(pid, mes)
    xlsx = await asyncio.to_thread(_cruz_xlsx_bytes, data, project.get("name") or "Proyecto")
    fname = f"cruz_de_seguridad_{data['mes']}.xlsx"
    return StreamingResponse(
        io.BytesIO(xlsx),
        media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        headers={"Content-Disposition": f'attachment; filename="{fname}"'},
    )


