# === LOCATION NODES (Árbol Recursivo) =======================================
def _acceso_predio_efectivo(node: dict) -> bool:
    """Si nadie decidió explícitamente `acceso_predio_habilitado` para este
    nodo, el default histórico era "solo Subtramo" (depth==1) — antes
    estaba hardcodeado así en el frontend (AccesoPredioManager filtraba
    `depth === 1` a secas); ahora el Coordinador/Sub-Coordinador puede
    habilitarlo/deshabilitarlo nodo por nodo, a cualquier profundidad."""
    habilitado = node.get("acceso_predio_habilitado")
    return habilitado if habilitado is not None else (node.get("depth") == 1)


def _resolve_acceso_predio_node(subtramo_id: str, subtramo_node: dict, nodes_by_subtramo: dict) -> Optional[dict]:
    """Resuelve qué nodo representa el estatus de Acceso al Predio /
    Situación Social a IMPRIMIR para este Subtramo, respetando el toggle
    `acceso_predio_habilitado` (a cualquier profundidad, ver hub
    `AccesoPredioManager`). Antes el PDF/PPTX leían SIEMPRE el nodo Subtramo
    directo sin chequear si estaba habilitado — imprimían "Sin especificar"
    en TODOS los subtramos aunque en el hub solo estuvieran referenciadas/
    habilitadas unas partes del proyecto (logica rota).
    Prioridad: el propio Subtramo si está habilitado; si no, el primer nodo
    descendiente habilitado (p.ej. un Poste específico); si ninguno, None —
    la sección se omite por completo en la página impresa."""
    if _acceso_predio_efectivo(subtramo_node):
        return subtramo_node
    for n in nodes_by_subtramo.get(subtramo_id) or []:
        if n.get("id") == subtramo_id:
            continue
        if _acceso_predio_efectivo(n):
            return n
    return None


@api.get("/projects/{pid}/nodes")
async def list_nodes(pid: str, user: dict = Depends(current_user)):
    await ensure_project_access(user, pid)
    items = await db.location_nodes.find({"project_id": pid}).sort([("depth", 1), ("order", 1)]).to_list(length=10000)

    # --- FIX AMNESIA DE ESTADO: usar MAX(ultima_lectura) numérica, no SUM(avance) texto ---
    pipeline = [
        {"$match": {"project_id": pid, "ultima_lectura": {"$ne": None}}},
        {"$group": {"_id": "$node_id", "total_avance": {"$max": "$ultima_lectura"}}},
    ]
    aggr = await db.reports.aggregate(pipeline).to_list(length=10000)
    avances_dict = {doc["_id"]: float(doc.get("total_avance") or 0.0) for doc in aggr}
    # -------------------------------------------------------------------------------------

    # Sin filtro por scope: todos los roles ven el árbol completo del proyecto.
    for it in items:
        it.pop("_id", None)
        # Inyectamos el acumulado al nodo
        it["avance_actual"] = avances_dict.get(it["id"], 0.0)
        it["acceso_predio_efectivo"] = _acceso_predio_efectivo(it)

    return items


@api.get("/projects/{pid}/nodes/tree")
async def get_tree(pid: str, user: dict = Depends(current_user)):
    """Devuelve el árbol completo como estructura jerárquica."""
    await ensure_project_access(user, pid)
    items = await db.location_nodes.find({"project_id": pid}).sort([("depth", 1), ("order", 1)]).to_list(length=10000)
    
    # --- FIX AMNESIA DE ESTADO: usar MAX(ultima_lectura) numérica, no SUM(avance) texto ---
    pipeline = [
        {"$match": {"project_id": pid, "ultima_lectura": {"$ne": None}}},
        {"$group": {"_id": "$node_id", "total_avance": {"$max": "$ultima_lectura"}}},
    ]
    aggr = await db.reports.aggregate(pipeline).to_list(length=10000)
    avances_dict = {doc["_id"]: float(doc.get("total_avance") or 0.0) for doc in aggr}
    # -------------------------------------------------------------------------------------

    # Sin filtro por scope: todos los roles ven el árbol completo del proyecto.
    by_id = {}
    for it in items:
        it.pop("_id", None)
        # Inyectamos el acumulado al nodo antes de anidarlo
        it["avance_actual"] = avances_dict.get(it["id"], 0.0)
        it["children"] = []
        by_id[it["id"]] = it
        
    roots = []
    # Para sub-coord/especialista, "root" debe ser el primer nodo cuyo padre no está en el set filtrado
    for it in items:
        if it.get("parent_id") and it["parent_id"] in by_id:
            by_id[it["parent_id"]]["children"].append(it)
        else:
            roots.append(it)
    return roots


def validar_gps_nodo(lat: Optional[float], lon: Optional[float]) -> Tuple[Optional[float], Optional[float]]:
    """Valida la ubicación GPS de un nodo: ambos o ninguno, dentro de rango y finitos.
    Devuelve (lat, lon) o lanza ValueError con un mensaje legible en es-MX."""
    if lat is None and lon is None:
        return None, None
    if lat is None or lon is None:
        raise ValueError("La ubicación GPS necesita latitud y longitud juntas.")
    if not (math.isfinite(lat) and math.isfinite(lon)):
        raise ValueError("La ubicación GPS no es válida.")
    if not -90 <= lat <= 90:
        raise ValueError("La latitud debe estar entre -90 y 90 grados.")
    if not -180 <= lon <= 180:
        raise ValueError("La longitud debe estar entre -180 y 180 grados.")
    return float(lat), float(lon)


@api.post("/projects/{pid}/nodes")
async def create_node(pid: str, body: LocationNodeIn, user: dict = Depends(require_role(ROLE_COORD))):
    if body.project_id != pid:
        raise HTTPException(400, "project_id mismatch")
    try:
        gps_lat, gps_lon = validar_gps_nodo(body.gps_lat, body.gps_lon)
    except ValueError as e:
        raise HTTPException(400, str(e))
    await ensure_project_access(user, pid)
    parent = None
    depth = 0
    if body.parent_id:
        parent = await db.location_nodes.find_one({"id": body.parent_id, "project_id": pid})
        if not parent:
            raise HTTPException(404, "Nodo padre no existe")
        depth = parent["depth"] + 1
        # Si el padre era hoja, deja de serlo automáticamente.
        if parent.get("is_leaf"):
            await db.location_nodes.update_one(
                {"id": parent["id"]},
                {"$set": {"is_leaf": False, "measurement_type": None, "target_lat": None, "target_lon": None, "target_elev": None}},
            )
    if body.is_leaf and body.measurement_type not in MEASUREMENT_TYPES:
        raise HTTPException(400, "Nodos hoja requieren measurement_type válido")
    nid = str(uuid.uuid4())
    # Coordenadas objetivo: sólo aplican a hojas coord_latlon.
    is_coord_leaf = body.is_leaf and body.measurement_type == "coord_latlon"
    doc = {
        "id": nid,
        "project_id": pid,
        "parent_id": body.parent_id,
        "name": body.name.strip(),
        "depth": depth,
        "order": body.order,
        "is_leaf": body.is_leaf,
        "measurement_type": body.measurement_type if body.is_leaf else None,
        "target_lat": body.target_lat if is_coord_leaf else None,
        "target_lon": body.target_lon if is_coord_leaf else None,
        "target_elev": body.target_elev if is_coord_leaf else None,
        "gps_lat": gps_lat,
        "gps_lon": gps_lon,
        "acceso_predio": body.acceso_predio,
        "situacion_social": body.situacion_social,
        "tipo_nodo": body.tipo_nodo,
        "ubicacion": body.ubicacion,
        "estatus_pilas": body.estatus_pilas,
        "estatus_cabezal": body.estatus_cabezal,
        "estatus_fuste": body.estatus_fuste,
        "estatus_poste": body.estatus_poste,
        "created_at": datetime.now(timezone.utc),
    }
    await db.location_nodes.insert_one(doc)
    doc.pop("_id", None)
    return doc


class NodePatch(BaseModel):
    name: Optional[str] = None
    order: Optional[int] = None
    is_leaf: Optional[bool] = None
    measurement_type: Optional[Literal["coord_latlon", "cadenamiento", "eje", "nivel"]] = None
    target_lat: Optional[float] = None
    target_lon: Optional[float] = None
    target_elev: Optional[float] = None
    # Ubicación GPS real (ver LocationNodeIn). `quitar_gps=True` la borra (None = no tocar).
    gps_lat: Optional[float] = None
    gps_lon: Optional[float] = None
    quitar_gps: Optional[bool] = None
    acceso_predio: Optional[str] = None
    situacion_social: Optional[str] = None
    # None = no tocar (deja el default: antes fijo a "solo Subtramo,
    # depth==1"); True/False = decisión explícita de si ESTE nodo (a
    # cualquier profundidad) participa en Acceso al Predio.
    acceso_predio_habilitado: Optional[bool] = None
    # Ver mismos campos en LocationNodeIn — formato del resumen impreso
    # (Estación vs Intertramo) y datos de la tabla Actividad en Postes.
    tipo_nodo: Optional[Literal["estacion", "intertramo"]] = None
    ubicacion: Optional[str] = None
    estatus_pilas: Optional[Literal["sin_iniciar", "en_proceso", "concluido", "cambio_trayectoria"]] = None
    estatus_cabezal: Optional[Literal["sin_iniciar", "en_proceso", "concluido", "cambio_trayectoria"]] = None
    estatus_fuste: Optional[Literal["sin_iniciar", "en_proceso", "concluido", "cambio_trayectoria"]] = None
    estatus_poste: Optional[Literal["sin_iniciar", "en_proceso", "concluido", "cambio_trayectoria"]] = None


@api.patch("/nodes/{nid}")
async def update_node(nid: str, body: NodePatch, user: dict = Depends(require_role(ROLE_COORD, ROLE_SUB))):
    node = await db.location_nodes.find_one({"id": nid})
    if not node:
        raise HTTPException(404, "Nodo no existe")
    upd: dict = {}
    if body.name is not None:
        upd["name"] = body.name.strip()
    if body.order is not None:
        upd["order"] = body.order
    if body.is_leaf is not None:
        if body.is_leaf:
            # Para convertirse en hoja no debe tener hijos
            has_children = await db.location_nodes.find_one({"parent_id": nid})
            if has_children:
                raise HTTPException(400, "No se puede marcar como hoja: tiene hijos")
            if body.measurement_type not in MEASUREMENT_TYPES:
                raise HTTPException(400, "Hoja requiere measurement_type")
            upd["is_leaf"] = True
            upd["measurement_type"] = body.measurement_type
        else:
            upd["is_leaf"] = False
            upd["measurement_type"] = None
            upd["target_lat"] = None
            upd["target_lon"] = None
            upd["target_elev"] = None
    elif body.measurement_type is not None:
        if not node.get("is_leaf"):
            raise HTTPException(400, "measurement_type solo aplica a hojas")
        if body.measurement_type not in MEASUREMENT_TYPES:
            raise HTTPException(400, "measurement_type inválido")
        upd["measurement_type"] = body.measurement_type
        # Si cambia el tipo y deja de ser coord_latlon, limpia coords objetivo.
        if body.measurement_type != "coord_latlon":
            upd["target_lat"] = None
            upd["target_lon"] = None
            upd["target_elev"] = None
    # Coordenadas objetivo (sólo válidas en hojas coord_latlon — usar valor final).
    final_is_leaf = upd.get("is_leaf", node.get("is_leaf"))
    final_mtype = upd.get("measurement_type", node.get("measurement_type"))
    is_coord_leaf = bool(final_is_leaf and final_mtype == "coord_latlon")
    for fld, val in (("target_lat", body.target_lat), ("target_lon", body.target_lon), ("target_elev", body.target_elev)):
        if val is not None and is_coord_leaf:
            upd[fld] = val
    # Ubicación GPS: aplica a cualquier nodo y es independiente de target_*.
    if body.quitar_gps:
        upd["gps_lat"] = None
        upd["gps_lon"] = None
    elif body.gps_lat is not None or body.gps_lon is not None:
        try:
            upd["gps_lat"], upd["gps_lon"] = validar_gps_nodo(body.gps_lat, body.gps_lon)
        except ValueError as e:
            raise HTTPException(400, str(e))
    if body.acceso_predio is not None:
        upd["acceso_predio"] = body.acceso_predio.strip()
    if body.situacion_social is not None:
        upd["situacion_social"] = body.situacion_social.strip()
    if body.acceso_predio_habilitado is not None:
        upd["acceso_predio_habilitado"] = body.acceso_predio_habilitado
    if body.tipo_nodo is not None:
        upd["tipo_nodo"] = body.tipo_nodo
    if body.ubicacion is not None:
        upd["ubicacion"] = body.ubicacion.strip()
    if body.estatus_pilas is not None:
        upd["estatus_pilas"] = body.estatus_pilas
    if body.estatus_cabezal is not None:
        upd["estatus_cabezal"] = body.estatus_cabezal
    if body.estatus_fuste is not None:
        upd["estatus_fuste"] = body.estatus_fuste
    if body.estatus_poste is not None:
        upd["estatus_poste"] = body.estatus_poste
    if upd:
        await db.location_nodes.update_one({"id": nid}, {"$set": upd})
    out = await db.location_nodes.find_one({"id": nid})
    out.pop("_id", None)
    return out


# --- Estatus de Poste (Pilas/Cabezal/Fuste/Poste) — captura de campo ------
# `PATCH /nodes/{nid}` (arriba) exige Coordinador/Sub-Coordinador porque
# toca TODO el nodo (nombre, tipo, estructura). El módulo "Control de Obra"
# necesita que Especialista (presente en campo) también pueda ciclar el
# estatus de un poste sin poder tocar nada más del nodo — por eso este
# endpoint aparte, acotado a SOLO estos 4 campos, gateado por el módulo
# (mismo criterio que `upsert_weather_log`/`upsert_resource_log`).
class PosteEstatusPatch(BaseModel):
    estatus_pilas: Optional[Literal["sin_iniciar", "en_proceso", "concluido", "cambio_trayectoria"]] = None
    estatus_cabezal: Optional[Literal["sin_iniciar", "en_proceso", "concluido", "cambio_trayectoria"]] = None
    estatus_fuste: Optional[Literal["sin_iniciar", "en_proceso", "concluido", "cambio_trayectoria"]] = None
    estatus_poste: Optional[Literal["sin_iniciar", "en_proceso", "concluido", "cambio_trayectoria"]] = None


@api.patch("/nodes/{nid}/poste-estatus")
async def update_poste_estatus(nid: str, body: PosteEstatusPatch, user: dict = Depends(current_user)):
    _assert_write_allowed(user)
    node = await db.location_nodes.find_one({"id": nid})
    if not node:
        raise HTTPException(404, "Nodo no existe")
    project = await ensure_project_access(user, node["project_id"])
    _ensure_modulo_activo(project, "control_obra")
    upd: dict = {}
    for campo in ("estatus_pilas", "estatus_cabezal", "estatus_fuste", "estatus_poste"):
        val = getattr(body, campo)
        if val is not None:
            upd[campo] = val
    if upd:
        await db.location_nodes.update_one({"id": nid}, {"$set": upd})
    out = await db.location_nodes.find_one({"id": nid})
    out.pop("_id", None)
    return out


# --- Estatus por actividad de Poste (plantilla configurable, ver
# EtapaPosteElemento) — endpoint aparte de update_poste_estatus (arriba):
# ese sigue existiendo tal cual para Acceso al Predio y el resumen impreso,
# este es el detalle fino que consume el tab "Postes" de Control de Obra.
class PosteActividadEstatusPatch(BaseModel):
    actividad_key: str  # "Elemento::Actividad", debe existir en project.etapas_poste
    estatus: Literal["sin_iniciar", "en_proceso", "concluido", "cambio_trayectoria"]


@api.patch("/nodes/{nid}/poste-actividad-estatus")
async def update_poste_actividad_estatus(nid: str, body: PosteActividadEstatusPatch, user: dict = Depends(current_user)):
    _assert_write_allowed(user)
    node = await db.location_nodes.find_one({"id": nid})
    if not node:
        raise HTTPException(404, "Nodo no existe")
    project = await ensure_project_access(user, node["project_id"])
    _ensure_modulo_activo(project, "control_obra")

    etapas = etapas_poste_de(project)
    claves_validas = {f"{el['nombre']}::{act}" for el in etapas for act in el.get("actividades", [])}
    if body.actividad_key not in claves_validas:
        raise HTTPException(400, f"'{body.actividad_key}' no es una actividad configurada en la plantilla de este proyecto")

    # Dot-notation de Mongo para tocar SOLO esta clave del dict — nunca lee-
    # modifica-escribe el mapa completo, así que dos posteos concurrentes a
    # actividades distintas del mismo poste nunca se pisan entre sí.
    await db.location_nodes.update_one(
        {"id": nid},
        {"$set": {f"estatus_actividades.{body.actividad_key}": body.estatus}},
    )
    out = await db.location_nodes.find_one({"id": nid})
    out.pop("_id", None)
    return out


@api.delete("/nodes/{nid}")
async def delete_node(nid: str, user: dict = Depends(require_role(ROLE_COORD))):
    node = await db.location_nodes.find_one({"id": nid})
    if not node:
        raise HTTPException(404, "Nodo no existe")
    ids_to_delete = await descendants_ids(nid)
    await db.location_nodes.delete_many({"id": {"$in": ids_to_delete}})
    # NO borramos reportes huérfanos automáticamente (preservación). Marcar como huérfanos:
    await db.reports.update_many(
        {"node_id": {"$in": ids_to_delete}}, {"$set": {"node_orphan": True}}
    )
    return {"ok": True, "deleted_count": len(ids_to_delete)}


# === PORTADILLA POR NODO (cover_image) =====================================
# Se almacena como data URL base64 en el propio documento del nodo.
# Usado por el motor PDF para renderizar la "Portadilla de Nodo" dinámica:
#   fondo con color institucional + nombre del nodo (grande) + imagen incrustada.
_NODE_COVER_MIME = {"image/jpeg", "image/jpg", "image/png", "image/webp"}
_NODE_COVER_MAX_BYTES = 8 * 1024 * 1024  # 8 MB por portada


@api.post("/projects/{pid}/nodes/{nid}/cover")
async def upload_node_cover(
    pid: str,
    nid: str,
    file: UploadFile = File(...),
    user: dict = Depends(require_role(ROLE_COORD, ROLE_SUB)),
):
    """Sube (o reemplaza) la portada institucional de un nodo.
    Acepta JPG/PNG/WebP hasta 8 MB. Devuelve el nodo actualizado."""
    node = await db.location_nodes.find_one({"id": nid, "project_id": pid})
    if not node:
        raise HTTPException(404, "Nodo no existe")
    content_type = (file.content_type or "").lower()
    if content_type and content_type not in _NODE_COVER_MIME:
        raise HTTPException(415, f"Formato no soportado: {content_type}. Usa JPG/PNG/WebP.")
    raw = await file.read(_NODE_COVER_MAX_BYTES + 1)
    if len(raw) > _NODE_COVER_MAX_BYTES:
        raise HTTPException(413, f"Imagen demasiado grande (máx {_NODE_COVER_MAX_BYTES // (1024*1024)} MB).")
    # Serializar como data URL base64
    import base64 as _b64
    mime = content_type or "image/jpeg"
    b64_str = _b64.b64encode(raw).decode("ascii")
    data_url = f"data:{mime};base64,{b64_str}"
    await db.location_nodes.update_one({"id": nid}, {"$set": {"cover_image": data_url}})
    updated = await db.location_nodes.find_one({"id": nid})
    updated.pop("_id", None)
    return updated


@api.delete("/projects/{pid}/nodes/{nid}/cover")
async def delete_node_cover(
    pid: str,
    nid: str,
    user: dict = Depends(require_role(ROLE_COORD, ROLE_SUB)),
):
    """Elimina la portada institucional del nodo (vuelve a la portadilla genérica)."""
    node = await db.location_nodes.find_one({"id": nid, "project_id": pid})
    if not node:
        raise HTTPException(404, "Nodo no existe")
    await db.location_nodes.update_one({"id": nid}, {"$set": {"cover_image": None}})
    updated = await db.location_nodes.find_one({"id": nid})
    updated.pop("_id", None)
    return updated


# === FOTOS LIDAR (módulo: foto ORIGINAL vs foto ACTUAL por frente) ===========
# Un registro por frente/estación (o tema libre): dos fotos reemplazables
# independientemente — "original" (línea base, ej. el vuelo LiDAR inicial) y
# "actual" (la más reciente). Reemplazar una foto sobrescribe la anterior: solo
# importa el estado vigente (mismo criterio que Plano de Avance / Tabla
# Resumen), por eso el export NO filtra por período.
_FOTOS_LIDAR_SLOTS = ("original", "actual")
_FOTOS_LIDAR_MAX_RAW = 15 * 1024 * 1024


def _normalize_photo_b64(b64_str: str, max_dim: int = 1800, quality: int = 82) -> str:
    """Valida y normaliza una foto (base64 o data URL) a un data URL JPEG
    acotado a `max_dim` px por lado — mantiene cada documento Mongo muy por
    debajo del límite de 16 MB aun con dos fotos por registro. Bloqueante
    (CPU-bound): llamar vía asyncio.to_thread."""
    import base64 as _b64
    from PIL import Image as _PILImage
    from PIL.ImageOps import exif_transpose as _exif_transpose
    try:
        raw = _b64.b64decode(_strip_b64_prefix(b64_str))
    except Exception:
        raise HTTPException(400, "Imagen inválida (base64)")
    if not raw:
        raise HTTPException(400, "Imagen vacía")
    if len(raw) > _FOTOS_LIDAR_MAX_RAW:
        raise HTTPException(413, f"Imagen demasiado grande (máx {_FOTOS_LIDAR_MAX_RAW // (1024*1024)} MB).")
    try:
        img = _PILImage.open(io.BytesIO(raw))
        img = _exif_transpose(img) or img
        img = img.convert("RGB")
        img.thumbnail((max_dim, max_dim))
        out = io.BytesIO()
        img.save(out, format="JPEG", quality=quality, optimize=True)
    except Exception:
        raise HTTPException(400, "No se pudo leer la imagen (usa JPG/PNG/WebP)")
    return "data:image/jpeg;base64," + _b64.b64encode(out.getvalue()).decode("ascii")


def _png_bytes_to_jpeg_dataurl(png: bytes, max_dim: int = 2000, quality: int = 85) -> str:
    """PNG (p. ej. el snapshot de un plano) → data URL JPEG acotado — el
    export embebe imágenes de ~300 KB en vez de PNGs de decenas de MB.
    Bloqueante: llamar vía asyncio.to_thread."""
    import base64 as _b64
    from PIL import Image as _PILImage
    img = _PILImage.open(io.BytesIO(png)).convert("RGB")
    img.thumbnail((max_dim, max_dim))
    out = io.BytesIO()
    img.save(out, format="JPEG", quality=quality, optimize=True)
    return "data:image/jpeg;base64," + _b64.b64encode(out.getvalue()).decode("ascii")


def _fmt_iso_dmy(value: Optional[str]) -> str:
    """'2026-09-29' → '29/09/2026'; cualquier otra cosa se devuelve tal cual."""
    try:
        return date.fromisoformat(str(value)[:10]).strftime("%d/%m/%Y")
    except (ValueError, TypeError):
        return str(value or "")


def _fotos_lidar_etiqueta(base: str, fecha: Optional[str]) -> str:
    return f"{base} · {_fmt_iso_dmy(fecha)}" if fecha else base


def _foto_comp_etiqueta(it: dict, slot: str, base: str) -> str:
    """Etiqueta bajo cada foto de un bloque `fotos_comparativa`: la
    personalizada del item (ej. "TAPIAL" / "VUELO DRON") o, si no hay,
    ORIGINAL/ACTUAL con su fecha."""
    key = f"etiqueta_{slot}"
    if key in it:  # presente (aunque vacío) = el item decide; vacío → sin pie
        return it[key] or ""
    return _fotos_lidar_etiqueta(base, it.get(f"fecha_{slot}"))


def _foto_comp_desc(it: dict, slot: str) -> str:
    """Texto opcional ARRIBA de cada foto de un bloque `fotos_comparativa`
    (ej. "Actividades de control de calidad" + descripción)."""
    return (it.get(f"desc_{slot}") or "").strip()


class FotoLidarIn(BaseModel):
    titulo: str
    node_id: Optional[str] = None  # Estación/intertramo del árbol, si aplica
    orden: int = 0


class FotoLidarPatch(BaseModel):
    titulo: Optional[str] = None
    node_id: Optional[str] = None
    orden: Optional[int] = None


class FotoLidarFotoIn(BaseModel):
    image: str  # base64 / data URL
    fecha: Optional[str] = None  # ISO date de la toma; default = hoy (CDMX)


def _foto_lidar_public(doc: dict, *, with_images: bool) -> dict:
    out = {k: v for k, v in doc.items() if k != "_id"}
    out["tiene_original"] = bool(doc.get("foto_original"))
    out["tiene_actual"] = bool(doc.get("foto_actual"))
    if not with_images:
        out.pop("foto_original", None)
        out.pop("foto_actual", None)
    return out


