# === SUPERVISIÓN AMBIENTAL =================================================
# Sección "AMBIENTAL" del reporte semanal integral, TODA editable (nada fijo):
#  - informe: informes de cumplimiento (trimestral/semestral...) con su % de
#    avance y fecha de cierre → donas.
#  - autorizacion: oficios / acuerdos / MIA que amparan la intervención.
#  - arbolado: un grupo por autorización o afectación (ej. "MIA-E", "Nueva
#    afectación, en proceso de autorización") con podas/trasplantes/derribos
#    AUTORIZADOS y EJECUTADOS → donas "39 / 143".
#  - resarcimiento: plantaciones de reposición (lugar, cantidad, foto, pie).
#  - avance_estudio: "TABLA RESUMEN GENERAL" (actividad + % de avance).
# Más una configuración por proyecto: la resolución/referencia de las medidas
# y el total de árboles a restituir. Una sola colección (`ambiental`, campo
# `seccion`) y un CRUD genérico; el export arma bloques `imagen`/`table`/
# `fotos_comparativa` que los 3 motores ya dibujan.
_AMBIENTAL_SECCIONES = {
    "informe": {"req": "nombre", "textos": ("nombre",), "numeros": ("avance",), "fechas": ("fecha_cierre",)},
    "autorizacion": {"req": "folio", "textos": ("tipo", "folio")},
    "arbolado": {"req": "nombre", "textos": ("nombre",),
                 "enteros": ("poda_aut", "trasplante_aut", "derribo_aut", "poda_ej", "trasplante_ej", "derribo_ej")},
    "resarcimiento": {"req": "lugar", "textos": ("lugar", "pie"), "enteros": ("cantidad",), "foto": True},
    "avance_estudio": {"req": "actividad", "textos": ("actividad",), "numeros": ("avance",)},
}
_AMBIENTAL_ROTULO = {
    "nombre": "El nombre", "folio": "El folio", "lugar": "El lugar", "actividad": "La actividad",
    "avance": "El avance", "fecha_cierre": "La fecha de cierre", "cantidad": "La cantidad",
}


class _AmbientalCampos(BaseModel):
    nombre: Optional[str] = None
    tipo: Optional[str] = None
    folio: Optional[str] = None
    lugar: Optional[str] = None
    pie: Optional[str] = None
    actividad: Optional[str] = None
    avance: Optional[float] = None
    fecha_cierre: Optional[str] = None
    cantidad: Optional[int] = None
    poda_aut: Optional[int] = None
    trasplante_aut: Optional[int] = None
    derribo_aut: Optional[int] = None
    poda_ej: Optional[int] = None
    trasplante_ej: Optional[int] = None
    derribo_ej: Optional[int] = None
    orden: Optional[int] = None
    image: Optional[str] = None  # resarcimiento: foto (base64 / data URL)


class AmbientalIn(_AmbientalCampos):
    seccion: Literal["informe", "autorizacion", "arbolado", "resarcimiento", "avance_estudio"]


class AmbientalPatch(_AmbientalCampos):
    pass


class AmbientalConfigIn(BaseModel):
    referencia: Optional[str] = None  # resolución / acuerdo de las medidas de impacto ambiental
    total_a_restituir: Optional[int] = None


def _ambiental_normalizar(seccion: str, fields: dict) -> dict:
    """Valida y limpia SOLO los campos de la sección que vengan en `fields`."""
    spec = _AMBIENTAL_SECCIONES[seccion]
    upd: dict = {}
    for campo in spec.get("textos", ()):
        if campo in fields:
            upd[campo] = (fields[campo] or "").strip() or None
    for campo in spec.get("numeros", ()):
        if campo in fields:
            v = fields[campo]
            if v is not None and not (0 <= v <= 100):
                raise HTTPException(400, f"{_AMBIENTAL_ROTULO.get(campo, campo)} debe estar entre 0 y 100")
            upd[campo] = None if v is None else round(float(v), 2)
    for campo in spec.get("enteros", ()):
        if campo in fields:
            v = fields[campo]
            if v is not None and v < 0:
                raise HTTPException(400, f"{_AMBIENTAL_ROTULO.get(campo, campo)} no puede ser negativa")
            upd[campo] = v
    for campo in spec.get("fechas", ()):
        if campo in fields:
            v = (fields[campo] or "").strip()
            if not v:
                upd[campo] = None
                continue
            try:
                upd[campo] = _fecha_flexible(v).isoformat()
            except ValueError:
                raise HTTPException(400, f"{_AMBIENTAL_ROTULO.get(campo, campo)} inválida: usa AAAA-MM-DD o DD/MM/AAAA")
    if "orden" in fields and fields["orden"] is not None:
        upd["orden"] = fields["orden"]
    return upd


def _ambiental_public(doc: dict) -> dict:
    return {k: v for k, v in doc.items() if k not in ("_id", "foto")}


@api.get("/projects/{pid}/ambiental")
async def list_ambiental(pid: str, user: dict = Depends(current_user)):
    await ensure_project_access(user, pid)
    cursor = db.ambiental.find({"project_id": pid}, {"foto": 0}).sort([("seccion", 1), ("orden", 1), ("created_at", 1)])
    cfg = await db.ambiental_config.find_one({"project_id": pid}) or {}
    return {"items": [_ambiental_public(d) for d in await cursor.to_list(length=2000)],
            "config": {"referencia": cfg.get("referencia"), "total_a_restituir": cfg.get("total_a_restituir")}}


@api.put("/projects/{pid}/ambiental-config")
async def set_ambiental_config(pid: str, body: AmbientalConfigIn, user: dict = Depends(current_user)):
    _assert_write_allowed(user)
    project = await ensure_project_access(user, pid)
    _ensure_modulo_activo(project, "supervision_ambiental")
    fields = body.model_dump(exclude_unset=True)
    upd: dict = {}
    if "referencia" in fields:
        upd["referencia"] = (fields["referencia"] or "").strip() or None
    if "total_a_restituir" in fields:
        t = fields["total_a_restituir"]
        if t is not None and t < 0:
            raise HTTPException(400, "El total a restituir no puede ser negativo")
        upd["total_a_restituir"] = t
    if upd:
        await db.ambiental_config.update_one({"project_id": pid}, {"$set": upd}, upsert=True)
    cfg = await db.ambiental_config.find_one({"project_id": pid}) or {}
    return {"referencia": cfg.get("referencia"), "total_a_restituir": cfg.get("total_a_restituir")}


@api.post("/projects/{pid}/ambiental")
async def create_ambiental(pid: str, body: AmbientalIn, user: dict = Depends(current_user)):
    _assert_write_allowed(user)
    project = await ensure_project_access(user, pid)
    _ensure_modulo_activo(project, "supervision_ambiental")
    spec = _AMBIENTAL_SECCIONES[body.seccion]
    fields = body.model_dump(exclude_unset=True)
    doc = {"id": str(uuid.uuid4()), "project_id": pid, "seccion": body.seccion}
    doc.update(_ambiental_normalizar(body.seccion, fields))
    if not doc.get(spec["req"]):
        raise HTTPException(400, f"{_AMBIENTAL_ROTULO.get(spec['req'], spec['req'])} es obligatorio")
    if "orden" not in doc:
        ultimo = await db.ambiental.find({"project_id": pid, "seccion": body.seccion}, {"orden": 1}).sort("orden", -1).limit(1).to_list(length=1)
        doc["orden"] = (ultimo[0].get("orden") or 0) + 1 if ultimo else 1
    if spec.get("foto") and body.image:
        doc["foto"] = await asyncio.to_thread(_normalize_photo_b64, body.image)
        doc["thumb"] = await asyncio.to_thread(_compress_image_b64, doc["foto"])
    now = datetime.now(timezone.utc)
    doc.update({"created_by": user["id"], "created_by_name": user["name"], "created_at": now, "updated_at": now})
    await db.ambiental.insert_one(doc)
    return _ambiental_public(doc)


@api.patch("/projects/{pid}/ambiental/{rid}")
async def update_ambiental(pid: str, rid: str, body: AmbientalPatch, user: dict = Depends(current_user)):
    _assert_write_allowed(user)
    project = await ensure_project_access(user, pid)
    _ensure_modulo_activo(project, "supervision_ambiental")
    doc = await db.ambiental.find_one({"id": rid, "project_id": pid}, {"foto": 0, "thumb": 0})
    if not doc:
        raise HTTPException(404, "Registro no existe")
    spec = _AMBIENTAL_SECCIONES[doc["seccion"]]
    fields = body.model_dump(exclude_unset=True)
    upd = _ambiental_normalizar(doc["seccion"], fields)
    if spec["req"] in upd and not upd[spec["req"]]:
        raise HTTPException(400, f"{_AMBIENTAL_ROTULO.get(spec['req'], spec['req'])} es obligatorio")
    if spec.get("foto") and fields.get("image"):
        upd["foto"] = await asyncio.to_thread(_normalize_photo_b64, fields["image"])
        upd["thumb"] = await asyncio.to_thread(_compress_image_b64, upd["foto"])
    if upd:
        upd["updated_at"] = datetime.now(timezone.utc)
        await db.ambiental.update_one({"id": rid}, {"$set": upd})
    return _ambiental_public(await db.ambiental.find_one({"id": rid}))


@api.delete("/projects/{pid}/ambiental/{rid}")
async def delete_ambiental(pid: str, rid: str, user: dict = Depends(current_user)):
    """Coordinador/Sub-Coordinador borran cualquiera; el resto solo lo suyo."""
    _assert_write_allowed(user)
    await ensure_project_access(user, pid)
    doc = await db.ambiental.find_one({"id": rid, "project_id": pid}, {"created_by": 1})
    if not doc:
        raise HTTPException(404, "Registro no existe")
    if user.get("role") not in (ROLE_COORD, ROLE_SUB) and doc.get("created_by") != user["id"]:
        raise HTTPException(403, "Solo puedes eliminar los registros que tú capturaste")
    await db.ambiental.delete_one({"id": rid, "project_id": pid})
    return {"ok": True}


def _fecha_larga_es(iso: Optional[str]) -> str:
    """'2026-09-17' → '17 de septiembre de 2026'."""
    try:
        d = date.fromisoformat((iso or "")[:10])
    except ValueError:
        return iso or "-"
    return f"{d.day} de {_SEGURIDAD_MESES[d.month - 1].lower()} de {d.year}"


def _fmt_pct_amb(v) -> str:
    return f"{float(v):g}%"


async def _ambiental_bloques(items: List[dict], config: dict) -> List[dict]:
    """Bloques de la sección SUPERVISIÓN AMBIENTAL a partir de lo capturado.
    Una sección vacía no imprime nada; sin ningún dato → []."""
    por = {sec: sorted((i for i in items if i.get("seccion") == sec),
                       key=lambda i: (i.get("orden") or 0, str(i.get("created_at") or "")))
           for sec in _AMBIENTAL_SECCIONES}
    bloques: List[dict] = []

    async def _donas(titulo: str, filas: List[tuple], detalles: List[str]) -> str:
        it = iter(detalles)
        png = await asyncio.to_thread(_grafica_donas_png, titulo, filas, lambda r, t: next(it))
        return await asyncio.to_thread(_png_bytes_to_jpeg_dataurl, png)

    informes = por["informe"]
    for i in range(0, len(informes), 4):
        trozo = informes[i:i + 4]
        filas = [(r["nombre"], float(r.get("avance") or 0), 100) for r in trozo]
        detalles = [("Fecha de cierre: " + _fecha_larga_es(r["fecha_cierre"])) if r.get("fecha_cierre") else "" for r in trozo]
        bloques.append({
            "type": "imagen",
            "heading": "SEGUIMIENTO AL CUMPLIMIENTO DE LAS MEDIDAS DE IMPACTO AMBIENTAL" if i == 0 else None,
            "imagen": await _donas("Avance de informes", filas, detalles),
            "caption": (config.get("referencia") or "") if i == 0 else "",
        })
    if por["autorizacion"]:
        bloques.append({
            "type": "table", "heading": "INTERVENCIÓN DE ARBOLADO – AUTORIZACIONES",
            "headers": ["TIPO", "FOLIO / OFICIO"],
            "rows": [[r.get("tipo") or "-", r["folio"]] for r in por["autorizacion"]],
            "col_widths": [0.35, 0.65], "empty_text": "Sin autorizaciones.",
        })
    for g in por["arbolado"]:
        filas = [(rot, g.get(f"{k}_ej") or 0, g.get(f"{k}_aut") or 0)
                 for rot, k in (("PODAS", "poda"), ("TRASPLANTES", "trasplante"), ("DERRIBOS", "derribo"))]
        detalles = [f"{ej} / {aut}" for _, ej, aut in filas]
        bloques.append({
            "type": "imagen", "heading": f"INTERVENCIÓN DE ARBOLADO · {g['nombre'].upper()}",
            "imagen": await _donas(g["nombre"], filas, detalles),
            "caption": "Ejecutado / autorizado",
        })
    resarc = por["resarcimiento"]
    if resarc:
        restituidos = sum(r.get("cantidad") or 0 for r in resarc)
        a_restituir = config.get("total_a_restituir")
        bloques.append({
            "type": "table", "heading": "RESARCIMIENTO DE ARBOLADO",
            "headers": ["PLANTACIÓN", "CANTIDAD"],
            "rows": [[r["lugar"], str(r.get("cantidad") if r.get("cantidad") is not None else "-")] for r in resarc],
            "col_widths": [0.8, 0.2], "empty_text": "Sin plantaciones.",
        })
        bloques.append({
            "type": "summary",
            "text": (f"Total a restituir: {a_restituir} · " if a_restituir is not None else "") + f"Total restituidos: {restituidos}",
        })
        con_foto = [r for r in resarc if r.get("foto")]
        pares = []
        for i in range(0, len(con_foto), 2):
            a = con_foto[i]
            b = con_foto[i + 1] if i + 1 < len(con_foto) else None
            pares.append({
                "titulo": "RESARCIMIENTO DE ARBOLADO", "original": a["foto"], "actual": b["foto"] if b else None,
                "desc_encabezado": "RESARCIMIENTO DE ARBOLADO",
                "desc_original": a["lugar"], "desc_actual": (b or {}).get("lugar") or "",
                "etiqueta_original": a.get("pie") or "", "etiqueta_actual": (b or {}).get("pie") or "",
                "sin_placeholder": True,
            })
        if pares:
            bloques.append({"type": "fotos_comparativa", "items": pares})
    if por["avance_estudio"]:
        bloques.append({
            "type": "table", "heading": "TABLA RESUMEN GENERAL", "headers": ["ACTIVIDAD", "AVANCE SEMANAL (%)"],
            "rows": [[r["actividad"], _fmt_pct_amb(r["avance"]) if r.get("avance") is not None else "-"]
                     for r in por["avance_estudio"]],
            "col_widths": [0.75, 0.25], "empty_text": "Sin actividades.",
        })
    return bloques


# === ACTIVIDADES PARTICULARES ==============================================
# "ACTIVIDADES DESGLOSADAS" de cada estación/intertramo en el reporte semanal
# integral: lo que la supervisión hizo en ese punto, ordenado por CATEGORÍA
# (Estudios y análisis, Proyecto ejecutivo, Obras inducidas...) y
# SUBCATEGORÍA (Mecánica de suelos, Topografía...). El catálogo de categorías
# es EDITABLE por proyecto (`act_part_cat`; hay una carga de sugeridas, las del
# reporte de referencia, que se pueden cambiar/quitar/ampliar). Cada registro
# (`actividades_particulares`) es UNA viñeta: estación + categoría +
# subcategoría + texto + fecha. El export imprime una tabla por estación con
# TODAS las categorías del catálogo; las que no tuvieron registros dicen
# "Sin actividades ésta semana".
ACT_PART_SUGERIDAS = [
    ("ESTUDIOS Y ANÁLISIS", ["Mecánica de Suelos", "Topografía", "Hidrológico",
                             "Levantamiento de instalaciones municipales (OI)", "Movilidad", "Ambiental", "Urbano", "Riesgos"]),
    ("PROYECTO EJECUTIVO", ["General", "Proyecto Arquitectónico", "Proyecto Estructural", "Proyecto Geotécnico", "Señalización de Obra"]),
    ("OBRAS INDUCIDAS", []),
    ("COADYUVAR EN LA LIBERACIÓN DEL DERECHO DE VÍA", ["Atención de vecinos"]),
    ("CONSTRUCCIÓN DE OBRA CIVIL", []),
    ("SISTEMA ELECTROMECÁNICO", []),
    ("ACABADOS E INSTALACIONES", []),
    ("INSTALACIONES ESPECIALES", []),
    ("CERTIFICACIÓN", []),
]
ACT_PART_SIN_ACTIVIDAD = "Sin actividades ésta semana"


def _act_part_subcats(valores) -> List[str]:
    out: List[str] = []
    for v in (valores or []):
        t = str(v or "").strip()[:120]
        if t and t not in out:
            out.append(t)
    return out[:60]


class ActPartCatIn(BaseModel):
    nombre: str
    subcategorias: List[str] = Field(default_factory=list)
    orden: Optional[int] = None


class ActPartCatPatch(BaseModel):
    nombre: Optional[str] = None
    subcategorias: Optional[List[str]] = None
    orden: Optional[int] = None


class ActPartIn(BaseModel):
    node_id: str
    categoria_id: str
    subcategoria: Optional[str] = None
    texto: str
    fecha: Optional[str] = None
    jerarquia: Optional[str] = None  # informe al que llega (ver JERARQUIAS_MODULO)


class ActPartPatch(BaseModel):
    node_id: Optional[str] = None
    categoria_id: Optional[str] = None
    subcategoria: Optional[str] = None
    texto: Optional[str] = None
    fecha: Optional[str] = None
    jerarquia: Optional[str] = None


def _act_part_public(doc: dict) -> dict:
    return {k: v for k, v in doc.items() if k != "_id"}


@api.get("/projects/{pid}/actividades-particulares/catalogo")
async def list_act_part_cat(pid: str, user: dict = Depends(current_user)):
    await ensure_project_access(user, pid)
    items = await db.act_part_cat.find({"project_id": pid}).sort("orden", 1).to_list(length=200)
    return [_act_part_public(d) for d in items]


@api.post("/projects/{pid}/actividades-particulares/catalogo")
async def create_act_part_cat(pid: str, body: ActPartCatIn, user: dict = Depends(require_role(ROLE_COORD, ROLE_SUB))):
    project = await ensure_project_access(user, pid)
    _ensure_modulo_activo(project, "actividades_particulares")
    nombre = body.nombre.strip()
    if not nombre:
        raise HTTPException(400, "El nombre de la categoría es obligatorio")
    if await db.act_part_cat.find_one({"project_id": pid, "nombre": nombre}, {"id": 1}):
        raise HTTPException(409, "Ya existe una categoría con ese nombre")
    ultimo = await db.act_part_cat.find({"project_id": pid}, {"orden": 1}).sort("orden", -1).limit(1).to_list(length=1)
    doc = {"id": str(uuid.uuid4()), "project_id": pid, "nombre": nombre,
           "subcategorias": _act_part_subcats(body.subcategorias),
           "orden": body.orden if body.orden is not None else ((ultimo[0].get("orden") or 0) + 1 if ultimo else 1),
           "created_at": datetime.now(timezone.utc)}
    await db.act_part_cat.insert_one(doc)
    return _act_part_public(doc)


@api.post("/projects/{pid}/actividades-particulares/catalogo/sugeridas")
async def cargar_act_part_sugeridas(pid: str, user: dict = Depends(require_role(ROLE_COORD, ROLE_SUB))):
    """Agrega las categorías del reporte de referencia que aún no existan (por
    nombre). No toca ni borra nada de lo ya capturado/editado."""
    project = await ensure_project_access(user, pid)
    _ensure_modulo_activo(project, "actividades_particulares")
    existentes = {d["nombre"] async for d in db.act_part_cat.find({"project_id": pid}, {"nombre": 1})}
    ultimo = await db.act_part_cat.find({"project_id": pid}, {"orden": 1}).sort("orden", -1).limit(1).to_list(length=1)
    orden = (ultimo[0].get("orden") or 0) if ultimo else 0
    nuevas = 0
    for nombre, subs in ACT_PART_SUGERIDAS:
        if nombre in existentes:
            continue
        orden += 1
        nuevas += 1
        await db.act_part_cat.insert_one({"id": str(uuid.uuid4()), "project_id": pid, "nombre": nombre,
                                          "subcategorias": list(subs), "orden": orden, "created_at": datetime.now(timezone.utc)})
    items = await db.act_part_cat.find({"project_id": pid}).sort("orden", 1).to_list(length=200)
    return {"agregadas": nuevas, "items": [_act_part_public(d) for d in items]}


@api.patch("/projects/{pid}/actividades-particulares/catalogo/{cid}")
async def update_act_part_cat(pid: str, cid: str, body: ActPartCatPatch, user: dict = Depends(require_role(ROLE_COORD, ROLE_SUB))):
    project = await ensure_project_access(user, pid)
    _ensure_modulo_activo(project, "actividades_particulares")
    doc = await db.act_part_cat.find_one({"id": cid, "project_id": pid})
    if not doc:
        raise HTTPException(404, "Categoría no existe")
    fields = body.model_dump(exclude_unset=True)
    upd: dict = {}
    if "nombre" in fields:
        nombre = (fields["nombre"] or "").strip()
        if not nombre:
            raise HTTPException(400, "El nombre de la categoría es obligatorio")
        if nombre != doc["nombre"] and await db.act_part_cat.find_one({"project_id": pid, "nombre": nombre}, {"id": 1}):
            raise HTTPException(409, "Ya existe una categoría con ese nombre")
        upd["nombre"] = nombre
    if "subcategorias" in fields and fields["subcategorias"] is not None:
        upd["subcategorias"] = _act_part_subcats(fields["subcategorias"])
    if fields.get("orden") is not None:
        upd["orden"] = fields["orden"]
    if upd:
        await db.act_part_cat.update_one({"id": cid}, {"$set": upd})
        if "nombre" in upd:  # los registros guardan el nombre vigente de su categoría
            await db.actividades_particulares.update_many({"project_id": pid, "categoria_id": cid},
                                                          {"$set": {"categoria_nombre": upd["nombre"]}})
    return _act_part_public(await db.act_part_cat.find_one({"id": cid}))


@api.delete("/projects/{pid}/actividades-particulares/catalogo/{cid}")
async def delete_act_part_cat(pid: str, cid: str, user: dict = Depends(require_role(ROLE_COORD, ROLE_SUB))):
    await ensure_project_access(user, pid)
    if not await db.act_part_cat.find_one({"id": cid, "project_id": pid}, {"id": 1}):
        raise HTTPException(404, "Categoría no existe")
    usados = await db.actividades_particulares.count_documents({"project_id": pid, "categoria_id": cid})
    if usados:
        raise HTTPException(409, f"La categoría tiene {usados} actividad(es) capturada(s): cámbialas de categoría o elimínalas primero")
    await db.act_part_cat.delete_one({"id": cid, "project_id": pid})
    return {"ok": True}


async def _act_part_validar(pid: str, node_id: Optional[str], categoria_id: Optional[str]) -> Optional[dict]:
    if node_id is not None:
        await _validate_node_in_project(pid, node_id)
    if categoria_id is not None:
        cat = await db.act_part_cat.find_one({"id": categoria_id, "project_id": pid})
        if not cat:
            raise HTTPException(400, "La categoría no existe en este proyecto")
        return cat
    return None


@api.get("/projects/{pid}/actividades-particulares")
async def list_act_part(pid: str, desde: Optional[str] = None, hasta: Optional[str] = None,
                        node_id: Optional[str] = None, user: dict = Depends(current_user)):
    await ensure_project_access(user, pid)
    q: dict = {"project_id": pid}
    rango: dict = {}
    for clave, valor in (("$gte", desde), ("$lte", hasta)):
        if valor:
            rango[clave] = _prueba_calidad_fecha(valor)
    if rango:
        q["fecha"] = rango
    if node_id:
        q["node_id"] = node_id
    items = await db.actividades_particulares.find(q).sort([("fecha", -1), ("created_at", -1)]).to_list(length=3000)
    return [_act_part_public(d) for d in items]


@api.post("/projects/{pid}/actividades-particulares")
async def create_act_part(pid: str, body: ActPartIn, user: dict = Depends(current_user)):
    _assert_write_allowed(user)
    project = await ensure_project_access(user, pid)
    _ensure_modulo_activo(project, "actividades_particulares")
    texto = body.texto.strip()
    if not texto:
        raise HTTPException(400, "Escribe la actividad realizada")
    cat = await _act_part_validar(pid, body.node_id, body.categoria_id)
    now = datetime.now(timezone.utc)
    doc = {"id": str(uuid.uuid4()), "project_id": pid, "node_id": body.node_id, "categoria_id": body.categoria_id,
           "categoria_nombre": cat["nombre"], "subcategoria": (body.subcategoria or "").strip() or None,
           "texto": texto, "fecha": _prueba_calidad_fecha(body.fecha),
           "jerarquia": _jerarquia_modulo(body.jerarquia),
           "created_by": user["id"], "created_by_name": user["name"], "created_at": now, "updated_at": now}
    await db.actividades_particulares.insert_one(doc)
    return _act_part_public(doc)


@api.patch("/projects/{pid}/actividades-particulares/{rid}")
async def update_act_part(pid: str, rid: str, body: ActPartPatch, user: dict = Depends(current_user)):
    _assert_write_allowed(user)
    project = await ensure_project_access(user, pid)
    _ensure_modulo_activo(project, "actividades_particulares")
    if not await db.actividades_particulares.find_one({"id": rid, "project_id": pid}, {"id": 1}):
        raise HTTPException(404, "Registro no existe")
    fields = body.model_dump(exclude_unset=True)
    upd: dict = {}
    if fields.get("node_id") is not None:
        await _validate_node_in_project(pid, fields["node_id"])
        upd["node_id"] = fields["node_id"]
    if fields.get("categoria_id") is not None:
        cat = await _act_part_validar(pid, None, fields["categoria_id"])
        upd["categoria_id"], upd["categoria_nombre"] = fields["categoria_id"], cat["nombre"]
    if "subcategoria" in fields:
        upd["subcategoria"] = (fields["subcategoria"] or "").strip() or None
    if "texto" in fields:
        texto = (fields["texto"] or "").strip()
        if not texto:
            raise HTTPException(400, "Escribe la actividad realizada")
        upd["texto"] = texto
    if "fecha" in fields:
        upd["fecha"] = _prueba_calidad_fecha(fields["fecha"])
    if fields.get("jerarquia"):
        upd["jerarquia"] = _jerarquia_modulo(fields["jerarquia"])
    if upd:
        upd["updated_at"] = datetime.now(timezone.utc)
        await db.actividades_particulares.update_one({"id": rid}, {"$set": upd})
    return _act_part_public(await db.actividades_particulares.find_one({"id": rid}))


@api.delete("/projects/{pid}/actividades-particulares/{rid}")
async def delete_act_part(pid: str, rid: str, user: dict = Depends(current_user)):
    """Coordinador/Sub-Coordinador borran cualquiera; el resto solo lo suyo."""
    _assert_write_allowed(user)
    await ensure_project_access(user, pid)
    doc = await db.actividades_particulares.find_one({"id": rid, "project_id": pid}, {"created_by": 1})
    if not doc:
        raise HTTPException(404, "Registro no existe")
    if user.get("role") not in (ROLE_COORD, ROLE_SUB) and doc.get("created_by") != user["id"]:
        raise HTTPException(403, "Solo puedes eliminar las actividades que tú capturaste")
    await db.actividades_particulares.delete_one({"id": rid, "project_id": pid})
    return {"ok": True}


def _orden_arbol(nodos: List[dict]) -> dict:
    """{node_id: posición} recorriendo el árbol de ubicaciones en profundidad
    (hermanos por `order`): el mismo orden del árbol, para imprimir estaciones
    e intertramos tal como están en el proyecto."""
    hijos: dict = {}
    for n in nodos:
        hijos.setdefault(n.get("parent_id"), []).append(n)
    for lst in hijos.values():
        lst.sort(key=lambda n: (n.get("order") or 0, n.get("name") or ""))
    orden: dict = {}

    def visita(padre) -> None:
        for n in hijos.get(padre, []):
            orden[n["id"]] = len(orden)
            visita(n["id"])
    visita(None)
    for n in nodos:  # nodos huérfanos al final
        orden.setdefault(n["id"], len(orden))
    return orden


def _actividades_particulares_bloques(registros: List[dict], catalogo: List[dict], nodos: List[dict]) -> List[dict]:
    """Una tabla `table` por estación/intertramo con registros en el período:
    categoría / subcategoría / actividad (una viñeta por renglón). Se listan
    TODAS las categorías del catálogo; sin registros dicen "Sin actividades
    ésta semana". Registros de una categoría que ya no está en el catálogo se
    imprimen al final con el nombre que guardaron."""
    nombre_nodo = {n["id"]: n.get("name") or "" for n in nodos}
    orden_nodo = _orden_arbol(nodos)
    por_nodo: dict = {}
    for r in registros:
        if r.get("node_id") in nombre_nodo:
            por_nodo.setdefault(r["node_id"], []).append(r)
    bloques = []
    for nid in sorted(por_nodo, key=lambda i: orden_nodo.get(i, 10 ** 9)):
        regs = sorted(por_nodo[nid], key=lambda r: (r.get("fecha") or "", str(r.get("created_at") or "")))
        cats = [(c["id"], c["nombre"], c.get("subcategorias") or []) for c in catalogo]
        conocidas = {c[0] for c in cats}
        for r in regs:  # categoría borrada del catálogo: se conserva con su nombre
            if r.get("categoria_id") not in conocidas:
                conocidas.add(r.get("categoria_id"))
                cats.append((r.get("categoria_id"), r.get("categoria_nombre") or "Otras", []))
        rows: List[list] = []
        for cid, cnombre, subs in cats:
            recs = [r for r in regs if r.get("categoria_id") == cid]
            if not recs:
                rows.append([cnombre, "", ACT_PART_SIN_ACTIVIDAD])
                continue
            claves = [None] + list(subs)
            for r in recs:
                if r.get("subcategoria") and r["subcategoria"] not in claves:
                    claves.append(r["subcategoria"])
            primera_cat = True
            for sub in claves:
                grupo = [r for r in recs if (r.get("subcategoria") or None) == sub]
                for j, r in enumerate(grupo):
                    rows.append([cnombre if primera_cat else "", (sub or "") if j == 0 else "", "• " + r["texto"]])
                    primera_cat = False
        bloques.append({
            "type": "table", "heading": f"{nombre_nodo[nid].upper()} · ACTIVIDADES DESGLOSADAS",
            "headers": ["CATEGORÍA", "SUBCATEGORÍA", "ACTIVIDADES"], "rows": rows,
            "col_widths": [0.22, 0.2, 0.58], "empty_text": ACT_PART_SIN_ACTIVIDAD,
        })
    return bloques


# === CAPA FINANCIERA DEL REPORTE SEMANAL ===================================
# Tres módulos del reporte semanal de Cablebús:
#  - avance_obra: CALCULADO (sin captura propia) desde el motor EVM que ya
#    existe (conceptos, partidas, registros de avance y gastos reales):
#    tabla de avance por partidas (semanal/acumulado como aporte al total del
#    contrato), avance programado vs real y las gráficas físico/financiera.
#  - estimaciones: concentrado capturado a mano (obra o supervisión).
#  - pendientes_generales: pendientes/requerimientos vigentes (obra o
#    supervisión).
CONTRATOS_FIN = ("obra", "supervision")
CONTRATO_FIN_LABEL = {"obra": "OBRA", "supervision": "SUPERVISIÓN"}
# Los pendientes generales también existen para Aspectos Sociales (liberaciones
# de postes y predios). El campo sigue llamándose `contrato` por compatibilidad,
# pero aquí es un ÁMBITO: obra, supervisión o aspectos sociales.
PENDIENTES_AMBITOS = ("obra", "supervision", "sociales", "seguridad")
PENDIENTE_AMBITO_HEADING = {
    "obra": "PENDIENTES O REQUERIMIENTOS GENERALES (OBRA)",
    "supervision": "PENDIENTES O REQUERIMIENTOS GENERALES (SUPERVISIÓN)",
    "sociales": "PENDIENTES GENERALES (ASPECTOS SOCIALES)",
    "seguridad": "PENDIENTES ADMINISTRATIVOS (SEGURIDAD E HIGIENE)",
}


# Estatus que, de no caber completos en la tabla de postes, se abrevian a una
# sola línea antes de recortar filas con "+N más".
_ESTATUS_CORTO = {"Cambio de trayectoria": "Cambio tray."}


def _estacion_titulos(ordinal: Optional[int], nombre: str) -> tuple:
    """(título chico, título grande) de la página/diapositiva resumen de una
    Estación. Formato de referencia: "ESTACIÓN 5." (chico) y "CEFORMA"
    (grande). Si el nombre del nodo ya empieza con "Estación N" (mismo N que el
    ordinal), ese prefijo se quita del grande para no imprimirlo dos veces; si
    el nombre ES solo "Estación N", se omite el chico. Pura."""
    grande = (nombre or "").strip()
    if ordinal is None:
        return None, grande
    m = re.match(r"(?is)^\s*estaci[oó]n\s*(?:n[°o.]*\s*)?(\d+)\s*[.\-:]?\s*(.*)$", grande)
    if m and int(m.group(1)) == ordinal:
        resto = m.group(2).strip()
        return (f"ESTACIÓN {ordinal}.", resto) if resto else (None, grande)
    return f"ESTACIÓN {ordinal}.", grande


def _pptx_texto_lineas(texto: str, ancho_emu: int, size_pt: float) -> int:
    """Líneas que ocupa `texto` en una celda de `ancho_emu` a `size_pt`
    (estimación conservadora: ancho medio de carácter ≈ 0.55 em, descontando
    el margen interno de 0.25 cm por lado del cuadro de texto de PowerPoint)."""
    util_pt = max(ancho_emu / 12700 - 2 * 0.25 / 2.54 * 72, size_pt)
    por_linea = max(int(util_pt / (size_pt * 0.55)), 1)
    return sum(max(-(-len(parrafo) // por_linea), 1) for parrafo in str(texto).split("\n"))


def _pptx_fila_alto(celdas: List[str], anchos_emu: List[int], size_pt: float) -> int:
    """Alto (EMU) de una fila: la celda con más líneas manda, más el margen
    vertical del cuadro de texto (0.13 cm arriba y abajo)."""
    lineas = max(_pptx_texto_lineas(c, w, size_pt) for c, w in zip(celdas, anchos_emu))
    return int(lineas * size_pt * 1.2 * 12700 + 0.26 / 2.54 * 914400)


_RIESGO_NUM_RE = re.compile(r"^\s*\d+\s*[\)\.\-]\s*")


def _riesgos_grupos(registros: List[dict]) -> List[dict]:
    """Agrupa los riesgos por estación/poste (en el orden recibido) y numera
    cada fila "1) ...", "2) ..." dentro de su grupo — la numeración es lo que
    permite referirse a ellos ("Poste 2. Riesgos 1, 2 y 6"). Una fila con
    `numerar=False` (ej. la de postes, que solo cita números de otra) no se
    numera ni cuenta; a las numeradas se les quita el número que el usuario
    haya tecleado para no duplicarlo."""
    orden: List[str] = []
    grupos: Dict[str, list] = {}
    for r in registros:
        estacion = r.get("estacion_nombre") or "—"
        if estacion not in grupos:
            orden.append(estacion)
            grupos[estacion] = []
        grupos[estacion].append(r)
    out = []
    for estacion in orden:
        n = 0
        filas = []
        for r in grupos[estacion]:
            texto = (r.get("descripcion_riesgo") or "").strip()
            if r.get("numerar", True):
                n += 1
                texto = f"{n}) {_RIESGO_NUM_RE.sub('', texto)}"
            filas.append({"descripcion": texto, "control": r.get("propuesta_control") or "",
                          "avance": r.get("porcentaje_avance", 0)})
        out.append({"estacion": estacion, "filas": filas})
    return out


def _money_fmt(value) -> str:
    return f"${chr(0xA0)}{to_decimal(value):,.2f}"  # espacio sin salto: nunca se parte entre "$" y la cifra


def _pct_fmt(value) -> str:
    return f"{to_decimal(value):.2f}%"


def _avance_obra_resumen(
    conceptos: List[dict], partidas: List[dict], registros: List[dict], gastos: List[dict],
    ini: date, fin: date,
) -> Optional[dict]:
    """Avance del contrato de obra al corte `fin` y en la ventana [ini, fin].

    Cada partida RAÍZ muestra su APORTE al total del contrato (EV de sus
    conceptos / presupuesto total, en %), por eso la columna suma el avance
    real del contrato — es como lo imprime el reporte. EV sale de lo ya
    CONGELADO en cada registro de avance (nunca se recalcula con el precio de
    hoy) y PV del prorrateo analítico por días (mismo criterio que
    `analisis_periodo`). Devuelve None si no hay presupuesto."""
    total = sum((_concepto_importe_efectivo(c) for c in conceptos), start=Decimal("0"))
    if total <= 0:
        return None
    padre = {pa["id"]: pa.get("partida_padre_id") for pa in partidas}

    def raiz(pid: Optional[str]) -> Optional[str]:
        vistos: set = set()
        while pid and padre.get(pid) and pid not in vistos:
            vistos.add(pid)
            pid = padre[pid]
        return pid

    concepto_raiz = {c["id"]: raiz(c.get("partida_id")) for c in conceptos}
    ini_iso, fin_iso = ini.isoformat(), fin.isoformat()
    cien = Decimal("100")
    sem: dict = {}
    acum: dict = {}
    ev_mes: dict = {}
    for a in registros:
        f = a.get("fecha") or ""
        if a.get("importe_ganado_congelado") is None or not f or f > fin_iso:
            continue
        v = to_decimal(a["importe_ganado_congelado"])
        r = concepto_raiz.get(a.get("concepto_id"))
        acum[r] = acum.get(r, Decimal("0")) + v
        if f >= ini_iso:
            sem[r] = sem.get(r, Decimal("0")) + v
        ev_mes[f[:7]] = ev_mes.get(f[:7], Decimal("0")) + v

    raices = sorted(
        (pa for pa in partidas if not pa.get("partida_padre_id") and pa.get("activo", True)),
        key=lambda pa: (pa.get("orden", 0), pa.get("nombre", "")),
    )
    filas = []
    for i, pa in enumerate(raices, start=1):
        filas.append({
            "numero": i, "partida": pa.get("nombre") or "",
            "semanal": sem.get(pa["id"], Decimal("0")) / total * cien,
            "acumulado": acum.get(pa["id"], Decimal("0")) / total * cien,
        })
    huerfano_s, huerfano_a = sem.get(None, Decimal("0")), acum.get(None, Decimal("0"))
    ids_raiz = {pa["id"] for pa in raices}
    for r, v in acum.items():  # raíces inactivas o conceptos sin partida: no se pierden del total
        if r is not None and r not in ids_raiz:
            huerfano_a += v
            huerfano_s += sem.get(r, Decimal("0"))
    if huerfano_a != 0 or huerfano_s != 0:
        filas.append({"numero": len(filas) + 1, "partida": "OTRAS PARTIDAS",
                      "semanal": huerfano_s / total * cien, "acumulado": huerfano_a / total * cien})

    pv_acum = sum((_prorrateo_concepto_en_ventana(c, date(1900, 1, 1), fin) for c in conceptos), start=Decimal("0"))
    ev_acum = sum(acum.values(), start=Decimal("0"))

    pv_mes: dict = {}
    for c in conceptos:
        for punto in _curva_mensual_concepto(c):
            pv_mes[punto["mes"]] = pv_mes.get(punto["mes"], Decimal("0")) + to_decimal(punto["valor"])
    ac_mes: dict = {}
    for g in gastos:
        if g.get("fecha") and g["fecha"] <= fin_iso:
            ac_mes[g["fecha"][:7]] = ac_mes.get(g["fecha"][:7], Decimal("0")) + to_decimal(g["monto"])
    meses = sorted(m for m in (set(pv_mes) | set(ev_mes) | set(ac_mes)) if m <= fin_iso[:7])
    curva = {"meses": meses, "pv": [], "ev": [], "ac": []}
    a_pv = a_ev = a_ac = Decimal("0")
    for m in meses:
        a_pv += pv_mes.get(m, Decimal("0"))
        a_ev += ev_mes.get(m, Decimal("0"))
        a_ac += ac_mes.get(m, Decimal("0"))
        curva["pv"].append(a_pv)
        curva["ev"].append(a_ev)
        curva["ac"].append(a_ac)
    return {
        "presupuesto_total": total,
        "programado_pct": pv_acum / total * cien,
        "real_pct": ev_acum / total * cien,
        "filas": filas,
        "total_semanal": sum((f["semanal"] for f in filas), start=Decimal("0")),
        "total_acumulado": sum((f["acumulado"] for f in filas), start=Decimal("0")),
        "curva": curva,
    }


_CHART_FONT_CANDIDATAS = (
    "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
    "/usr/share/fonts/dejavu/DejaVuSans.ttf",
    "/usr/share/fonts/TTF/DejaVuSans.ttf",
    "/usr/share/fonts/truetype/liberation/LiberationSans-Regular.ttf",
    "C:/Windows/Fonts/segoeui.ttf",
    "C:/Windows/Fonts/arial.ttf",
    "/Library/Fonts/Arial.ttf",
    "/System/Library/Fonts/Supplemental/Arial.ttf",
)


def _sin_acentos(texto: str) -> str:
    import unicodedata
    return "".join(c for c in unicodedata.normalize("NFKD", str(texto)) if not unicodedata.combining(c))


def _chart_canvas(img, *tamanos: int):
    """(draw, [fuentes...]) para las gráficas dibujadas con Pillow. La fuente
    por defecto de Pillow NO trae vocales acentuadas (salen como cuadros), así
    que se busca una TrueType del sistema (DejaVu en el servidor Ubuntu); si
    no hay ninguna, el draw quita los acentos del texto para que se lea."""
    from PIL import ImageDraw as _D, ImageFont as _F
    fuentes, acentos = None, False
    for ruta in _CHART_FONT_CANDIDATAS:
        try:
            fuentes, acentos = [_F.truetype(ruta, t) for t in tamanos], True
            break
        except OSError:
            continue
    if fuentes is None:
        try:
            fuentes = [_F.load_default(size=t) for t in tamanos]
        except TypeError:  # Pillow viejo sin tamaño
            fuentes = [_F.load_default() for _ in tamanos]

    class _Draw(_D.ImageDraw):
        def text(self, xy, text, *a, **k):
            return super().text(xy, text if acentos else _sin_acentos(text), *a, **k)

        def textlength(self, text, *a, **k):
            return super().textlength(text if acentos else _sin_acentos(text), *a, **k)

    return _Draw(img), fuentes


def _grafica_lineas_png(titulo: str, etiquetas: List[str], series: List[tuple], formato) -> bytes:
    """Gráfica de líneas acumuladas dibujada con Pillow (el backend no usa
    matplotlib). `series` = [(nombre, "#RRGGBB", [valores...]), ...]."""
    from PIL import Image as _I
    W, H = 1800, 800
    img = _I.new("RGB", (W, H), "white")
    d, (f_txt, f_tit) = _chart_canvas(img, 22, 28)
    d.text((W / 2, 28), titulo, fill="#0F172A", font=f_tit, anchor="mm")
    x0, x1, y0, y1 = 150, W - 60, 80, H - 150
    vmax = max([float(v) for _, _, vals in series for v in vals] + [0.0])
    vmax = vmax * 1.08 if vmax > 0 else 1.0
    for i in range(6):
        y = y1 - (y1 - y0) * i / 5
        d.line([(x0, y), (x1, y)], fill="#E2E8F0", width=1)
        d.text((x0 - 12, y), formato(vmax * i / 5), fill="#475569", font=f_txt, anchor="rm")
    d.line([(x0, y0), (x0, y1), (x1, y1)], fill="#475569", width=2)
    n = len(etiquetas)
    xs = [x0 + (x1 - x0) * (i / (n - 1) if n > 1 else 0.5) for i in range(n)]
    paso = max(1, n // 12)
    for i, et in enumerate(etiquetas):
        if i % paso == 0 or i == n - 1:
            d.text((xs[i], y1 + 14), et, fill="#475569", font=f_txt, anchor="mt")
    lx = x0
    for nombre, color, vals in series:
        pts = [(xs[i], y1 - (y1 - y0) * float(v) / vmax) for i, v in enumerate(vals)]
        if len(pts) > 1:
            d.line(pts, fill=color, width=5, joint="curve")
        for px, py in pts:
            d.ellipse([px - 6, py - 6, px + 6, py + 6], fill=color)
        d.rectangle([lx, H - 60, lx + 28, H - 40], fill=color)
        d.text((lx + 38, H - 50), nombre, fill="#0F172A", font=f_txt, anchor="lm")
        lx += 60 + int(d.textlength(nombre, font=f_txt)) + 40
    out = io.BytesIO()
    img.save(out, format="PNG")
    return out.getvalue()


def _avance_obra_bloques(res: dict, ini: date, fin: date, contrato: str = "obra") -> List[dict]:
    filas = res["filas"]
    rows = [[str(f["numero"]), f["partida"], _pct_fmt(f["semanal"]), _pct_fmt(f["acumulado"])] for f in filas]
    rows.append(["", "TOTAL", _pct_fmt(res["total_semanal"]), _pct_fmt(res["total_acumulado"])])
    bloques: List[dict] = [
        {"type": "summary",
         "text": f"AVANCE  ·  PROGRAMADO {_pct_fmt(res['programado_pct'])}  ·  REAL {_pct_fmt(res['real_pct'])}"},
        {"type": "table", "heading": f"TABLA DE AVANCE POR PARTIDAS ({CONTRATO_FIN_LABEL[contrato]})",
         "headers": ["N°", "PARTIDAS", "AVANCE SEMANAL (%)", "AVANCE ACUMULADO (%)"],
         "rows": rows, "col_widths": [0.07, 0.55, 0.19, 0.19], "empty_text": "Sin partidas."},
    ]
    return bloques


PROGRAMA_FILAS_POR_GRAFICA = 18


def _programa_barras(
    conceptos: List[dict], partidas: List[dict], registros: List[dict], corte: date, max_nivel: int = 1,
) -> List[dict]:
    """Filas del programa en barras: cada partida raíz y sus subpartidas
    (hasta `max_nivel`), con el rango de fechas que abarcan sus conceptos, el
    avance REAL acumulado al corte (valor ganado congelado / importe) y el
    PROGRAMADO (prorrateo por días / importe). Las partidas sin conceptos con
    fechas no se dibujan. Pura — sin Mongo."""
    activas = [pa for pa in partidas if pa.get("activo", True)]
    hijos: Dict[Optional[str], list] = {}
    for pa in activas:
        hijos.setdefault(pa.get("partida_padre_id") or None, []).append(pa)
    for lista in hijos.values():
        lista.sort(key=lambda pa: (pa.get("orden", 0), pa.get("clave", ""), pa.get("nombre", "")))
    por_partida: Dict[Optional[str], list] = {}
    for c in conceptos:
        por_partida.setdefault(c.get("partida_id"), []).append(c)
    corte_iso = corte.isoformat()
    ev_concepto: Dict[str, Decimal] = {}
    for r in registros:
        if r.get("importe_ganado_congelado") is not None and (r.get("fecha") or "") <= corte_iso:
            ev_concepto[r.get("concepto_id")] = ev_concepto.get(r.get("concepto_id"), Decimal("0")) + to_decimal(r["importe_ganado_congelado"])

    def subarbol(pa: dict) -> List[dict]:
        out, pila, vistos = [], [pa], set()
        while pila:
            cur = pila.pop()
            if cur["id"] in vistos:
                continue
            vistos.add(cur["id"])
            out += por_partida.get(cur["id"], [])
            pila += hijos.get(cur["id"], [])
        return out

    filas: List[dict] = []

    def visitar(pa: dict, nivel: int) -> None:
        cs = subarbol(pa)
        datados = [c for c in cs if _concepto_tiene_datos_evm(c) and c.get("fecha_inicio") and c.get("fecha_fin")]
        if datados:
            importe = sum((_concepto_importe_efectivo(c) for c in cs), start=Decimal("0"))
            ev = sum((ev_concepto.get(c["id"], Decimal("0")) for c in cs), start=Decimal("0"))
            pv = sum((_prorrateo_concepto_en_ventana(c, date(1900, 1, 1), corte) for c in cs), start=Decimal("0"))
            filas.append({
                "nombre": pa.get("nombre") or "", "nivel": nivel,
                "inicio": min(date.fromisoformat(c["fecha_inicio"]) for c in datados),
                "fin": max(date.fromisoformat(c["fecha_fin"]) for c in datados),
                "real": float(min(ev / importe * 100, Decimal(100))) if importe > 0 else 0.0,
                "programado": float(min(pv / importe * 100, Decimal(100))) if importe > 0 else 0.0,
            })
        if nivel < max_nivel:
            for h in hijos.get(pa["id"], []):
                visitar(h, nivel + 1)

    for raiz in hijos.get(None, []):
        visitar(raiz, 0)
    return filas


def _grafica_programa_png(titulo: str, filas: List[dict], corte: date) -> bytes:
    """Programa de obra en barras: la barra clara es el plazo de la partida
    (inicio → fin), el relleno oscuro el avance REAL y la línea roja el corte.
    A la derecha, real y programado en %. Dibujada con Pillow."""
    from PIL import Image as _I
    W = 1800
    row_h = 40
    top, left, right = 100, 560, 250
    H = top + row_h * len(filas) + 130
    img = _I.new("RGB", (W, H), "white")
    d, (f_txt, f_tit, f_peq) = _chart_canvas(img, 20, 28, 17)
    d.text((W / 2, 40), titulo, fill="#0F172A", font=f_tit, anchor="mm")
    t0 = min(f["inicio"] for f in filas)
    t1 = max(max(f["fin"] for f in filas), t0 + timedelta(days=1))
    span = (t1 - t0).days or 1
    x0, x1 = left, W - right

    def xpos(dt: date) -> float:
        return x0 + (x1 - x0) * (min(max(dt, t0), t1) - t0).days / span

    n_meses = (t1.year - t0.year) * 12 + t1.month - t0.month + 1
    paso = max(1, -(-64 // max(int((x1 - x0) / n_meses), 1)))  # una etiqueta cada `paso` meses: sin amontonarse
    cur, k = date(t0.year, t0.month, 1), 0
    while cur <= t1:  # una línea por mes
        if cur >= t0:
            x = xpos(cur)
            d.line([(x, top - 14), (x, H - 100)], fill="#E2E8F0", width=1)
            if k % paso == 0:
                d.text((x, H - 88), cur.strftime("%m/%y"), fill="#475569", font=f_peq, anchor="mt")
            k += 1
        cur = date(cur.year + (cur.month == 12), cur.month % 12 + 1, 1)
    for i, f in enumerate(filas):
        y = top + i * row_h
        raiz = f["nivel"] == 0
        etiqueta = (f["nombre"] if len(f["nombre"]) <= 44 else f["nombre"][:43] + "…")
        if raiz:
            etiqueta = etiqueta.upper()
        tx = 20 + f["nivel"] * 28
        d.text((tx, y + row_h / 2), etiqueta, fill="#0F172A" if raiz else "#334155", font=f_txt, anchor="lm")
        if raiz:
            d.text((tx + 1, y + row_h / 2), etiqueta, fill="#0F172A", font=f_txt, anchor="lm")
        xa, xb = xpos(f["inicio"]), max(xpos(f["fin"]), xpos(f["inicio"]) + 6)
        alto = 20 if raiz else 14
        ya = y + (row_h - alto) / 2
        d.rectangle([xa, ya, xb, ya + alto], fill="#93C5FD" if raiz else "#BFDBFE")
        if f["real"] > 0:
            d.rectangle([xa, ya, xa + (xb - xa) * f["real"] / 100, ya + alto], fill="#1D4ED8" if raiz else "#3B82F6")
        d.text((x1 + 20, y + row_h / 2), f"real {f['real']:.1f}% · prog {f['programado']:.1f}%", fill="#475569", font=f_peq, anchor="lm")
    xc = xpos(corte)
    d.line([(xc, top - 14), (xc, H - 100)], fill="#DC2626", width=3)
    d.text((xc, top - 18), f"Corte {corte.strftime('%d/%m/%Y')}", fill="#DC2626", font=f_peq, anchor="mb")
    ly = H - 40
    for k, (color, texto) in enumerate((("#93C5FD", "Plazo programado"), ("#1D4ED8", "Avance real"), ("#DC2626", "Corte"))):
        lx = left + k * 260
        d.rectangle([lx, ly - 8, lx + 28, ly + 8], fill=color)
        d.text((lx + 38, ly), texto, fill="#0F172A", font=f_peq, anchor="lm")
    out = io.BytesIO()
    img.save(out, format="PNG")
    return out.getvalue()


def _programa_barras_graficas(
    conceptos: List[dict], partidas: List[dict], registros: List[dict], ini: date, fin: date, contrato: str = "obra",
) -> List[tuple]:
    """[(heading, caption, png)] del programa del contrato al corte `fin`,
    en bloques de `PROGRAMA_FILAS_POR_GRAFICA` filas si es largo."""
    filas = _programa_barras(conceptos, partidas, registros, fin)
    if not filas:
        return []
    lbl = {"obra": "OBRA", "supervision": "SUPERVISIÓN"}[contrato]
    texto = "obra" if contrato == "obra" else "servicios de supervisión"
    caption = f"Programa de {texto} de la semana del {_fmt_iso_dmy(ini.isoformat())} al {_fmt_iso_dmy(fin.isoformat())}"
    n = PROGRAMA_FILAS_POR_GRAFICA
    total = (len(filas) + n - 1) // n
    out = []
    for k in range(total):
        pag = f" ({k + 1}/{total})" if total > 1 else ""
        out.append((f"PROGRAMA DE {lbl}{pag}", caption,
                    _grafica_programa_png(f"Programa de {texto} en barras", filas[k * n:(k + 1) * n], fin)))
    return out


def _avance_obra_graficas(res: dict, fin: date, contrato: str = "obra") -> List[tuple]:
    """[(heading, caption, png_bytes), ...] — gráfica física (% acumulado
    programado vs real) y financiera (importe acumulado programado, ganado y
    real, en millones)."""
    c = res["curva"]
    if not c["meses"]:
        return []
    total = res["presupuesto_total"]
    etiquetas = [f"{m[5:]}/{m[2:4]}" for m in c["meses"]]
    cien = Decimal("100")
    fisica = _grafica_lineas_png(
        "Avance físico acumulado (% del contrato)", etiquetas,
        [("Programado", "#2563EB", [v / total * cien for v in c["pv"]]),
         ("Real", "#16A34A", [v / total * cien for v in c["ev"]])],
        lambda v: f"{v:.0f}%",
    )
    fin_png = _grafica_lineas_png(
        "Físico-financiero acumulado (millones de pesos)", etiquetas,
        [("Programado", "#2563EB", [v / Decimal("1000000") for v in c["pv"]]),
         ("Ganado (avance)", "#16A34A", [v / Decimal("1000000") for v in c["ev"]]),
         ("Gasto real", "#DC2626", [v / Decimal("1000000") for v in c["ac"]])][: 3 if any(c["ac"]) else 2],
        lambda v: f"{v:,.0f} M",
    )
    corte = f"al {_fmt_iso_dmy(fin.isoformat())}"
    lbl = CONTRATO_FIN_LABEL[contrato]
    return [(f"GRÁFICA DE AVANCE ({lbl})", f"Avance físico acumulado {corte}", fisica),
            (f"FÍSICO – FINANCIERO ({lbl})", f"Gráfica físico–financiera {corte}", fin_png)]


class EstimacionIn(BaseModel):
    contrato: Literal["obra", "supervision"] = "obra"
    numero: int
    periodo_inicio: Optional[str] = None
    periodo_fin: Optional[str] = None
    estatus: Optional[str] = None  # ej. LIBERADA / NO LIBERADA
    obra_ejecutada: Optional[str] = None
    amortizacion: Optional[str] = None
    pct_amortizacion_anticipo: Optional[str] = None
    total_deducciones: Optional[str] = None
    iva: Optional[str] = None
    total_neto: Optional[str] = None
    fecha_pago: Optional[str] = None  # fecha o texto libre ("Por pagar")


class EstimacionPatch(BaseModel):
    numero: Optional[int] = None
    periodo_inicio: Optional[str] = None
    periodo_fin: Optional[str] = None
    estatus: Optional[str] = None
    obra_ejecutada: Optional[str] = None
    amortizacion: Optional[str] = None
    pct_amortizacion_anticipo: Optional[str] = None
    total_deducciones: Optional[str] = None
    iva: Optional[str] = None
    total_neto: Optional[str] = None
    fecha_pago: Optional[str] = None


_ESTIMACION_IMPORTES = ("obra_ejecutada", "amortizacion", "pct_amortizacion_anticipo", "total_deducciones", "iva", "total_neto")
_ESTIMACION_TEXTOS = ("estatus", "fecha_pago")
_ESTIMACION_FECHAS = ("periodo_inicio", "periodo_fin")
_ESTIMACION_ROTULO = {
    "obra_ejecutada": "Obra ejecutada", "amortizacion": "Amortización",
    "pct_amortizacion_anticipo": "% amortización del anticipo", "total_deducciones": "Total deducciones",
    "iva": "IVA", "total_neto": "Total neto", "periodo_inicio": "Periodo: inicio", "periodo_fin": "Periodo: fin",
}


def _estimacion_valor(campo: str, value: Optional[str]) -> Optional[str]:
    """Normaliza un campo de la estimación: importes y % como Decimal (texto
    limpio o None), fechas como YYYY-MM-DD, el resto como texto recortado."""
    if value is None or not str(value).strip():
        return None
    v = str(value).strip()
    if campo in _ESTIMACION_IMPORTES:
        limpio = re.sub(r"[\s$,%]", "", v)
        if limpio in ("-", "--", "—", "N/A", "n/a", "NA", "S/D"):  # "sin dato" pegado de Excel = vacío
            return None
        try:
            d = to_decimal(limpio)
            if not d.is_finite():
                raise ValueError
            return dec_to_str(d)
        except Exception:
            raise HTTPException(400, f"{_ESTIMACION_ROTULO.get(campo, campo)} debe ser un número (ej. 5978451.30)")
    if campo in _ESTIMACION_FECHAS:
        try:
            return _fecha_flexible(v).isoformat()
        except ValueError:
            raise HTTPException(400, f"{_ESTIMACION_ROTULO.get(campo, campo)} inválida: usa AAAA-MM-DD o DD/MM/AAAA")
    if campo == "fecha_pago":  # fecha real si lo es; si no ("Por pagar") se guarda el texto
        try:
            return _fecha_flexible(v).isoformat()
        except ValueError:
            return v
    return v


def _estimaciones_bloques(registros: List[dict]) -> List[dict]:
    """Un bloque `table` por contrato (obra / supervisión). La SUMA ACUMULADA
    se calcula aquí (acumulado de obra ejecutada hasta ese número), no se
    captura: así nunca queda desfasada de las filas."""
    bloques = []
    for contrato in CONTRATOS_FIN:
        regs = sorted((r for r in registros if r.get("contrato", "obra") == contrato), key=lambda r: r.get("numero", 0))
        if not regs:
            continue
        acumulado = Decimal("0")
        rows = []
        for r in regs:
            acumulado += to_decimal(r.get("obra_ejecutada") or "0")
            money = lambda k: _money_fmt(r[k]) if r.get(k) is not None else "-"  # noqa: E731
            rows.append([
                str(r.get("numero", "")),
                f"{_fmt_iso_dmy(r.get('periodo_inicio'))} al {_fmt_iso_dmy(r.get('periodo_fin'))}" if r.get("periodo_inicio") else "-",
                r.get("estatus") or "-",
                money("obra_ejecutada"),
                _money_fmt(acumulado),
                money("amortizacion"),
                _pct_fmt(r["pct_amortizacion_anticipo"]) if r.get("pct_amortizacion_anticipo") is not None else "-",
                money("total_deducciones"),
                money("iva"),
                money("total_neto"),
                _fmt_iso_dmy(r["fecha_pago"]) if r.get("fecha_pago") else "-",
            ])
        bloques.append({
            "type": "table",
            "heading": f"CONCENTRADO ESTIMACIONES ({CONTRATO_FIN_LABEL[contrato]})",
            "headers": ["N°", "PERIODO", "ESTATUS GENERAL", "OBRA EJECUTADA", "SUMA ACUMULADA", "AMORTIZACIÓN",
                        "% ACUM. AMORT. ANTICIPO", "TOTAL DEDUCCIONES", "IVA 16%", "TOTAL NETO", "FECHA DE PAGO"],
            "rows": rows,
            "col_widths": [0.04, 0.12, 0.075, 0.105, 0.105, 0.105, 0.075, 0.105, 0.095, 0.105, 0.07],
            "empty_text": "Sin estimaciones.",
        })
    return bloques


@api.get("/projects/{pid}/estimaciones")
async def list_estimaciones(pid: str, contrato: Optional[str] = None, user: dict = Depends(current_user)):
    await ensure_project_access(user, pid)
    q: dict = {"project_id": pid}
    if contrato:
        q["contrato"] = contrato
    items = await db.estimaciones.find(q).sort([("contrato", 1), ("numero", 1)]).to_list(length=500)
    return [{k: v for k, v in d.items() if k != "_id"} for d in items]


@api.post("/projects/{pid}/estimaciones")
async def create_estimacion(pid: str, body: EstimacionIn, user: dict = Depends(require_role(ROLE_COORD, ROLE_SUB))):
    project = await ensure_project_access(user, pid)
    _ensure_modulo_activo(project, "estimaciones")
    if await db.estimaciones.find_one({"project_id": pid, "contrato": body.contrato, "numero": body.numero}, {"id": 1}):
        raise HTTPException(409, f"Ya existe la estimación {body.numero} de {CONTRATO_FIN_LABEL[body.contrato].lower()}")
    now = datetime.now(timezone.utc)
    doc = {"id": str(uuid.uuid4()), "project_id": pid, "contrato": body.contrato, "numero": body.numero,
           "created_by": user["id"], "created_at": now, "updated_at": now}
    for campo in _ESTIMACION_IMPORTES + _ESTIMACION_TEXTOS + _ESTIMACION_FECHAS:
        doc[campo] = _estimacion_valor(campo, getattr(body, campo))
    await db.estimaciones.insert_one(doc)
    return {k: v for k, v in doc.items() if k != "_id"}


@api.patch("/projects/{pid}/estimaciones/{eid}")
async def update_estimacion(pid: str, eid: str, body: EstimacionPatch, user: dict = Depends(require_role(ROLE_COORD, ROLE_SUB))):
    project = await ensure_project_access(user, pid)
    _ensure_modulo_activo(project, "estimaciones")
    doc = await db.estimaciones.find_one({"id": eid, "project_id": pid})
    if not doc:
        raise HTTPException(404, "Estimación no existe")
    fields = body.model_dump(exclude_unset=True)
    upd: dict = {}
    if fields.get("numero") is not None and fields["numero"] != doc["numero"]:
        if await db.estimaciones.find_one({"project_id": pid, "contrato": doc["contrato"], "numero": fields["numero"]}, {"id": 1}):
            raise HTTPException(409, f"Ya existe la estimación {fields['numero']}")
        upd["numero"] = fields["numero"]
    for campo in _ESTIMACION_IMPORTES + _ESTIMACION_TEXTOS + _ESTIMACION_FECHAS:
        if campo in fields:
            upd[campo] = _estimacion_valor(campo, fields[campo])
    if upd:
        upd["updated_at"] = datetime.now(timezone.utc)
        await db.estimaciones.update_one({"id": eid}, {"$set": upd})
    out = await db.estimaciones.find_one({"id": eid})
    return {k: v for k, v in out.items() if k != "_id"}


@api.delete("/projects/{pid}/estimaciones/{eid}")
async def delete_estimacion(pid: str, eid: str, user: dict = Depends(require_role(ROLE_COORD, ROLE_SUB))):
    await ensure_project_access(user, pid)
    res = await db.estimaciones.delete_one({"id": eid, "project_id": pid})
    if not res.deleted_count:
        raise HTTPException(404, "Estimación no existe")
    return {"ok": True}


class PendienteIn(BaseModel):
    contrato: Literal["obra", "supervision", "sociales", "seguridad"] = "obra"
    titulo: str
    descripcion: Optional[str] = None
    orden: int = 0


class PendientePatch(BaseModel):
    titulo: Optional[str] = None
    descripcion: Optional[str] = None
    orden: Optional[int] = None
    resuelto: Optional[bool] = None


def _pendiente_resuelto_en(r: dict, desde: datetime, hasta: datetime) -> Optional[datetime]:
    """Fecha de resolución de un pendiente resuelto si cae en [desde, hasta]
    (None si no está resuelto o quedó fuera). Un pendiente resuelto antes de
    que se guardara `resuelto_at` usa su última actualización como aproximación."""
    if not r.get("resuelto"):
        return None
    cuando = r.get("resuelto_at") or r.get("updated_at")
    if not isinstance(cuando, datetime):
        return None
    if cuando.tzinfo is None:
        cuando = cuando.replace(tzinfo=timezone.utc)
    return cuando if desde <= cuando <= hasta else None


def _pendientes_bloques(
    registros: List[dict], resueltos_desde: Optional[datetime] = None, resueltos_hasta: Optional[datetime] = None,
) -> List[dict]:
    """Un bloque `list` por contrato con los pendientes VIGENTES. Los resueltos
    no se imprimen, salvo que se pida el rango (informes semanal y mensual):
    entonces se agrega, por contrato, "RESUELTOS EN EL PERÍODO" con los que se
    cerraron dentro del rango. Sin nada que imprimir → sin bloque."""
    bloques = []
    con_rango = resueltos_desde is not None and resueltos_hasta is not None
    for contrato in PENDIENTES_AMBITOS:
        propios = [r for r in registros if r.get("contrato", "obra") == contrato]
        vigentes = sorted(
            (r for r in propios if not r.get("resuelto")),
            key=lambda r: (r.get("orden", 0), str(r.get("created_at") or "")),
        )
        if vigentes:
            bloques.append({
                "type": "list",
                "heading": PENDIENTE_AMBITO_HEADING[contrato],
                "items": [{"title": r["titulo"], "body": r.get("descripcion") or "", "extra": None, "meta": None}
                          for r in vigentes],
                "empty_text": "Sin pendientes.",
            })
        if not con_rango:
            continue
        cerrados = sorted(
            ((cuando, r) for r in propios if (cuando := _pendiente_resuelto_en(r, resueltos_desde, resueltos_hasta))),
            key=lambda x: (x[0], x[1].get("orden", 0)),
        )
        if cerrados:
            bloques.append({
                "type": "list",
                "heading": f"{PENDIENTE_AMBITO_HEADING[contrato]} · RESUELTOS EN EL PERÍODO",
                "items": [{"title": r["titulo"], "body": r.get("descripcion") or "", "extra": None,
                           "meta": f"Resuelto el {cuando.astimezone(MX_TZ).strftime('%d/%m/%Y')}"}
                          for cuando, r in cerrados],
                "empty_text": "Sin pendientes resueltos.",
            })
    return bloques


