@api.get("/projects/{pid}/areas")
async def list_areas(pid: str, user: dict = Depends(current_user)):
    await ensure_project_access(user, pid)
    items = await db.areas.find({"project_id": pid}).sort("name", 1).to_list(length=200)
    for it in items:
        it.pop("_id", None)
        _area_con_defaults(it)
    return items


@api.post("/projects/{pid}/areas")
async def create_area(pid: str, body: AreaIn, user: dict = Depends(require_role(ROLE_COORD))):
    if body.project_id != pid:
        raise HTTPException(400, "project_id mismatch")
    await ensure_project_access(user, pid)
    name = body.name.strip()
    if not name:
        raise HTTPException(400, "Nombre requerido")
    # Comparación insensible a mayúsculas/acentos/espacios: dos áreas que
    # solo difieren en casing (p. ej. "Calidad" vs "CALIDAD") imprimían dos
    # portadillas de Área consecutivas en los reportes (ver
    # `_normalize_area_name`); bloquearlas aquí evita que el problema vuelva
    # a entrar por la puerta de alta.
    def _fold(s: str) -> str:
        flat = "".join(
            ch for ch in unicodedata.normalize("NFD", s.strip().lower())
            if unicodedata.category(ch) != "Mn"
        )
        return " ".join(flat.replace("-", " ").replace("_", " ").split())
    name_fold = _fold(name)
    existing_areas = await db.areas.find({"project_id": pid}).to_list(length=200)
    if any(_fold(a.get("name") or "") == name_fold for a in existing_areas):
        raise HTTPException(409, "Área ya existe en este proyecto")
    doc = {
        "id": str(uuid.uuid4()),
        "project_id": pid,
        "name": name,
        "color": validar_color_hex(body.color, "Color del área") or "#1E40AF",
        "created_at": datetime.now(timezone.utc),
        "captura_personal": body.captura_personal,
        "captura_equipo": body.captura_equipo,
        "campos_extra": _normalizar_campos_extra(body.campos_extra),
    }
    await db.areas.insert_one(doc)
    doc.pop("_id", None)
    return doc


@api.patch("/areas/{aid}/config")
async def update_area_config(aid: str, body: AreaConfigIn, user: dict = Depends(require_role(ROLE_COORD))):
    """Define qué captura el Área en sus reportes: Personal, Equipo y campos
    libres (p. ej. Banderilleros). Los reportes ya capturados no cambian."""
    a = await db.areas.find_one({"id": aid})
    if not a:
        raise HTTPException(404, "Área no existe")
    await ensure_project_access(user, a["project_id"])
    cambios: dict = {}
    if body.captura_personal is not None:
        cambios["captura_personal"] = body.captura_personal
    if body.captura_equipo is not None:
        cambios["captura_equipo"] = body.captura_equipo
    if body.campos_extra is not None:
        cambios["campos_extra"] = _normalizar_campos_extra(body.campos_extra)
    if cambios:
        await db.areas.update_one({"id": aid}, {"$set": cambios})
    a = await db.areas.find_one({"id": aid})
    a.pop("_id", None)
    return _area_con_defaults(a)


@api.delete("/areas/{aid}")
async def delete_area(aid: str, user: dict = Depends(require_role(ROLE_COORD))):
    a = await db.areas.find_one({"id": aid})
    if not a:
        raise HTTPException(404, "Área no existe")
    await db.areas.delete_one({"id": aid})
    return {"ok": True}


