async def _validate_and_build_invitation_doc(
    pid: str, project: dict, *, email: str, name: str, role: str,
    area_id: Optional[str], puesto: Optional[str], no_control: Optional[str],
) -> dict:
    """Valida las reglas de negocio de una invitación y arma el doc listo para
    insertar. Compartido por el alta individual (wizard) y la carga masiva por
    Excel (`/invitations/bulk_import/*`) para no duplicar la lógica.

    NOTA scope de nodos: sub-coordinador y especialista ya NO requieren
    seleccionar nodos del árbol — ambos roles tienen acceso GLOBAL al
    proyecto una vez aceptada la invitación (ver checks de `scope_node_ids`
    en reportes/nodos, que tratan una lista vacía como "sin restricción").
    `scope_node_id`/`scope_node_ids` se conservan en el esquema solo por
    compatibilidad con datos viejos.
    """
    email = email.lower().strip()
    name = (name or "").strip()
    if not name:
        raise HTTPException(400, "Nombre requerido")
    if role == "sub_coordinador":
        # Área/disciplina opcional del sub-coordinador — se usa en los exports
        # ejecutivos (PDF/PPTX) para etiquetar los reportes bajo esta disciplina.
        # Si NO se asigna, exports usan "Obra Civil" como fallback.
        if area_id:
            area = await db.areas.find_one({"id": area_id, "project_id": pid})
            if not area:
                raise HTTPException(404, "area_id inválido para sub-coordinador")
    elif role == "especialista":
        if not area_id:
            raise HTTPException(400, "Especialista requiere area_id")
        area = await db.areas.find_one({"id": area_id, "project_id": pid})
        if not area:
            raise HTTPException(404, "area_id inválido")
    elif role != "jefe_proyecto":
        raise HTTPException(400, f"Rol inválido: {role}")
    # ====================================================================
    # REGLA GLOBAL: 1 USUARIO = 1 PROYECTO
    # --------------------------------------------------------------------
    # Un mismo correo NO puede ser invitado ni dado de alta en más de un
    # proyecto. Si ya existe como usuario en ANY proyecto, o si tiene una
    # invitación pendiente en OTRO proyecto, rechazamos con 400.
    # ====================================================================
    existing_user = await db.users.find_one({"email": email})
    if existing_user:
        raise HTTPException(400, "Este usuario ya está asignado a otro proyecto")
    pending_in_other = await db.invitations.find_one({
        "email": email,
        "status": "pending",
        "project_id": {"$ne": pid},
    })
    if pending_in_other:
        raise HTTPException(400, "Este usuario ya está asignado a otro proyecto")
    return {
        "id": str(uuid.uuid4()),
        "token": secrets.token_urlsafe(24),
        "project_id": pid,
        "project_name": project["name"],
        "email": email,
        "name": name,
        "role": role,
        "area_id": area_id,
        "puesto": (puesto or "").strip() or None,
        "no_control": (no_control or "").strip() or None,
        "scope_node_id": None,
        "scope_node_ids": [],
        "status": "pending",
        "created_at": datetime.now(timezone.utc),
        "expires_at": datetime.now(timezone.utc) + timedelta(days=30),
    }


@api.post("/projects/{pid}/invitations")
async def create_invite(pid: str, body: InvitationIn, user: dict = Depends(require_role(ROLE_COORD))):
    if body.project_id != pid:
        raise HTTPException(400, "project_id mismatch")
    project = await ensure_project_access(user, pid)
    doc = await _validate_and_build_invitation_doc(
        pid, project,
        email=body.email, name=body.name, role=body.role,
        area_id=body.area_id, puesto=body.puesto, no_control=body.no_control,
    )
    doc["creado_por"] = user["id"]
    await db.invitations.insert_one(doc)
    doc.pop("_id", None)
    return doc


@api.delete("/invitations/{iid}")
async def revoke_invite(iid: str, user: dict = Depends(require_role(ROLE_COORD))):
    r = await db.invitations.update_one({"id": iid, "status": "pending"}, {"$set": {"status": "revoked"}})
    if r.matched_count == 0:
        raise HTTPException(404, "Invitación no pendiente")
    return {"ok": True}


@api.get("/invitations/by-token/{tok}")
async def invite_preview(tok: str):
    inv = await db.invitations.find_one({"token": tok})
    if not inv:
        raise HTTPException(404, "Invitación inválida")
    if inv["status"] != "pending":
        raise HTTPException(410, f"Invitación {inv['status']}")
    exp = inv["expires_at"]
    if exp.tzinfo is None:
        exp = exp.replace(tzinfo=timezone.utc)
    if exp < datetime.now(timezone.utc):
        raise HTTPException(410, "Invitación expirada")
    inv.pop("_id", None)
    area_name = None
    if inv.get("area_id"):
        area = await db.areas.find_one({"id": inv["area_id"]})
        if area:
            area_name = area.get("name")
    return {
        "project_name": inv["project_name"],
        "email": inv["email"],
        "name": inv["name"],
        "role": inv["role"],
        "puesto": inv.get("puesto"),
        "area_name": area_name,
    }


@api.post("/invitations/accept", response_model=Token)
async def accept_invite(body: AcceptInviteIn):
    inv = await db.invitations.find_one({"token": body.token})
    if not inv:
        raise HTTPException(404, "Invitación inválida")
    if inv["status"] != "pending":
        raise HTTPException(410, f"Invitación {inv['status']}")
    exp = inv["expires_at"]
    if exp.tzinfo is None:
        exp = exp.replace(tzinfo=timezone.utc)
    if exp < datetime.now(timezone.utc):
        raise HTTPException(410, "Invitación expirada")
    if len(body.password) < 6:
        raise HTTPException(400, "Password mínimo 6 caracteres")
    existing = await db.users.find_one({"email": inv["email"]})
    if existing:
        raise HTTPException(400, "Este usuario ya está asignado a otro proyecto")
    uid = str(uuid.uuid4())
    # Obtener nombre del área si aplica
    area_name = None
    if inv.get("area_id"):
        a = await db.areas.find_one({"id": inv["area_id"]})
        if a:
            area_name = a["name"]
    user_doc = {
        "id": uid,
        "email": inv["email"],
        "password": hash_pw(body.password),
        "name": inv["name"],
        "role": inv["role"],
        "area": area_name,
        "area_id": inv.get("area_id"),
        "puesto": inv.get("puesto"),
        "no_control": inv.get("no_control"),
        "scope_node_id": inv.get("scope_node_id"),
        "scope_node_ids": inv.get("scope_node_ids") or [],
        "project_ids": [inv["project_id"]],
        "created_at": datetime.now(timezone.utc),
    }
    await db.users.insert_one(user_doc)
    await db.invitations.update_one(
        {"id": inv["id"]}, {"$set": {"status": "accepted", "accepted_at": datetime.now(timezone.utc), "accepted_user_id": uid}}
    )
    asyncio.create_task(_notify_invitation_accepted(inv, user_doc["name"]))
    return {"token": make_token(uid), "user": user_to_out(user_doc)}


# === INVITATIONS: CARGA MASIVA POR EXCEL ====================================
# Formato fijo de columnas (A→G), sin fila de encabezado alternativa ni
# mapeo configurable (a diferencia de los importadores de catálogo/gasto
# real): No. (se ignora) | No. de Control | Iniciales | Puesto | Área |
# Rol (especialista/subcoordinador) | Correo. La fila 1 siempre es
# encabezado; los datos empiezan en la fila 2.
class InvitationBulkRowIn(BaseModel):
    fila: Optional[int] = None
    no_control: Optional[str] = None
    name: str
    puesto: Optional[str] = None
    area_name: Optional[str] = None
    role: Optional[str] = None
    email: str


class InvitationBulkCommitIn(BaseModel):
    rows: List[InvitationBulkRowIn]


def _normalize_bulk_role(raw: Any) -> Optional[str]:
    key = _normalize_text(str(raw or "")).replace("-", "").replace("_", "").replace(" ", "")
    if key in {"especialista", "esp", "e"}:
        return "especialista"
    if key in {"subcoordinador", "subcoord", "sub", "s"}:
        return "sub_coordinador"
    return None


def _parse_bulk_invitation_rows(filename: str, content: bytes) -> List[dict]:
    sheets = _read_workbook_sheets(filename, content)
    first_sheet = next(iter(sheets.values()), [])
    data_rows = first_sheet[1:] if len(first_sheet) > 1 else []
    rows: List[dict] = []
    for idx, row in enumerate(data_rows):
        if not row or all(c is None or str(c).strip() == "" for c in row):
            continue
        def cell(i: int):
            return row[i] if i < len(row) else None
        rows.append({
            "fila": idx + 2,  # +1 por encabezado (fila 1), +1 porque Excel es 1-based
            "no_control": cell(1),
            "name": cell(2),
            "puesto": cell(3),
            "area_name": cell(4),
            "role_raw": cell(5),
            "email": cell(6),
        })
    return rows


async def _validate_bulk_invitation_row(
    fila: int, no_control: Any, name: Any, puesto: Any, area_name: Any, role_raw: Any, email: Any,
    *, pid: str, areas_by_name: dict, seen_emails: set,
) -> dict:
    """Valida una fila de la carga masiva de invitaciones. Se reutiliza tal
    cual desde `/bulk_import/validate` (vista previa, no persiste nada) y
    desde `/bulk_import/commit` (re-valida justo antes de insertar, para no
    confiar en lo que el cliente devolvió de la vista previa)."""
    name_clean = str(name or "").strip()
    email_clean = str(email or "").strip().lower()
    area_name_clean = str(area_name or "").strip()
    role = _normalize_bulk_role(role_raw)
    area_id: Optional[str] = None
    estado = "ok"
    motivo: Optional[str] = None

    if not name_clean:
        estado, motivo = "error", "Iniciales vacías"
    elif not email_clean or not re.match(r"^[^\s@]+@[^\s@]+\.[^\s@]+$", email_clean):
        estado, motivo = "error", "Correo inválido"
    elif role is None:
        estado, motivo = "error", 'Rol inválido — usa "especialista" o "subcoordinador"'
    elif email_clean in seen_emails:
        estado, motivo = "error", "Correo duplicado dentro del archivo"

    if estado == "ok" and area_name_clean:
        area = areas_by_name.get(_normalize_text(area_name_clean))
        if area:
            area_id = area["id"]
        else:
            estado, motivo = "error", f'Área "{area_name_clean}" no existe en el proyecto — créala primero en Áreas'

    if estado == "ok" and role == "especialista" and not area_id:
        estado, motivo = "error", "Especialista requiere Área (columna vacía o no encontrada)"

    if estado == "ok" and await db.users.find_one({"email": email_clean}):
        estado, motivo = "error", "Ya existe un usuario con este correo (en otro proyecto)"

    if estado == "ok" and await db.invitations.find_one(
        {"email": email_clean, "status": "pending", "project_id": {"$ne": pid}}
    ):
        estado, motivo = "error", "Ya tiene una invitación pendiente en otro proyecto"

    if estado == "ok" and await db.invitations.find_one(
        {"email": email_clean, "status": "pending", "project_id": pid}
    ):
        estado, motivo = "duplicado", "Ya existe una invitación pendiente para este correo en este proyecto"

    if estado != "error":
        seen_emails.add(email_clean)

    return {
        "fila": fila,
        "no_control": str(no_control).strip() if no_control not in (None, "") else None,
        "name": name_clean,
        "puesto": str(puesto).strip() if puesto not in (None, "") else None,
        "area_name": area_name_clean or None,
        "role": role,
        "email": email_clean,
        "area_id": area_id,
        "estado": estado,
        "motivo": motivo,
    }


@api.get("/projects/{pid}/invitations/bulk_import/plantilla.xlsx")
async def invitations_bulk_template(pid: str, user: dict = Depends(require_role(ROLE_COORD))):
    from openpyxl import Workbook
    from openpyxl.styles import Font, PatternFill, Alignment
    from openpyxl.utils import get_column_letter

    await ensure_project_access(user, pid)
    wb = Workbook()
    ws = wb.active
    ws.title = "Invitaciones"
    headers = ["No.", "No. de Control", "Iniciales", "Puesto", "Área", "Rol", "Correo"]
    header_fill = PatternFill(start_color="1E40AF", end_color="1E40AF", fill_type="solid")
    header_font = Font(color="FFFFFF", bold=True)
    for col, h in enumerate(headers, start=1):
        c = ws.cell(row=1, column=col, value=h)
        c.font = header_font
        c.fill = header_fill
        c.alignment = Alignment(wrap_text=True, vertical="center")
    ws.append([1, "1234", "J. Pérez", "Ingeniero de campo", "Estructura", "especialista", "jperez@example.com"])
    ws.append([2, "5678", "A. López", "Supervisor de obra", "", "subcoordinador", "alopez@example.com"])
    for col, width in enumerate([6, 16, 20, 24, 18, 20, 30], start=1):
        ws.column_dimensions[get_column_letter(col)].width = width

    ws2 = wb.create_sheet("Instrucciones")
    instrucciones = [
        "Cómo llenar esta plantilla:",
        "1. No.: solo cuenta cuántas personas hay, no se importa.",
        "2. No. de Control: número de control interno de la persona (opcional).",
        "3. Iniciales: nombre corto con el que se identificará a la persona en la app.",
        "4. Puesto: puesto de la persona.",
        '5. Área: debe coincidir EXACTAMENTE con una de las áreas ya creadas en el proyecto (pantalla Áreas). '
        'Obligatoria para especialista; opcional para subcoordinador.',
        '6. Rol: escribe "especialista" o "subcoordinador" (sin acentos; mayúsculas/minúsculas no importan).',
        "7. Correo: correo con el que la persona iniciará sesión. No puede repetirse ni estar ya asignado a otro proyecto.",
    ]
    for i, line in enumerate(instrucciones, start=1):
        ws2.cell(row=i, column=1, value=line)
    ws2.column_dimensions["A"].width = 100

    buf = io.BytesIO()
    wb.save(buf)
    buf.seek(0)
    return StreamingResponse(
        buf,
        media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        headers={"Content-Disposition": 'attachment; filename="plantilla_invitaciones_dirac.xlsx"'},
    )


@api.post("/projects/{pid}/invitations/bulk_import/validate")
async def invitations_bulk_validate(
    pid: str, file: UploadFile = File(...), user: dict = Depends(require_role(ROLE_COORD)),
):
    await ensure_project_access(user, pid)
    content = await file.read()
    raw_rows = _parse_bulk_invitation_rows(file.filename or "invitaciones.xlsx", content)
    if not raw_rows:
        raise HTTPException(400, "El archivo no tiene filas de datos (deben empezar en la fila 2).")
    if len(raw_rows) > 500:
        raise HTTPException(400, "Máximo 500 personas por archivo.")

    areas = await db.areas.find({"project_id": pid}).to_list(length=1000)
    areas_by_name = {_normalize_text(a["name"]): a for a in areas}
    seen_emails: set = set()

    filas = []
    for r in raw_rows:
        filas.append(await _validate_bulk_invitation_row(
            r["fila"], r["no_control"], r["name"], r["puesto"], r["area_name"], r["role_raw"], r["email"],
            pid=pid, areas_by_name=areas_by_name, seen_emails=seen_emails,
        ))
    resumen = {
        "total": len(filas),
        "ok": sum(1 for r in filas if r["estado"] == "ok"),
        "error": sum(1 for r in filas if r["estado"] == "error"),
        "duplicado": sum(1 for r in filas if r["estado"] == "duplicado"),
    }
    return {"resumen": resumen, "filas": filas}


@api.post("/projects/{pid}/invitations/bulk_import/commit")
async def invitations_bulk_commit(
    pid: str, body: InvitationBulkCommitIn, user: dict = Depends(require_role(ROLE_COORD)),
):
    project = await ensure_project_access(user, pid)
    if not body.rows:
        raise HTTPException(400, "No hay filas para importar")
    if len(body.rows) > 500:
        raise HTTPException(400, "Máximo 500 personas por archivo.")

    areas = await db.areas.find({"project_id": pid}).to_list(length=1000)
    areas_by_name = {_normalize_text(a["name"]): a for a in areas}
    seen_emails: set = set()

    creados: List[dict] = []
    omitidos: List[dict] = []
    errores: List[dict] = []
    for i, row_in in enumerate(body.rows):
        fila = row_in.fila or (i + 2)
        validado = await _validate_bulk_invitation_row(
            fila, row_in.no_control, row_in.name, row_in.puesto, row_in.area_name, row_in.role, row_in.email,
            pid=pid, areas_by_name=areas_by_name, seen_emails=seen_emails,
        )
        if validado["estado"] == "ok":
            doc = await _validate_and_build_invitation_doc(
                pid, project,
                email=validado["email"], name=validado["name"], role=validado["role"],
                area_id=validado["area_id"], puesto=validado["puesto"], no_control=validado["no_control"],
            )
            doc["creado_por"] = user["id"]
            await db.invitations.insert_one(doc)
            doc.pop("_id", None)
            creados.append(doc)
        elif validado["estado"] == "duplicado":
            omitidos.append(validado)
        else:
            errores.append(validado)

    return {
        "creados": len(creados),
        "omitidos": len(omitidos),
        "con_error": len(errores),
        "invitations": creados,
        "errores": errores,
        "duplicados": omitidos,
    }


# === REPORTS ================================================================
def validate_measurement_value(mtype: str, value: dict):
    if mtype == "coord_latlon":
        lat, lon = value.get("lat"), value.get("lon")
        if not isinstance(lat, (int, float)) or not isinstance(lon, (int, float)):
            raise HTTPException(400, "coord_latlon requiere lat y lon numéricos")
        # Nota: en obra civil usamos UTM (X/Y en cientos de miles o millones),
        # por lo que NO aplicamos restricción geográfica -90/90, -180/180.
    elif mtype == "cadenamiento":
        v = value.get("cadenamiento") or value.get("value")
        if not isinstance(v, str) or not re.match(r"^\d+\+\d{1,4}(\.\d+)?$", v):
            raise HTTPException(400, "cadenamiento formato '5+100' o '5+100.50'")
    elif mtype == "eje":
        v = value.get("eje") or value.get("value")
        if not isinstance(v, str) or not v.strip():
            raise HTTPException(400, "eje requiere texto")
    elif mtype == "nivel":
        v = value.get("nivel") if "nivel" in value else value.get("value")
        if not isinstance(v, (int, float)):
            raise HTTPException(400, "nivel requiere número decimal")
    else:
        raise HTTPException(400, f"measurement_type desconocido: {mtype}")


@api.get("/report-templates")
async def list_report_templates(tipo_obra: Optional[str] = None, user: dict = Depends(current_user)):
    """Plantillas de reporte. Sin `tipo_obra` (o con "legado") devuelve todas, como
    siempre; con un tipo de obra devuelve las que sirven para ese tipo. Cada
    plantilla incluye `tipos_obra` ("*" = cualquier tipo)."""
    if tipo_obra and tipo_obra != TIPO_OBRA_LEGADO and tipo_obra not in TIPOS_OBRA_IDS:
        raise HTTPException(400, f"Tipo de obra inválido: {tipo_obra}")
    cursor = db.report_templates.find({}, {"_id": 0}).sort("name", 1)
    plantillas = await cursor.to_list(length=None)
    salida = []
    for tpl in plantillas:
        tpl["tipos_obra"] = tipos_de_plantilla(tpl)
        if plantilla_visible_para_tipo(tpl, tipo_obra):
            salida.append(tpl)
    return salida


def _normalize_template_code(raw: str) -> str:
    code = (raw or "").strip().lower().replace(" ", "_")
    code = re.sub(r"[^a-z0-9_]", "", code)
    return code


@api.post("/report-templates")
async def create_report_template(body: ReportTemplateIn, user: dict = Depends(require_role(ROLE_COORD))):
    code = _normalize_template_code(body.code)
    if not code:
        raise HTTPException(400, "code requerido")
    name = body.name.strip()
    if not name:
        raise HTTPException(400, "name requerido")
    existing = await db.report_templates.find_one({"code": code})
    if existing:
        raise HTTPException(409, "Ya existe una plantilla con ese código")
    doc = {
        "id": str(uuid.uuid4()),
        "code": code,
        "name": name,
        "category": (body.category or "General").strip() or "General",
        "fields": [f.model_dump() for f in body.fields],
    }
    await db.report_templates.insert_one(doc)
    doc.pop("_id", None)
    return doc


@api.put("/report-templates/{tid}")
async def update_report_template(tid: str, body: ReportTemplatePatch, user: dict = Depends(require_role(ROLE_COORD))):
    tpl = await db.report_templates.find_one({"id": tid})
    if not tpl:
        raise HTTPException(404, "Plantilla no existe")
    update: dict = {}
    if body.name is not None:
        name = body.name.strip()
        if not name:
            raise HTTPException(400, "name no puede quedar vacío")
        update["name"] = name
    if body.category is not None:
        update["category"] = body.category.strip() or "General"
    if body.fields is not None:
        update["fields"] = [f.model_dump() for f in body.fields]
    if update:
        await db.report_templates.update_one({"id": tid}, {"$set": update})
    tpl = await db.report_templates.find_one({"id": tid}, {"_id": 0})
    return tpl


@api.delete("/report-templates/{tid}")
async def delete_report_template(tid: str, user: dict = Depends(require_role(ROLE_COORD))):
    tpl = await db.report_templates.find_one({"id": tid})
    if not tpl:
        raise HTTPException(404, "Plantilla no existe")
    await db.report_templates.delete_one({"id": tid})
    return {"ok": True}


@api.post("/reports")
async def create_report(body: ReportIn, user: dict = Depends(current_user)):
    if user["role"] not in (ROLE_ESPECIALISTA, ROLE_COORD, ROLE_SUB, ROLE_JEFE):
        raise HTTPException(403, "Tu rol no puede capturar reportes")
    # [OFFLINE 2026-08-07] Idempotencia: si este client_id ya se insertó (ej.
    # el cliente reintentó tras perder la respuesta), devolvemos el existente
    # en vez de crear un reporte duplicado. Corta antes de validar nodo/
    # ubicación para no repetir ese trabajo en cada reintento.
    if body.client_id:
        existing = await db.reports.find_one({"client_id": body.client_id})
        if existing:
            existing.pop("_id", None)
            return existing
    await ensure_project_access(user, body.project_id)
    node = await db.location_nodes.find_one({"id": body.node_id, "project_id": body.project_id})
    if not node:
        raise HTTPException(404, "Nodo no existe en este proyecto")
    if not node.get("is_leaf"):
        raise HTTPException(400, "Solo se puede capturar en nodos hoja")
    # Sub-coordinador: scope GLOBAL (puede capturar en cualquier hoja del proyecto).
    # Especialista sin scope_node_ids asignado: acceso GLOBAL (igual que sub-coordinador).
    # ====================================================================
    # FALLBACK DE COORDENADAS DESDE metadata DEL NODO (pre-validación)
    # --------------------------------------------------------------------
    # Si el nodo es coord_latlon y el cliente NO mandó lat/lon válidos,
    # intentamos inyectar X/Y desde node.metadata ANTES de validar para que
    # la captura no falle cuando el Coordinador ya cargó coords vía Excel.
    # El cliente conserva el control: si manda valores, esos se respetan.
    # ====================================================================
    pre_mv = dict(body.measurement_value or {})
    if node.get("measurement_type") == "coord_latlon":
        pre_lat = pre_mv.get("lat")
        pre_lon = pre_mv.get("lon")
        client_valid = (
            isinstance(pre_lat, (int, float)) and isinstance(pre_lon, (int, float))
            and not (pre_lat == 0 and pre_lon == 0)
        )
        if not client_valid:
            node_meta = node.get("metadata") or {}
            inh_x = None
            inh_y = None
            if isinstance(node_meta, dict):
                for k, v in node_meta.items():
                    if v is None or not isinstance(k, str):
                        continue
                    kn = k.strip().lower()
                    for src, dst in (("á","a"),("é","e"),("í","i"),("ó","o"),("ú","u")):
                        kn = kn.replace(src, dst)
                    if kn in {"x", "coordenada x", "coord x"} and inh_x is None:
                        try: inh_x = float(v)
                        except Exception: pass
                    elif kn in {"y", "coordenada y", "coord y"} and inh_y is None:
                        try: inh_y = float(v)
                        except Exception: pass
            if inh_x is not None and inh_y is not None:
                pre_mv["lat"] = inh_y
                pre_mv["lon"] = inh_x
                # marcamos source para que el cierre sepa que fue fallback
                pre_mv["coord_source"] = "node_metadata"
                body.measurement_value = pre_mv

    area_doc = None
    area_name = None
    area_id_efectivo = body.area_id or user.get("area_id")
    if area_id_efectivo:
        area_doc = await db.areas.find_one({"id": area_id_efectivo, "project_id": body.project_id})
    if body.area_id:
        if area_doc:
            area_name = area_doc["name"]
    elif user.get("area"):
        area_name = user["area"]
    # Lo que el Área captura (Personal, Equipo, campos libres) lo define el
    # Coordinador; lo que el Área no captura se descarta aunque el cliente lo mande.
    if area_doc:
        area_doc = _area_con_defaults(area_doc)
        if not area_doc["captura_personal"]:
            body.personnel = []
        if not area_doc["captura_equipo"]:
            body.equipment = []
    campos_extra_rep = _campos_extra_para_reporte(area_doc, body.campos_extra)
    if body.solo_fuerza_trabajo:
        if (not any((p or "").strip() for p in body.personnel)
                and not any((e or "").strip() for e in body.equipment)
                and not campos_extra_rep):
            raise HTTPException(400, "Captura al menos una categoría de personal o de equipo")
    if not (body.solo_fuerza_trabajo and not body.measurement_value):
        validate_measurement_value(node["measurement_type"], body.measurement_value)
    path_names = await node_path_names(body.node_id)
    # Persistimos lecturas P/U también dentro de measurement_value para que el
    # endpoint /history pueda devolverlas a la siguiente captura del nodo.
    mv = dict(body.measurement_value or {})
    if body.primera_lectura is not None:
        mv["primera_lectura"] = body.primera_lectura
    if body.ultima_lectura is not None:
        mv["ultima_lectura"] = body.ultima_lectura

    # ====================================================================
    # Trace de fuente de coordenadas (para auditoría).
    # Si pre-validación ya marcó coord_source=node_metadata, se mantiene.
    # En caso contrario, asumimos user_input.
    # ====================================================================
    if node.get("measurement_type") == "coord_latlon" and "coord_source" not in mv and not body.solo_fuerza_trabajo:
        mv["coord_source"] = "user_input"
    inherited_target = None
    if mv.get("coord_source") == "node_metadata":
        inherited_target = {"lat": mv.get("lat"), "lon": mv.get("lon"), "elev": None}

    # ====================================================================
    # Normalizar severidad (informativo / diario / importante / urgente).
    # Ahora acepta selección múltiple: un reporte puede pertenecer a varios
    # informes a la vez (p.ej. Diario + Mensual). Default = ["informativo"]
    # (no escala a supervisores en exportaciones).
    # ====================================================================
    sev_list = _normalize_severidad_list(body.severidad)

    # Lista de ids ancestrales (incluye el propio nodo) — para filtros y
    # vinculación de noticias a ancestros en la exportación.
    node_path_ids = list(node.get("path") or [])
    if body.node_id not in node_path_ids:
        node_path_ids.append(body.node_id)

    # Thumbnail comprimido persistido: evita transferir el base64 original completo
    # en el feed. Se calcula en un thread aparte por ser CPU-bound (Pillow).
    thumbnail_b64 = None
    if body.images:
        body.images = await asyncio.to_thread(_normalize_images_b64, body.images)
        thumbnail_b64 = await asyncio.to_thread(_compress_image_b64, body.images[0])

    # [OFFLINE 2026-09-09] Si el cliente mandó `captured_at` (hora real de
    # captura en el dispositivo, fijada ANTES de encolar sin conexión), se usa
    # como `created_at` en vez de la hora de llegada al servidor -- de lo
    # contrario un reporte capturado tarde y sincronizado horas/días después
    # (o pasada la medianoche) se fecha con la hora de sincronización y
    # desaparece silenciosamente del informe Diario del día en que en
    # realidad se capturó. Se tolera un rango razonable alrededor de "ahora"
    # para no confiar ciegamente en relojes de dispositivo mal configurados.
    now_utc = datetime.now(timezone.utc)
    effective_created_at = now_utc
    if body.captured_at is not None:
        cap = body.captured_at
        if cap.tzinfo is None:
            cap = cap.replace(tzinfo=timezone.utc)
        if (now_utc - timedelta(days=14)) <= cap <= (now_utc + timedelta(minutes=10)):
            effective_created_at = cap

    doc = {
        "id": str(uuid.uuid4()),
        "project_id": body.project_id,
        "node_id": body.node_id,
        "node_path_names": path_names,
        "node_path_ids": node_path_ids,
        "measurement_type": node["measurement_type"],
        "measurement_value": mv,
        "node_target": inherited_target if inherited_target is not None else (
            {
                "lat": node.get("target_lat"),
                "lon": node.get("target_lon"),
                "elev": node.get("target_elev"),
            } if node.get("measurement_type") == "coord_latlon" else None
        ),
        "area_id": body.area_id or user.get("area_id"),
        "area_name": area_name,
        "title": (body.title or "").strip()[:200] or None,
        "actividades": (body.actividades or "").strip() or None,
        "notes": (body.notes or "").strip() or None,
        "avance": (body.avance or "").strip() or None,
        "observaciones": (body.observaciones or "").strip() or None,
        "incidencias": (body.incidencias or "").strip() or None,
        "severidad": sev_list,
        "gravedad": _normalize_gravedad(body.gravedad),
        "contratista": (body.contratista or "").strip() or None,
        "personnel": body.personnel,
        "equipment": body.equipment,
        "images": body.images,
        "thumbnail_base64": thumbnail_b64,
        "photo_captions": (body.photo_captions or [])[:len(body.images or [])],
        "files": body.files,
        "primera_lectura": body.primera_lectura,
        "ultima_lectura": body.ultima_lectura,
        "unidad": (body.unidad or "m").strip() or "m",
        "captured_by": user["id"],
        "captured_by_name": user["name"],
        "created_at": effective_created_at,
        "template_id": body.template_id or None,
        "dynamic_data": body.dynamic_data or {},
        "campos_extra": campos_extra_rep,
    }
    if area_doc and not area_doc["captura_personal"]:
        doc["captura_personal"] = False
    if area_doc and not area_doc["captura_equipo"]:
        doc["captura_equipo"] = False
    if body.solo_fuerza_trabajo:
        doc["solo_fuerza_trabajo"] = True
    if body.client_id:
        # Solo se agrega si hay valor: el índice es sparse, y una clave con
        # `None` explícito en todos los docs rompería esa exclusión.
        doc["client_id"] = body.client_id
    try:
        await db.reports.insert_one(doc)
    except DuplicateKeyError:
        # Dos reintentos casi simultáneos con el mismo client_id (ej. flush
        # automático y un tap manual de "reintentar" a la vez).
        existing = await db.reports.find_one({"client_id": body.client_id})
        if existing:
            existing.pop("_id", None)
            return existing
        raise
    doc.pop("_id", None)

    # ====================================================================
    # PUSH NOTIFICATION DISPATCH (background, fire-and-forget)
    # --------------------------------------------------------------------
    # Notifica a los supervisores del proyecto (Coordinador General y Jefe
    # de Proyecto) cuando se captura un nuevo reporte. Se ejecuta como
    # tarea en segundo plano con asyncio.create_task() para no bloquear
    # la respuesta al especialista.
    # ====================================================================
    try:
        project = await db.projects.find_one(
            {"id": body.project_id},
            {"_id": 0, "name": 1},
        )
        project_name = (project or {}).get("name") or "el proyecto"
        node_name = (path_names[-1] if path_names else None) or node.get("name") or "nodo"
        asyncio.create_task(
            _notify_supervisors_new_report(
                project_id=body.project_id,
                project_name=project_name,
                node_name=node_name,
                report_id=doc["id"],
                author_id=user["id"],
                author_name=user.get("name") or "Especialista",
            )
        )
    except Exception as exc:  # defensive: nunca rompemos el return del reporte.
        log.exception("[push] no se pudo agendar la notificación: %s", exc)

    # WhatsApp (Whapi.cloud): grupo propio de cada proyecto, también en segundo plano.
    try:
        asyncio.create_task(_whatsapp_enviar_reporte(doc))
    except Exception as exc:
        log.exception("[whatsapp] no se pudo agendar el envío: %s", exc)

    return doc


_WHATSAPP_MAX_FOTOS = 10  # tope por reporte para no saturar el grupo
_WHATSAPP_MAX_CAPTION = 1000  # límite de WhatsApp para el pie de foto (~1024)


_WHATSAPP_MESES = ["enero", "febrero", "marzo", "abril", "mayo", "junio", "julio",
             "agosto", "septiembre", "octubre", "noviembre", "diciembre"]


def _whatsapp_valor_dinamico(v: Any) -> str:
    if v is None or v == "":
        return "-"
    if isinstance(v, bool):
        return "Sí" if v else "No"
    if isinstance(v, list):
        return ", ".join(str(x) for x in v) if v else "-"
    return str(v)


def _whatsapp_texto_reporte(
    doc: dict,
    project: Optional[dict] = None,
    autor_puesto: Optional[str] = None,
    template_fields: Optional[List[dict]] = None,
) -> str:
    """Texto del reporte para WhatsApp: MISMO formato que la vista previa de la
    app (frontend/src/utils/reportText.ts, `buildReportShareText`). Si cambia
    uno, cambiar el otro."""
    project = project or {}
    ts = doc.get("created_at")
    if not isinstance(ts, datetime):
        ts = datetime.now(timezone.utc)
    elif ts.tzinfo is None:
        ts = ts.replace(tzinfo=timezone.utc)
    ts = ts.astimezone(MX_TZ)
    fecha = f"{ts.day} de {_WHATSAPP_MESES[ts.month - 1]} de {ts.year}"

    path_names = doc.get("node_path_names") or []
    hoja = path_names[-1] if path_names else ""

    secciones: List[str] = [
        f"{fecha}.\n{doc.get('captured_by_name') or ''}\n{autor_puesto or ''}",
        f"Constructora: {project.get('constructora') or ''}\nNo de contrato: {project.get('contract_number') or ''}",
    ]
    if hoja:
        secciones.append(hoja)
    if doc.get("actividades"):
        secciones.append(f"*Actividades:*\n{doc['actividades']}")

    dyn = doc.get("dynamic_data") or {}
    if dyn:
        label = {f.get("key"): f.get("label") for f in (template_fields or [])}
        lineas = [f"{label.get(k) or k}: {_whatsapp_valor_dinamico(v)}" for k, v in dyn.items()]
        secciones.append("*Datos del reporte:*\n" + "\n".join(lineas))

    if doc.get("observaciones"):
        secciones.append(f"*Observaciones:*\n{doc['observaciones']}")
    if doc.get("incidencias"):
        secciones.append(f"Incidencias:\n{doc['incidencias']}")
    if doc.get("captura_personal") is not False:
        secciones.append("Personal:\n" + ("\n".join(doc.get("personnel") or []) or "-"))
    if doc.get("captura_equipo") is not False:
        secciones.append("Equipo:\n" + ("\n".join(doc.get("equipment") or []) or "-"))
    extras = doc.get("campos_extra") or []
    if extras:
        secciones.append("\n".join(_campo_extra_texto(c) for c in extras))
    return "\n\n".join(secciones)


def _whatsapp_imagen_para_envio(b64_str: str) -> Optional[str]:
    """Reduce la foto (JPEG, máx. 1600 px) y la devuelve como data URI. Bloqueante."""
    try:
        import base64 as _b64
        from PIL import Image as _PILImage
        from PIL.ImageOps import exif_transpose as _exif
        raw = _b64.b64decode(b64_str.split(",", 1)[-1])
        img = _PILImage.open(io.BytesIO(raw))
        img = _exif(img) or img
        img = img.convert("RGB")
        img.thumbnail((1600, 1600))
        out = io.BytesIO()
        img.save(out, format="JPEG", quality=80, optimize=True)
        return "data:image/jpeg;base64," + _b64.b64encode(out.getvalue()).decode("ascii")
    except Exception:
        log.warning("[whatsapp] no se pudo preparar la imagen", exc_info=True)
        return None


async def _whatsapp_enviar_reporte(doc: dict) -> None:
    """Publica el reporte en el/los grupo(s) de WhatsApp del proyecto (Whapi.cloud).

    Todas las fotos vía POST /messages/image (el texto en la última); sin foto
    (o si el texto no cabe como pie de foto), POST /messages/text. Es
    best-effort: cualquier fallo se loguea y nunca afecta el reporte. Si el
    proyecto no tiene `whatsapp_group_id` (o faltan credenciales) no hace nada.
    """
    try:
        if not WHAPI_TOKEN:
            return
        project = await db.projects.find_one(
            {"id": doc["project_id"]},
            {"_id": 0, "name": 1, "constructora": 1, "contract_number": 1, "whatsapp_group_id": 1},
        )
        group_ids = _whatsapp_group_ids((project or {}).get("whatsapp_group_id"))
        if not group_ids:
            return
        autor = await db.users.find_one({"id": doc.get("captured_by")}, {"_id": 0, "puesto": 1})
        tpl_fields = None
        if doc.get("template_id"):
            tpl = await db.report_templates.find_one({"id": doc["template_id"]}, {"_id": 0, "fields": 1})
            tpl_fields = (tpl or {}).get("fields")
        texto = _whatsapp_texto_reporte(doc, project, (autor or {}).get("puesto"), tpl_fields)
        base = WHAPI_URL.rstrip("/")
        headers = {"Authorization": f"Bearer {WHAPI_TOKEN}", "Accept": "application/json"}

        medias: List[str] = []
        for img_b64 in (doc.get("images") or [])[:_WHATSAPP_MAX_FOTOS]:
            m = await asyncio.to_thread(_whatsapp_imagen_para_envio, img_b64)
            if m:
                medias.append(m)

        # WhatsApp limita el pie de foto (~1024 caracteres): si el texto cabe,
        # va en la ÚLTIMA foto; si no, las fotos van solas y el texto después.
        texto_en_ultima = bool(medias) and len(texto) <= _WHATSAPP_MAX_CAPTION

        async def _enviar_a_grupo(client: "httpx.AsyncClient", group_id: str) -> None:
            resp = None
            for i, media in enumerate(medias):
                es_ultima = i == len(medias) - 1
                resp = await client.post(
                    f"{base}/messages/image",
                    headers=headers,
                    json={"to": group_id, "media": media,
                          "caption": texto if (es_ultima and texto_en_ultima) else ""},
                )
                if resp.status_code >= 300:
                    break
            if not texto_en_ultima and (resp is None or resp.status_code < 300):
                resp = await client.post(
                    f"{base}/messages/text",
                    headers=headers,
                    json={"to": group_id, "body": texto},
                )
            if resp.status_code >= 300:
                log.warning("[whatsapp] Whapi respondió %s para el grupo %s: %s",
                            resp.status_code, group_id, resp.text[:300])
            else:
                log.info("[whatsapp] reporte %s enviado al grupo %s (proyecto %s)",
                         doc.get("id"), group_id, doc["project_id"])

        # Un grupo que falle (ID erróneo, sin permiso...) no impide el envío a los demás.
        async with httpx.AsyncClient(timeout=30.0) as client:
            for group_id in group_ids:
                try:
                    await _enviar_a_grupo(client, group_id)
                except Exception as exc:
                    log.exception("[whatsapp] fallo enviando al grupo %s: %s", group_id, exc)
    except Exception as exc:
        log.exception("[whatsapp] fallo enviando reporte: %s", exc)


async def _notify_supervisors_new_report(
    project_id: str,
    project_name: str,
    node_name: str,
    report_id: str,
    author_id: str,
    author_name: str,
) -> None:
    """
    Carga a los supervisores del proyecto (coordinador_general + jefe_proyecto)
    y dispara `send_push_notification` para cada uno. Se excluye al autor del
    reporte para que no se auto-notifique cuando él mismo lo captura.

    Esta función es defensiva: si un envío falla, se loguea y se continúa con
    el siguiente destinatario.
    """
    try:
        cursor = db.users.find(
            {
                "project_ids": project_id,
                "role": {"$in": [ROLE_COORD, ROLE_JEFE]},
                "deleted_at": {"$exists": False},
            },
            {"_id": 0, "id": 1, "name": 1, "role": 1, "expo_push_tokens": 1},
        )
        recipients = [u async for u in cursor]
    except Exception as exc:
        log.exception("[push] no se pudo cargar destinatarios: %s", exc)
        return

    if not recipients:
        log.info(
            "[push] sin destinatarios (proyecto=%s, autor=%s)",
            project_id,
            author_name,
        )
        return

    title = f"Nuevo reporte en {project_name}"
    body_text = f"{author_name} registró un avance en {node_name}."
    payload = {
        "type": "new_report",
        "project_id": project_id,
        "report_id": report_id,
        "node_name": node_name,
    }

    for recipient in recipients:
        if recipient.get("id") == author_id:
            continue  # Skip self-notification.
        if not (recipient.get("expo_push_tokens") or []):
            continue  # Skip users without registered devices.
        try:
            result = await send_push_notification(
                user_id=recipient["id"],
                title=title,
                body=body_text,
                data=payload,
            )
            log.info(
                "[push] new_report → user=%s sent=%d ok=%s",
                recipient.get("name"),
                result.get("sent", 0),
                result.get("ok"),
            )
        except Exception as exc:
            log.exception(
                "[push] envío falló user=%s: %s",
                recipient.get("name"),
                exc,
            )


@api.get("/projects/{pid}/nodes/{nid}/history")
async def node_history(pid: str, nid: str, user: dict = Depends(current_user)):
    """Devuelve el último reporte del nodo para que el especialista pueda ver
    la lectura previa registrada (helper "Última lectura registrada en este
    nodo: [valor]"). Aplica el mismo RBAC que /reports.
    """
    await ensure_project_access(user, pid)
    node = await db.location_nodes.find_one({"id": nid, "project_id": pid})
    if not node:
        raise HTTPException(404, "Nodo no existe en este proyecto")
    # Sub-coordinador / Especialista sin scope: acceso GLOBAL (sin restricción).

    last = await db.reports.find_one(
        {"project_id": pid, "node_id": nid},
        sort=[("created_at", -1)],
    )
    if not last:
        return {
            "node_id": nid,
            "measurement_type": node.get("measurement_type"),
            "has_previous": False,
            "last_report": None,
        }
    last.pop("_id", None)
    mv = last.get("measurement_value") or {}
    return {
        "node_id": nid,
        "measurement_type": node.get("measurement_type"),
        "has_previous": True,
        "last_report": {
            "id": last.get("id"),
            "created_at": last.get("created_at"),
            "captured_by_name": last.get("captured_by_name"),
            "measurement_value": mv,
            "primera_lectura": mv.get("primera_lectura"),
            "ultima_lectura": mv.get("ultima_lectura"),
            "avance": last.get("avance"),
            "notes": last.get("notes"),
        },
    }


# === Asistencia (Coordinador / Sub-Coordinador) ============================
# La asistencia del Especialista se DERIVA de los reportes: el primer reporte
# del día (hora CDMX) marca su asistencia, con la hora y la ubicación donde
# reportó. La del Sub-Coordinador sale igual de sus reportes, o bien él mismo
# la registra (POST .../asistencia/registrar). Coordinador y Sub-Coordinador
# pueden sobrescribir un día (p. ej. justificar una inasistencia) en
# `db.asistencia`; la del Sub-Coordinador solo la edita él mismo (o el
# Coordinador).
ASISTENCIA_MAX_DIAS = 62


class AsistenciaEditIn(BaseModel):
    # "auto" quita la edición manual y vuelve a lo derivado de los reportes.
    estado: Literal["asistio", "justificada", "falta", "auto"]
    nota: Optional[str] = None


class AsistenciaRegistrarIn(BaseModel):
    lat: Optional[float] = None
    lon: Optional[float] = None


def _asistencia_parse_fecha(s: str) -> date:
    try:
        return date.fromisoformat(s)
    except Exception:
        raise HTTPException(400, "Fecha inválida (usa AAAA-MM-DD)")


def _asistencia_ubicacion(r: dict) -> Tuple[Optional[str], Optional[float], Optional[float]]:
    names = [n for n in (r.get("node_path_names") or []) if n]
    mv = r.get("measurement_value") or {}
    lat, lon = mv.get("lat"), mv.get("lon")
    if not (isinstance(lat, (int, float)) and isinstance(lon, (int, float))) or (lat == 0 and lon == 0):
        lat = lon = None
    return (" › ".join(names) or None), lat, lon


def _asistencia_hora(dt: Any) -> Tuple[Optional[str], Optional[str]]:
    """(fecha ISO, 'HH:MM') en hora CDMX."""
    if not isinstance(dt, datetime):
        return None, None
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    mx = dt.astimezone(MX_TZ)
    return mx.date().isoformat(), mx.strftime("%H:%M")


async def _asistencia_personas(pid: str) -> List[dict]:
    users = await db.users.find(
        {"project_ids": pid, "role": {"$in": [ROLE_ESPECIALISTA, ROLE_SUB]}},
        {"_id": 0, "id": 1, "name": 1, "role": 1, "puesto": 1, "area_id": 1, "area": 1, "created_at": 1},
    ).to_list(length=2000)
    areas = {a["id"]: a.get("name") async for a in db.areas.find({"project_id": pid}, {"_id": 0, "id": 1, "name": 1})}
    out = []
    for u in users:
        alta, _ = _asistencia_hora(u.get("created_at"))
        out.append({
            "id": u["id"], "name": u.get("name") or "", "role": u["role"], "puesto": u.get("puesto"),
            "area_name": areas.get(u.get("area_id")) or u.get("area"),
            "alta": alta,  # antes de esta fecha no se le cuenta falta
        })
    out.sort(key=lambda p: (0 if p["role"] == ROLE_SUB else 1, (p["name"] or "").lower()))
    return out


@api.get("/projects/{pid}/asistencia")
async def get_asistencia(pid: str, desde: str, hasta: str, user: dict = Depends(require_role(ROLE_COORD, ROLE_SUB, ROLE_JEFE))):
    await ensure_project_access(user, pid)
    d0, d1 = _asistencia_parse_fecha(desde), _asistencia_parse_fecha(hasta)
    if d1 < d0:
        raise HTTPException(400, "'hasta' no puede ser anterior a 'desde'")
    if (d1 - d0).days + 1 > ASISTENCIA_MAX_DIAS:
        raise HTTPException(400, f"Rango máximo: {ASISTENCIA_MAX_DIAS} días")
    return await _asistencia_calcular(pid, d0, d1)


async def _asistencia_calcular(pid: str, d0: date, d1: date) -> dict:
    personas = await _asistencia_personas(pid)
    ids = [p["id"] for p in personas]

    start = datetime.combine(d0, datetime.min.time(), tzinfo=MX_TZ).astimezone(timezone.utc)
    end = datetime.combine(d1 + timedelta(days=1), datetime.min.time(), tzinfo=MX_TZ).astimezone(timezone.utc)
    registros: Dict[str, dict] = {}
    cursor = db.reports.find(
        {"project_id": pid, "captured_by": {"$in": ids}, "created_at": {"$gte": start, "$lt": end}},
        {"_id": 0, "captured_by": 1, "created_at": 1, "node_path_names": 1, "measurement_value": 1},
    ).sort("created_at", 1)
    async for r in cursor:
        fecha, hora = _asistencia_hora(r.get("created_at"))
        if not fecha:
            continue
        key = f"{r['captured_by']}|{fecha}"
        if key in registros:
            continue  # el primer reporte del día es el que marca la asistencia
        ubic, lat, lon = _asistencia_ubicacion(r)
        registros[key] = {"estado": "asistio", "hora": hora, "ubicacion": ubic, "lat": lat, "lon": lon, "fuente": "reporte"}

    f0, f1 = d0.isoformat(), d1.isoformat()
    async for a in db.asistencia.find({"project_id": pid, "fecha": {"$gte": f0, "$lte": f1}}, {"_id": 0}):
        key = f"{a['user_id']}|{a['fecha']}"
        base = registros.get(key)
        if a.get("tipo") == "checkin":
            # Auto-registro del Sub-Coordinador: gana el más temprano.
            if base and base.get("hora") and base["hora"] <= (a.get("hora") or "99:99"):
                continue
            registros[key] = {"estado": "asistio", "hora": a.get("hora"), "ubicacion": a.get("ubicacion"),
                              "lat": a.get("lat"), "lon": a.get("lon"), "fuente": "registro"}
        else:  # edición manual (justificada / falta / asistio)
            reg = dict(base or {"hora": None, "ubicacion": None, "lat": None, "lon": None})
            reg.update({"estado": a["estado"], "fuente": "manual", "nota": a.get("nota"),
                        "editado_por": a.get("by_name")})
            registros[key] = reg
    return {"desde": f0, "hasta": f1, "hoy": datetime.now(MX_TZ).date().isoformat(),
            "personas": personas, "registros": registros}


_ASIST_CELDA_TXT = {"ok": "A", "just": "J", "no": "F", "pend": "·", "na": "–"}


def _asistencia_celda(p: dict, fecha: str, data: dict) -> str:
    """Misma regla que `celdaDe` del frontend: ok / just / no / pend / na."""
    reg = data["registros"].get(f"{p['id']}|{fecha}")
    if reg:
        return "ok" if reg["estado"] == "asistio" else "just" if reg["estado"] == "justificada" else "no"
    if fecha > data["hoy"]:
        return "na"
    if fecha == data["hoy"]:
        return "pend"
    if date.fromisoformat(fecha).weekday() == 6:  # domingo sin reporte: descanso
        return "na"
    if p.get("alta") and fecha < p["alta"]:
        return "na"
    return "no"


@api.get("/projects/{pid}/asistencia/export.xlsx")
async def export_asistencia_xlsx(
    pid: str, vista: Literal["hoy", "semana", "mes", "total"], desde: Optional[str] = None, hasta: Optional[str] = None,
    user: dict = Depends(require_role(ROLE_COORD, ROLE_SUB, ROLE_JEFE)),
):
    """Excel de asistencia. `hoy`/`semana`/`mes` usan el rango pedido (el mismo
    que ve la pantalla); `total` abarca desde el alta más antigua hasta hoy."""
    await ensure_project_access(user, pid)
    from openpyxl import Workbook
    from openpyxl.styles import Alignment, Font, PatternFill
    from openpyxl.utils import get_column_letter

    hoy = datetime.now(MX_TZ).date()
    if vista == "total":
        personas0 = await _asistencia_personas(pid)
        altas = [p["alta"] for p in personas0 if p.get("alta")]
        d0 = date.fromisoformat(min(altas)) if altas else hoy
        d1 = hoy
    else:
        if not desde or not hasta:
            raise HTTPException(400, "desde y hasta son requeridos")
        d0, d1 = _asistencia_parse_fecha(desde), _asistencia_parse_fecha(hasta)
        if d1 < d0:
            raise HTTPException(400, "'hasta' no puede ser anterior a 'desde'")
        if (d1 - d0).days + 1 > ASISTENCIA_MAX_DIAS:
            raise HTTPException(400, f"Rango máximo: {ASISTENCIA_MAX_DIAS} días")
    data = await _asistencia_calcular(pid, d0, d1)
    personas = data["personas"]
    dias_l = [(d0 + timedelta(days=i)).isoformat() for i in range((d1 - d0).days + 1)]

    wb = Workbook()
    ws = wb.active
    head_fill = PatternFill("solid", fgColor="1F3864")
    head_font = Font(bold=True, color="FFFFFF")

    def _encabezado(hoja, fila: int):
        for c in hoja[fila]:
            if c.value is not None:
                c.fill, c.font = head_fill, head_font
                c.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)

    def _totales(p: dict) -> tuple:
        ok = just = no = 0
        for f in dias_l:
            c = _asistencia_celda(p, f, data)
            if c == "ok":
                ok += 1
            elif c == "just":
                just += 1
            elif c == "no":
                no += 1
        return ok, just, no

    def rol_txt(p: dict) -> str:
        return "Sub-Coordinador" if p["role"] == ROLE_SUB else "Especialista"

    if vista == "hoy":
        ws.title = "Asistencia diaria"
        ws.append([f"Asistencia del {d0.strftime('%d/%m/%Y')}"])
        ws["A1"].font = Font(bold=True, size=13)
        ws.append(["Persona", "Rol", "Puesto", "Área", "Estado", "Hora", "Ubicación", "Fuente", "Nota"])
        _encabezado(ws, 2)
        estado_txt = {"ok": "Asistió", "just": "Justificada", "no": "Falta", "pend": "Sin reporte", "na": "Descanso"}
        for p in personas:
            c = _asistencia_celda(p, d0.isoformat(), data)
            reg = data["registros"].get(f"{p['id']}|{d0.isoformat()}") or {}
            ws.append([p["name"], rol_txt(p), p.get("puesto") or "", p.get("area_name") or "", estado_txt[c],
                       reg.get("hora") or "", reg.get("ubicacion") or "", reg.get("fuente") or "", reg.get("nota") or ""])
        anchos = [28, 16, 20, 20, 14, 8, 36, 12, 36]
    elif vista in ("semana", "mes"):
        ws.title = "Asistencia semanal" if vista == "semana" else "Asistencia mensual"
        ws.append([f"Asistencia del {d0.strftime('%d/%m/%Y')} al {d1.strftime('%d/%m/%Y')}  (A=Asistió, J=Justificada, F=Falta, ·=Pendiente, –=Descanso/No aplica)"])
        ws["A1"].font = Font(bold=True, size=12)
        ws.append(["Persona", "Rol", "Puesto"]
                  + [f"{date.fromisoformat(f).day}\n{'LMMJVSD'[date.fromisoformat(f).weekday()]}" for f in dias_l]
                  + ["Asistencias", "Justificadas", "Faltas", "% Asistencia"])
        _encabezado(ws, 2)
        for p in personas:
            ok, just, no = _totales(p)
            base = ok + just + no
            ws.append([p["name"], rol_txt(p), p.get("puesto") or ""]
                      + [_ASIST_CELDA_TXT[_asistencia_celda(p, f, data)] for f in dias_l]
                      + [ok, just, no, round((ok + just) / base, 4) if base else None])
            ws.cell(row=ws.max_row, column=ws.max_column).number_format = "0.0%"
            for c in ws[ws.max_row][3:3 + len(dias_l)]:
                c.alignment = Alignment(horizontal="center")
        anchos = [28, 16, 20] + [4.5] * len(dias_l) + [12, 12, 8, 13]
    else:
        ws.title = "Total"
        ws.append([f"Asistencia total del {d0.strftime('%d/%m/%Y')} al {d1.strftime('%d/%m/%Y')}"])
        ws["A1"].font = Font(bold=True, size=13)
        ws.append(["Persona", "Rol", "Puesto", "Área", "Alta", "Asistencias", "Justificadas", "Faltas", "% Asistencia"])
        _encabezado(ws, 2)
        for p in personas:
            ok, just, no = _totales(p)
            base = ok + just + no
            ws.append([p["name"], rol_txt(p), p.get("puesto") or "", p.get("area_name") or "", p.get("alta") or "",
                       ok, just, no, round((ok + just) / base, 4) if base else None])
            ws.cell(row=ws.max_row, column=9).number_format = "0.0%"
        anchos = [28, 16, 20, 20, 12, 12, 12, 8, 13]
        # Hoja por mes: asistencias (incluye justificadas) y faltas de cada persona.
        meses = sorted({f[:7] for f in dias_l})
        wm = wb.create_sheet("Por mes")
        wm.append(["Persona"] + [h for m in meses for h in (f"{m} Asist.", f"{m} Faltas")])
        _encabezado(wm, 1)
        for p in personas:
            fila = [p["name"]]
            for m in meses:
                ok = no = 0
                for f in (x for x in dias_l if x[:7] == m):
                    c = _asistencia_celda(p, f, data)
                    ok += c in ("ok", "just")
                    no += c == "no"
                fila += [ok, no]
            wm.append(fila)
        wm.column_dimensions["A"].width = 28
        for i in range(2, 2 + 2 * len(meses)):
            wm.column_dimensions[get_column_letter(i)].width = 13
    for i, w in enumerate(anchos, start=1):
        ws.column_dimensions[get_column_letter(i)].width = w
    ws.freeze_panes = "B3"

    buf = io.BytesIO()
    wb.save(buf)
    buf.seek(0)
    sufijo = {"hoy": d0.isoformat(), "semana": f"{d0.isoformat()}_{d1.isoformat()}",
              "mes": d0.strftime("%Y-%m"), "total": f"total_{hoy.isoformat()}"}[vista]
    return StreamingResponse(
        buf,
        media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        headers={"Content-Disposition": f'attachment; filename="asistencia_{sufijo}.xlsx"'},
    )


@api.put("/projects/{pid}/asistencia/{uid}/{fecha}")
async def put_asistencia(pid: str, uid: str, fecha: str, body: AsistenciaEditIn,
                         user: dict = Depends(require_role(ROLE_COORD, ROLE_SUB))):
    await ensure_project_access(user, pid)
    f = _asistencia_parse_fecha(fecha)
    if f > datetime.now(MX_TZ).date():
        raise HTTPException(400, "No se puede editar la asistencia de un día futuro")
    target = await db.users.find_one({"id": uid, "project_ids": pid, "role": {"$in": [ROLE_ESPECIALISTA, ROLE_SUB]}})
    if not target:
        raise HTTPException(404, "Persona no encontrada en este proyecto")
    if target["role"] == ROLE_SUB and user["role"] == ROLE_SUB and user["id"] != uid:
        raise HTTPException(403, "La asistencia de un Sub-Coordinador solo la edita él mismo o el Coordinador")
    flt = {"project_id": pid, "user_id": uid, "fecha": f.isoformat(), "tipo": "edicion"}
    if body.estado == "auto":
        await db.asistencia.delete_one(flt)  # solo la edición manual; el auto-registro se conserva
        return {"ok": True}
    await db.asistencia.update_one(flt, {"$set": {
        "estado": body.estado, "nota": (body.nota or "").strip()[:300] or None,
        "by": user["id"], "by_name": user.get("name"), "updated_at": datetime.now(timezone.utc),
    }, "$setOnInsert": {"id": str(uuid.uuid4())}}, upsert=True)
    return {"ok": True}


@api.post("/projects/{pid}/asistencia/registrar")
async def registrar_asistencia(pid: str, body: AsistenciaRegistrarIn, user: dict = Depends(require_role(ROLE_SUB))):
    """El Sub-Coordinador registra su propia asistencia de hoy (hora CDMX del servidor)."""
    await ensure_project_access(user, pid)
    now = datetime.now(MX_TZ)
    flt = {"project_id": pid, "user_id": user["id"], "fecha": now.date().isoformat(), "tipo": "checkin"}
    if await db.asistencia.find_one(flt):
        return {"ok": True, "ya_registrada": True}
    ubic = None
    if body.lat is not None and body.lon is not None and not (body.lat == 0 and body.lon == 0):
        ubic = f"{body.lat:.5f}, {body.lon:.5f}"
    await db.asistencia.insert_one({
        **flt, "id": str(uuid.uuid4()), "estado": "asistio", "hora": now.strftime("%H:%M"),
        "lat": body.lat, "lon": body.lon, "ubicacion": ubic,
        "by": user["id"], "by_name": user.get("name"), "updated_at": datetime.now(timezone.utc),
    })
    return {"ok": True, "ya_registrada": False}


@api.get("/projects/{pid}/reports")
async def list_reports(pid: str, user: dict = Depends(current_user)):
    await ensure_project_access(user, pid)
    q: dict = {"project_id": pid}
    # Sub-coordinador / Especialista sin scope: acceso GLOBAL al listado (sin filtro).
    items = await db.reports.find(q).sort("created_at", -1).to_list(length=2000)
    for it in items:
        it.pop("_id", None)
        it["severidad"] = _normalize_severidad_list(it.get("severidad"))
        it["gravedad"] = _normalize_gravedad(it.get("gravedad"))
    return items


def _normalize_report_photo_b64(b64_str, max_dim: int = 2000, quality: int = 85):
    """Normaliza una foto (data URL o base64) a JPEG: abre HEIC/HEIF/WebP/PNG/JPEG de
    cualquier tamaño, respeta la rotación EXIF y limita el lado mayor a `max_dim`.
    Si la imagen no se puede procesar se devuelve tal cual (nunca se pierde la foto).
    Bloqueante (CPU-bound): invocar vía asyncio.to_thread."""
    if not isinstance(b64_str, str) or not b64_str.startswith("data:image/"):
        return b64_str
    try:
        import base64 as _b64
        from PIL import Image as _PILImage
        from PIL.ImageOps import exif_transpose as _pil_exif_transpose
        raw = _b64.b64decode(b64_str.split(",", 1)[-1])
        img = _PILImage.open(io.BytesIO(raw))
        try:
            img.draft("RGB", (max_dim * 2, max_dim * 2))  # JPEG enormes: decodifica reducido
        except Exception:
            pass
        img = _pil_exif_transpose(img) or img
        img = img.convert("RGB")
        img.thumbnail((max_dim, max_dim))
        out = io.BytesIO()
        img.save(out, format="JPEG", quality=quality, optimize=True)
        return "data:image/jpeg;base64," + _b64.b64encode(out.getvalue()).decode("ascii")
    except Exception:
        log.warning("No se pudo normalizar la foto; se guarda el original", exc_info=True)
        return b64_str


def _normalize_images_b64(items):
    return [_normalize_report_photo_b64(i) for i in (items or [])]


# ---- FEED endpoint (Specialist Dashboard) ---------------------------------
def _compress_image_b64(b64_str: Optional[str], max_dim: int = 320, quality: int = 55) -> Optional[str]:
    """Genera un thumbnail JPEG comprimido (base64) a partir de una imagen base64 original.

    Usado para mantener el feed liviano sin transferir el base64 completo de la foto
    en cada respuesta. Devuelve None si la imagen es inválida o Pillow no está disponible.
    Es una función bloqueante (CPU-bound): debe invocarse vía asyncio.to_thread.
    """
    if not b64_str:
        return None
    try:
        import base64 as _b64
        from PIL import Image as _PILImage
        from PIL.ImageOps import exif_transpose as _pil_exif_transpose
        raw = _b64.b64decode(b64_str.split(",", 1)[-1])
        img = _PILImage.open(io.BytesIO(raw))
        img = _pil_exif_transpose(img) or img
        img = img.convert("RGB")
        img.thumbnail((max_dim, max_dim))
        out = io.BytesIO()
        img.save(out, format="JPEG", quality=quality, optimize=True)
        return _b64.b64encode(out.getvalue()).decode("ascii")
    except Exception:
        log.warning("No se pudo generar thumbnail comprimido", exc_info=True)
        return None


def _compress_missing_thumbnails(raw_items: List[dict]) -> dict:
    """Calcula en batch (bloqueante) los thumbnails de items legacy sin `thumbnail_base64`
    persistido, a partir de la primera imagen de su array `images`. Se ejecuta una sola
    vez vía asyncio.to_thread para no bloquear el event loop por cada item individual."""
    out: dict = {}
    for it in raw_items:
        if it.get("thumbnail_base64"):
            continue
        imgs = it.get("images") or []
        if not imgs:
            continue
        thumb = _compress_image_b64(imgs[0])
        if thumb:
            out[it["id"]] = thumb
    return out


def _feed_day_bounds(date_str: str, zona=None) -> Optional[tuple]:
    """Convierte 'YYYY-MM-DD' (día natural de la zona del proyecto; CDMX por
    defecto) en (inicio, fin) UTC."""
    try:
        y, m, d = (int(x) for x in date_str.split("-"))
        start_mx = datetime(y, m, d, 0, 0, 0, tzinfo=zona or MX_TZ)
    except Exception:
        return None
    end_mx = start_mx + timedelta(days=1)
    return start_mx.astimezone(timezone.utc), end_mx.astimezone(timezone.utc)


def _inicio_semana_local(now_local: datetime, project: Optional[dict] = None) -> datetime:
    """00:00 del primer día de la semana (lunes por defecto) en la zona de `now_local`."""
    ini = inicio_semana(now_local.date(), (project or {}).get("dia_inicio_semana"))
    return datetime(ini.year, ini.month, ini.day, tzinfo=now_local.tzinfo)


def _feed_range_start(rng: str, project: Optional[dict] = None) -> Optional[datetime]:
    """Devuelve el inicio del rango en UTC (zona del proyecto; CDMX por defecto).

    today  → hoy 00:00
    week   → inicio de la semana (lunes, o el `dia_inicio_semana` del proyecto)
    month  → día 1 del mes actual
    all/None → None (sin filtro temporal)
    """
    now_utc = datetime.now(timezone.utc)
    now_mx = now_utc.astimezone(zona_proyecto(project))
    rng = (rng or "today").lower()

    if rng == "today":
        start_mx = now_mx.replace(hour=0, minute=0, second=0, microsecond=0)
        return start_mx.astimezone(timezone.utc)

    if rng == "week":
        return _inicio_semana_local(now_mx, project).astimezone(timezone.utc)

    if rng == "month":
        # [FIX] Mes natural (día 1)
        start_mx = now_mx.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
        return start_mx.astimezone(timezone.utc)

    return None


@api.get("/projects/{pid}/reports/feed")
async def reports_feed(
    pid: str,
    range: str = "today",
    limit: int = 50,
    skip: int = 0,
    q: Optional[str] = None,
    node: Optional[str] = None,
    area: Optional[str] = None,
    date: Optional[str] = None,
    since: Optional[str] = None,
    user: dict = Depends(current_user),
):
    """Feed consolidado para Especialistas / Sub-Coordinadores / Coordinadores.

    Devuelve estadísticas (total, mine, others) y una página de reportes recientes
    livianos (thumbnail comprimido, conteo del resto de imágenes). Soporta
    paginación real vía `skip`/`limit` para scroll infinito sin cargar todo el
    historial en memoria. Aplica el mismo scope RBAC que list_reports.

    Búsqueda inteligente (`q`): filtra reportes cuyo `title`, `notes`,
    `observaciones`, `incidencias`, `contratista`, `captured_by_name` o
    cualquier segmento de `node_path_names` contenga el texto (case-insensitive).

    `node`/`area`: filtran por el nombre exacto del nodo raíz (Tramo) o del área.
    `date`: filtra un día natural CDMX exacto ('YYYY-MM-DD'), con prioridad sobre `range`.
    `since`: chequeo ligero de reportes nuevos — filtra `created_at` estrictamente
    posterior al ISO datetime dado, ignora `skip`/`range`/`date` y ordena desc.
    """
    proj_feed = await ensure_project_access(user, pid)
    query: dict = {"project_id": pid}
    # Sub-coordinador/Coordinador/Especialista sin scope: feed GLOBAL (sin restricción).

    since_dt: Optional[datetime] = None
    if since:
        try:
            since_dt = datetime.fromisoformat(since.replace("Z", "+00:00"))
        except Exception:
            since_dt = None

    if since_dt is not None:
        query["created_at"] = {"$gt": since_dt}
    else:
        day_bounds = _feed_day_bounds(date, zona_proyecto(proj_feed)) if date else None
        if day_bounds is not None:
            query["created_at"] = {"$gte": day_bounds[0], "$lt": day_bounds[1]}
        else:
            start = _feed_range_start(range, proj_feed)
            if start is not None:
                query["created_at"] = {"$gte": start}

    if node:
        query["node_path_names.0"] = node
    if area:
        query["area_name"] = area

    # Búsqueda inteligente por texto libre — regex case-insensitive sobre
    # múltiples campos. Se escapan meta-caracteres regex para evitar errores
    # cuando el usuario escribe símbolos.
    q_txt = (q or "").strip()
    if q_txt:
        import re as _re
        pat = _re.escape(q_txt)
        query["$or"] = [
            {"title": {"$regex": pat, "$options": "i"}},
            {"notes": {"$regex": pat, "$options": "i"}},
            {"observaciones": {"$regex": pat, "$options": "i"}},
            {"incidencias": {"$regex": pat, "$options": "i"}},
            {"contratista": {"$regex": pat, "$options": "i"}},
            {"captured_by_name": {"$regex": pat, "$options": "i"}},
            {"node_path_names": {"$regex": pat, "$options": "i"}},
        ]

    # Conteos agregados por captured_by (con un solo round trip). Refleja el
    # total real de TODA la query (no solo la página), útil para badges "Todos (N)".
    pipeline = [
        {"$match": query},
        {"$group": {"_id": "$captured_by", "count": {"$sum": 1}}},
    ]
    groups = await db.reports.aggregate(pipeline).to_list(length=10000)
    total = sum(int(g.get("count", 0)) for g in groups)
    mine = sum(int(g.get("count", 0)) for g in groups if g.get("_id") == user["id"])
    others = total - mine

    # Página de items livianos (orden desc, skip/limit reales de Mongo).
    safe_limit = max(1, min(int(limit or 50), 200))
    safe_skip = max(0, int(skip or 0))
    if since_dt is not None:
        # Chequeo ligero de "nuevos desde X": sin paginar, tope razonable.
        safe_skip = 0
        safe_limit = min(safe_limit, 50)
    # Nunca traer el array `images` completo (fotos base64, hasta ~8MB c/u):
    # el feed solo necesita un thumbnail y el conteo. Se recorta a la
    # primera imagen (insumo del fallback de thumbnail legacy de abajo) y el
    # conteo real se computa en Mongo antes del recorte, no en Python.
    pipeline_items = [
        {"$match": query},
        {"$sort": {"created_at": -1}},
        {"$skip": safe_skip},
        {"$limit": safe_limit},
        {"$addFields": {
            "images_count": {"$size": {"$ifNull": ["$images", []]}},
            "images": {"$slice": [{"$ifNull": ["$images", []]}, 1]},
        }},
    ]
    raw_items = await db.reports.aggregate(pipeline_items).to_list(length=safe_limit)

    # Fallback: thumbnails de reportes legacy sin `thumbnail_base64` persistido.
    # Bloqueante (Pillow) — se ejecuta una sola vez en un thread aparte para
    # no trabar el event loop por cada item individual.
    fallback_thumbs = await asyncio.to_thread(_compress_missing_thumbnails, raw_items)
    # Se persiste de inmediato para que las próximas cargas del feed reutilicen
    # el thumbnail ya calculado en vez de re-decodificar la imagen original
    # completa cada vez (esto era lo que relentizaba el feed progresivamente
    # a medida que crecía el número de reportes legacy sin thumbnail).
    if fallback_thumbs:
        for rid, thumb in fallback_thumbs.items():
            await db.reports.update_one({"id": rid}, {"$set": {"thumbnail_base64": thumb}})

    # Mapa de áreas (para color y nombre real).
    area_ids = {it.get("area_id") for it in raw_items if it.get("area_id")}
    areas_by_id: dict = {}
    if area_ids:
        async for a in db.areas.find({"id": {"$in": list(area_ids)}}):
            areas_by_id[a["id"]] = {"name": a.get("name"), "color": a.get("color")}

    items_out = []
    for it in raw_items:
        area_id = it.get("area_id")
        area_info = areas_by_id.get(area_id) if area_id else None
        items_out.append({
            "id": it["id"],
            "project_id": it["project_id"],
            "node_id": it["node_id"],
            "node_path_names": it.get("node_path_names") or [],
            "measurement_type": it.get("measurement_type"),
            "measurement_value": it.get("measurement_value") or {},
            "title": it.get("title"),
            "area_id": area_id,
            "area_name": (area_info or {}).get("name") or it.get("area_name"),
            "area_color": (area_info or {}).get("color"),
            "avance": it.get("avance"),
            "contratista": it.get("contratista"),
            "incidencias": it.get("incidencias"),
            "severidad": _normalize_severidad_list(it.get("severidad")),
            "gravedad": _normalize_gravedad(it.get("gravedad")),
            "personnel": it.get("personnel") or [],
            "equipment": it.get("equipment") or [],
            "captured_by": it.get("captured_by"),
            "captured_by_name": it.get("captured_by_name"),
            "actividades": it.get("actividades"),
            "notes": it.get("notes"),
            "observaciones": it.get("observaciones"),
            "is_mine": it.get("captured_by") == user["id"],
            "images_count": it.get("images_count", 0),
            "thumbnail_base64": it.get("thumbnail_base64") or fallback_thumbs.get(it["id"]),
            "created_at": it.get("created_at"),
        })

    return {
        "range": range,
        "skip": safe_skip,
        "has_more": len(raw_items) == safe_limit,
        "stats": {"total": total, "mine": mine, "others": others},
        "reports": items_out,
    }


@api.get("/reports/{rid}")
async def get_report(rid: str, user: dict = Depends(current_user)):
    r = await db.reports.find_one({"id": rid})
    if not r:
        raise HTTPException(404, "Reporte no existe")
    await ensure_project_access(user, r["project_id"])
    # Scope check
    # Sub-coordinador / Especialista sin scope: acceso GLOBAL (sin filtro).
    r.pop("_id", None)
    r["severidad"] = _normalize_severidad_list(r.get("severidad"))
    r["gravedad"] = _normalize_gravedad(r.get("gravedad"))
    return r


# ---------------------------------------------------------------------------
# COLLAGE 2x2 (Fallback nativo para compartir en WhatsApp / mensajeros)
# ---------------------------------------------------------------------------
@api.get("/reports/{rid}/collage.jpg")
async def get_report_collage(rid: str, user: dict = Depends(current_user)):
    """Devuelve un JPEG con un collage 2x2 de hasta 4 fotos del reporte.
    Diseñado como fallback de compartir nativo: una sola imagen unificada
    incluye todo el material fotográfico clave del reporte.
    """
    r = await db.reports.find_one({"id": rid})
    if not r:
        raise HTTPException(404, "Reporte no existe")
    await ensure_project_access(user, r["project_id"])
    imgs = (r.get("images") or [])[:4]
    if not imgs:
        raise HTTPException(404, "El reporte no tiene fotografías")

    from PIL import Image, ImageDraw, ImageFont  # noqa: WPS433

    # Lienzo final 1600x1600 (cuadrado, compatible con previews de WhatsApp).
    CANVAS = 1600
    GAP = 16
    CELL = (CANVAS - 3 * GAP) // 2  # 784 px por celda
    canvas = Image.new("RGB", (CANVAS, CANVAS), (245, 246, 250))

    # Cargar y normalizar cada imagen como un cuadrado CELL x CELL (cover).
    cells = []
    for b64 in imgs:
        try:
            raw = base64.b64decode(_strip_b64_prefix(b64))
            im = Image.open(io.BytesIO(raw)).convert("RGB")
            # Cover crop: escalar y recortar al centro
            iw, ih = im.size
            ratio = max(CELL / iw, CELL / ih)
            new_w, new_h = int(iw * ratio), int(ih * ratio)
            im = im.resize((new_w, new_h), Image.LANCZOS)
            left = (new_w - CELL) // 2
            top = (new_h - CELL) // 2
            im = im.crop((left, top, left + CELL, top + CELL))
            cells.append(im)
        except Exception:
            placeholder = Image.new("RGB", (CELL, CELL), (220, 220, 220))
            cells.append(placeholder)

    positions = [
        (GAP, GAP),
        (GAP * 2 + CELL, GAP),
        (GAP, GAP * 2 + CELL),
        (GAP * 2 + CELL, GAP * 2 + CELL),
    ]
    for i, cell in enumerate(cells):
        if i >= 4:
            break
        canvas.paste(cell, positions[i])

    # Marca Dirac discreta en la esquina inferior derecha
    try:
        draw = ImageDraw.Draw(canvas)
        try:
            font = ImageFont.truetype("/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf", 22)
        except Exception:
            font = ImageFont.load_default()
        stamp = f"Dirac · {len(cells)} foto{'s' if len(cells) != 1 else ''}"
        bbox = draw.textbbox((0, 0), stamp, font=font)
        w = bbox[2] - bbox[0]
        h = bbox[3] - bbox[1]
        pad = 10
        x0 = CANVAS - w - 2 * pad - GAP
        y0 = CANVAS - h - 2 * pad - GAP
        draw.rectangle([x0, y0, x0 + w + 2 * pad, y0 + h + 2 * pad],
                       fill=(15, 23, 42))
        draw.text((x0 + pad, y0 + pad), stamp, fill=(255, 255, 255), font=font)
    except Exception:
        pass

    buf = io.BytesIO()
    canvas.save(buf, format="JPEG", quality=88, optimize=True)
    buf.seek(0)
    return StreamingResponse(
        buf,
        media_type="image/jpeg",
        headers={"Content-Disposition": f'inline; filename="collage_{rid[:8]}.jpg"'},
    )




@api.delete("/reports/{rid}")
async def delete_report(rid: str, user: dict = Depends(current_user)):
    r = await db.reports.find_one({"id": rid})
    if not r:
        raise HTTPException(404, "Reporte no existe")
    if user["role"] != ROLE_COORD and r["captured_by"] != user["id"]:
        raise HTTPException(403, "Solo el autor o un Coordinador General puede borrar")
    await db.reports.delete_one({"id": rid})
    return {"ok": True}


# --- Edición de descripciones individuales por foto ------------------------
# Endpoint quirúrgico que sólo permite modificar `photo_captions` sin tocar
# ningún otro dato del reporte. Cualquier miembro con acceso al proyecto y
# que sea el autor (o Coordinador General / Jefe de Proyecto) puede editar.
class ReportCaptionsPatch(BaseModel):
    photo_captions: List[str] = Field(default_factory=list)


@api.patch("/reports/{rid}/captions", response_model=ReportOut)
async def patch_report_captions(
    rid: str,
    body: ReportCaptionsPatch,
    user: dict = Depends(current_user),
):
    r = await db.reports.find_one({"id": rid})
    if not r:
        raise HTTPException(404, "Reporte no existe")
    # Autorización: autor original o roles supervisores (Coord General, Jefe
    # de Proyecto, Sub-Coordinador — mismo criterio que severity/workforce-entry).
    if user.get("role") not in (ROLE_COORD, ROLE_JEFE, ROLE_SUB) and r.get("captured_by") != user["id"]:
        raise HTTPException(403, "Solo el autor o un Coordinador puede editar descripciones")
    # Sanitizamos: máximo 160 chars por caption y sólo se guardan hasta el
    # número real de imágenes que tiene el reporte (tope duro = 2 en export).
    raw_caps = body.photo_captions or []
    total_imgs = len(r.get("images") or [])
    cleaned = []
    for i, c in enumerate(raw_caps[:total_imgs]):
        s = (c or "").strip()
        if len(s) > 160:
            s = s[:160]
        cleaned.append(s)
    await db.reports.update_one(
        {"id": rid},
        {"$set": {"photo_captions": cleaned}},
    )
    updated = await db.reports.find_one({"id": rid}, {"_id": 0})
    return updated


# --- Edición de severidad del reporte ---------------------------------------
class ReportSeverityPatch(BaseModel):
    # Acepta un string único (legacy) o una lista (selección múltiple).
    severidad: Any


@api.patch("/reports/{rid}/severity", response_model=ReportOut)
async def patch_report_severity(
    rid: str,
    body: ReportSeverityPatch,
    user: dict = Depends(current_user),
):
    r = await db.reports.find_one({"id": rid})
    if not r:
        raise HTTPException(404, "Reporte no existe")
    # Autorización: Autor original, Sub-coordinador o Coordinador General.
    # Jefe de Proyecto es explícitamente de solo lectura (ver ROLE_JEFE) y NO
    # debe poder editar la jerarquía del reporte, en ningún momento.
    is_author = r.get("captured_by") == user["id"]
    is_mgmt = user.get("role") in (ROLE_COORD, ROLE_SUB)

    if not (is_author or is_mgmt):
        raise HTTPException(403, "No tienes permiso para cambiar la severidad de este reporte")

    sev_list = _normalize_severidad_list(body.severidad)
    await db.reports.update_one(
        {"id": rid},
        {"$set": {"severidad": sev_list}},
    )
    updated = await db.reports.find_one({"id": rid}, {"_id": 0})
    return updated


