CM_MAX_OPCIONES = 60
CM_MAX_MODULOS_POR_PROYECTO = 60
CM_MAX_FOTOS_EXPORT = 200
CM_MAX_GRAFICAS = 6
CM_MAX_FILAS_IMPORT = 1000
