# --- Endpoints: registros ---------------------------------------------------
def _cm_assert_puede_capturar(modulo: dict, user: dict) -> None:
    _assert_write_allowed(user)
    if not modulo.get("activo"):
        raise HTTPException(403, "Este módulo está apagado")
    if modulo.get("solo_coordinacion") and user.get("role") not in (ROLE_COORD, ROLE_SUB):
        raise HTTPException(403, "Este módulo solo lo captura la coordinación")


def _cm_assert_puede_editar(existente: dict, user: dict) -> None:
    if user.get("role") not in (ROLE_COORD, ROLE_SUB) and existente.get("created_by") != user["id"]:
        raise HTTPException(403, "Solo puedes editar los registros que tú capturaste")


async def _cm_siguiente_folio(modulo: dict) -> Optional[str]:
    """Folio consecutivo (atómico) si el módulo lo tiene activado."""
    op = modulo["opciones"]
    if not op.get("folio_activo"):
        return None
    doc = await db.custom_modules.find_one_and_update(
        {"id": modulo["id"]}, {"$inc": {"folio_contador": 1}}, return_document=ReturnDocument.AFTER)
    n = int((doc or {}).get("folio_contador", 1)) + max(0, int(op.get("folio_inicio", 1)) - 1)
    return f"{op.get('folio_prefijo', '')}{str(n).zfill(int(op.get('folio_digitos', 4)))}"


def _cm_captured_at(raw) -> Optional[datetime]:
    """Hora real de captura (dispositivo) si es creíble: entre hace 30 días y
    10 minutos en el futuro; si no, None (se usa la hora del servidor)."""
    try:
        dt = datetime.fromisoformat(str(raw).replace("Z", "+00:00"))
    except ValueError:
        return None
    dt = _cm_aware(dt)
    ahora = datetime.now(timezone.utc)
    return dt if ahora - timedelta(days=30) <= dt <= ahora + timedelta(minutes=10) else None


async def _cm_alta_registro(pid: str, modulo: dict, body: dict, user: dict, client_id: Optional[str] = None) -> dict:
    """Crea un registro. Con `client_id` es idempotente (reintentos de la cola
    offline no duplican)."""
    if client_id:
        ya = await db.custom_module_records.find_one(
            {"project_id": pid, "module_id": modulo["id"], "client_id": client_id}, {"fotos": 0, "historial": 0})
        if ya:
            return _cm_registro_public(ya)
    valores, fotos, thumbs = await _cm_construye_registro(modulo, body, None)
    now = datetime.now(timezone.utc)
    creado = _cm_captured_at(body.get("captured_at")) or now
    doc = {
        "id": str(uuid.uuid4()), "project_id": pid, "module_id": modulo["id"],
        "fecha": _prueba_calidad_fecha(body.get("fecha")),
        "valores": valores, "fotos": fotos, "thumbs": thumbs,
        "jerarquia": _jerarquia_modulo(body.get("jerarquia")) if modulo.get("usar_jerarquia") else None,
        "folio": await _cm_siguiente_folio(modulo), "client_id": client_id,
        "cierres": _cm_cierres(modulo, valores, None, creado),
        "n_ediciones": 0,
        "historial": [{"at": creado, "by": user["id"], "by_name": user["name"], "accion": "creado", "cambios": []}],
        "created_by": user["id"], "created_by_name": user["name"], "created_at": creado, "updated_at": now,
    }
    await db.custom_module_records.insert_one(doc)
    return _cm_registro_public(doc)


async def _cm_edita_registro(pid: str, modulo: dict, existente: dict, body: dict, user: dict) -> dict:
    upd: dict = {"updated_at": datetime.now(timezone.utc)}
    valores, fotos, thumbs = existente.get("valores") or {}, existente.get("fotos") or {}, existente.get("thumbs") or {}
    if "valores" in body:
        valores, fotos, thumbs = await _cm_construye_registro(modulo, body, existente)
        upd.update({"valores": valores, "fotos": fotos, "thumbs": thumbs})
    fecha = _prueba_calidad_fecha(body.get("fecha")) if "fecha" in body else existente.get("fecha")
    upd["fecha"] = fecha
    if "jerarquia" in body and modulo.get("usar_jerarquia"):
        upd["jerarquia"] = _jerarquia_modulo(body.get("jerarquia"))
    cambios = _cm_diff(modulo, existente, valores, fotos, fecha)
    if cambios:
        ahora = upd["updated_at"]
        hist = list(existente.get("historial") or [])[-99:]
        hist.append({"at": ahora, "by": user["id"], "by_name": user["name"], "accion": "editado", "cambios": cambios})
        upd["historial"] = hist
        upd["n_ediciones"] = int(existente.get("n_ediciones", 0)) + 1
    upd["cierres"] = _cm_cierres(modulo, valores, existente.get("cierres"), upd["updated_at"])
    await db.custom_module_records.update_one({"id": existente["id"]}, {"$set": upd})
    return _cm_registro_public(await db.custom_module_records.find_one({"id": existente["id"]}))


@api.get("/projects/{pid}/custom-modules/{mid}/records")
async def list_custom_module_records(
    pid: str, mid: str, desde: Optional[str] = None, hasta: Optional[str] = None, user: dict = Depends(current_user),
):
    await ensure_project_access(user, pid)
    modulo = await _cm_get_modulo(pid, mid)
    if not modulo.get("activo") and user.get("role") not in (ROLE_COORD, ROLE_JEFE):
        raise HTTPException(404, "El módulo no existe")
    q: dict = {"project_id": pid, "module_id": mid}
    if desde or hasta:
        q["fecha"] = {}
        if desde:
            q["fecha"]["$gte"] = _prueba_calidad_fecha(desde)
        if hasta:
            q["fecha"]["$lte"] = _prueba_calidad_fecha(hasta)
    cursor = db.custom_module_records.find(q, {"fotos": 0, "historial": 0}).sort([("fecha", -1), ("created_at", -1)])
    return [_cm_registro_public(d) for d in await cursor.to_list(length=2000)]


@api.get("/projects/{pid}/custom-modules/{mid}/records/{rid}")
async def get_custom_module_record(pid: str, mid: str, rid: str, user: dict = Depends(current_user)):
    """Un registro CON sus fotos completas (`fotos`: {id_campo: data URL}) y su
    historial de cambios."""
    await ensure_project_access(user, pid)
    doc = await db.custom_module_records.find_one({"id": rid, "project_id": pid, "module_id": mid})
    if not doc:
        raise HTTPException(404, "El registro no existe")
    out = _cm_registro_public(doc)
    out["fotos"] = doc.get("fotos") or {}
    out["historial"] = doc.get("historial") or []
    return out


@api.post("/projects/{pid}/custom-modules/{mid}/records")
async def create_custom_module_record(pid: str, mid: str, body: dict, user: dict = Depends(current_user)):
    await ensure_project_access(user, pid)
    modulo = await _cm_get_modulo(pid, mid)
    _cm_assert_puede_capturar(modulo, user)
    body = body or {}
    return await _cm_alta_registro(pid, modulo, body, user, client_id=str(body.get("client_id") or "")[:80] or None)


@api.patch("/projects/{pid}/custom-modules/{mid}/records/{rid}")
async def update_custom_module_record(pid: str, mid: str, rid: str, body: dict, user: dict = Depends(current_user)):
    await ensure_project_access(user, pid)
    modulo = await _cm_get_modulo(pid, mid)
    _cm_assert_puede_capturar(modulo, user)
    existente = await db.custom_module_records.find_one({"id": rid, "project_id": pid, "module_id": mid})
    if not existente:
        raise HTTPException(404, "El registro no existe")
    _cm_assert_puede_editar(existente, user)
    return await _cm_edita_registro(pid, modulo, existente, body or {}, user)


@api.post("/custom-records/sync")
async def sync_custom_record(body: dict, user: dict = Depends(current_user)):
    """Destino de la cola offline de la app: `{client_id, project_id, module_id,
    op: create|update, record_id?, fecha, valores, jerarquia?, captured_at?}`.
    Idempotente por `client_id` (un reintento nunca duplica el registro)."""
    body = body or {}
    pid, mid = str(body.get("project_id") or ""), str(body.get("module_id") or "")
    await ensure_project_access(user, pid)
    modulo = await _cm_get_modulo(pid, mid)
    _cm_assert_puede_capturar(modulo, user)
    if body.get("op") == "update":
        existente = await db.custom_module_records.find_one({"id": str(body.get("record_id") or ""), "project_id": pid, "module_id": mid})
        if not existente:
            raise HTTPException(404, "El registro no existe")
        _cm_assert_puede_editar(existente, user)
        return await _cm_edita_registro(pid, modulo, existente, body, user)
    return await _cm_alta_registro(pid, modulo, body, user, client_id=str(body.get("client_id") or "")[:80] or None)


@api.delete("/projects/{pid}/custom-modules/{mid}/records/{rid}")
async def delete_custom_module_record(pid: str, mid: str, rid: str, user: dict = Depends(current_user)):
    _assert_write_allowed(user)
    await ensure_project_access(user, pid)
    doc = await db.custom_module_records.find_one({"id": rid, "project_id": pid, "module_id": mid}, {"fotos": 0, "thumbs": 0, "historial": 0})
    if not doc:
        raise HTTPException(404, "El registro no existe")
    if user.get("role") not in (ROLE_COORD, ROLE_SUB) and doc.get("created_by") != user["id"]:
        raise HTTPException(403, "Solo puedes eliminar los registros que tú capturaste")
    await db.custom_module_records.delete_one({"id": rid, "project_id": pid})
    # Bitácora de eliminados (auditoría): qué se borró, quién y cuándo. Sin fotos.
    await db.custom_module_borrados.insert_one({
        "id": str(uuid.uuid4()), "project_id": pid, "module_id": mid, "record_id": rid,
        "folio": doc.get("folio"), "fecha": doc.get("fecha"), "valores": doc.get("valores") or {},
        "created_by_name": doc.get("created_by_name"), "deleted_by": user["id"], "deleted_by_name": user["name"],
        "deleted_at": datetime.now(timezone.utc),
    })
    return {"ok": True}


@api.get("/projects/{pid}/custom-modules/{mid}/borrados")
async def list_custom_module_deleted(pid: str, mid: str, user: dict = Depends(require_role(ROLE_COORD, ROLE_SUB, ROLE_JEFE))):
    await ensure_project_access(user, pid)
    await _cm_get_modulo(pid, mid)
    items = await db.custom_module_borrados.find({"project_id": pid, "module_id": mid}).sort("deleted_at", -1).to_list(length=200)
    return [{k: v for k, v in it.items() if k != "_id"} for it in items]


# --- Excel / CSV: exportar, plantilla e importar -----------------------------
def _cm_nombre_archivo(txt: str, ext: str) -> str:
    base = re.sub(r"[^A-Za-z0-9_-]+", "_", unicodedata.normalize("NFKD", txt or "modulo").encode("ascii", "ignore").decode()).strip("_")
    return f"{base or 'modulo'}.{ext}"


def _cm_celda(campo: dict, val):
    """Valor almacenado → (valor de celda, formato numérico|None)."""
    t = campo["tipo"]
    if t in ("numero", "moneda", "porcentaje", "calculado"):
        fm = campo.get("formato", "numero") if t == "calculado" else t
        dec = campo.get("decimales")
        if dec is None:
            dec = 2 if fm == "moneda" else (1 if fm == "porcentaje" else None)
        base = "#,##0" + ("" if dec == 0 else "." + ("0" * dec if dec else "####"))
        fmt = f'"$"{base}' if fm == "moneda" else f'{base}"%"' if fm == "porcentaje" else base
        return (float(val) if isinstance(val, (int, float)) and not isinstance(val, bool) else None), fmt
    if t == "fecha":
        try:
            return date.fromisoformat(str(val)[:10]), "DD/MM/YYYY"
        except (ValueError, TypeError):
            return None, None
    return _cm_fmt_valor(campo, val), None


@api.get("/projects/{pid}/custom-modules/{mid}/export")
async def export_custom_module_records(
    pid: str, mid: str, formato: str = "xlsx", desde: Optional[str] = None, hasta: Optional[str] = None,
    user: dict = Depends(current_user),
):
    """Concentrado de registros del módulo en Excel (`xlsx`) o CSV, con el
    mismo filtro de fechas de la lista y una fila de totales."""
    await ensure_project_access(user, pid)
    modulo = await _cm_get_modulo(pid, mid)
    if not modulo.get("activo") and user.get("role") not in (ROLE_COORD, ROLE_JEFE):
        raise HTTPException(404, "El módulo no existe")
    if formato not in ("xlsx", "csv"):
        raise HTTPException(400, "formato debe ser xlsx o csv")
    q: dict = {"project_id": pid, "module_id": mid}
    if desde or hasta:
        q["fecha"] = {}
        if desde:
            q["fecha"]["$gte"] = _prueba_calidad_fecha(desde)
        if hasta:
            q["fecha"]["$lte"] = _prueba_calidad_fecha(hasta)
    regs = await db.custom_module_records.find(q, {"fotos": 0, "historial": 0}).sort([("fecha", 1), ("created_at", 1)]).to_list(length=20000)
    await _cm_refresca_ubicaciones(pid, modulo, regs)
    campos = modulo["campos"]
    con_folio = bool(modulo["opciones"].get("folio_activo"))
    estatus = [c for c in campos if c.get("estatus")]
    headers = (["Folio"] if con_folio else []) + ["Fecha"] + [c["etiqueta"] for c in campos] \
        + [f"Cierre · {c['etiqueta']}" for c in estatus] + ["Registró", "Capturado el"]
    filas: List[list] = []
    for r in regs:
        v = r.get("valores") or {}
        fila: list = ([r.get("folio") or ""] if con_folio else [])
        fila.append(_cm_celda({"tipo": "fecha"}, r.get("fecha")))
        for c in campos:
            if c["tipo"] == "foto":
                fila.append(("Sí" if c["id"] in (r.get("thumbs") or {}) else "", None))
            else:
                fila.append(_cm_celda(c, v.get(c["id"])) if _cm_campo_visible(c, v) else ("", None))
        for c in estatus:
            cierre = (r.get("cierres") or {}).get(c["id"])
            fila.append((_cm_aware(cierre).astimezone(MX_TZ).date() if cierre else None, "DD/MM/YYYY"))
        creado = r.get("created_at")
        fila += [(r.get("created_by_name") or "", None),
                 (_cm_aware(creado).astimezone(MX_TZ).replace(tzinfo=None) if creado else None, "DD/MM/YYYY HH:MM")]
        filas.append(fila)
    nombre = _cm_nombre_archivo(modulo["nombre"], formato)
    if formato == "csv":
        buf = io.StringIO()
        w = csv.writer(buf)
        w.writerow(headers)
        for fila in filas:
            w.writerow(["" if c[0] is None else (c[0].strftime("%d/%m/%Y") if isinstance(c[0], (date, datetime)) else c[0]) for c in
                        [x if isinstance(x, tuple) else (x, None) for x in fila]])
        data = ("﻿" + buf.getvalue()).encode("utf-8")
        return StreamingResponse(io.BytesIO(data), media_type="text/csv; charset=utf-8",
                                 headers={"Content-Disposition": f'attachment; filename="{nombre}"'})
    from openpyxl.styles import Alignment, Font, PatternFill
    from openpyxl.utils import get_column_letter
    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = _cm_texto(modulo["nombre"], 28).replace("/", "-").replace("\\", "-").replace("*", "").replace("?", "").replace(":", "").replace("[", "").replace("]", "") or "Registros"
    ws.append(headers)
    for c in ws[1]:
        c.font = Font(bold=True, color="FFFFFF")
        c.fill = PatternFill("solid", fgColor="1E40AF")
        c.alignment = Alignment(wrap_text=True, vertical="center")
    for fila in filas:
        ws.append([x[0] if isinstance(x, tuple) else x for x in fila])
        for i, x in enumerate(fila, start=1):
            if isinstance(x, tuple) and x[1]:
                ws.cell(row=ws.max_row, column=i).number_format = x[1]
    # Fila de totales (solo campos que el módulo totaliza).
    off = (1 if con_folio else 0) + 1
    if filas and any(c.get("agregacion", "ninguna") != "ninguna" for c in campos):
        fila_t = [""] * len(headers)
        fila_t[0] = "TOTALES"
        for i, c in enumerate(campos):
            if c.get("agregacion", "ninguna") == "ninguna":
                continue
            val = _cm_agregar(c, regs)
            if val is not None:
                fila_t[off + i] = val
        ws.append(fila_t)
        for cel in ws[ws.max_row]:
            cel.font = Font(bold=True)
        for i, c in enumerate(campos):
            if c.get("agregacion", "ninguna") != "ninguna":
                _, fmt = _cm_celda(c, 0)
                if fmt and c["tipo"] != "interruptor" and c.get("agregacion") != "conteo":
                    ws.cell(row=ws.max_row, column=off + i + 1).number_format = fmt
    ws.freeze_panes = "A2"
    ws.auto_filter.ref = f"A1:{get_column_letter(len(headers))}{max(1, len(filas) + 1)}"
    for i, h in enumerate(headers, start=1):
        largo = max([len(str(h))] + [len(str(f[i - 1][0] if isinstance(f[i - 1], tuple) else f[i - 1])) for f in filas[:200]])
        ws.column_dimensions[get_column_letter(i)].width = min(max(12, largo + 2), 48)
    out = io.BytesIO()
    wb.save(out)
    return StreamingResponse(io.BytesIO(out.getvalue()), media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                             headers={"Content-Disposition": f'attachment; filename="{nombre}"'})


def _cm_campos_importables(modulo: dict) -> List[dict]:
    return [c for c in modulo["campos"] if c["tipo"] not in ("foto", "calculado")]


@api.get("/projects/{pid}/custom-modules/{mid}/plantilla")
async def custom_module_import_template(pid: str, mid: str, user: dict = Depends(current_user)):
    """Excel vacío con los encabezados del módulo (y listas desplegables) para
    llenar y luego importar."""
    await ensure_project_access(user, pid)
    modulo = await _cm_get_modulo(pid, mid)
    from openpyxl.styles import Font, PatternFill
    from openpyxl.worksheet.datavalidation import DataValidation
    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = "Datos"
    campos = _cm_campos_importables(modulo)
    ws.append(["Fecha"] + [c["etiqueta"] + (" *" if c["requerido"] else "") for c in campos])
    for c in ws[1]:
        c.font = Font(bold=True, color="FFFFFF")
        c.fill = PatternFill("solid", fgColor="1E40AF")
    for i, c in enumerate(campos, start=2):
        letra = openpyxl.utils.get_column_letter(i)
        ws.column_dimensions[letra].width = max(14, len(c["etiqueta"]) + 4)
        lista = None
        if c["tipo"] in ("seleccion",):
            lista = c["opciones"]
        elif c["tipo"] == "interruptor":
            lista = ["Sí", "No"]
        if lista and len(",".join(lista)) < 250:
            dv = DataValidation(type="list", formula1='"' + ",".join(o.replace('"', "") for o in lista) + '"', allow_blank=True)
            ws.add_data_validation(dv)
            dv.add(f"{letra}2:{letra}1000")
    ws.column_dimensions["A"].width = 14
    ws.freeze_panes = "A2"
    ins = wb.create_sheet("Instrucciones")
    ins.append(["Columna", "Tipo", "Obligatorio", "Valores permitidos / formato"])
    for c in ins[1]:
        c.font = Font(bold=True)
    ins.append(["Fecha", "fecha", "No", "DD/MM/AAAA o AAAA-MM-DD. Vacía = hoy."])
    nombres_tipo = {t: t for t in CM_TIPOS}
    for c in campos:
        if c["tipo"] in ("seleccion", "multiseleccion"):
            ayuda = "Una de: " + ", ".join(c["opciones"]) + (" (varias separadas por coma)" if c["tipo"] == "multiseleccion" else "")
        elif c["tipo"] == "interruptor":
            ayuda = "Sí / No"
        elif c["tipo"] == "fecha":
            ayuda = "DD/MM/AAAA o AAAA-MM-DD"
        elif c["tipo"] in ("numero", "moneda", "porcentaje"):
            ayuda = "Número (sin letras)" + (f" en {c['unidad']}" if c.get("unidad") else "")
        elif c["tipo"] == "ubicacion":
            ayuda = "Nombre exacto de la estación / ubicación del proyecto"
        else:
            ayuda = "Texto libre"
        ins.append([c["etiqueta"], nombres_tipo[c["tipo"]], "Sí" if c["requerido"] else "No", ayuda])
    ins.column_dimensions["A"].width = 28
    ins.column_dimensions["D"].width = 70
    out = io.BytesIO()
    wb.save(out)
    return StreamingResponse(io.BytesIO(out.getvalue()), media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                             headers={"Content-Disposition": f'attachment; filename="{_cm_nombre_archivo("plantilla_" + modulo["nombre"], "xlsx")}"'})


def _cm_coerce_import(campo: dict, raw):
    """Valor tal como viene de Excel → forma que entiende la captura. ValueError
    con mensaje para el usuario si no se puede interpretar."""
    t, et = campo["tipo"], campo["etiqueta"]
    if raw is None or (isinstance(raw, str) and not raw.strip()):
        return None
    if t == "interruptor":
        s = _cm_norm(raw)
        if s in ("si", "s", "x", "true", "1", "verdadero", "yes", "y", "cumple"):
            return True
        if s in ("no", "n", "false", "0", "falso", "no cumple"):
            return False
        raise ValueError(f"«{et}»: usa Sí o No")
    if t == "seleccion":
        for o in campo["opciones"]:
            if _cm_norm(o) == _cm_norm(raw):
                return o
        raise ValueError(f"«{et}»: «{raw}» no está en la lista ({', '.join(campo['opciones'][:6])}…)")
    if t == "multiseleccion":
        partes = [p for p in re.split(r"[,;|]", str(raw)) if p.strip()]
        out = []
        for p in partes:
            o = next((o for o in campo["opciones"] if _cm_norm(o) == _cm_norm(p)), None)
            if o is None:
                raise ValueError(f"«{et}»: «{p.strip()}» no está en la lista")
            out.append(o)
        return out
    if t == "fecha":
        if isinstance(raw, (int, float)) and not isinstance(raw, bool):  # serie de Excel
            return (date(1899, 12, 30) + timedelta(days=int(raw))).isoformat()
        return str(raw)
    if t in ("texto", "texto_largo"):
        return str(int(raw)) if isinstance(raw, float) and raw.is_integer() else str(raw)
    return raw


@api.post("/projects/{pid}/custom-modules/{mid}/import")
async def import_custom_module_records(
    pid: str, mid: str, body: dict, user: dict = Depends(require_role(ROLE_COORD, ROLE_SUB)),
):
    """Importa registros desde filas ya leídas del Excel:
    `{filas: [{fila?, fecha?, valores: {id_campo: valor}}], simular?, importar_validas?}`.
    `simular` solo valida y devuelve los errores por fila. Sin `importar_validas`,
    una sola fila con error cancela toda la importación."""
    await ensure_project_access(user, pid)
    modulo = await _cm_get_modulo(pid, mid)
    _cm_assert_puede_capturar(modulo, user)
    body = body or {}
    filas = body.get("filas")
    if not isinstance(filas, list) or not filas:
        raise HTTPException(400, "No hay filas para importar")
    if len(filas) > CM_MAX_FILAS_IMPORT:
        raise HTTPException(400, f"Máximo {CM_MAX_FILAS_IMPORT} filas por importación")
    importables = {c["id"]: c for c in _cm_campos_importables(modulo)}
    validas: List[Tuple[str, dict]] = []
    errores: List[dict] = []
    for idx, f in enumerate(filas, start=1):
        num = f.get("fila", idx) if isinstance(f, dict) else idx
        try:
            if not isinstance(f, dict):
                raise ValueError("fila inválida")
            crudos = f.get("valores") if isinstance(f.get("valores"), dict) else {}
            entrada = {fid: _cm_coerce_import(importables[fid], v) for fid, v in crudos.items() if fid in importables}
            valores, _, _ = await _cm_construye_registro(modulo, {"valores": entrada}, None)
            fecha_raw = f.get("fecha")
            if isinstance(fecha_raw, (int, float)) and not isinstance(fecha_raw, bool):  # serie de Excel
                fecha_raw = (date(1899, 12, 30) + timedelta(days=int(fecha_raw))).isoformat()
            validas.append((_prueba_calidad_fecha(str(fecha_raw) if fecha_raw is not None else None), valores))
        except (ValueError, TypeError, OverflowError, HTTPException) as e:
            errores.append({"fila": num, "mensaje": e.detail if isinstance(e, HTTPException) else str(e)})
    resumen = {"total": len(filas), "validas": len(validas), "errores": errores[:200], "n_errores": len(errores), "importados": 0}
    if body.get("simular") or not validas or (errores and not body.get("importar_validas")):
        return resumen
    now = datetime.now(timezone.utc)
    docs = []
    for fecha, valores in validas:
        docs.append({
            "id": str(uuid.uuid4()), "project_id": pid, "module_id": mid, "fecha": fecha,
            "valores": valores, "fotos": {}, "thumbs": {},
            "jerarquia": _jerarquia_modulo(None) if modulo.get("usar_jerarquia") else None,
            "folio": await _cm_siguiente_folio(modulo), "client_id": None,
            "cierres": _cm_cierres(modulo, valores, None, now), "n_ediciones": 0,
            "historial": [{"at": now, "by": user["id"], "by_name": user["name"], "accion": "importado", "cambios": []}],
            "created_by": user["id"], "created_by_name": user["name"], "created_at": now, "updated_at": now,
        })
    await db.custom_module_records.insert_many(docs)
    resumen["importados"] = len(docs)
    return resumen


# --- Vista previa del informe ----------------------------------------------
def _cm_registro_muestra(modulo: dict, n: int, hoy: date) -> dict:
    """Registro inventado (solo para la vista previa de un módulo sin datos)."""
    valores: dict = {}
    for c in modulo["campos"]:
        t = c["tipo"]
        if t in ("texto", "texto_largo"):
            valores[c["id"]] = f"{c['etiqueta']} de ejemplo {n}"
        elif t in ("numero", "moneda", "porcentaje"):
            valores[c["id"]] = float(10 * n + (n % 3) * 2.5)
        elif t == "fecha":
            valores[c["id"]] = (hoy - timedelta(days=n)).isoformat()
        elif t == "seleccion":
            valores[c["id"]] = c["opciones"][(n - 1) % len(c["opciones"])]
        elif t == "multiseleccion":
            valores[c["id"]] = c["opciones"][:max(1, min(2, len(c["opciones"])))]
        elif t == "interruptor":
            valores[c["id"]] = n % 2 == 1
        elif t == "ubicacion":
            valores[c["id"]] = {"id": f"x{n}", "nombre": f"Estación {n}"}
    _cm_recalcula(modulo["campos"], valores)
    op = modulo["opciones"]
    folio = f"{op.get('folio_prefijo', '')}{str(n).zfill(int(op.get('folio_digitos', 4)))}" if op.get("folio_activo") else None
    return {"id": f"muestra{n}", "fecha": (hoy - timedelta(days=n - 1)).isoformat(), "valores": valores, "folio": folio,
            "created_by_name": "Nombre Apellido", "created_at": datetime.now(timezone.utc) - timedelta(hours=n)}


def _cm_ventana(categoria: str, fin: date) -> Tuple[date, date]:
    if categoria == "reportes_semanales":
        return fin - timedelta(days=6), fin
    if categoria == "reportes_mensuales":
        return fin.replace(day=1), fin
    return fin, fin


@api.post("/projects/{pid}/custom-modules/preview")
async def preview_custom_module(pid: str, body: dict, user: dict = Depends(require_role(ROLE_COORD))):
    """Cómo saldría el módulo en un informe: `{definicion, module_id?, categoria,
    fecha?, muestra?}`. Usa la definición SIN guardar (para ver el efecto de los
    interruptores antes de aplicarlos) y los registros reales del `module_id`;
    sin registros (o con `muestra=true`) usa datos de ejemplo."""
    await ensure_project_access(user, pid)
    body = body or {}
    categoria = body.get("categoria")
    if categoria not in CM_CATEGORIAS:
        raise HTTPException(400, "categoria debe ser reportes_diarios, reportes_semanales o reportes_mensuales")
    existente = None
    if body.get("module_id"):
        existente = await _cm_get_modulo(pid, str(body["module_id"]))
    definicion = body.get("definicion") if isinstance(body.get("definicion"), dict) else {}
    datos = await _cm_sanitize_modulo(pid, definicion, parcial_de=existente)
    modulo = {**(existente or {}), **datos, "id": (existente or {}).get("id", "preview"), "project_id": pid}
    try:
        fin = _fecha_flexible(body.get("fecha") or datetime.now(MX_TZ).date().isoformat())
    except ValueError:
        raise HTTPException(400, "fecha inválida")
    ini, fin = _cm_ventana(categoria, fin)
    registros: List[dict] = []
    usar_muestra = bool(body.get("muestra")) or not existente
    if not usar_muestra:
        registros = await _cm_registros_periodo(pid, modulo, categoria, ini.isoformat(), fin.isoformat())
        if not registros and not await db.custom_module_records.count_documents({"project_id": pid, "module_id": modulo["id"]}):
            usar_muestra = True
    if usar_muestra:
        registros = [_cm_registro_muestra(modulo, i, fin) for i in range(1, 4)]
    muestra = usar_muestra
    ventana = (datetime.combine(ini, datetime.min.time(), tzinfo=MX_TZ), datetime.combine(fin, datetime.max.time(), tzinfo=MX_TZ))
    seccion = await asyncio.to_thread(_cm_construye_seccion, modulo, registros, categoria, usar_thumbs=True, ventana=ventana)
    modo = (modulo["salida"].get(categoria) or {}).get("modo", "oculto")
    return {"seccion": seccion, "muestra": muestra, "modo": modo,
            "periodo": {"desde": ini.isoformat(), "hasta": fin.isoformat()}, "n_registros": len(registros)}


# Sistema Multi-Proyecto Modular — esquema GENÉRICO de "bloques imprimibles".
# Los 3 motores de exportación (PDF/DOCX/PPTX) NUNCA conocen el nombre de un
# módulo ni su forma de datos particular: solo saben dibujar estos 3 tipos
# de bloque. Un módulo nuevo (actual o futuro) sólo necesita:
#   1) agregar su clave a MODULOS_KEYS,
#   2) agregar una entrada a `out` en `_gather_modulos_export_data` (abajo)
#      con {"titulo": "...", "blocks": [...]} usando estos 3 tipos,
# y aparece impreso en PDF/DOCX/PPTX sin tocar ninguno de los 3 motores. El
# interruptor por informe (Diario/Semanal/Mensual, ver
# `_modulos_categoria_para_export`) es la ÚNICA puerta: si `activos.get(key)`
# es falso, esa entrada de `out` queda None y el módulo no aparece en NADA
# de lo impreso, sin importar qué datos tenga capturados.
#
# Tipos de bloque:
#   {"type": "summary", "text": str}
#       Una línea destacada (ej. contadores globales).
#   {"type": "table", "heading": str|None, "headers": [str,...],
#    "rows": [[str,...], ...], "col_widths": [float,...]|None,
#    "empty_text": str}
#       Tabla simple. `col_widths` son fracciones que suman 1.0 (si se
#       omite, columnas iguales). Si `rows` viene vacío se pinta
#       `empty_text` en su lugar — nunca se omite la sección en silencio.
#   {"type": "list", "heading": str|None,
#    "heading_color": "good"|"bad"|None, "items": [
#       {"title": str|None, "body": str, "extra": str|None, "meta": str|None},
#       ...
#    ], "empty_text": str}
#       Lista de viñetas/tarjetas (reportes, notas de bitácora, auditoría).
#       `heading_color` permite un encabezado verde ("good") o rojo ("bad")
#       — ej. Cumplimientos vs. Incumplimientos en Impacto Ambiental.
async def _gather_modulos_export_data(
    pid: str, proj: dict, start_dt: datetime, end_dt: datetime, categoria: str,
) -> dict:
    """Datos de los módulos piloto (sistema Multi-Proyecto Modular) para la
    sección de cierre de los reportes exportados (PDF/DOCX/PPTX), en el
    esquema genérico de bloques descrito arriba.

    `categoria` (reportes_diarios/semanales/mensuales, ver
    `_modulos_categoria_para_export`) decide qué toggle del Coordinador se
    consulta: un módulo puede estar activo para captura pero apagado para
    ESTE informe en particular — el Coordinador elige, por módulo, en qué
    informes quiere ver el recuento.

    Regla explícita del Coordinador: un módulo apagado para esta categoría
    NUNCA aparece en la impresión, sin importar si tiene datos capturados
    (`out[clave]` queda None). Uno encendido pero SIN NINGÚN dato capturado
    en el período TAMPOCO aparece (se omite la hoja/sección completa,
    silenciosamente) — antes se imprimía igual con un texto "sin registros"
    para dejar constancia de que el módulo estaba activo; el Coordinador
    pidió lo contrario: una hoja en blanco en el reporte impreso confunde
    más de lo que aclara, así que si no hubo actividad simplemente no se
    imprime nada de ese módulo ese período.

    Se filtra por `created_at` (mismo criterio que `reports`), NO por el
    campo `fecha` (string) — created_at es el datetime real de captura y
    ya viene consistente en UTC aware desde cada endpoint de creación."""
    modulos = _sanitize_modulos(proj.get("modulos"))
    activos = modulos.get(categoria, {})
    out: dict = {
        "forestal": None, "seguridad": None, "riesgos": None, "estudios": None, "ambiental": None,
        "tabla_resumen": None, "fotos_lidar": None, "tapial": None,
        "pruebas_calidad": None, "control_calidad": None,
        "avance_obra": None, "estimaciones": None, "pendientes_generales": None,
        "aspectos_sociales": None, "indicadores_seguridad": None, "juntas_trabajo": None,
        "supervision_ambiental": None, "actividades_particulares": None, "electromecanica": None,
    }
    # Jerarquía por registro: solo entran al informe los registros que le
    # corresponden (o sin jerarquía = legado), ver `_jerarquia_q`.
    jq = _jerarquia_q(categoria)
    date_q = {"created_at": {"$gte": start_dt, "$lte": end_dt}, **jq}
    # Riesgos y Estudios son matrices mutables (el % de avance se actualiza
    # in situ, no se recrea la fila) — una fila cuenta para el período si se
    # creó O se actualizó dentro de él, no sólo si se creó.
    mutable_date_q = {"$or": [
        {"created_at": {"$gte": start_dt, "$lte": end_dt}},
        {"updated_at": {"$gte": start_dt, "$lte": end_dt}},
    ]}

    if activos.get("forestal_arbolado"):
        registros_periodo = await db.forestal_registros.find({"project_id": pid, **date_q}).to_list(length=5000)
        if registros_periodo:
            cursor = db.forestal_registros.aggregate([
                {"$match": {"project_id": pid, **date_q}},
                {"$group": {"_id": {"fecha": "$fecha", "tipo": "$tipo"}, "total": {"$sum": "$cantidad"}}},
            ])
            rows = await cursor.to_list(length=5000)
            d0 = start_dt.astimezone(MX_TZ).date()
            d1 = end_dt.astimezone(MX_TZ).date()
            fechas: List[str] = []
            d = d0
            while d <= d1 and len(fechas) < 31:
                fechas.append(d.isoformat())
                d += timedelta(days=1)
            por_fecha: Dict[str, Dict[str, int]] = {f: {"poda": 0, "trasplante": 0, "derribo": 0} for f in fechas}
            for r in rows:
                f = r["_id"]["fecha"]
                tipo = r["_id"]["tipo"]
                if f in por_fecha and tipo in por_fecha[f]:
                    por_fecha[f][tipo] = r["total"]
            dias = []
            contadores = {"poda": 0, "trasplante": 0, "derribo": 0}
            for f in fechas:
                conteos = por_fecha[f]
                for k in contadores:
                    contadores[k] += conteos[k]
                dias.append({"fecha": f, **conteos, "total": sum(conteos.values())})
            autorizado_rows = await db.forestal_autorizado.find({"project_id": pid}).sort("orden", 1).to_list(length=200)
            for it in autorizado_rows:
                it.pop("_id", None)
            total_autorizado = {"poda": 0, "trasplante": 0, "derribo": 0, "total_dictaminados": 0}
            for r in autorizado_rows:
                total_autorizado["poda"] += r.get("poda", 0)
                total_autorizado["trasplante"] += r.get("trasplante", 0)
                total_autorizado["derribo"] += r.get("derribo", 0)
                total_autorizado["total_dictaminados"] += r.get("total_dictaminados", 0)
            out["forestal"] = {
                "titulo": "TRATAMIENTO DE ARBOLADO",
                "blocks": [{
                    "type": "forestal_sheet",
                    "autorizado_rows": autorizado_rows,
                    "autorizado_total": total_autorizado,
                    "contadores": contadores,
                    "dias": dias,
                    "desde": fechas[0] if fechas else None,
                    "hasta": fechas[-1] if fechas else None,
                }],
            }

    if activos.get("seguridad_higiene"):
        # "Indicadores de Seguridad e Higiene: Acciones Correctivas
        # Pendientes" — a diferencia del resto de los módulos, esto NO es
        # un log de actividad del período: es una foto del estado ACTUAL
        # (qué sigue pendiente hoy), tomada del checklist más reciente
        # capturado para el proyecto — cada captura reemplaza a la
        # anterior como "estado vigente" (ver SeguridadHigieneScreen, un
        # checklist nuevo por captura, no ediciones in situ de uno viejo).
        ultimo_checklist = await db.seguridad_checklist.find(
            {"project_id": pid}
        ).sort("created_at", -1).limit(1).to_list(length=1)
        pendientes = [
            it.get("item") for it in (ultimo_checklist[0].get("items") or [])
            if it.get("tipo") == "correctiva" and not it.get("cumplido")
        ] if ultimo_checklist else []
        # Registro de accidentes DEL PERÍODO (por created_at, igual que el
        # resto de módulos): una fila por renglón de la bitácora.
        accidentes = await db.seguridad_reportes.find(
            {"project_id": pid, **date_q}
        ).sort("created_at", 1).to_list(length=2000)
        filas_accidentes = []
        for a in accidentes:
            ubicacion = a.get("ubicacion") or ""
            if not ubicacion and a.get("node_id"):
                ubicacion = " › ".join(await node_path_names(a["node_id"]))
            filas_accidentes.append({
                "fecha": a.get("fecha") or "",
                "mes": _seguridad_mes(a.get("fecha")),
                "trabajador": a.get("trabajador") or "",
                "contratista": a.get("contratista") or "",
                "registro": _seguridad_registro_label(a),
                "ubicacion": ubicacion,
                "descripcion": a.get("descripcion") or "",
                "foto": (a.get("images") or [None])[0],
                "seguimiento": a.get("seguimiento") or a.get("acciones_tomadas") or "",
            })
        bloques_seguridad: list = []
        if filas_accidentes:
            bloques_seguridad.append({
                "type": "seguridad_accidentes",
                "heading": "Registro de accidentes",
                "rows": filas_accidentes,
            })
        if pendientes:
            bloques_seguridad.append({
                "type": "seguridad_indicadores",
                "subtitulo": "Acciones Correctivas Pendientes",
                "items": pendientes,
            })
        if bloques_seguridad:
            out["seguridad"] = {
                "titulo": "INDICADORES DE SEGURIDAD E HIGIENE",
                "blocks": bloques_seguridad,
            }

    if activos.get("gestion_riesgos"):
        # El mapa es una matriz VIVA: en el informe diario cuenta lo creado o
        # actualizado en el día; en el semanal y el mensual se imprime el mapa
        # vigente (todo lo que no está al 100%) más lo que se creó, actualizó
        # o cerró en el período — si no, cada semana saldría un fragmento.
        if categoria in ("reportes_semanales", "reportes_mensuales"):
            riesgos_q = {"project_id": pid, **jq, "$or": [{"porcentaje_avance": {"$lt": 100}}] + mutable_date_q["$or"]}
        else:
            riesgos_q = {"project_id": pid, **jq, **mutable_date_q}
        registros = await db.riesgos_registros.find(riesgos_q).sort(
            [("estacion_nombre", 1), ("created_at", 1)]
        ).to_list(length=2000)
        if registros:
            out["riesgos"] = {
                "titulo": "MAPA DE RIESGOS",
                "blocks": [{"type": "riesgos_mapa", "grupos": _riesgos_grupos(registros)}],
            }

    if activos.get("estudios_proyecto"):
        bitacora = await db.estudios_bitacora.find(
            {"project_id": pid, **date_q}
        ).sort("created_at", 1).to_list(length=2000)
        if bitacora:
            por_disciplina: Dict[str, list] = {}
            for b in bitacora:
                key = b.get("disciplina") or "—"
                por_disciplina.setdefault(key, []).append(b.get("texto") or "")
            out["estudios"] = {
                "titulo": "ESTUDIOS Y PROYECTO EJECUTIVO",
                "blocks": [{
                    "type": "estudios_avances",
                    "grupos": [
                        {"disciplina": ESTUDIOS_DISCIPLINA_LABEL.get(k, k), "items": por_disciplina[k]}
                        for k in ESTUDIOS_DISCIPLINAS if k in por_disciplina
                    ],
                }],
            }

    if activos.get("impacto_ambiental"):
        auditoria = await db.ambiental_auditoria.find(
            {"project_id": pid, **date_q}
        ).sort("created_at", 1).to_list(length=2000)

        def _audit_items(tipo: str) -> list:
            return [{
                "title": None,
                "body": a.get("descripcion") or "",
                "extra": None,
                "meta": f"{a.get('fecha', '—')} · {a.get('captured_by_name') or '—'}",
            } for a in auditoria if a.get("tipo") == tipo]

        if auditoria:
            out["ambiental"] = {
                "titulo": "IMPACTO AMBIENTAL",
                "blocks": [
                    {
                        "type": "list", "heading": "Cumplimientos", "heading_color": "good",
                        "items": _audit_items("cumplimiento"),
                        "empty_text": "Sin cumplimientos registrados en este período.",
                    },
                    {
                        "type": "list", "heading": "Incumplimientos / Observaciones", "heading_color": "bad",
                        "items": _audit_items("incumplimiento"),
                        "empty_text": "Sin incumplimientos registrados en este período.",
                    },
                ],
            }

    if activos.get("tabla_resumen"):
        # Tabla 100% configurable por proyecto — a diferencia del resto de
        # los módulos NO se filtra por período: es un estado vigente (como
        # una hoja de cálculo), no un log de eventos capturados en el rango
        # de fechas del reporte.
        actividades = await db.tabla_resumen_actividades.find({"project_id": pid}).sort("orden", 1).to_list(length=500)
        columnas = await db.tabla_resumen_columnas.find({"project_id": pid}).sort("orden", 1).to_list(length=200)
        celdas = await db.tabla_resumen_celdas.find({"project_id": pid}).to_list(length=20000)
        celda_map = {(c["actividad_id"], c["columna_id"]): c for c in celdas}
        filas = []
        for act in actividades:
            if act.get("es_seccion"):
                filas.append({"actividad": act["nombre"], "seccion": True, "valores": [], "total": None})
                continue
            valores = []
            for col in columnas:
                c = celda_map.get((act["id"], col["id"]))
                valores.append({
                    "valor": c["valor"] if c else None,
                    "no_aplica": bool(c and c.get("no_aplica")),
                })
            nums = [v["valor"] for v in valores if v["valor"] is not None and not v["no_aplica"]]
            total = round(sum(nums) / len(nums), 2) if nums else None
            filas.append({"actividad": act["nombre"], "valores": valores, "total": total})
        has_data = any(v["valor"] is not None or v["no_aplica"] for f in filas for v in f["valores"])
        if columnas and filas and has_data:
            out["tabla_resumen"] = {
                "titulo": "TABLA DE AVANCE ACUMULADO",
                "blocks": [{
                    "type": "tabla_resumen_matriz",
                    "columnas": [{"tipo": col["tipo"], "label": col["label"]} for col in columnas],
                    "filas": filas,
                }],
            }

    if activos.get("fotos_lidar"):
        # Estado vigente (como tabla_resumen): NO se filtra por período — lo
        # que importa es la foto original y la actual de cada frente hoy.
        registros = await db.fotos_lidar.find({"project_id": pid}).sort(
            [("orden", 1), ("created_at", 1)]
        ).to_list(length=200)
        items = []
        for r in registros:
            if not (r.get("foto_original") or r.get("foto_actual")):
                continue
            items.append({
                "titulo": r.get("titulo") or "",
                "node_id": r.get("node_id"),
                "original": r.get("foto_original"),
                "actual": r.get("foto_actual"),
                "fecha_original": r.get("foto_original_fecha"),
                "fecha_actual": r.get("foto_actual_fecha"),
            })
        if items:
            out["fotos_lidar"] = {
                "titulo": "FOTOS LIDAR",
                "blocks": [{"type": "fotos_comparativa", "items": items}],
            }

    if activos.get("tapial"):
        # Igual que arriba: estado vigente de cada plano de Tapial. Un plano
        # sin ningún tramo dibujado no se imprime.
        planos = await db.planos_avance.find({"project_id": pid, "categoria": "tapial"}).sort(
            "created_at", 1
        ).to_list(length=50)
        bloques_tapial = []
        # Vuelo DRON: foto ACTUAL del registro de Fotos LiDAR ligado a la
        # misma estación (solo si ese módulo está encendido para este informe).
        dron_por_nodo: dict = {}
        if activos.get("fotos_lidar"):
            for r in await db.fotos_lidar.find({"project_id": pid, "node_id": {"$ne": None}}).to_list(length=200):
                if r.get("foto_actual"):
                    dron_por_nodo.setdefault(r["node_id"], r["foto_actual"])
        leyenda_tapial = [
            ("Concluido", _PLANO_MARKER_ESTADO_COLOR["terminado"]),
            ("En proceso", _PLANO_MARKER_ESTADO_COLOR["en_proceso"]),
            ("Sin realizar", _PLANO_MARKER_ESTADO_COLOR["sin_iniciar"]),
        ]
        for pl in planos:
            if not any(m.get("tipo") == "tramo" for m in (pl.get("markers") or [])):
                continue
            png = await asyncio.to_thread(_bake_plano_snapshot, pl)
            jpg = await asyncio.to_thread(_png_bytes_to_jpeg_dataurl, png)
            av = _plano_tapial_avance(pl)
            dron = dron_por_nodo.get(pl.get("node_id")) if pl.get("node_id") else None
            if dron:
                # Formato del informe diario: TAPIAL a la izquierda, VUELO DRON
                # a la derecha, leyenda debajo (mismo bloque de comparativa).
                bloques_tapial.append({
                    "type": "fotos_comparativa",
                    "items": [{
                        "titulo": pl.get("nombre") or "Tapial",
                        "original": jpg, "actual": dron,
                        "etiqueta_original": "TAPIAL", "etiqueta_actual": "VUELO DRON",
                    }],
                    "leyenda": leyenda_tapial,
                })
                continue
            partes = []
            if av["pct_terminado"] is not None:
                partes.append(f"Terminado: {av['pct_terminado']:.1f}% de la longitud")
            if av["pct_en_proceso"]:
                partes.append(f"En proceso: {av['pct_en_proceso']:.1f}%")
            partes.append(f"{av['tramos']} tramo(s)")
            bloques_tapial.append({
                "type": "imagen",
                "heading": pl.get("nombre") or "Tapial",
                "imagen": jpg,
                "caption": " · ".join(partes),
                "leyenda": [
                    ("Terminado", _PLANO_MARKER_ESTADO_COLOR["terminado"]),
                    ("En proceso", _PLANO_MARKER_ESTADO_COLOR["en_proceso"]),
                    ("Sin iniciar", _PLANO_MARKER_ESTADO_COLOR["sin_iniciar"]),
                ],
            })
        if bloques_tapial:
            out["tapial"] = {"titulo": "TAPIAL", "blocks": bloques_tapial}

    if activos.get("pruebas_calidad"):
        # Log de eventos: se filtra por la `fecha` de la prueba (string ISO,
        # en hora de CDMX), no por created_at — una prueba capturada hoy
        # puede ser de ayer.
        d_ini = start_dt.astimezone(MX_TZ).date().isoformat()
        d_fin = end_dt.astimezone(MX_TZ).date().isoformat()
        pruebas = await db.pruebas_calidad.find(
            {"project_id": pid, "fecha": {"$gte": d_ini, "$lte": d_fin}, **jq}
        ).to_list(length=5000)
        nodos = await db.location_nodes.find(
            {"project_id": pid, "id": {"$in": list({p["node_id"] for p in pruebas if p.get("node_id")})}}
        ).to_list(length=500)
        bloques_pc = _pruebas_calidad_bloques(pruebas, {n["id"]: n.get("name") or "" for n in nodos})
        if bloques_pc:
            out["pruebas_calidad"] = {"titulo": "PRUEBAS DE CALIDAD", "blocks": bloques_pc}

    if activos.get("control_calidad"):
        d_ini = start_dt.astimezone(MX_TZ).date().isoformat()
        d_fin = end_dt.astimezone(MX_TZ).date().isoformat()
        fotos_cc = await db.control_calidad.find(
            {"project_id": pid, "fecha": {"$gte": d_ini, "$lte": d_fin}, **jq}
        ).to_list(length=1000)
        nodos_cc = await db.location_nodes.find(
            {"project_id": pid, "id": {"$in": list({r["node_id"] for r in fotos_cc if r.get("node_id")})}}
        ).to_list(length=500)
        bloques_cc = _control_calidad_bloques(fotos_cc, {n["id"]: n.get("name") or "" for n in nodos_cc})
        if bloques_cc:
            out["control_calidad"] = {"titulo": "CONTROL DE CALIDAD", "blocks": bloques_cc}

    if activos.get("avance_obra"):
        # Estado acumulado al corte del informe (no un log): se calcula del
        # motor EVM, sin captura propia — una sección por contrato (obra y
        # supervisión) que tenga presupuesto y avance o programa.
        ini_d = start_dt.astimezone(MX_TZ).date()
        fin_d = end_dt.astimezone(MX_TZ).date()
        por_contrato = _split_por_contrato(
            await db.conceptos.find({"project_id": pid}).to_list(length=100000),
            await db.partidas.find({"project_id": pid}).to_list(length=5000),
            await db.registros_avance.find({"project_id": pid}).to_list(length=200000),
        )
        gastos_ao = await db.gastos_reales.find({"project_id": pid}).to_list(length=100000)
        blocks_ao: List[dict] = []
        contratos_ao: List[str] = []
        for contrato_ao in CONTRATOS_FIN:
            conceptos_c, partidas_c, registros_c = por_contrato[contrato_ao]
            res_ao = _avance_obra_resumen(
                conceptos_c, partidas_c, registros_c, gastos_ao if contrato_ao == "obra" else [], ini_d, fin_d,
            )
            if not (res_ao and (res_ao["real_pct"] or res_ao["programado_pct"])):
                continue
            contratos_ao.append(contrato_ao)
            for heading, caption, png in _programa_barras_graficas(conceptos_c, partidas_c, registros_c, ini_d, fin_d, contrato_ao):
                jpg = await asyncio.to_thread(_png_bytes_to_jpeg_dataurl, png)
                blocks_ao.append({"type": "imagen", "heading": heading, "imagen": jpg, "caption": caption})
            blocks_ao += _avance_obra_bloques(res_ao, ini_d, fin_d, contrato_ao)
            for heading, caption, png in _avance_obra_graficas(res_ao, fin_d, contrato_ao):
                jpg = await asyncio.to_thread(_png_bytes_to_jpeg_dataurl, png)
                blocks_ao.append({"type": "imagen", "heading": heading, "imagen": jpg, "caption": caption})
        if blocks_ao:
            titulo_ao = ("AVANCE DE OBRA Y SUPERVISIÓN" if len(contratos_ao) == 2
                         else f"AVANCE DE {CONTRATO_FIN_LABEL[contratos_ao[0]]}")
            out["avance_obra"] = {"titulo": titulo_ao, "blocks": blocks_ao}

    if activos.get("estimaciones"):
        bloques_es = _estimaciones_bloques(await db.estimaciones.find({"project_id": pid}).to_list(length=500))
        if bloques_es:
            out["estimaciones"] = {"titulo": "CONCENTRADO DE ESTIMACIONES", "blocks": bloques_es}

    if activos.get("pendientes_generales"):
        # Semanal y mensual además listan los pendientes cerrados en el período.
        con_cierre = categoria in ("reportes_semanales", "reportes_mensuales")
        bloques_pg = _pendientes_bloques(
            await db.pendientes_generales.find({"project_id": pid}).to_list(length=500),
            start_dt if con_cierre else None, end_dt if con_cierre else None,
        )
        if bloques_pg:
            out["pendientes_generales"] = {"titulo": "PENDIENTES O REQUERIMIENTOS GENERALES", "blocks": bloques_pg}

    if activos.get("aspectos_sociales"):
        # Estado vigente al corte del informe (no un log): levantamientos y
        # salvamento acumulan desde el arranque de los trabajos.
        corte_as = end_dt.astimezone(MX_TZ).date()
        lev_as = await db.levantamientos_sociales.find({"project_id": pid}).to_list(length=50)
        salv_as = await db.salvamento_arqueologico.find({"project_id": pid}).to_list(length=2000)
        blocks_as = _levantamientos_bloques(lev_as)
        for heading, caption, png in _levantamientos_graficas(lev_as) + _salvamento_graficas(salv_as, corte_as):
            jpg = await asyncio.to_thread(_png_bytes_to_jpeg_dataurl, png)
            blocks_as.append({"type": "imagen", "heading": heading, "imagen": jpg, "caption": caption})
        if blocks_as:
            out["aspectos_sociales"] = {"titulo": "ASPECTOS SOCIALES", "blocks": blocks_as}

    if activos.get("actividades_particulares"):
        d_ini_ap = start_dt.astimezone(MX_TZ).date().isoformat()
        d_fin_ap = end_dt.astimezone(MX_TZ).date().isoformat()
        regs_ap = await db.actividades_particulares.find(
            {"project_id": pid, "fecha": {"$gte": d_ini_ap, "$lte": d_fin_ap}, **jq}
        ).to_list(length=5000)
        if regs_ap:
            cat_ap = await db.act_part_cat.find({"project_id": pid}).sort("orden", 1).to_list(length=200)
            nodos_ap = await db.location_nodes.find({"project_id": pid}).to_list(length=20000)
            bloques_ap = _actividades_particulares_bloques(regs_ap, cat_ap, nodos_ap)
            if bloques_ap:
                out["actividades_particulares"] = {"titulo": "ACTIVIDADES PARTICULARES", "blocks": bloques_ap}

    if activos.get("electromecanica"):
        # Estado vigente (no un log): lo capturado/editado en el módulo.
        doc_em = await db.electromecanica.find_one({"project_id": pid})
        bloques_em = await _electromec_bloques(doc_em) if doc_em else []
        if bloques_em:
            out["electromecanica"] = {"titulo": "SISTEMA ELECTROMECÁNICO", "blocks": bloques_em}

    if activos.get("supervision_ambiental"):
        # Estado vigente (no un log): lo capturado/editado a mano en el módulo.
        items_amb = await db.ambiental.find({"project_id": pid}).to_list(length=2000)
        cfg_amb = await db.ambiental_config.find_one({"project_id": pid}) or {}
        bloques_amb = await _ambiental_bloques(items_amb, cfg_amb)
        if bloques_amb:
            out["supervision_ambiental"] = {"titulo": "SUPERVISIÓN AMBIENTAL", "blocks": bloques_amb}

    if activos.get("juntas_trabajo"):
        # CALCULADO de las minutas (sin captura propia): las juntas del período
        # por fecha de reunión, con el consecutivo de la minuta.
        d_ini_jt = start_dt.astimezone(MX_TZ).date().isoformat()
        d_fin_jt = end_dt.astimezone(MX_TZ).date().isoformat()
        minutas_jt = await db.minutas.find(
            {"project_id": pid, "fecha_reunion": {"$gte": d_ini_jt, "$lte": d_fin_jt}}
        ).to_list(length=2000)
        bloques_jt = _juntas_bloques(minutas_jt)
        if bloques_jt:
            out["juntas_trabajo"] = {"titulo": "RELACIÓN DE JUNTAS DE TRABAJO", "blocks": bloques_jt}

    if activos.get("indicadores_seguridad"):
        corte_is = end_dt.astimezone(MX_TZ).date()
        bloques_is, graficas_is, bloques_pipc = _indicadores_seguridad_graficas(
            await db.seguridad_indicadores.find({"project_id": pid}).to_list(length=5000),
            await db.seguridad_reportes.find({"project_id": pid}).to_list(length=20000),
            corte_is,
        )
        for heading, caption, png in graficas_is:
            jpg = await asyncio.to_thread(_png_bytes_to_jpeg_dataurl, png)
            bloques_is.append({"type": "imagen", "heading": heading, "imagen": jpg, "caption": caption})
        bloques_is += bloques_pipc
        if bloques_is:
            out["indicadores_seguridad"] = {"titulo": "CUMPLIMIENTO SEGURIDAD E HIGIENE", "blocks": bloques_is}

    # Creador de módulos: cada módulo personalizado trae su propio modo de impresión
    # por informe (texto/tabla/resumen/fotos/oculto), ver `_cm_secciones_export`.
    out.update(await _cm_secciones_export(pid, categoria, start_dt, end_dt))

    return out


@api.get("/projects/{pid}/export/reports.docx")
async def export_reports_docx(
    pid: str,
    period: str = Query("today", description="today|yesterday|week|month"),
    period_type: Optional[str] = Query(
        None,
        description="diario | semanal | mensual · categoría de reporte. "
                    "Si se envía, sobrescribe `period` y aplica la política "
                    "de severidad correspondiente.",
    ),
    area_id: Optional[str] = Query(None, description="Filtro por área (opcional)"),
    scope: Optional[str] = Query(None, description="mine|area (para especialistas)"),
    user: dict = Depends(current_user),
):
    """Exporta reportes en formato Microsoft Word (.docx). 100 % en RAM.

    Filtros idénticos al PDF/PPTX: severidad (según `period_type` si se
    envía, o Importante+Urgente por default), área opcional, y scope para
    especialistas."""
    try:
        import base64
        from docx import Document
        from docx.shared import Cm, Pt, RGBColor
        from docx.enum.text import WD_ALIGN_PARAGRAPH
        from docx.oxml.ns import qn
        from docx.oxml import OxmlElement
    except Exception as e:
        raise HTTPException(500, f"python-docx no instalado: {e}")

    scope_mine_only = (scope or "").lower() == "mine"
    data = await _gather_export_data(
        pid, period, user,
        area_id=area_id,
        scope_mine_only=scope_mine_only,
        period_type=period_type,
    )
    proj = data["proj"]
    leaf_nodes = data["leaf_nodes"]
    reports_by_node = data["reports_by_node"]
    announcements_by_node = data["announcements_by_node"]
    path_cache = data["path_cache"]
    start_dt = data["start_dt"]
    end_dt = data["end_dt"]
    cover_ancestor_by_node = data.get("cover_ancestor_by_node", {})

    project_name = proj.get("name", "Proyecto")
    project_contract = proj.get("contract_number") or "—"
    project_constructora = proj.get("constructora") or "—"
    project_objeto = proj.get("objeto_contrato") or None
    project_cliente = (proj.get("cliente_principal") or "").strip() or None
    project_color = _sanitize_color_hex(proj.get("color_institucional") or proj.get("color_tema")) or "#003366"
    constructora_logo_b64 = (proj.get("constructora_logo") or "").strip() or None
    fechas_label = f"{_fmt_fecha_dd_mm_yyyy(start_dt)} a {_fmt_fecha_dd_mm_yyyy(end_dt)}"

    area_label = "Todas las áreas"
    if area_id:
        area = await db.areas.find_one({"id": area_id, "project_id": pid})
        if area:
            area_label = f"Área: {area.get('name', '—')}"

    # Sistema Multi-Proyecto Modular: sección de cierre con Forestal y
    # Arbolado / Seguridad e Higiene, solo si el Coordinador los encendió
    # para este proyecto — ver _gather_modulos_export_data.
    modulos_categoria = _modulos_categoria_para_export(period_type, period)
    modulos_data = await _gather_modulos_export_data(pid, proj, start_dt, end_dt, modulos_categoria)
    firma_cierre = _cierre_firma(proj, modulos_categoria, start_dt, end_dt)

    def _build_docx_blocking() -> bytes:
        """Motor DOCX estrictamente MONOCROMÁTICO, enfocado a LECTURA
        (2026-07-06 · CDMX · Batch de Producción V2).

        Diseño solicitado:
          * Un solo reporte por página (page break forzoso al finalizar cada uno).
          * SIN imágenes ni columnas: puro texto ordenado y legible.
          * Encabezado repetido en cada página con logo de la empresa (o nombre
            del proyecto si no hay logo) + fecha de exportación (CDMX).
          * Cuerpo por reporte: Ubicación · Área/Disciplina · Fecha · Autor,
            descripciones individuales por foto (`photo_captions[i]`) y la
            observación general al final.
          * PALETA ESTRICTAMENTE B/N (ahorro de tinta, impresión ejecutiva):
              - Títulos/etiquetas fuertes → negro puro (0,0,0).
              - Cuerpo de texto            → negro puro (0,0,0).
              - Texto secundario/atenuado  → gris oscuro (0x59,0x59,0x59).
              - Etiquetas muy sutiles      → gris medio (0x8C,0x8C,0x8C).
            No se aplica `project_color` en ninguna parte del documento; el
            color de marca del proyecto sólo se conserva para el PDF/PPTX.
        """
        def _fmt_cdmx(dt) -> str:
            if not dt:
                return "—"
            try:
                if isinstance(dt, str):
                    try:
                        dt = datetime.fromisoformat(dt.replace("Z", "+00:00"))
                    except Exception:
                        return dt
                if isinstance(dt, datetime):
                    if dt.tzinfo is None:
                        dt = dt.replace(tzinfo=timezone.utc)
                    dt = dt.astimezone(MX_TZ)
                    return dt.strftime("%d/%m/%Y %H:%M")
            except Exception:
                pass
            return str(dt)

        # Fecha de exportación (para el header institucional) — misma zona
        # horaria institucional (MX_TZ) que el resto del sistema, nunca una
        # re-derivación local con su propio fallback.
        exported_at = datetime.now(timezone.utc).astimezone(MX_TZ).strftime("%d/%m/%Y %H:%M CDMX")

        # Logo (bytes) o None → nombre proyecto en su lugar.
        logo_bytes = _resolve_export_logo_bytes(constructora_logo_b64)

        # ============================================================
        # PALETA ESTRICTAMENTE MONOCROMÁTICA (blanco y negro / gris)
        # ------------------------------------------------------------
        # Requerimiento ejecutivo (Batch Producción V2): la salida DOCX
        # NO usa colores de marca — sólo negro y grises — para impresión
        # profesional y lectura sin ruido visual. Todos los alias de
        # colores que existían antes (BRAND_RGB, TEXT_RGB, MUTED_RGB,
        # SUBTLE_RGB) se conservan pero apuntan a la misma escala de
        # grises, para minimizar el diff y no romper el layout.
        # ============================================================
        _BLACK = RGBColor(0x00, 0x00, 0x00)
        _DARK_GRAY = RGBColor(0x59, 0x59, 0x59)
        _MID_GRAY = RGBColor(0x8C, 0x8C, 0x8C)

        # Alias semánticos (todos ⊂ B/N — el color de proyecto NO se usa).
        BRAND_RGB = _BLACK        # títulos/etiquetas fuertes
        TEXT_RGB = _BLACK         # cuerpo del texto
        MUTED_RGB = _DARK_GRAY    # texto atenuado (fecha export, "sin datos")
        SUBTLE_RGB = _MID_GRAY    # etiquetas muy sutiles ("Reporte n de N")

        doc = Document()

        # ---- Ajuste de márgenes cómodos para lectura ----
        for section in doc.sections:
            section.top_margin = Cm(2.0)
            section.bottom_margin = Cm(2.0)
            section.left_margin = Cm(2.2)
            section.right_margin = Cm(2.2)

            # === Header institucional (aparece en TODAS las páginas) ======
            header = section.header
            # Limpiamos y añadimos una tabla 1×2: [logo/nombre] | [fecha export]
            for old in list(header.paragraphs):
                # python-docx no permite borrar el primer párrafo, lo reusamos.
                pass
            hdr_table = header.add_table(rows=1, cols=2, width=Cm(17))
            hdr_table.autofit = True
            left_cell = hdr_table.cell(0, 0)
            right_cell = hdr_table.cell(0, 1)

            # Celda izquierda: logo si hay bytes, si no el nombre del proyecto.
            left_p = left_cell.paragraphs[0]
            left_p.alignment = WD_ALIGN_PARAGRAPH.LEFT
            if logo_bytes:
                try:
                    left_p.add_run().add_picture(io.BytesIO(logo_bytes), height=Cm(1.2))
                except Exception:
                    lr = left_p.add_run(project_name)
                    lr.bold = True
                    lr.font.size = Pt(11)
                    lr.font.color.rgb = BRAND_RGB
            else:
                lr = left_p.add_run(project_name)
                lr.bold = True
                lr.font.size = Pt(11)
                lr.font.color.rgb = BRAND_RGB

            # Celda derecha: fecha de exportación.
            right_p = right_cell.paragraphs[0]
            right_p.alignment = WD_ALIGN_PARAGRAPH.RIGHT
            rr = right_p.add_run(f"Exportado: {exported_at}")
            rr.italic = True
            rr.font.size = Pt(9)
            rr.font.color.rgb = MUTED_RGB

        # ---- Portada (1 página) --------------------------------------
        cover_title = doc.add_paragraph()
        cover_title.alignment = WD_ALIGN_PARAGRAPH.CENTER
        # Aire vertical (~1/3 de página) usando párrafos vacíos.
        for _ in range(6):
            doc.add_paragraph()
        ct = cover_title.add_run(project_name)
        ct.bold = True
        ct.font.size = Pt(28)
        ct.font.color.rgb = BRAND_RGB

        sub = doc.add_paragraph()
        sub.alignment = WD_ALIGN_PARAGRAPH.CENTER
        sr = sub.add_run("Reporte de actividades")
        sr.font.size = Pt(16)
        sr.font.color.rgb = TEXT_RGB

        # Datos del proyecto
        meta_lines = [
            ("Contrato", str(project_contract or "—")),
            ("Constructora", str(project_constructora or "—")),
        ]
        if project_cliente:
            meta_lines.append(("Cliente", project_cliente))
        if project_objeto:
            meta_lines.append(("Objeto", project_objeto))
        meta_lines.append(("Período", fechas_label))
        meta_lines.append(("Filtro", area_label))

        # Separador visual
        doc.add_paragraph()
        for k, v in meta_lines:
            p = doc.add_paragraph()
            p.alignment = WD_ALIGN_PARAGRAPH.CENTER
            k_r = p.add_run(f"{k}: ")
            k_r.bold = True
            k_r.font.size = Pt(11)
            k_r.font.color.rgb = MUTED_RGB
            v_r = p.add_run(v)
            v_r.font.size = Pt(11)
            v_r.font.color.rgb = TEXT_RGB

        # Un solo reporte por página → salto de página tras portada.
        doc.add_page_break()

        # ---- Página DATOS DE CONTRATO (OBRA / SUPERVISIÓN) -------------
        _contrato_blq = _contrato_bloques(proj)
        if _contrato_blq:
            for _blq in _contrato_blq:
                _hp = doc.add_paragraph()
                _hr = _hp.add_run("DATOS DE CONTRATO — " + _blq["etiqueta"])
                _hr.bold = True
                _hr.font.size = Pt(15)
                _hr.font.color.rgb = BRAND_RGB
                for _lbl, _val in _blq["lineas"]:
                    _lp = doc.add_paragraph()
                    _l1 = _lp.add_run(_lbl + " ")
                    _l1.bold = True
                    _l1.font.size = Pt(11)
                    _l1.font.color.rgb = TEXT_RGB
                    _l2 = _lp.add_run(_val)
                    _l2.font.size = Pt(11)
                    _l2.font.color.rgb = TEXT_RGB
                if _blq["filas"]:
                    _ct = doc.add_table(rows=1 + len(_blq["filas"]), cols=3)
                    _ct.style = "Table Grid"
                    for _j, _h in enumerate(("", "Inicio", "Fin")):
                        _c0 = _ct.rows[0].cells[_j]
                        _r0 = _c0.paragraphs[0].add_run(_h)
                        _r0.bold = True
                        _r0.font.size = Pt(10)
                    for _ri, (_l, _v1, _v2, _unida) in enumerate(_blq["filas"], start=1):
                        _cells = _ct.rows[_ri].cells
                        _rl = _cells[0].paragraphs[0].add_run(_l)
                        _rl.bold = True
                        _rl.font.size = Pt(10)
                        if _unida:
                            _m = _cells[1].merge(_cells[2])
                            _m.paragraphs[0].add_run(_v1).font.size = Pt(10)
                        else:
                            _cells[1].paragraphs[0].add_run(_v1).font.size = Pt(10)
                            _cells[2].paragraphs[0].add_run(_v2).font.size = Pt(10)
                doc.add_paragraph()
            doc.add_page_break()

        # ---- Iteración de reportes ------------------------------------
        any_data = False
        reports_flat = []  # lista lineal en orden de árbol
        for n in leaf_nodes:
            node_reps = reports_by_node.get(n["id"]) or []
            for r in node_reps:
                reports_flat.append((n, r))

        total_reports = len(reports_flat)
        for idx, (node, r) in enumerate(reports_flat):
            any_data = True

            # ---- Encabezado del reporte ----
            title_p = doc.add_paragraph()
            title_p.alignment = WD_ALIGN_PARAGRAPH.LEFT
            title_r = title_p.add_run(f"Reporte {idx + 1} de {total_reports}")
            title_r.bold = True
            title_r.font.size = Pt(9)
            title_r.font.color.rgb = SUBTLE_RGB

            # Ubicación (jerarquía completa del nodo)
            path = path_cache.get(node["id"]) or [node.get("name", "—")]
            path_txt = " › ".join([str(x) for x in path if x])

            loc_p = doc.add_paragraph()
            l_lbl = loc_p.add_run("Ubicación:  ")
            l_lbl.bold = True
            l_lbl.font.size = Pt(12)
            l_lbl.font.color.rgb = BRAND_RGB
            l_val = loc_p.add_run(path_txt)
            l_val.font.size = Pt(12)
            l_val.font.color.rgb = TEXT_RGB

            # Área / Disciplina
            area_p = doc.add_paragraph()
            a_lbl = area_p.add_run("Área / Disciplina:  ")
            a_lbl.bold = True
            a_lbl.font.size = Pt(11)
            a_lbl.font.color.rgb = BRAND_RGB
            a_val = area_p.add_run(_normalize_area_name(
                r.get("area_name"), user_role=user.get("role"), user_area=user.get("area"),
            ))
            a_val.font.size = Pt(11)
            a_val.font.color.rgb = TEXT_RGB

            # Fecha + Autor (misma línea)
            fa_p = doc.add_paragraph()
            f_lbl = fa_p.add_run("Fecha:  ")
            f_lbl.bold = True
            f_lbl.font.size = Pt(11)
            f_lbl.font.color.rgb = BRAND_RGB
            f_val = fa_p.add_run(_fmt_cdmx(r.get("created_at")))
            f_val.font.size = Pt(11)
            f_val.font.color.rgb = TEXT_RGB
            sep_r = fa_p.add_run("        ")
            sep_r.font.size = Pt(11)
            au_lbl = fa_p.add_run("Autor:  ")
            au_lbl.bold = True
            au_lbl.font.size = Pt(11)
            au_lbl.font.color.rgb = BRAND_RGB
            au_val = fa_p.add_run(str(r.get("captured_by_name") or "—"))
            au_val.font.size = Pt(11)
            au_val.font.color.rgb = TEXT_RGB

            # Contratista, si viene informado.
            contratista_val = (r.get("contratista") or "").strip()
            if contratista_val:
                ct_p = doc.add_paragraph()
                ct_lbl = ct_p.add_run("Contratista:  ")
                ct_lbl.bold = True
                ct_lbl.font.size = Pt(11)
                ct_lbl.font.color.rgb = BRAND_RGB
                ct_val = ct_p.add_run(contratista_val)
                ct_val.font.size = Pt(11)
                ct_val.font.color.rgb = TEXT_RGB

            # Separador visual
            doc.add_paragraph()

            # ---- Descripciones por fotografía ----
            captions = r.get("photo_captions") or []
            images_count = len(r.get("images") or [])
            # Usamos el máximo real detectado, con mínimo 2 (spec del usuario).
            slots = max(2, images_count, len(captions))
            has_any_caption = False
            for i in range(slots):
                cap = (captions[i] if i < len(captions) else "") or ""
                cap = cap.strip()
                if not cap:
                    # Sólo omitimos los slots vacíos que excedan las 2 primeras
                    # cuando NO hay imagen para ellos. Los dos primeros siempre
                    # aparecen para dejar rastro documental.
                    if i >= 2 and i >= images_count:
                        continue

                cap_p = doc.add_paragraph()
                cap_lbl = cap_p.add_run(f"Fotografía {i + 1} — descripción:")
                cap_lbl.bold = True
                cap_lbl.font.size = Pt(11)
                cap_lbl.font.color.rgb = BRAND_RGB

                body_p = doc.add_paragraph()
                if cap:
                    body_r = body_p.add_run(cap)
                    body_r.font.size = Pt(11)
                    body_r.font.color.rgb = TEXT_RGB
                    has_any_caption = True
                else:
                    body_r = body_p.add_run("(Sin descripción capturada)")
                    body_r.italic = True
                    body_r.font.size = Pt(11)
                    body_r.font.color.rgb = MUTED_RGB

            # ---- Observación general ----
            obs = (r.get("observaciones") or "").strip()
            obs_p = doc.add_paragraph()
            obs_lbl = obs_p.add_run("Observación general:")
            obs_lbl.bold = True
            obs_lbl.font.size = Pt(11)
            obs_lbl.font.color.rgb = BRAND_RGB
            obs_body = doc.add_paragraph()
            if obs:
                obs_r = obs_body.add_run(obs)
                obs_r.font.size = Pt(11)
                obs_r.font.color.rgb = TEXT_RGB
            else:
                obs_r = obs_body.add_run("(Sin observaciones)")
                obs_r.italic = True
                obs_r.font.size = Pt(11)
                obs_r.font.color.rgb = MUTED_RGB

            # Avance / medición, si aparece.
            avance_val = (r.get("avance") or "").strip()
            if avance_val:
                av_p = doc.add_paragraph()
                av_lbl = av_p.add_run("Avance / medición:  ")
                av_lbl.bold = True
                av_lbl.font.size = Pt(11)
                av_lbl.font.color.rgb = BRAND_RGB
                av_val = av_p.add_run(f"{avance_val} {r.get('unidad') or ''}".strip())
                av_val.font.size = Pt(11)
                av_val.font.color.rgb = TEXT_RGB

            # Page break forzoso al finalizar cada reporte.
            doc.add_page_break()

        # ---- Empty state ---------------------------------------------
        if not any_data:
            empty = doc.add_paragraph()
            empty.alignment = WD_ALIGN_PARAGRAPH.CENTER
            er = empty.add_run("Sin reportes en el período seleccionado.")
            er.italic = True
            er.font.size = Pt(12)
            er.font.color.rgb = MUTED_RGB

        # ---- Sección de cierre GENÉRICA del sistema Multi-Proyecto Modular:
        # recorre `modulos_data` (ver `_gather_modulos_export_data`) y
        # escribe cada módulo activo a partir de sus bloques declarativos
        # (summary/table/list) — este bloque NO conoce el nombre de ningún
        # módulo ni su forma de datos particular, así que un módulo nuevo
        # (actual o futuro) aparece impreso automáticamente en cuanto
        # `_gather_modulos_export_data` lo agrega a `out` con ese esquema,
        # sin tocar ni una línea de aquí. Mismo período que el resto del
        # export.
        HEADING_RGB = {"good": RGBColor(0x16, 0xA3, 0x4A), "bad": RGBColor(0xDC, 0x26, 0x26)}

        def _mod_section_title(text: str):
            p = doc.add_paragraph()
            r = p.add_run(text)
            r.bold = True
            r.font.size = Pt(18)
            r.font.color.rgb = BRAND_RGB

        def _mod_period_sub():
            p = doc.add_paragraph()
            r = p.add_run(f"Período: {fechas_label}")
            r.italic = True
            r.font.size = Pt(10)
            r.font.color.rgb = MUTED_RGB

        def _mod_table(headers: list, rows: list):
            table = doc.add_table(rows=1, cols=len(headers))
            table.style = "Table Grid"
            for i, h in enumerate(headers):
                cell_p = table.rows[0].cells[i].paragraphs[0]
                cr = cell_p.add_run(h)
                cr.bold = True
                cr.font.size = Pt(10)
                cr.font.color.rgb = BRAND_RGB
            for row in rows:
                cells = table.add_row().cells
                for i, val in enumerate(row):
                    cp = cells[i].paragraphs[0]
                    cvr = cp.add_run(str(val))
                    cvr.font.size = Pt(10)
                    cvr.font.color.rgb = TEXT_RGB

        def _mod_heading(text: str, color_key=None):
            p = doc.add_paragraph()
            r = p.add_run(text)
            r.bold = True
            r.font.size = Pt(13)
            r.font.color.rgb = HEADING_RGB.get(color_key, BRAND_RGB)

        def _mod_empty(text: str):
            p = doc.add_paragraph()
            r = p.add_run(text)
            r.italic = True
            r.font.size = Pt(11)
            r.font.color.rgb = MUTED_RGB

        def _mod_summary_block(block: dict):
            p = doc.add_paragraph()
            r = p.add_run(block["text"])
            r.bold = True
            r.font.size = Pt(13)
            r.font.color.rgb = TEXT_RGB

        def _mod_table_block(block: dict):
            if block.get("heading"):
                _mod_heading(block["heading"])
            rows = block.get("rows") or []
            if rows:
                _mod_table(block["headers"], rows)
            else:
                _mod_empty(block.get("empty_text", "Sin datos en este período."))

        def _mod_list_block(block: dict):
            if block.get("heading"):
                _mod_heading(block["heading"], block.get("heading_color"))
            items = block.get("items") or []
            if not items:
                _mod_empty(block.get("empty_text", "Sin datos en este período."))
                return
            for it in items:
                if it.get("title"):
                    tp = doc.add_paragraph()
                    tr = tp.add_run(it["title"])
                    tr.bold = True
                    tr.font.size = Pt(11)
                    tr.font.color.rgb = BRAND_RGB
                bp = doc.add_paragraph()
                br = bp.add_run(it.get("body") or "")
                br.font.size = Pt(11)
                br.font.color.rgb = TEXT_RGB
                if it.get("extra"):
                    ep = doc.add_paragraph()
                    er = ep.add_run(it["extra"])
                    er.italic = True
                    er.font.size = Pt(10)
                    er.font.color.rgb = MUTED_RGB
                if it.get("meta"):
                    mp = doc.add_paragraph()
                    mr = mp.add_run(it["meta"])
                    mr.italic = True
                    mr.font.size = Pt(9)
                    mr.font.color.rgb = SUBTLE_RGB
                doc.add_paragraph()

        def _mod_forestal_sheet_block(block: dict):
            # Word no reproduce el formato exacto de la hoja (fuera de
            # alcance) — sirve una versión funcional simple: contadores +
            # tabla de renglones autorizados + tabla de días ejecutados.
            contadores = block.get("contadores") or {}
            _mod_summary_block({
                "text": f"Podas: {contadores.get('poda', 0)}    "
                        f"Trasplantes: {contadores.get('trasplante', 0)}    "
                        f"Derribos: {contadores.get('derribo', 0)}",
            })
            autorizado_rows = block.get("autorizado_rows") or []
            if autorizado_rows:
                _mod_heading("Resumen autorizado mediante resolución administrativa")
                _mod_table(
                    ["Estación", "Poda", "Trasplante", "Derribo", "Total árboles"],
                    [[r["estacion"], r["poda"], r["trasplante"], r["derribo"], r["total_dictaminados"]] for r in autorizado_rows],
                )
            dias = block.get("dias") or []
            if dias:
                _mod_heading("Actividades ejecutadas en el período")
                _mod_table(
                    ["Fecha", "Podas", "Trasplantes", "Derribos", "Total"],
                    [[d["fecha"], d["poda"], d["trasplante"], d["derribo"], d["total"]] for d in dias],
                )

        def _mod_riesgos_mapa_block(block: dict):
            # Idem: versión simple para Word, sin celdas combinadas.
            rows = []
            for g in block.get("grupos") or []:
                for f in g.get("filas") or []:
                    rows.append([g["estacion"], f["descripcion"], f["control"], f"{f['avance']}%"])
            if rows:
                _mod_table(["Estación/Poste", "Riesgo", "Propuesta de control", "Avance"], rows)

        def _mod_seguridad_indicadores_block(block: dict):
            _mod_heading(block.get("subtitulo") or "")
            items = block.get("items") or []
            if not items:
                _mod_empty("Sin acciones correctivas pendientes.")
                return
            for text in items:
                p = doc.add_paragraph(style="List Bullet")
                r = p.add_run(text)
                r.font.size = Pt(11)
                r.font.color.rgb = TEXT_RGB

        def _mod_estudios_avances_block(block: dict):
            _mod_heading("Avances")
            grupos = block.get("grupos") or []
            any_item = False
            for g in grupos:
                items = g.get("items") or []
                if not items:
                    continue
                any_item = True
                dp = doc.add_paragraph()
                dr = dp.add_run(g["disciplina"])
                dr.bold = True
                dr.font.size = Pt(11)
                dr.font.color.rgb = BRAND_RGB
                for text in items:
                    p = doc.add_paragraph(style="List Bullet")
                    r = p.add_run(text)
                    r.font.size = Pt(10.5)
                    r.font.color.rgb = TEXT_RGB
            if not any_item:
                _mod_empty("Sin avances registrados en este período.")

        def _mod_tabla_resumen_matriz_block(block: dict):
            # Word no reproduce el formato exacto (colores/leyenda, fuera de
            # alcance) — una sola tabla plana con todas las columnas.
            columnas = block.get("columnas") or []
            filas = block.get("filas") or []
            if not columnas or not filas:
                _mod_empty("Sin datos capturados en la Tabla Resumen.")
                return
            headers = ["Actividad"] + [col["label"] for col in columnas] + ["Total"]
            rows = []
            for f in filas:
                row = [f["actividad"]]
                if f.get("seccion"):
                    rows.append(row + [""] * (len(headers) - 1))
                    continue
                for v in f["valores"]:
                    if v["no_aplica"]:
                        row.append("N/A")
                    elif v["valor"] is None:
                        row.append("")
                    else:
                        val = v["valor"]
                        row.append(f"{val:.0f}%" if float(val).is_integer() else f"{val:.2f}%")
                t = f.get("total")
                row.append(f"{t:.2f}%" if t is not None else "—")
                rows.append(row)
            _mod_table(headers, rows)

        def _mod_image_b64(b64_str, width_cm: float) -> bool:
            try:
                raw = base64.b64decode(_strip_b64_prefix(b64_str))
                doc.add_picture(io.BytesIO(raw), width=Cm(width_cm))
                return True
            except Exception:
                return False

        def _mod_fotos_comparativa_block(block: dict):
            for it in (block.get("items") or []):
                if it.get("titulo"):
                    _mod_heading(it["titulo"])
                t = doc.add_table(rows=2, cols=2)
                for col, (key, lbl, fkey) in enumerate((
                    ("original", "ORIGINAL", "fecha_original"), ("actual", "ACTUAL", "fecha_actual"),
                )):
                    celda = t.rows[0].cells[col]
                    if _foto_comp_desc(it, key):
                        dp = celda.paragraphs[0]
                        if it.get("desc_encabezado"):
                            dr = dp.add_run(it["desc_encabezado"] + "\n")
                            dr.bold = True
                            dr.font.size = Pt(9)
                        dt = dp.add_run(_foto_comp_desc(it, key))
                        dt.font.size = Pt(9)
                        cp = celda.add_paragraph()
                    else:
                        cp = celda.paragraphs[0]
                    cp.alignment = WD_ALIGN_PARAGRAPH.CENTER
                    if not it.get(key) and it.get("sin_placeholder"):
                        continue
                    if it.get(key):
                        try:
                            cp.add_run().add_picture(
                                io.BytesIO(base64.b64decode(_strip_b64_prefix(it[key]))), width=Cm(8.0),
                            )
                        except Exception:
                            cp.add_run("Sin foto").italic = True
                    else:
                        cp.add_run("Sin foto").italic = True
                    lp = t.rows[1].cells[col].paragraphs[0]
                    lp.alignment = WD_ALIGN_PARAGRAPH.CENTER
                    lr = lp.add_run(_foto_comp_etiqueta(it, key, lbl))
                    lr.bold = True
                    lr.font.size = Pt(10)
                if block.get("leyenda"):
                    lgp = doc.add_paragraph()
                    lgp.alignment = WD_ALIGN_PARAGRAPH.CENTER
                    for lb, hexcolor in block["leyenda"]:
                        dot = lgp.add_run("\u25CF ")
                        dot.font.color.rgb = RGBColor(*tuple(int(hexcolor[i:i + 2], 16) for i in (1, 3, 5)))
                        t = lgp.add_run(lb + "    ")
                        t.font.size = Pt(9)
                doc.add_paragraph()

        def _mod_imagen_block(block: dict):
            if block.get("heading"):
                _mod_heading(block["heading"])
            _mod_image_b64(block["imagen"], 16.0)
            if block.get("caption"):
                p = doc.add_paragraph()
                r = p.add_run(block["caption"])
                r.bold = True
                r.font.size = Pt(10)
                r.font.color.rgb = TEXT_RGB

        def _mod_seguridad_accidentes_block(block: dict):
            """Registro de accidentes en Word: tabla de 9 columnas con la foto
            dentro de su celda."""
            if block.get("heading"):
                _mod_heading(block["heading"])
            rows = block.get("rows") or []
            if not rows:
                _mod_empty("Sin registros de accidentes en este período.")
                return
            headers = ["Fecha", "Mes", "Trabajador", "Contratista", "Registro", "Ubicación", "Descripción", "Foto", "Seguimiento"]
            keys = ["fecha", "mes", "trabajador", "contratista", "registro", "ubicacion",
                    "descripcion", None, "seguimiento"]
            t = doc.add_table(rows=1, cols=len(headers))
            t.style = "Table Grid"
            for i, h in enumerate(headers):
                cr = t.rows[0].cells[i].paragraphs[0].add_run(h)
                cr.bold = True
                cr.font.size = Pt(8)
            for r in rows:
                cells = t.add_row().cells
                for i, k in enumerate(keys):
                    cp = cells[i].paragraphs[0]
                    if k is None:
                        if r.get("foto"):
                            try:
                                cp.add_run().add_picture(
                                    io.BytesIO(base64.b64decode(_strip_b64_prefix(r["foto"]))), width=Cm(2.2),
                                )
                                continue
                            except Exception:
                                pass
                        cp.add_run("—").font.size = Pt(8)
                        continue
                    cp.add_run(str(r.get(k) or "—")).font.size = Pt(8)
            doc.add_paragraph()

        _MOD_BLOCK_RENDERERS = {
            "summary": _mod_summary_block,
            "fotos_comparativa": _mod_fotos_comparativa_block,
            "imagen": _mod_imagen_block,
            "table": _mod_table_block,
            "list": _mod_list_block,
            "forestal_sheet": _mod_forestal_sheet_block,
            "riesgos_mapa": _mod_riesgos_mapa_block,
            "seguridad_indicadores": _mod_seguridad_indicadores_block,
            "seguridad_accidentes": _mod_seguridad_accidentes_block,
            "estudios_avances": _mod_estudios_avances_block,
            "tabla_resumen_matriz": _mod_tabla_resumen_matriz_block,
        }

        for _mod_data in modulos_data.values():
            if _mod_data is None:
                continue
            doc.add_page_break()
            _mod_section_title(_mod_data["titulo"])
            _mod_period_sub()
            doc.add_paragraph()
            for block in _mod_data["blocks"]:
                _MOD_BLOCK_RENDERERS[block["type"]](block)

        if firma_cierre:
            doc.add_page_break()
            for _txt, _sz, _color, _gap in (
                (firma_cierre["titulo"], 26, BRAND_RGB, 60), (firma_cierre["periodo"], 13, None, 8),
                (firma_cierre["nombre"], 15, None, 70), (firma_cierre["cargo"], 11, MUTED_RGB, 0),
            ):
                _p = doc.add_paragraph()
                _p.alignment = WD_ALIGN_PARAGRAPH.CENTER
                _p.paragraph_format.space_before = Pt(_gap)
                _r = _p.add_run(_txt)
                _r.bold = True
                _r.font.size = Pt(_sz)
                if _color is not None:
                    _r.font.color.rgb = _color

        buf = io.BytesIO()
        doc.save(buf)
        return buf.getvalue()

    docx_bytes = await asyncio.to_thread(_build_docx_blocking)
    fname = _safe_export_filename(project_name, period, "docx")
    return StreamingResponse(
        io.BytesIO(docx_bytes),
        media_type="application/vnd.openxmlformats-officedocument.wordprocessingml.document",
        headers={"Content-Disposition": f'attachment; filename="{fname}"'},
    )


@api.get("/projects/{pid}/export/reports.pptx")
async def export_reports_pptx(
    pid: str,
    period: str = Query("today", description="today|yesterday|week|month"),
    period_type: Optional[str] = Query(
        None,
        description="diario | semanal | mensual · categoría ejecutiva.",
    ),
    area_id: Optional[str] = Query(None, description="Filtro por área (opcional)"),
    scope: Optional[str] = Query(None, description="mine|area (para especialistas)"),
    recuento_nivel: Optional[str] = Query(
        None, description="tramo|subtramo|hoja|personalizado — nivel de agregación del Recuento "
                           "General. Si se omite, usa la preferencia guardada del proyecto o "
                           "'subtramo' por defecto.",
    ),
    recuento_node_ids: Optional[str] = Query(
        None, description="IDs de nodo separados por coma — solo aplica si recuento_nivel="
                           "personalizado. Si se omite, usa la preferencia guardada del proyecto.",
    ),
    recuento_sin_datos: Optional[str] = Query(
        None, description="omitir|leyenda — qué hacer con nodos de agregación sin actividad en "
                           "el período. Si se omite, usa la preferencia guardada del proyecto o "
                           "'omitir' por defecto.",
    ),
    user: dict = Depends(current_user),
):
    """Exporta reportes en formato PowerPoint (.pptx) — Layout Ejecutivo."""
    try:
        import base64
        from pptx import Presentation
        from pptx.util import Cm, Pt
        from pptx.dml.color import RGBColor as PRGBColor
        from pptx.enum.text import PP_ALIGN
    except Exception as e:
        raise HTTPException(500, f"python-pptx no instalado: {e}")

    # === Datos comunes del export ===========================================
    scope_mine_only = (scope or "").lower() == "mine"
    data = await _gather_export_data(
        pid, period, user,
        area_id=area_id,
        scope_mine_only=scope_mine_only,
        period_type=period_type,
    )
    proj = data["proj"]
    leaf_nodes = data["leaf_nodes"]
    reports_by_node = data["reports_by_node"]
    path_cache = data["path_cache"]
    start_dt = data["start_dt"]
    end_dt = data["end_dt"]
    cover_ancestor_by_node = data.get("cover_ancestor_by_node", {})
    areas_by_id = data.get("areas_by_id", {})
    pt_norm = data.get("period_type")
    nodes_by_id = data.get("nodes_by_id") or {}
    nodes_by_subtramo = data.get("nodes_by_subtramo") or {}
    root_ids = data.get("root_ids") or []
    workforce_reports_by_node = data.get("reports_by_node_workforce") or reports_by_node
    # Página de resumen por Subtramo: mismo resumen consolidado (sin
    # desglose por día ni autor), actividades y clima usados en el PDF
    # ejecutivo — reemplaza el panel dual agrupado por Tramo (nodo raíz).
    resource_consolidated_by_subtramo = _workforce_consolidated_by_subtramo(workforce_reports_by_node, nodes_by_id)
    # Turno nocturno (ver export_reports_pdf): hoja diurna + hoja nocturna de
    # la misma estación; sin turno configurado `_wf_noche` queda vacío.
    _wf_dia, _wf_noche = separar_reportes_por_turno(workforce_reports_by_node, proj)
    resource_consolidated_dia_by_subtramo = _workforce_consolidated_by_subtramo(_wf_dia, nodes_by_id)
    resource_consolidated_noche_by_subtramo = _workforce_consolidated_by_subtramo(_wf_noche, nodes_by_id)
    actividades_by_subtramo = _actividades_by_subtramo(_wf_dia, nodes_by_id)
    actividades_noche_by_subtramo = _actividades_by_subtramo(_wf_noche, nodes_by_id)
    # Numeración "ESTACIÓN N." del título de la slide-resumen por Subtramo —
    # ver la misma nota en export_reports_pdf.
    _subtramo_ordinal = {
        n["id"]: i + 1
        for i, n in enumerate(
            sorted((n for n in nodes_by_id.values() if n.get("depth") == 1),
                   key=lambda n: (n.get("order", 0), n.get("name", "")))
        )
    }
    # Slide(s) de cierre "RECUENTO GENERAL": consolidado del período
    # completo, agrupado por el nivel de agregación configurado — ver la
    # misma nota en export_reports_pdf.
    recuento_nivel_eff, recuento_node_ids_eff, recuento_incluir_sin_datos = _resolve_recuento_config(
        proj, recuento_nivel, recuento_node_ids, recuento_sin_datos,
    )
    recuento_general_rows = _recuento_general_by_nodo(
        workforce_reports_by_node, nodes_by_id, root_ids,
        nivel=recuento_nivel_eff, node_ids=recuento_node_ids_eff,
        incluir_sin_datos=recuento_incluir_sin_datos,
    )
    # Resumen de Actividades Generales CURADAS por Área, para insertar
    # dentro de cada bloque de Área del cuerpo del PPTX — ver la misma nota
    # en export_reports_pdf.
    actividades_curadas_idx = await _actividades_curadas_resumen_por_area(pid, start_dt, end_dt, user)
    # Página-resumen por Subtramo: misma corrección que en export_reports_pdf
    # — sus viñetas "ACTIVIDADES" ahora reflejan ediciones del hub en vez de
    # leer `report.actividades` crudo.
    actividades_curadas_by_subtramo = await _actividades_curadas_resumen_por_subtramo(
        pid, start_dt, end_dt, user, nodes_by_id,
    )
    for _sid, _textos in actividades_curadas_by_subtramo.items():
        if _textos and _sid not in actividades_noche_by_subtramo:
            actividades_by_subtramo[_sid] = _textos
    # Resumen de actividades POR FRENTE, al inicio del PPTX con el formato del
    # reporte semanal de referencia — mismas actividades que muestra el hub
    # (`_actividades_generales_core`) para el rango exacto del informe.
    _actividades_items_resumen = await _actividades_generales_core(
        pid, None, {"$gte": start_dt, "$lte": end_dt}, user, incluir_ocultas=False,
    )
    actividades_resumen_frente = _actividades_resumen_por_frente(_actividades_items_resumen, nodes_by_id)
    # Clima: misma prioridad manual > automático que `export_reports_pdf` —
    # ver módulo "Estado del Tiempo" más arriba.
    _fecha_cdmx_hoy = datetime.now(timezone.utc).astimezone(MX_TZ).date().isoformat()
    _weather_logs_hoy = await db.weather_logs.find(
        {"project_id": pid, "fecha_cdmx": _fecha_cdmx_hoy},
    ).to_list(length=500)
    _weather_logs_by_node = _latest_weather_log_by_node(_weather_logs_hoy)

    weather_by_subtramo: dict = {}
    _weather_cache: dict = {}
    # FIX (2026-09): ver la misma nota en export_reports_pdf — un Subtramo
    # sin reportes pero con clima capturado a mano hoy no debe quedar sin
    # resolver solo porque no aparece en `resource_consolidated_by_subtramo`.
    _subtramo_ids_for_weather = set(resource_consolidated_by_subtramo.keys()) | set(_weather_logs_by_node.keys())
    for _subtramo_id in _subtramo_ids_for_weather:
        _manual = _weather_logs_by_node.get(_subtramo_id)
        _manual_fields = (
            {k: _manual.get(k) for k in ("temperature_c", "wind_kmh", "precipitation_mm", "us_aqi")}
            if _manual else None
        )
        if _manual_fields and any(v is not None for v in _manual_fields.values()):
            weather_by_subtramo[_subtramo_id] = _manual_fields
            continue
        _lat, _lon = _weather_coords_for_subtramo(_subtramo_id, nodes_by_id, workforce_reports_by_node)
        _cache_key = (_lat, _lon)
        if _cache_key not in _weather_cache:
            _weather_cache[_cache_key] = await _fetch_weather_for_export(_lat, _lon)
        weather_by_subtramo[_subtramo_id] = _weather_cache[_cache_key]

    project_name = proj.get("name", "Proyecto")
    project_contract = proj.get("contract_number") or "—"  # noqa: F841
    project_constructora = proj.get("constructora") or "—"  # noqa: F841
    project_color = _sanitize_color_hex(proj.get("color_institucional") or proj.get("color_tema")) or "#003366"
    _ch = project_color.lstrip("#")
    BRAND_RGB = (int(_ch[0:2], 16), int(_ch[2:4], 16), int(_ch[4:6], 16))
    fechas_label = f"{_fmt_fecha_dd_mm_yyyy(start_dt)} a {_fmt_fecha_dd_mm_yyyy(end_dt)}"

    # Sistema Multi-Proyecto Modular: slides de cierre con Forestal y
    # Arbolado / Seguridad e Higiene, solo si el Coordinador los encendió
    # para este proyecto — ver _gather_modulos_export_data.
    modulos_categoria = _modulos_categoria_para_export(period_type, period)
    modulos_data = await _gather_modulos_export_data(pid, proj, start_dt, end_dt, modulos_categoria)
    firma_cierre = _cierre_firma(proj, modulos_categoria, start_dt, end_dt)

    # Título ejecutivo dependiendo del tipo de reporte.
    _report_title_map = {
        "diario": "REPORTE DIARIO",
        "semanal": "REPORTE SEMANAL",
        "mensual": "REPORTE MENSUAL",
    }
    report_title = _report_title_map.get(pt_norm or "", "REPORTE")

    area_label = "Todas las áreas"  # noqa: F841
    if area_id:
        area = await db.areas.find_one({"id": area_id, "project_id": pid})
        if area:
            area_label = f"Área: {area.get('name', '—')}"

    def _build_pptx_blocking() -> bytes:
        tpl_pptx = _get_project_template(proj, "pptx")

        # ==============================================================
        # Motor PPTX (v2): TODO fondo proviene del MEMBRETE del usuario.
        # Si la plantilla existe, la 1ª slide es el "membrete master" y
        # se clona para CADA nueva slide del reporte. NO se dibujan
        # rectángulos de color hardcoded, ni bandas, ni headers, ni
        # footers programáticos: solo se INYECTA contenido dinámico
        # (texto, imágenes) sobre copias del membrete.
        # Si no hay plantilla, se generan slides en blanco sin decoración.
        # ==============================================================
        # tpl_cover_slide  = Slide 0 de la plantilla → PORTADA (se deja 100% intacta).
        # tpl_master_slide = Slide 1 de la plantilla ("ACTIVIDADES GENERALES") →
        #                    fondo/membrete UNIVERSAL clonado para Mapa, Nodos,
        #                    Reportes, Notas, etc.
        tpl_cover_slide = None
        tpl_master_slide = None
        if tpl_pptx:
            try:
                prs = Presentation(tpl_pptx)
                _n_tpl_slides = len(prs.slides)
                if _n_tpl_slides > 0:
                    tpl_cover_slide = prs.slides[0]
                if _n_tpl_slides > 1:
                    tpl_master_slide = prs.slides[1]
                else:
                    # Plantilla con una sola diapositiva: se reutiliza esa misma
                    # como membrete universal.
                    tpl_master_slide = tpl_cover_slide
                if _n_tpl_slides == 0:
                    prs = Presentation()
                    prs.slide_width = Cm(29.7)
                    prs.slide_height = Cm(21.0)
            except Exception:
                prs = Presentation()
                prs.slide_width = Cm(29.7)
                prs.slide_height = Cm(21.0)
        else:
            prs = Presentation()
            prs.slide_width = Cm(29.7)
            prs.slide_height = Cm(21.0)
        _force_pptx_theme_font(prs, "Arial")
        SW, SH = prs.slide_width, prs.slide_height
        # Margen superior seguro para no invadir logos/encabezado del membrete.
        TOP_MARGIN = Cm(3.5)
        BOTTOM_MARGIN = Cm(2.0)
        blank = prs.slide_layouts[6]

        # Marcas de sección para el índice editable: (clave, título, posición
        # en `sldIdLst` de la primera diapositiva de la sección). Ver
        # `_indice_ranges`/`_apply_indice_pptx`.
        _indice_marks: List[tuple] = []

        def _indice_mark(key: str, title: str) -> None:
            _indice_marks.append((key, title, len(prs.slides._sldIdLst)))

        # Imports adicionales para shape fill
        from pptx.enum.shapes import MSO_SHAPE  # noqa: F401  (kept for compat)
        from pptx.oxml.ns import qn as _qn  # noqa: F401
        from lxml import etree as _ET  # noqa: F401
        from copy import deepcopy as _deepcopy

        def _clone_slide(source_slide):
            """Clona una slide arbitraria (portada o membrete) reparando rIds.

            Deep-copia los shapes reparando las relaciones (`r:embed`,
            `r:link`) de imágenes para apuntar a rIds válidos en la slide
            destino. Sirve para clonar TANTO el membrete (Slide 1) como
            la portada institucional (Slide 0, usada para portadillas de
            área).
            """
            if source_slide is None:
                return prs.slides.add_slide(blank)
            try:
                from pptx.oxml.ns import qn as _qn
                _IMG_REL = (
                    "http://schemas.openxmlformats.org/"
                    "officeDocument/2006/relationships/image"
                )
                _EMBED = _qn("r:embed")
                _LINK = _qn("r:link")
                new_slide = prs.slides.add_slide(source_slide.slide_layout)
                for shp in list(new_slide.shapes):
                    try:
                        shp.element.getparent().remove(shp.element)
                    except Exception:
                        pass
                for shp in source_slide.shapes:
                    try:
                        new_el = _deepcopy(shp.element)
                        _skip_shape = False
                        for blip in new_el.iter(_qn("a:blip")):
                            for _attr in (_EMBED, _LINK):
                                old_rid = blip.get(_attr)
                                if not old_rid:
                                    continue
                                try:
                                    image_part = source_slide.part.related_part(old_rid)
                                    new_rid = new_slide.part.relate_to(image_part, _IMG_REL)
                                    blip.set(_attr, new_rid)
                                except Exception:
                                    _skip_shape = True
                                    break
                            if _skip_shape:
                                break
                        if _skip_shape:
                            continue
                        new_slide.shapes._spTree.insert_element_before(new_el, "p:extLst")
                    except Exception:
                        continue
                return new_slide
            except Exception:
                return prs.slides.add_slide(blank)

        def _clone_membrete():
            """Clona el membrete institucional (Slide 1) para páginas de contenido."""
            return _clone_slide(tpl_master_slide)

        def _clone_cover_bg():
            """Clona el fondo de la portada (Slide 0) para portadillas de Área."""
            return _clone_slide(tpl_cover_slide) if tpl_cover_slide else _clone_membrete()

        def add_bg_rect(slide, x, y, w, h, rgb_tuple):
            """DEPRECATED · no-op: los fondos ahora provienen exclusivamente
            del membrete de la plantilla. Mantenida por compatibilidad."""
            return None

        def add_text(slide, x, y, w, h, text, *, size=14, bold=False, color=(0x0F, 0x17, 0x2A),
                     align=PP_ALIGN.LEFT, italic=False, tight=False):
            tb = slide.shapes.add_textbox(x, y, w, h)
            tf = tb.text_frame
            tf.word_wrap = True
            if tight:
                # Celdas de tabla: sin márgenes internos y centrado vertical,
                # para que el texto no se salga de su fila y lo tape la de abajo.
                from pptx.enum.text import MSO_ANCHOR
                tf.margin_top = tf.margin_bottom = 0
                tf.margin_left = tf.margin_right = 0
                tf.vertical_anchor = MSO_ANCHOR.MIDDLE
            p = tf.paragraphs[0]
            p.alignment = align
            run = p.add_run()
            run.text = str(text)
            run.font.size = Pt(size)
            run.font.bold = bold
            run.font.italic = italic
            run.font.color.rgb = PRGBColor(*color)
            return tb

        # === Paleta derivada de BRAND (mismo criterio que el PDF: nunca hex fijo) ===
        _total_tint_hex = _blend_hex_with_white(project_color, 0.78)
        _header_shadow_hex = _blend_hex_with_black(project_color, 0.28)
        _zebra_tint_hex = _blend_hex_with_white(project_color, 0.95)
        WF_TOTAL_TINT_RGB = tuple(int(_total_tint_hex.lstrip("#")[i:i + 2], 16) for i in (0, 2, 4))
        WF_HEADER_SHADOW_RGB = tuple(int(_header_shadow_hex.lstrip("#")[i:i + 2], 16) for i in (0, 2, 4))
        WF_ZEBRA_TINT_RGB = tuple(int(_zebra_tint_hex.lstrip("#")[i:i + 2], 16) for i in (0, 2, 4))
        WF_BORDER_RGB = (0xE2, 0xE8, 0xF0)
        WF_MUTED_RGB = (0x64, 0x74, 0x8B)
        WF_TEXT_RGB = (0x0F, 0x17, 0x2A)
        WF_WHITE_RGB = (0xFF, 0xFF, 0xFF)
        # FIX 2026-08-13 · CONTRASTE EN PPTX (paridad con el motor PDF)
        # ─────────────────────────────────────────────────────────
        # `BRAND_RGB` (arriba) es el color de identidad CRUDO del proyecto —
        # correcto para RELLENOS sólidos (headers de tabla, íconos, barras),
        # pero si se usa tal cual como color de TEXTO sobre fondo BLANCO y el
        # proyecto tiene un tema claro/pastel, el texto queda casi invisible
        # (mismo bug ya resuelto en el motor PDF vía `_readable_dark_hex` y
        # en el frontend vía `readableAccent()` — ver theme.ts). Dos
        # variables nuevas, cero hex fijo:
        #   - READABLE_BRAND_RGB: para TEXTO de marca sobre fondo blanco
        #     (títulos de sección, "RECUENTO GENERAL", cifras destacadas).
        #   - HEADER_TEXT_RGB: para texto DENTRO de un encabezado de tabla
        #     con fondo BRAND_RGB crudo — blanco si el fondo es oscuro,
        #     oscuro si el fondo es claro (antes hardcodeado a blanco fijo).
        _readable_brand_hex = _readable_dark_hex(project_color)
        READABLE_BRAND_RGB = tuple(int(_readable_brand_hex.lstrip("#")[i:i + 2], 16) for i in (0, 2, 4))
        HEADER_TEXT_RGB = WF_WHITE_RGB if _hex_luminance(project_color) <= 0.6 else (0x1A, 0x1A, 0x1A)

        def _wf_rect(slide, x, y, w, h, fill_rgb=None, line_rgb=None, line_pt=None):
            sh = slide.shapes.add_shape(MSO_SHAPE.RECTANGLE, x, y, w, h)
            sh.shadow.inherit = False
            if fill_rgb is not None:
                sh.fill.solid()
                sh.fill.fore_color.rgb = PRGBColor(*fill_rgb)
            else:
                sh.fill.background()
            if line_rgb is not None:
                sh.line.color.rgb = PRGBColor(*line_rgb)
                sh.line.width = Pt(line_pt or 0.75)
            else:
                sh.line.fill.background()
            return sh

        def _wf_oval(slide, x, y, w, h, fill_rgb):
            sh = slide.shapes.add_shape(MSO_SHAPE.OVAL, x, y, w, h)
            sh.shadow.inherit = False
            sh.fill.solid()
            sh.fill.fore_color.rgb = PRGBColor(*fill_rgb)
            sh.line.fill.background()
            return sh

        def _wf_person_icon(slide, cx: int, cy: int, r: int) -> None:
            _wf_oval(slide, cx - r, cy - r, 2 * r, 2 * r, BRAND_RGB)
            head_r = int(r * 0.30)
            _wf_oval(slide, cx - head_r, cy - int(r * 0.30) - head_r, 2 * head_r, 2 * head_r, WF_WHITE_RGB)
            body_w, body_h = int(r * 1.08), int(r * 0.62)
            _wf_oval(slide, cx - body_w // 2, cy + int(r * 0.02) - body_h, body_w, body_h, WF_WHITE_RGB)

        def _wf_gear_icon(slide, cx: int, cy: int, r: int) -> None:
            _wf_oval(slide, cx - r, cy - r, 2 * r, 2 * r, BRAND_RGB)
            body_r = int(r * 0.52)
            _wf_oval(slide, cx - body_r, cy - body_r, 2 * body_r, 2 * body_r, WF_WHITE_RGB)
            tooth_w, tooth_h, n_teeth = int(r * 0.26), int(r * 0.32), 8
            for i in range(n_teeth):
                angle = (360.0 / n_teeth) * i
                rad = math.radians(angle)
                tx = cx + int(math.cos(rad) * r * 0.58)
                ty = cy + int(math.sin(rad) * r * 0.58)
                tooth = slide.shapes.add_shape(MSO_SHAPE.RECTANGLE, tx - tooth_w // 2, ty - tooth_h // 2, tooth_w, tooth_h)
                tooth.rotation = angle
                tooth.shadow.inherit = False
                tooth.fill.solid()
                tooth.fill.fore_color.rgb = PRGBColor(*WF_WHITE_RGB)
                tooth.line.fill.background()
            hole_r = int(r * 0.20)
            _wf_oval(slide, cx - hole_r, cy - hole_r, 2 * hole_r, 2 * hole_r, BRAND_RGB)

        WF_ACCESO_COLORS = {
            "con acceso": (0x16, 0xA3, 0x4A), "permitido": (0x16, 0xA3, 0x4A), "acceso permitido": (0x16, 0xA3, 0x4A),
            "liberado": (0x16, 0xA3, 0x4A), "libre": (0x16, 0xA3, 0x4A), "si": (0x16, 0xA3, 0x4A), "sí": (0x16, 0xA3, 0x4A),
            "sin acceso": (0xDC, 0x26, 0x26), "bloqueado": (0xDC, 0x26, 0x26), "denegado": (0xDC, 0x26, 0x26), "no": (0xDC, 0x26, 0x26),
            "parcial": (0xD9, 0x77, 0x06), "restringido": (0xD9, 0x77, 0x06), "acceso parcial al predio": (0xD9, 0x77, 0x06),
        }

        def _wf_structure_icon(slide, cx: int, cy: int, r: int) -> None:
            _wf_oval(slide, cx - r, cy - r, 2 * r, 2 * r, BRAND_RGB)
            node_r = int(r * 0.17)
            top = (cx, cy - int(r * 0.38))
            bl = (cx - int(r * 0.40), cy + int(r * 0.32))
            br = (cx + int(r * 0.40), cy + int(r * 0.32))
            for (nx, ny) in (top, bl, br):
                _wf_oval(slide, nx - node_r, ny - node_r, 2 * node_r, 2 * node_r, WF_WHITE_RGB)

        def _wf_weather_icon(slide, cx: int, cy: int, r: int) -> None:
            _wf_oval(slide, cx - r, cy - r, 2 * r, 2 * r, BRAND_RGB)
            sun_r = int(r * 0.34)
            _wf_oval(slide, cx - int(r * 0.10) - sun_r, cy - int(r * 0.20) - sun_r, 2 * sun_r, 2 * sun_r, WF_WHITE_RGB)
            cloud_w, cloud_h = int(r * 1.1), int(r * 0.5)
            _wf_oval(slide, cx - cloud_w // 2, cy + int(r * 0.05), cloud_w, cloud_h, WF_WHITE_RGB)

        def _wf_truncate(text: str, max_chars: int) -> str:
            text = (text or "").strip()
            if len(text) <= max_chars:
                return text
            return text[:max(1, max_chars - 1)].rstrip() + "…"

        def _wf_bullets(slide, x: int, y: int, w: int, h: int, items: list, max_items: int, font_size: float = 11,
                        resto_out: Optional[list] = None) -> None:
            """Textbox con viñetas (una por párrafo). Trunca por CANTIDAD de
            ítems (`max_items`) y por longitud de cada ítem. Con `resto_out`
            (lista) no imprime "+N más…": estima el alto de cada viñeta
            (líneas × interlineado), muestra las que caben en `h` y deposita
            el resto en `resto_out` para que el llamador las continúe en
            otra slide de la misma estación."""
            tb = slide.shapes.add_textbox(x, y, w, h)
            tf = tb.text_frame
            tf.word_wrap = True
            shown = (items or [])[:max_items]
            max_chars = max(40, int((w / 360000.0) * 5.4 * 2))
            if resto_out is not None and items:
                cpl = max(20, int((w / 360000.0) / (font_size * 0.0176)))   # caracteres por línea
                line_h = font_size * 1.25 * 12700                            # EMU por línea
                max_lines = max(1, int(h / line_h) - 1)
                shown, usadas = [], 0
                for t in items:
                    n_lin = max(1, -(-(len((t or "").strip()) + 3) // cpl))
                    if usadas + n_lin > max_lines and shown:
                        break
                    shown.append(t)
                    usadas += n_lin
                resto_out.extend(items[len(shown):])
                max_chars = cpl * max_lines
            if not shown:
                p = tf.paragraphs[0]
                run = p.add_run()
                run.text = "Sin información registrada"
                run.font.size = Pt(font_size)
                run.font.italic = True
                run.font.color.rgb = PRGBColor(*WF_MUTED_RGB)
                return
            for i, text in enumerate(shown):
                p = tf.paragraphs[0] if i == 0 else tf.add_paragraph()
                run = p.add_run()
                run.text = f"•  {_wf_truncate(text, max_chars)}"
                run.font.size = Pt(font_size)
                run.font.color.rgb = PRGBColor(*WF_TEXT_RGB)
            overflow = len(items or []) - len(shown)
            if overflow > 0 and resto_out is None:
                p = tf.add_paragraph()
                run = p.add_run()
                run.text = f"+ {overflow} más…"
                run.font.size = Pt(max(7, font_size - 1.5))
                run.font.italic = True
                run.font.color.rgb = PRGBColor(*WF_MUTED_RGB)

        def draw_subtramo_summary_slide(subtramo_node: dict, personal_rows: list, maquinaria_rows: list,
                                         actividades: list, situacion_social: Optional[str],
                                         acceso_predio: Optional[str], weather: Optional[dict],
                                         mostrar_acceso_predio: bool = True,
                                         acceso_node_label: Optional[str] = None,
                                         turno_label: Optional[str] = None,
                                         continuacion: bool = False) -> list:
            """(CONTINUACIÓN: devuelve las actividades que no cupieron; el
            llamador emite otra slide de la misma estación con
            `continuacion=True` — solo título + lista de actividades.)

            Slide de resumen por Subtramo — MISMO layout de 2 columnas que
            `draw_subtramo_summary_page` (motor PDF), con primitivas
            python-pptx: IZQUIERDA (título con ícono de estructura, Acceso al
            Predio con badge semántico, Situación Social, Actividades) y
            DERECHA (Estado del Tiempo 2x2 + mini-tablas Fuerza de
            Trabajo/Maquinaria y Equipo con TOTAL). Slide FIJA (1 sola, sin
            paginación adicional): el contenido que no cabe se trunca."""
            slide = _clone_membrete()

            MARGIN_X = Cm(1.5)
            GUTTER = Cm(0.9)
            content_w = SW - 2 * MARGIN_X
            col_w = int((content_w - GUTTER) / 2)
            left_x = MARGIN_X
            right_x = MARGIN_X + col_w + GUTTER
            divider_x = MARGIN_X + col_w + int(GUTTER / 2)
            top_y = TOP_MARGIN
            bottom_y = SH - BOTTOM_MARGIN

            # Etiqueta de turno hasta arriba (ej. "TURNO NOCTURNO"): franja de
            # color de marca a todo lo ancho; el resto de la slide baja.
            if turno_label:
                _tl_h = int(Cm(0.8))
                _wf_rect(slide, MARGIN_X, top_y, content_w, _tl_h, fill_rgb=BRAND_RGB)
                add_text(slide, MARGIN_X, top_y, content_w, _tl_h, turno_label.upper(),
                         size=13, bold=True, color=WF_WHITE_RGB, align=PP_ALIGN.CENTER)
                top_y += _tl_h + int(Cm(0.3))

            BADGE_R = int(Cm(0.5))
            # Título grande de la página: el nombre del nodo que REALMENTE
            # tiene Acceso al Predio configurado en el hub (`acceso_node_label`
            # — puede ser un Poste específico, no siempre el Subtramo), no el
            # nombre del Subtramo a secas. Si el Subtramo no tiene Acceso al
            # Predio habilitado en absoluto (`acceso_node_label` viene None),
            # cae de vuelta al nombre del propio Subtramo — la página sigue
            # necesitando un título aunque no haya nada de Acceso al Predio
            # que mostrar.
            subtramo_name = acceso_node_label or (subtramo_node or {}).get("name") or "Subtramo"

            def _section_title(x: int, y: int, w: int, text: str) -> int:
                add_text(slide, x, y, w, Cm(0.55), text.upper(), size=12, bold=True, color=READABLE_BRAND_RGB)
                return y + Cm(0.6)

            # ---- COLUMNA IZQUIERDA ------------------------------------------
            # Título en 2 líneas (formato de referencia del cliente):
            # "ESTACIÓN N." (chico) + nombre de la estación (grande) — ver
            # la misma nota en draw_subtramo_summary_page (motor PDF).
            y = top_y
            _ordinal = _subtramo_ordinal.get((subtramo_node or {}).get("id"))
            cx, cy = left_x + BADGE_R, y + BADGE_R
            _wf_structure_icon(slide, cx, cy, BADGE_R)
            _chico, _grande = _estacion_titulos(_ordinal, subtramo_name)
            if _chico:
                add_text(slide, left_x + 2 * BADGE_R + Cm(0.3), y + int(BADGE_R * 0.1),
                         col_w - 2 * BADGE_R - Cm(0.3), Cm(0.5),
                         _chico, size=12, bold=True, color=READABLE_BRAND_RGB)
            add_text(slide, left_x + 2 * BADGE_R + Cm(0.3), y + int(BADGE_R * 0.35) + Cm(0.42),
                     col_w - 2 * BADGE_R - Cm(0.3), Cm(0.8),
                     _grande.upper(), size=17, bold=True, color=READABLE_BRAND_RGB)
            y += Cm(1.8)
            _wf_rect(slide, left_x, y, col_w, Pt(1.6), fill_rgb=BRAND_RGB)
            y += Cm(0.35)

            # --- Acceso al Predio -----------------------------------------------
            # Se omite por completo si el coordinador no habilitó Acceso al
            # Predio para esta ubicación en el hub (ver `mostrar_acceso_predio`
            # / `_resolve_acceso_predio_node`) — antes se imprimía "Sin
            # especificar" en TODOS los subtramos sin importar el hub.
            if mostrar_acceso_predio and not continuacion:
                # Ya no hace falta repetir el nombre del nodo aquí como
                # subtítulo: es el título GRANDE de toda la slide (ver
                # `subtramo_name` arriba, resuelto vía `acceso_node_label`).
                y = _section_title(left_x, y, col_w, "Acceso al Predio")
                box_h = Cm(1.0)
                acceso_rgb = WF_ACCESO_COLORS.get((acceso_predio or "").strip().lower(), (0x94, 0xA3, 0xB8))
                _wf_rect(slide, left_x, y, col_w, box_h, fill_rgb=acceso_rgb)
                add_text(slide, left_x, y, col_w, box_h, (acceso_predio or "Sin especificar").strip().upper(),
                         size=13, bold=True, color=WF_WHITE_RGB, align=PP_ALIGN.CENTER)
                # FIX: se quita la nota de vigencia para calzar exacto con
                # el formato de referencia del cliente — ver la misma nota
                # en draw_subtramo_summary_page (motor PDF).
                y += box_h + Cm(0.3)

                # --- Situación Social -------------------------------------------
                y = _section_title(left_x, y, col_w, "Situación Social-Liberación Física del Predio")
                situ_items = [ln.strip() for ln in (situacion_social or "").splitlines() if ln.strip()]
                situ_h = Cm(3.2)
                _wf_bullets(slide, left_x, y, col_w, situ_h, situ_items, max_items=4, font_size=10.5)
                y += situ_h + Cm(0.2)

            # --- Actividades ------------------------------------------------------
            y = _section_title(left_x, y, col_w, "Se supervisa las siguientes actividades")
            act_h = max(Cm(1.5), bottom_y - y)
            _acts_all = list(actividades or [])
            _acts_resto: list = []
            _wf_bullets(slide, left_x, y, col_w, act_h, _acts_all, max_items=max(1, len(_acts_all)),
                        font_size=10.5, resto_out=_acts_resto)
            if continuacion:
                return _acts_resto

            # ---- LÍNEA DIVISORIA VERTICAL (delgada, color de marca) ---------
            _wf_rect(slide, divider_x, top_y, Pt(1.3), bottom_y - top_y, fill_rgb=BRAND_RGB)

            # ---- COLUMNA DERECHA ---------------------------------------------
            y = top_y
            cx, cy = right_x + BADGE_R, y + BADGE_R
            _wf_weather_icon(slide, cx, cy, BADGE_R)
            add_text(slide, right_x + 2 * BADGE_R + Cm(0.3), y + int(BADGE_R * 0.35),
                     col_w - 2 * BADGE_R - Cm(0.3), Cm(0.8),
                     "ESTADO DEL TIEMPO", size=14, bold=True, color=READABLE_BRAND_RGB)
            y += Cm(1.15)

            w = weather or {}
            temp = w.get("temperature_c")
            wind = w.get("wind_kmh")
            precip = w.get("precipitation_mm")
            aqi = w.get("us_aqi")
            # FIX: formato de referencia del cliente — una sola fila de 4
            # columnas SIN bordes, etiqueta "Label:" en altas y bajas, y
            # unidades/decimales exactos — ver la misma nota en
            # draw_subtramo_summary_page (motor PDF).
            cells = [
                ("Temperatura:", f"{temp:.0f}° C" if temp is not None else "—"),
                ("Viento:", f"{wind:.1f} km/hr." if wind is not None else "—"),
                ("Precipitación:", f"{precip:.1f} mm" if precip is not None else "—"),
                ("Calidad del aire:", f"{aqi:.1f} ICA" if aqi is not None else "—"),
            ]
            cell_w, cell_h = col_w // 4, Cm(1.1)
            grid_top = y
            for i, (label, val) in enumerate(cells):
                cx2 = right_x + i * cell_w
                add_text(slide, cx2, grid_top, cell_w - Cm(0.1), Cm(0.45),
                         label, size=8.5, bold=True, color=WF_TEXT_RGB)
                add_text(slide, cx2, grid_top + Cm(0.42), cell_w - Cm(0.1), Cm(0.6),
                         val, size=13, bold=True, color=WF_TEXT_RGB)
            y = grid_top + cell_h + Cm(0.3)

            # --- Mini-tablas FUERZA DE TRABAJO | MAQUINARIA Y EQUIPO ------------
            tbl_gutter = Cm(0.5)
            tbl_w = (col_w - tbl_gutter) // 2
            tbl_avail_h = bottom_y - y

            def _draw_mini_table(x: int, y_top: int, w: int, title: str, rows: list, icon_kind: str,
                                  col1_header: str = "RECURSO") -> None:
                mini_r = int(Cm(0.4))
                HEADER_H = Cm(0.75)
                TOTAL_H = Cm(0.7)
                MIN_ROW_H, MAX_ROW_H = Cm(0.55), Cm(0.8)
                cx3, cy3 = x + mini_r, y_top + mini_r
                if icon_kind == "person":
                    _wf_person_icon(slide, cx3, cy3, mini_r)
                else:
                    _wf_gear_icon(slide, cx3, cy3, mini_r)
                add_text(slide, x + 2 * mini_r + Cm(0.2), y_top + int(mini_r * 0.35),
                         w - 2 * mini_r - Cm(0.2), Cm(0.6), title.upper(), size=10.5, bold=True, color=READABLE_BRAND_RGB)
                yy = y_top + 2 * mini_r + Cm(0.15)
                _wf_rect(slide, x, yy, w, HEADER_H, fill_rgb=BRAND_RGB)
                pad = Cm(0.2)
                name_w_cell = int(w * 0.68) - pad
                qty_x = x + int(w * 0.68)
                qty_w_cell = w - int(w * 0.68) - pad
                add_text(slide, x + pad, yy, name_w_cell, HEADER_H, col1_header,
                         size=9, bold=True, color=HEADER_TEXT_RGB, tight=True)
                add_text(slide, qty_x, yy, qty_w_cell, HEADER_H, "CANTIDAD",
                         size=9, bold=True, color=HEADER_TEXT_RGB, align=PP_ALIGN.RIGHT, tight=True)
                yy += HEADER_H
                total_qty = sum(r["qty"] for r in rows)
                # La altura de fila se reparte en el espacio libre (entre el mínimo
                # y el máximo) para que nada se amontone; si aun así no caben
                # todas las filas, se corta con "+N más".
                espacio = tbl_avail_h - 2 * mini_r - Cm(0.15) - HEADER_H - TOTAL_H
                n_prev = max(1, len(rows))
                ROW_H = int(max(MIN_ROW_H, min(MAX_ROW_H, espacio / n_prev)))
                max_rows = max(1, int(espacio / ROW_H))
                shown = rows[:max_rows - 1] if len(rows) > max_rows else rows
                overflow = len(rows) - len(shown)
                for idx, r in enumerate(shown):
                    if idx % 2 == 1:
                        _wf_rect(slide, x, yy, w, ROW_H, fill_rgb=WF_ZEBRA_TINT_RGB)
                    main, _ = _format_workforce_desc(r["desc"])
                    main = main or "—"
                    # Nombres largos: se reduce la letra para que quepan en 1-2 líneas.
                    chars_por_linea = name_w_cell / Cm(0.17)
                    fs = 9 if len(main) <= chars_por_linea else 8 if len(main) <= chars_por_linea * 1.15 else 7
                    add_text(slide, x + pad, yy, name_w_cell, ROW_H, main, size=fs, color=WF_TEXT_RGB, tight=True)
                    add_text(slide, qty_x, yy, qty_w_cell, ROW_H, str(r["qty"]), size=9, bold=True,
                             color=READABLE_BRAND_RGB, align=PP_ALIGN.RIGHT, tight=True)
                    _wf_rect(slide, x, yy + ROW_H - Pt(0.75), w, Pt(0.75), fill_rgb=WF_BORDER_RGB)
                    yy += ROW_H
                if overflow > 0:
                    add_text(slide, x + pad, yy, w - 2 * pad, ROW_H, f"+ {overflow} más…", size=8, italic=True,
                             color=WF_MUTED_RGB, tight=True)
                    yy += ROW_H
                if not rows:
                    add_text(slide, x + pad, yy, w - 2 * pad, ROW_H, "Sin registros", size=9, italic=True,
                             color=WF_MUTED_RGB, tight=True)
                    yy += ROW_H
                _wf_rect(slide, x, yy, w, TOTAL_H, fill_rgb=WF_TOTAL_TINT_RGB)
                _wf_rect(slide, x, yy, w, Pt(1.6), fill_rgb=BRAND_RGB)
                add_text(slide, x + pad, yy, int(w * 0.5), TOTAL_H, "TOTAL", size=10, bold=True,
                         color=READABLE_BRAND_RGB, tight=True)
                add_text(slide, qty_x, yy, qty_w_cell, TOTAL_H, str(total_qty), size=10, bold=True,
                         color=READABLE_BRAND_RGB, align=PP_ALIGN.RIGHT, tight=True)

            _draw_mini_table(right_x, y, tbl_w, "Fuerza de Trabajo", personal_rows, "person", col1_header="PERSONAL")
            _draw_mini_table(right_x + tbl_w + tbl_gutter, y, tbl_w, "Maquinaria y Equipo", maquinaria_rows, "gear",
                              col1_header="MAQUINARIA Y EQUIPO")
            return _acts_resto

        _POSTE_ESTATUS_LABEL_PPTX = {
            "sin_iniciar": "Sin iniciar", "en_proceso": "En proceso", "concluido": "Concluido",
            "cambio_trayectoria": "Cambio de trayectoria",
        }

        def draw_intertramo_summary_slide(intertramo_node: dict, personal_rows: list, maquinaria_rows: list,
                                           actividades: list, situacion_social: Optional[str],
                                           postes: list, mostrar_situacion: bool = True) -> None:
            """Slide de resumen por Subtramo tipo INTERTRAMO — MISMO layout de
            2 columnas que `draw_subtramo_summary_slide` (formato de
            referencia del cliente, ver `draw_intertramo_summary_page` en el
            motor PDF): IZQUIERDA título (sin badge de Acceso al Predio ni
            ordinal — los Intertramos no se numeran) + Situación Social
            plural + tabla ACTIVIDAD EN POSTES (TODOS los postes, sin
            truncar salvo que de plano no quepan) + "Se supervisa las
            siguientes actividades". DERECHA: mini-tablas Fuerza de
            Trabajo/Maquinaria y Equipo a TODO lo alto (sin Estado del
            Tiempo). Separadas por línea vertical a todo lo alto."""
            slide = _clone_membrete()

            MARGIN_X = Cm(1.5)
            GUTTER = Cm(0.9)
            content_w = SW - 2 * MARGIN_X
            col_w = int((content_w - GUTTER) / 2)
            left_x = MARGIN_X
            right_x = MARGIN_X + col_w + GUTTER
            divider_x = MARGIN_X + col_w + int(GUTTER / 2)
            top_y = TOP_MARGIN
            bottom_y = SH - BOTTOM_MARGIN

            BADGE_R = int(Cm(0.5))
            intertramo_name = (intertramo_node or {}).get("name") or "Intertramo"

            def _section_title(x: int, y: int, w: int, text: str) -> int:
                add_text(slide, x, y, w, Cm(0.55), text.upper(), size=12, bold=True, color=READABLE_BRAND_RGB)
                return y + Cm(0.6)

            # ---- COLUMNA IZQUIERDA: título (sin ordinal — los Intertramos no
            # se numeran, ver `draw_intertramo_summary_page`) ----------------
            y = top_y
            cx, cy = left_x + BADGE_R, y + BADGE_R
            _wf_structure_icon(slide, cx, cy, BADGE_R)
            add_text(slide, left_x + 2 * BADGE_R + Cm(0.3), y + int(BADGE_R * 0.1),
                     col_w - 2 * BADGE_R - Cm(0.3), Cm(0.5),
                     "INTERTRAMO", size=12, bold=True, color=READABLE_BRAND_RGB)
            add_text(slide, left_x + 2 * BADGE_R + Cm(0.3), y + int(BADGE_R * 0.35) + Cm(0.42),
                     col_w - 2 * BADGE_R - Cm(0.3), Cm(0.8),
                     intertramo_name.upper(), size=17, bold=True, color=READABLE_BRAND_RGB)
            y += Cm(1.8)
            _wf_rect(slide, left_x, y, col_w, Pt(1.6), fill_rgb=BRAND_RGB)
            y += Cm(0.35)

            # --- Situación Social (plural) ---------------------------------------
            if mostrar_situacion:
                y = _section_title(left_x, y, col_w, "Situación Social-Liberación Física de Predios")
                situ_items = [ln.strip() for ln in (situacion_social or "").splitlines() if ln.strip()]
                situ_h = Cm(1.8)
                _wf_bullets(slide, left_x, y, col_w, situ_h, situ_items, max_items=3, font_size=10)
                y += situ_h + Cm(0.2)

            # --- Actividad en Postes (tabla dentro de la columna izquierda,
            # TODOS los hijos directos del Intertramo) ----------------------
            y = _section_title(left_x, y, col_w, "Actividad en Postes")

            POSTE_COLS = ["POSTE", "UBICACIÓN", "PILAS", "CABEZAL", "FUSTE", "POSTE"]
            POSTE_FRACS = [0.14, 0.17, 0.17, 0.17, 0.17, 0.18]  # 1ª columna: que "Poste S4" no se parta
            poste_col_w = [int(col_w * f) for f in POSTE_FRACS]
            # Reserva mínima para "Se supervisa las siguientes actividades",
            # que sigue debajo de esta tabla EN LA MISMA COLUMNA IZQUIERDA.
            MIN_BOTTOM_RESERVE = Cm(1.9) if len(actividades or []) <= 1 else Cm(2.6)
            postes_avail_h = max(Cm(2.0), (bottom_y - y) - MIN_BOTTOM_RESERVE)
            POSTE_PAD = int(Cm(0.07))

            def _poste_row_vals(p: dict) -> list:
                return [
                    p.get("name") or "—", p.get("ubicacion") or "—",
                    _POSTE_ESTATUS_LABEL_PPTX.get(p.get("estatus_pilas"), "Sin iniciar"),
                    _POSTE_ESTATUS_LABEL_PPTX.get(p.get("estatus_cabezal"), "Sin iniciar"),
                    _POSTE_ESTATUS_LABEL_PPTX.get(p.get("estatus_fuste"), "Sin iniciar"),
                    _POSTE_ESTATUS_LABEL_PPTX.get(p.get("estatus_poste"), "Sin iniciar"),
                ]

            def _poste_layout(size: float, filas: list, con_extra: bool) -> tuple:
                """(alto del encabezado, [alto de cada fila], alto total) con la
                letra `size`: cada fila crece con su texto más largo (un
                "Cambio de trayectoria" ocupa 2 líneas) y no se encima."""
                lead = int(size * 1.2 * 12700)
                header_h = lead + 2 * POSTE_PAD
                hs = [max(_pptx_texto_lineas(t, w, size) for t, w in zip(f, poste_col_w)) * lead + 2 * POSTE_PAD
                      for f in filas]
                extra = (lead + 2 * POSTE_PAD) if (con_extra or not filas) else 0
                return header_h, hs, header_h + sum(hs) + extra

            filas_postes = [_poste_row_vals(p) for p in postes]
            filas_cortas = [[_ESTATUS_CORTO.get(t, t) for t in f] for f in filas_postes]
            POSTE_FONT_SIZE, rows_to_draw, postes_overflow = 7.5, filas_cortas, 0
            # Estatus completos con letra grande; si no caben, abreviados
            # ("Cambio tray.", una línea); recién al final se recorta con "+N más".
            for _size, _cortas in ((11, False), (10, False), (9, False), (11, True), (10, True), (9, True),
                                   (8, True), (7.5, True)):
                _filas = filas_cortas if _cortas else filas_postes
                if _poste_layout(_size, _filas, False)[2] <= postes_avail_h:
                    POSTE_FONT_SIZE, rows_to_draw = _size, _filas
                    break
            else:
                _n = len(filas_cortas)
                while _n > 1 and _poste_layout(7.5, filas_cortas[:_n], True)[2] > postes_avail_h:
                    _n -= 1
                rows_to_draw = filas_cortas[:max(_n, 1)]
                postes_overflow = len(filas_cortas) - len(rows_to_draw)
            POSTE_HEADER_H, _row_hs, _ = _poste_layout(POSTE_FONT_SIZE, rows_to_draw, postes_overflow > 0)
            POSTE_ROW_H = int(POSTE_FONT_SIZE * 1.2 * 12700) + 2 * POSTE_PAD  # fila de una línea

            table_top = y
            xx = left_x
            for i, h in enumerate(POSTE_COLS):
                _wf_rect(slide, xx, table_top, poste_col_w[i], POSTE_HEADER_H, fill_rgb=BRAND_RGB,
                         line_rgb=WF_BORDER_RGB, line_pt=0.5)
                add_text(slide, xx, table_top, poste_col_w[i], POSTE_HEADER_H, h,
                         size=min(POSTE_FONT_SIZE, 9), bold=True, color=HEADER_TEXT_RGB, align=PP_ALIGN.CENTER)
                xx += poste_col_w[i]
            yy = table_top + POSTE_HEADER_H

            if not rows_to_draw:
                # Un solo renglón a todo lo ancho (partido en 6 celdas el
                # mensaje se encajonaba en la 1ª columna y pisaba el título de abajo).
                _wf_rect(slide, left_x, yy, col_w, POSTE_ROW_H, line_rgb=WF_BORDER_RGB, line_pt=0.5)
                add_text(slide, left_x, yy, col_w, POSTE_ROW_H, "Sin postes registrados", size=POSTE_FONT_SIZE,
                         italic=True, color=WF_MUTED_RGB, align=PP_ALIGN.CENTER)
                yy += POSTE_ROW_H
            for ridx, vals in enumerate(rows_to_draw):
                row_h = _row_hs[ridx]
                if ridx % 2 == 1:
                    _wf_rect(slide, left_x, yy, col_w, row_h, fill_rgb=WF_ZEBRA_TINT_RGB)
                xx = left_x
                for i, val in enumerate(vals):
                    _wf_rect(slide, xx, yy, poste_col_w[i], row_h, line_rgb=WF_BORDER_RGB, line_pt=0.5)
                    add_text(slide, xx, yy, poste_col_w[i], row_h, val, size=POSTE_FONT_SIZE, color=WF_TEXT_RGB,
                             align=PP_ALIGN.CENTER)
                    xx += poste_col_w[i]
                yy += row_h
            if postes_overflow > 0:
                add_text(slide, left_x, yy, col_w, POSTE_ROW_H, f"+ {postes_overflow} más…",
                         size=POSTE_FONT_SIZE, italic=True, color=WF_MUTED_RGB)
                yy += POSTE_ROW_H
            table_bottom_y = yy + Cm(0.2)

            # --- Se supervisa las siguientes actividades (sigue debajo de la
            # tabla, en la misma columna izquierda) -----------------------
            y2 = _section_title(left_x, table_bottom_y, col_w, "Se supervisa las siguientes actividades")
            act_h = max(Cm(1.0), bottom_y - y2)
            _wf_bullets(slide, left_x, y2, col_w, act_h, actividades or [], max_items=6, font_size=10.5)

            # ---- LÍNEA DIVISORIA VERTICAL — a TODO lo alto de la slide, igual
            # que en `draw_subtramo_summary_slide` (no solo bajo la tabla) ----
            _wf_rect(slide, divider_x, top_y, Pt(1.3), bottom_y - top_y, fill_rgb=BRAND_RGB)

            # ---- COLUMNA DERECHA: Fuerza de Trabajo / Maquinaria y Equipo a
            # TODO lo alto (sin Estado del Tiempo) --------------------------
            y3 = top_y
            tbl_gutter = Cm(0.5)
            tbl_w = (col_w - tbl_gutter) // 2
            tbl_avail_h = bottom_y - y3

            def _draw_mini_table2(x: int, y_top: int, w: int, title: str, rows: list, icon_kind: str,
                                  col1_header: str = "RECURSO") -> None:
                mini_r = int(Cm(0.4))
                HEADER_H = Cm(0.75)
                TOTAL_H = Cm(0.7)
                MIN_ROW_H, MAX_ROW_H = Cm(0.55), Cm(0.8)
                cx3, cy3 = x + mini_r, y_top + mini_r
                if icon_kind == "person":
                    _wf_person_icon(slide, cx3, cy3, mini_r)
                else:
                    _wf_gear_icon(slide, cx3, cy3, mini_r)
                add_text(slide, x + 2 * mini_r + Cm(0.2), y_top + int(mini_r * 0.35),
                         w - 2 * mini_r - Cm(0.2), Cm(0.6), title.upper(), size=10.5, bold=True, color=READABLE_BRAND_RGB)
                yy = y_top + 2 * mini_r + Cm(0.15)
                _wf_rect(slide, x, yy, w, HEADER_H, fill_rgb=BRAND_RGB)
                pad = Cm(0.2)
                name_w_cell = int(w * 0.68) - pad
                qty_x = x + int(w * 0.68)
                qty_w_cell = w - int(w * 0.68) - pad
                add_text(slide, x + pad, yy, name_w_cell, HEADER_H, col1_header,
                         size=9, bold=True, color=HEADER_TEXT_RGB, tight=True)
                add_text(slide, qty_x, yy, qty_w_cell, HEADER_H, "CANTIDAD",
                         size=9, bold=True, color=HEADER_TEXT_RGB, align=PP_ALIGN.RIGHT, tight=True)
                yy += HEADER_H
                total_qty = sum(r["qty"] for r in rows)
                # La altura de fila se reparte en el espacio libre (entre el mínimo
                # y el máximo) para que nada se amontone; si aun así no caben
                # todas las filas, se corta con "+N más".
                espacio = tbl_avail_h - 2 * mini_r - Cm(0.15) - HEADER_H - TOTAL_H
                n_prev = max(1, len(rows))
                ROW_H = int(max(MIN_ROW_H, min(MAX_ROW_H, espacio / n_prev)))
                max_rows = max(1, int(espacio / ROW_H))
                shown = rows[:max_rows - 1] if len(rows) > max_rows else rows
                overflow = len(rows) - len(shown)
                for idx, r in enumerate(shown):
                    if idx % 2 == 1:
                        _wf_rect(slide, x, yy, w, ROW_H, fill_rgb=WF_ZEBRA_TINT_RGB)
                    main, _ = _format_workforce_desc(r["desc"])
                    main = main or "—"
                    # Nombres largos: se reduce la letra para que quepan en 1-2 líneas.
                    chars_por_linea = name_w_cell / Cm(0.17)
                    fs = 9 if len(main) <= chars_por_linea else 8 if len(main) <= chars_por_linea * 1.15 else 7
                    add_text(slide, x + pad, yy, name_w_cell, ROW_H, main, size=fs, color=WF_TEXT_RGB, tight=True)
                    add_text(slide, qty_x, yy, qty_w_cell, ROW_H, str(r["qty"]), size=9, bold=True,
                             color=READABLE_BRAND_RGB, align=PP_ALIGN.RIGHT, tight=True)
                    _wf_rect(slide, x, yy + ROW_H - Pt(0.75), w, Pt(0.75), fill_rgb=WF_BORDER_RGB)
                    yy += ROW_H
                if overflow > 0:
                    add_text(slide, x + pad, yy, w - 2 * pad, ROW_H, f"+ {overflow} más…", size=8, italic=True,
                             color=WF_MUTED_RGB, tight=True)
                    yy += ROW_H
                if not rows:
                    add_text(slide, x + pad, yy, w - 2 * pad, ROW_H, "Sin registros", size=9, italic=True,
                             color=WF_MUTED_RGB, tight=True)
                    yy += ROW_H
                _wf_rect(slide, x, yy, w, TOTAL_H, fill_rgb=WF_TOTAL_TINT_RGB)
                _wf_rect(slide, x, yy, w, Pt(1.6), fill_rgb=BRAND_RGB)
                add_text(slide, x + pad, yy, int(w * 0.5), TOTAL_H, "TOTAL", size=10, bold=True,
                         color=READABLE_BRAND_RGB, tight=True)
                add_text(slide, qty_x, yy, qty_w_cell, TOTAL_H, str(total_qty), size=10, bold=True,
                         color=READABLE_BRAND_RGB, align=PP_ALIGN.RIGHT, tight=True)

            _draw_mini_table2(right_x, y3, tbl_w, "Fuerza de Trabajo", personal_rows, "person", col1_header="PERSONAL")
            _draw_mini_table2(right_x + tbl_w + tbl_gutter, y3, tbl_w, "Maquinaria y Equipo", maquinaria_rows, "gear",
                               col1_header="MAQUINARIA Y EQUIPO")

        _emitted_recuento_general_title = False

        def _emit_recuento_general_slides() -> None:
            """Slide(s) de cierre "RECUENTO GENERAL": una por Tramo, y tantas
            adicionales como haga falta si las filas no caben en una sola
            (NUNCA se trunca con "+N más" aquí — se pagina). Mismas
            mini-tablas gemelas PERSONAL / MAQUINARIA Y EQUIPO que
            `draw_subtramo_summary_slide`, pero más grandes y centradas en
            el ancho completo de la slide."""
            nonlocal _emitted_recuento_general_title
            if not recuento_general_rows:
                return
            _indice_mark("recuento", "Recuento general")

            MARGIN_X = Cm(1.5)
            content_w = SW - 2 * MARGIN_X
            tbl_gutter = Cm(0.6)
            pair_w = int(content_w * 0.85)
            tbl_w = (pair_w - tbl_gutter) // 2
            pair_x = MARGIN_X + (content_w - pair_w) // 2

            HEADER_H = Cm(1.05)
            ROW_H = Cm(0.85)
            TOTAL_H = Cm(1.0)
            ROW_FONT = 14
            HEADER_FONT = 13

            def _draw_big_table(x: int, y_top: int, title: str, items: list, draw_total: bool, total_qty,
                                 tiene_poste: bool) -> int:
                # Con columna POSTE (nivel de agregación por encima de hoja —
                # ver `_recuento_general_by_nodo`) el ancho se reparte en 3
                # franjas (POSTE/desc/CANT.), sin ella en 2 (histórico).
                if tiene_poste:
                    # POSTE angosta, descripción ancha: "MAQUINARIA Y EQUIPO"
                    # (13 pt, negritas) no cabe en menos y se partía en dos líneas.
                    poste_x0, name_x0, qty_x0 = 0.0, 0.26, 0.78
                else:
                    poste_x0, name_x0, qty_x0 = None, 0.0, 0.62
                _wf_rect(slide, x, y_top, tbl_w, HEADER_H, fill_rgb=BRAND_RGB)
                if tiene_poste:
                    add_text(slide, x + Cm(0.2), y_top + Cm(0.15), int(tbl_w * (name_x0 - poste_x0) - Cm(0.2)),
                             HEADER_H - Cm(0.2), "POSTE", size=HEADER_FONT, bold=True, color=HEADER_TEXT_RGB)
                add_text(slide, x + int(tbl_w * name_x0) + Cm(0.2), y_top + Cm(0.15),
                         int(tbl_w * (qty_x0 - name_x0)) - Cm(0.2), HEADER_H - Cm(0.2),
                         title.upper(), size=HEADER_FONT, bold=True, color=HEADER_TEXT_RGB)
                add_text(slide, x + int(tbl_w * qty_x0), y_top + Cm(0.15), int(tbl_w * (1 - qty_x0)),
                         HEADER_H - Cm(0.2), "CANT.", size=HEADER_FONT, bold=True, color=HEADER_TEXT_RGB,
                         align=PP_ALIGN.RIGHT)
                yy = y_top + HEADER_H
                for idx, r in enumerate(items):
                    if idx % 2 == 1:
                        _wf_rect(slide, x, yy, tbl_w, ROW_H, fill_rgb=WF_ZEBRA_TINT_RGB)
                    if tiene_poste:
                        add_text(slide, x + Cm(0.2), yy + Cm(0.12), int(tbl_w * (name_x0 - poste_x0)) - Cm(0.3),
                                 ROW_H - Cm(0.2), str(r.get("poste") or "—"), size=ROW_FONT - 2, color=WF_MUTED_RGB)
                    main, _ = _format_workforce_desc(r["desc"])
                    add_text(slide, x + int(tbl_w * name_x0) + Cm(0.2), yy + Cm(0.12),
                             int(tbl_w * (qty_x0 - name_x0)) - Cm(0.3), ROW_H - Cm(0.2),
                             main or "—", size=ROW_FONT, color=WF_TEXT_RGB)
                    add_text(slide, x + int(tbl_w * qty_x0), yy + Cm(0.12), int(tbl_w * (1 - qty_x0)) - Cm(0.2),
                             ROW_H - Cm(0.2), str(r["qty"]), size=ROW_FONT, bold=True, color=READABLE_BRAND_RGB,
                             align=PP_ALIGN.RIGHT)
                    _wf_rect(slide, x, yy + ROW_H - Pt(0.9), tbl_w, Pt(0.9), fill_rgb=WF_BORDER_RGB)
                    yy += ROW_H
                if not items:
                    add_text(slide, x + Cm(0.2), yy + Cm(0.12), tbl_w - Cm(0.4), ROW_H - Cm(0.2),
                             "Sin registros", size=ROW_FONT, italic=True, color=WF_MUTED_RGB)
                    yy += ROW_H
                if draw_total:
                    _wf_rect(slide, x, yy, tbl_w, TOTAL_H, fill_rgb=WF_TOTAL_TINT_RGB)
                    _wf_rect(slide, x, yy, tbl_w, Pt(2.0), fill_rgb=BRAND_RGB)
                    add_text(slide, x + Cm(0.2), yy + Cm(0.18), int(tbl_w * qty_x0) - Cm(0.2), TOTAL_H - Cm(0.25),
                             "TOTAL", size=ROW_FONT + 1, bold=True, color=READABLE_BRAND_RGB)
                    add_text(slide, x + int(tbl_w * qty_x0), yy + Cm(0.18), int(tbl_w * (1 - qty_x0)) - Cm(0.2),
                             TOTAL_H - Cm(0.25), str(total_qty), size=ROW_FONT + 1, bold=True,
                             color=READABLE_BRAND_RGB, align=PP_ALIGN.RIGHT)
                    yy += TOTAL_H
                return yy

            for entry in recuento_general_rows:
                nodo_name = (entry.get("nodo_name") or "Nodo").strip()
                nodo_path = (entry.get("nodo_path") or nodo_name).strip()
                show_path = bool(nodo_path) and nodo_path.upper() != nodo_name.upper()
                tiene_poste = bool(entry.get("tiene_columna_poste"))

                if entry.get("sin_datos"):
                    # Nodo de agregación sin personal/maquinaria en el período
                    # (`incluir_sin_datos=True`): leyenda, nunca tabla vacía.
                    slide = _clone_membrete()
                    y = TOP_MARGIN
                    if not _emitted_recuento_general_title:
                        add_text(slide, MARGIN_X, y, content_w, Cm(1.1), "RECUENTO GENERAL",
                                  size=30, bold=True, color=READABLE_BRAND_RGB, align=PP_ALIGN.CENTER)
                        y += Cm(1.3)
                        _emitted_recuento_general_title = True
                    add_text(slide, MARGIN_X, y, content_w, Cm(0.9), nodo_name.upper(),
                              size=18, bold=True, color=WF_TEXT_RGB, align=PP_ALIGN.CENTER)
                    y += Cm(1.0)
                    if show_path:
                        add_text(slide, MARGIN_X, y, content_w, Cm(0.55), nodo_path,
                                  size=11, color=WF_MUTED_RGB, align=PP_ALIGN.CENTER)
                        y += Cm(0.55)
                    add_text(slide, MARGIN_X, y + Cm(0.3), content_w, Cm(0.7), "Sin actividad en el periodo",
                              size=13, italic=True, color=WF_MUTED_RGB, align=PP_ALIGN.CENTER)
                    continue

                personal_rows_e = entry.get("personal") or []
                maquinaria_rows_e = entry.get("maquinaria") or []
                personal_total = sum(r["qty"] for r in personal_rows_e)
                maquinaria_total = sum(r["qty"] for r in maquinaria_rows_e)
                n_total = max(len(personal_rows_e), len(maquinaria_rows_e))

                title_reserved = Cm(1.3) if not _emitted_recuento_general_title else Cm(0)
                subtitle_reserved = Cm(1.0) + (Cm(0.8) if show_path else Cm(0))
                avail_h = (SH - BOTTOM_MARGIN) - TOP_MARGIN - title_reserved - subtitle_reserved - HEADER_H - TOTAL_H
                rows_per_slide = max(1, int(avail_h / ROW_H))

                idx = 0
                page_in_nodo = 0
                while idx < n_total or page_in_nodo == 0:
                    page_in_nodo += 1
                    slide = _clone_membrete()
                    y = TOP_MARGIN
                    if not _emitted_recuento_general_title:
                        add_text(slide, MARGIN_X, y, content_w, Cm(1.1), "RECUENTO GENERAL",
                                  size=30, bold=True, color=READABLE_BRAND_RGB, align=PP_ALIGN.CENTER)
                        y += Cm(1.3)
                        _emitted_recuento_general_title = True
                    subtitle = nodo_name.upper()
                    if page_in_nodo > 1:
                        subtitle += f"  (CONTINÚA · {page_in_nodo})"
                    add_text(slide, MARGIN_X, y, content_w, Cm(0.9), subtitle,
                              size=18, bold=True, color=WF_TEXT_RGB, align=PP_ALIGN.CENTER)
                    y += Cm(1.0)
                    if show_path:
                        add_text(slide, MARGIN_X, y, content_w, Cm(0.65), nodo_path,
                                  size=11, color=WF_MUTED_RGB, align=PP_ALIGN.CENTER)
                        y += Cm(0.8)  # aire bajo la ruta: el encabezado de la tabla la tapaba

                    chunk_end = min(idx + rows_per_slide, n_total)
                    is_last_chunk = chunk_end >= n_total
                    _draw_big_table(pair_x, y, "Personal", personal_rows_e[idx:chunk_end], is_last_chunk,
                                     personal_total, tiene_poste)
                    _draw_big_table(pair_x + tbl_w + tbl_gutter, y, "Maquinaria y Equipo",
                                     maquinaria_rows_e[idx:chunk_end], is_last_chunk, maquinaria_total, tiene_poste)

                    idx = chunk_end

        def _emit_resumen_frentes_slides() -> None:
            """Slides "RECURSOS GENERALES DE LA OBRA" (formato de los reportes de
            referencia, últimas diapositivas), con los subtítulos FUERZA DE
            TRABAJO y MAQUINARIA Y EQUIPO sobre cada tabla: a la izquierda FRENTE /
            CANTIDAD (personas) y a la derecha ESTACIÓN / MAQUINARIA Y
            EQUIPO / CANTIDAD, con una fila por Estación e Intertramo en el
            orden del árbol (incluidos los frentes sin actividad: "0
            Personas" / "Sin equipo") y el TOTAL general en la última
            diapositiva. Sale del mismo consolidado por Subtramo que las
            páginas de resumen (`resource_consolidated_by_subtramo`)."""
            frentes_nodes = sorted(
                (n for n in nodes_by_id.values() if n.get("depth") == 1),
                key=lambda n: (n.get("order", 0), n.get("name", "")),
            )
            if not frentes_nodes:
                return
            filas = []
            n_est = 0
            for n in frentes_nodes:
                es_inter = n.get("tipo_nodo") == "intertramo"
                if es_inter:
                    etiqueta = re.sub(r"(?i)^\s*inter\s*-?\s*tramo\s*", "", n.get("name") or "").strip() or (n.get("name") or "—")
                    etiqueta = etiqueta.upper()
                else:
                    n_est += 1
                    etiqueta = str(n_est)
                cons = resource_consolidated_by_subtramo.get(n["id"]) or {}
                personas = sum(r["qty"] for r in (cons.get("personal") or []))
                equipos_rows = cons.get("maquinaria") or []
                equipos_qty = sum(r["qty"] for r in equipos_rows)
                nombres: list = []
                for r in equipos_rows:
                    main, _ = _format_workforce_desc(r["desc"])
                    main = (main or r["desc"] or "").strip()
                    if main and main not in nombres:
                        nombres.append(main)
                texto = ", ".join(nombres) if nombres else "Sin equipo"
                if len(texto) > 120:
                    texto = texto[:117].rstrip(", ") + "…"
                filas.append({
                    "etiqueta": etiqueta, "personas": personas, "equipos": texto, "equipos_qty": equipos_qty,
                })
            if not any(f["personas"] or f["equipos_qty"] for f in filas):
                return  # sin actividad en ningún frente: no se imprime una hoja en blanco
            _indice_mark("resumen_frentes", "Recursos generales de la obra")

            MARGIN_X = Cm(1.5)
            content_w = SW - 2 * MARGIN_X
            gutter = Cm(0.8)
            left_w = int((content_w - gutter) * 0.36)
            right_w = content_w - gutter - left_w
            HEADER_H = Cm(1.0)
            ROW_H = Cm(1.0)
            TOTAL_H = Cm(1.0)
            title_h = Cm(1.6)
            SUB_H = Cm(1.3)  # subtítulo con ícono sobre cada tabla
            avail_h = (SH - BOTTOM_MARGIN) - TOP_MARGIN - title_h - SUB_H - HEADER_H - TOTAL_H
            rows_per_slide = max(1, int(avail_h / ROW_H))
            total_personas = sum(f["personas"] for f in filas)
            total_equipos = sum(f["equipos_qty"] for f in filas)

            def _cell(slide, x, y, w, h, text, *, bold=False, fill=None, color=None, size=11, align=PP_ALIGN.CENTER):
                _wf_rect(slide, x, y, w, h, fill_rgb=fill or WF_WHITE_RGB, line_rgb=WF_BORDER_RGB, line_pt=0.75)
                add_text(slide, x, y, w, h, text, size=size, bold=bold, color=color or WF_TEXT_RGB, align=align)

            paginas = [filas[i:i + rows_per_slide] for i in range(0, len(filas), rows_per_slide)]
            for pi, pagina in enumerate(paginas):
                is_last = pi == len(paginas) - 1
                slide = _clone_membrete()
                y0 = TOP_MARGIN
                add_text(slide, MARGIN_X, y0, content_w, Cm(1.3),
                         "RECURSOS GENERALES DE LA OBRA" + ("" if pi == 0 else " (continúa)"),
                         size=28, bold=True, color=READABLE_BRAND_RGB, align=PP_ALIGN.CENTER)
                y = y0 + title_h
                lx, rx = MARGIN_X, MARGIN_X + left_w + gutter
                icon_r = int(Cm(0.45))
                for ix, titulo_tbl, es_persona in ((lx, "FUERZA DE TRABAJO", True), (rx, "MAQUINARIA Y EQUIPO", False)):
                    if es_persona:
                        _wf_person_icon(slide, ix + icon_r, y + icon_r, icon_r)
                    else:
                        _wf_gear_icon(slide, ix + icon_r, y + icon_r, icon_r)
                    add_text(slide, ix + 2 * icon_r + Cm(0.25), y + Cm(0.05), (left_w if es_persona else right_w) - 2 * icon_r - Cm(0.25),
                             Cm(0.9), titulo_tbl, size=14, bold=True, color=READABLE_BRAND_RGB)
                y += SUB_H
                # La columna CANTIDAD necesita ≥16% del ancho: a 14% "CANTIDAD" se partía en dos líneas.
                e_w, m_w = int(right_w * 0.14), int(right_w * 0.70)
                q_w = right_w - e_w - m_w
                _cell(slide, lx, y, int(left_w * 0.45), HEADER_H, "FRENTE", bold=True, fill=BRAND_RGB, color=HEADER_TEXT_RGB, size=12)
                _cell(slide, lx + int(left_w * 0.45), y, left_w - int(left_w * 0.45), HEADER_H, "CANTIDAD",
                      bold=True, fill=BRAND_RGB, color=HEADER_TEXT_RGB, size=12)
                _cell(slide, rx, y, e_w, HEADER_H, "ESTACIÓN", bold=True, fill=BRAND_RGB, color=HEADER_TEXT_RGB, size=10)
                _cell(slide, rx + e_w, y, m_w, HEADER_H, "MAQUINARIA Y EQUIPO", bold=True, fill=BRAND_RGB,
                      color=HEADER_TEXT_RGB, size=12)
                _cell(slide, rx + e_w + m_w, y, q_w, HEADER_H, "CANTIDAD", bold=True, fill=BRAND_RGB,
                      color=HEADER_TEXT_RGB, size=11)
                y += HEADER_H
                for f in pagina:
                    lw1 = int(left_w * 0.45)
                    _cell(slide, lx, y, lw1, ROW_H, f["etiqueta"], size=11)
                    _cell(slide, lx + lw1, y, left_w - lw1, ROW_H,
                          f"{f['personas']} Persona" + ("" if f["personas"] == 1 else "s"), size=11)
                    _cell(slide, rx, y, e_w, ROW_H, f["etiqueta"], size=11)
                    _cell(slide, rx + e_w, y, m_w, ROW_H, f["equipos"], size=9, align=PP_ALIGN.LEFT)
                    _cell(slide, rx + e_w + m_w, y, q_w, ROW_H, str(f["equipos_qty"]), size=11)
                    y += ROW_H
                if is_last:
                    lw1 = int(left_w * 0.45)
                    _cell(slide, lx, y, lw1, TOTAL_H, "TOTAL", bold=True, fill=WF_TOTAL_TINT_RGB, size=12)
                    _cell(slide, lx + lw1, y, left_w - lw1, TOTAL_H, str(total_personas), bold=True,
                          fill=WF_TOTAL_TINT_RGB, size=12)
                    _cell(slide, rx, y, e_w + m_w, TOTAL_H, "TOTAL", bold=True, fill=WF_TOTAL_TINT_RGB, size=12)
                    _cell(slide, rx + e_w + m_w, y, q_w, TOTAL_H, str(total_equipos), bold=True,
                          fill=WF_TOTAL_TINT_RGB, size=12)

        def _emit_modulos_closing_slides(datos: Optional[dict] = None) -> None:
            """Slides de cierre GENÉRICAS del sistema Multi-Proyecto Modular:
            recorre `modulos_data` (ver `_gather_modulos_export_data`) y
            arma cada módulo activo a partir de sus bloques declarativos
            (summary/table/list) — esta función NO conoce el nombre de
            ningún módulo ni su forma de datos particular, así que un
            módulo nuevo (actual o futuro) aparece impreso automáticamente
            en cuanto `_gather_modulos_export_data` lo agrega a `out` con
            ese esquema, sin tocar ni una línea de aquí (mismo criterio que
            el motor PDF)."""
            MARGIN_X = Cm(1.5)
            content_w = SW - 2 * MARGIN_X
            top_y = Cm(1.6)
            bottom_y = SH - Cm(1.2)
            HEADING_RGB = {"good": (0x16, 0xA3, 0x4A), "bad": (0xDC, 0x26, 0x26)}

            def _new_slide(titulo: Optional[str]):
                slide = _clone_membrete()
                if not titulo:  # sin encabezado de sección (Vuelo LiDAR)
                    return slide, top_y
                add_text(slide, MARGIN_X, top_y, content_w, Cm(1.3), titulo,
                         size=32, bold=True, color=READABLE_BRAND_RGB, align=PP_ALIGN.CENTER)
                add_text(slide, MARGIN_X, top_y + Cm(1.3), content_w, Cm(0.8),
                         f"Período: {fechas_label}", size=12, italic=True, color=WF_MUTED_RGB,
                         align=PP_ALIGN.CENTER)
                return slide, top_y + Cm(2.5)

            state: dict = {}

            def _ensure_space(titulo_continua: str, need) -> None:
                if state["y"] > bottom_y - need:
                    state["slide"], state["y"] = _new_slide(titulo_continua)

            def _draw_heading(titulo_continua: str, text: str, color_key=None) -> None:
                _ensure_space(titulo_continua, Cm(1.2))
                add_text(state["slide"], MARGIN_X, state["y"], content_w, Cm(0.8), text,
                         size=15, bold=True, color=HEADING_RGB.get(color_key, WF_TEXT_RGB))
                state["y"] += Cm(1.0)

            def _draw_empty(text: str) -> None:
                add_text(state["slide"], MARGIN_X, state["y"], content_w, Cm(0.8), text,
                         size=12, italic=True, color=WF_MUTED_RGB)
                state["y"] += Cm(1.0)

            def _draw_summary_block(titulo_continua: str, block: dict) -> None:
                add_text(state["slide"], MARGIN_X, state["y"], content_w, Cm(1.0), block["text"],
                         size=16, bold=True, color=WF_TEXT_RGB, align=PP_ALIGN.CENTER)
                state["y"] += Cm(1.4)

            def _draw_table_block(titulo_continua: str, block: dict) -> None:
                if block.get("heading"):
                    _draw_heading(titulo_continua, block["heading"])
                rows = block.get("rows") or []
                if not rows:
                    _draw_empty(block.get("empty_text", "Sin datos en este período."))
                    return
                headers = block["headers"]
                fracs = block.get("col_widths") or [1.0 / len(headers)] * len(headers)
                widths = [int(content_w * f) for f in fracs]
                size = 11 if len(headers) <= 5 else 9 if len(headers) <= 8 else 8
                header_h = max(Cm(1.0), _pptx_fila_alto(headers, widths, size + 1))

                def _encabezado() -> None:
                    _wf_rect(state["slide"], MARGIN_X, state["y"], content_w, header_h, fill_rgb=BRAND_RGB)
                    cx = MARGIN_X
                    for h, w in zip(headers, widths):
                        add_text(state["slide"], cx, state["y"], w, header_h, h, size=size + 1, bold=True,
                                 color=HEADER_TEXT_RGB, align=PP_ALIGN.CENTER)
                        cx += w
                    state["y"] += header_h

                primera_h = _pptx_fila_alto([str(v) for v in rows[0]], widths, size)
                _ensure_space(titulo_continua, header_h + min(primera_h, Cm(4)))
                _encabezado()
                for row in rows:
                    celdas = [str(v) for v in row]
                    row_h = _pptx_fila_alto(celdas, widths, size)
                    if state["y"] + row_h > bottom_y:
                        state["slide"], state["y"] = _new_slide(titulo_continua)
                        _encabezado()
                    _wf_rect(state["slide"], MARGIN_X, state["y"], content_w, row_h, fill_rgb=WF_WHITE_RGB,
                             line_rgb=WF_BORDER_RGB, line_pt=0.75)
                    cx = MARGIN_X
                    for texto, w in zip(celdas, widths):
                        add_text(state["slide"], cx, state["y"], w, row_h, texto, size=size, color=WF_TEXT_RGB,
                                 align=PP_ALIGN.LEFT if len(texto) > 24 else PP_ALIGN.CENTER)
                        cx += w
                    state["y"] += row_h
                state["y"] += Cm(0.4)

            def _draw_list_block(titulo_continua: str, block: dict) -> None:
                if block.get("heading"):
                    _draw_heading(titulo_continua, block["heading"], block.get("heading_color"))
                items = block.get("items") or []
                if not items:
                    _draw_empty(block.get("empty_text", "Sin datos en este período."))
                    return
                for it in items:
                    _ensure_space(titulo_continua, Cm(1.4))
                    partes = [p for p in (it.get("title"), it.get("body"), it.get("extra")) if p]
                    linea = " — ".join(partes)
                    add_text(state["slide"], MARGIN_X, state["y"], content_w, Cm(1.2), linea,
                             size=11, color=WF_TEXT_RGB)
                    state["y"] += Cm(1.3)
                    if it.get("meta"):
                        add_text(state["slide"], MARGIN_X, state["y"], content_w, Cm(0.7), it["meta"],
                                 size=9, italic=True, color=WF_MUTED_RGB)
                        state["y"] += Cm(0.7)

            # --- Bloques bespoke (mismo criterio que el motor PDF): sin
            # tablas nativas de pptx, se dibujan a mano con `_wf_rect` +
            # `add_text` — eso permite una "celda combinada" en Riesgos con
            # solo un rectángulo más alto, sin API de merge de python-pptx.
            SHEET_TITLE_RGB = (0x7A, 0x10, 0x30)
            SHEET_GREEN_RGB = (0x2E, 0x7D, 0x32)
            SHEET_GREEN_BG_RGB = (0xEA, 0xF4, 0xEA)
            SHEET_GREEN_TOTAL_RGB = (0xDD, 0xEB, 0xDD)
            SHEET_SALMON_RGB = (0xF4, 0xB1, 0x83)
            SHEET_PINK_RGB = (0xF6, 0xD9, 0xE6)
            SHEET_SUBTOTAL_RGB = (0xDC, 0xEE, 0xFB)
            MAROON_RGB = (0x8B, 0x1E, 0x3F)

            def _draw_bar(titulo_continua: str, text: str, bg_rgb, text_rgb=None) -> None:
                _ensure_space(titulo_continua, Cm(1.0))
                bar_h = Cm(0.9)
                _wf_rect(state["slide"], MARGIN_X, state["y"], content_w, bar_h, fill_rgb=bg_rgb)
                add_text(state["slide"], MARGIN_X, state["y"], content_w, bar_h, text.upper(),
                         size=11, bold=True, color=text_rgb or SHEET_TITLE_RGB, align=PP_ALIGN.CENTER)
                state["y"] += bar_h + Cm(0.15)

            def _draw_sheet_table(headers, rows, col_fracs, header_rgb, zebra_rgb=None, bold_last=False,
                                   header_text_rgb=WF_WHITE_RGB, row_h=Cm(0.75)) -> None:
                widths = [int(content_w * f) for f in col_fracs]
                header_h = Cm(0.85)
                x = MARGIN_X
                y = state["y"]
                _wf_rect(state["slide"], x, y, content_w, header_h, fill_rgb=header_rgb)
                cx = x
                for i, h in enumerate(headers):
                    add_text(state["slide"], cx, y, widths[i], header_h, h,
                             size=9.5, bold=True, color=header_text_rgb, align=PP_ALIGN.CENTER)
                    cx += widths[i]
                cy = y + header_h
                n = len(rows)
                for ridx, row in enumerate(rows):
                    is_total = bold_last and ridx == n - 1
                    if is_total:
                        bg = SHEET_GREEN_TOTAL_RGB if header_rgb == SHEET_GREEN_RGB else SHEET_SUBTOTAL_RGB
                    elif zebra_rgb and ridx % 2 == 1:
                        bg = zebra_rgb
                    else:
                        bg = WF_WHITE_RGB
                    _wf_rect(state["slide"], x, cy, content_w, row_h, fill_rgb=bg, line_rgb=WF_BORDER_RGB, line_pt=0.5)
                    cx = x
                    for i, val in enumerate(row):
                        add_text(state["slide"], cx, cy, widths[i], row_h, str(val),
                                 size=9, bold=is_total, color=WF_TEXT_RGB,
                                 align=PP_ALIGN.LEFT if i == 0 else PP_ALIGN.CENTER)
                        cx += widths[i]
                    cy += row_h
                state["y"] = cy + Cm(0.3)

            def _draw_forestal_sheet_block(titulo_continua: str, block: dict) -> None:
                autorizado_rows = block.get("autorizado_rows") or []
                total = block.get("autorizado_total") or {"poda": 0, "trasplante": 0, "derribo": 0, "total_dictaminados": 0}
                contadores = block.get("contadores") or {"poda": 0, "trasplante": 0, "derribo": 0}

                _draw_bar(titulo_continua, "Resumen Arbolado autorizado mediante Resolución Admva.", SHEET_SALMON_RGB)
                _ensure_space(titulo_continua, Cm(0.85) * (len(autorizado_rows) + 2))
                rows = [[r["estacion"], r["poda"], r["trasplante"], r["derribo"], r["total_dictaminados"]] for r in autorizado_rows]
                rows.append(["TOTAL", total["poda"], total["trasplante"], total["derribo"], total["total_dictaminados"]])
                _draw_sheet_table(
                    ["Estación", "Poda", "Trasplante", "Derribo", "Total árboles"], rows,
                    [0.34, 0.16, 0.17, 0.16, 0.17], SHEET_GREEN_RGB, zebra_rgb=SHEET_GREEN_BG_RGB, bold_last=True,
                )

                _ensure_space(titulo_continua, Cm(1.0))
                add_text(
                    state["slide"], MARGIN_X, state["y"], content_w, Cm(0.9),
                    f"Podas: {contadores['poda']}/{total['poda']}    "
                    f"Trasplantes: {contadores['trasplante']}/{total['trasplante']}    "
                    f"Derribos: {contadores['derribo']}/{total['derribo']}",
                    size=13, bold=True, color=WF_TEXT_RGB, align=PP_ALIGN.CENTER,
                )
                state["y"] += Cm(1.1)

                desde, hasta = block.get("desde"), block.get("hasta")
                if desde and hasta:
                    dias = block.get("dias") or []
                    _draw_bar(titulo_continua, f"Actividades ejecutadas {_fmt_rango_dias_es(desde, hasta)}", SHEET_PINK_RGB)
                    _ensure_space(titulo_continua, Cm(0.75) * (len(dias) + 2))
                    d_rows = []
                    sub = {"poda": 0, "trasplante": 0, "derribo": 0, "total": 0}
                    for dia in dias:
                        d_rows.append([_fmt_dia_corto_es(dia["fecha"]), dia["poda"], dia["trasplante"], dia["derribo"], dia["total"]])
                        for k in sub:
                            sub[k] += dia[k]
                    d_rows.append(["SUBTOTAL", sub["poda"], sub["trasplante"], sub["derribo"], sub["total"]])
                    _draw_sheet_table(
                        ["Fecha", "Podas", "Trasplantes", "Derribos", "Total"], d_rows,
                        [0.36, 0.16, 0.18, 0.16, 0.14], (0xF1, 0xF5, 0xF9), bold_last=True,
                        header_text_rgb=WF_MUTED_RGB,
                    )

            def _draw_riesgos_mapa_block(titulo_continua: str, block: dict) -> None:
                grupos = block.get("grupos") or []
                if not any(g.get("filas") for g in grupos):
                    _draw_empty("Sin riesgos registrados en este período.")
                    return
                headers = ["Estaciones\nPostes", "Riesgos", "Propuesta de control", "Avance"]
                widths = [int(content_w * f) for f in (0.10, 0.38, 0.40, 0.12)]
                size = 9
                header_h = Cm(1.2)
                x = MARGIN_X

                def _encabezado() -> None:
                    _wf_rect(state["slide"], x, state["y"], content_w, header_h, fill_rgb=MAROON_RGB)
                    cx = x
                    for h, w in zip(headers, widths):
                        add_text(state["slide"], cx, state["y"], w, header_h, h, size=9.5, bold=True,
                                 color=WF_WHITE_RGB, align=PP_ALIGN.CENTER)
                        cx += w
                    state["y"] += header_h

                def _cerrar_grupo(estacion: str, top: int, continua: bool) -> None:
                    alto = state["y"] - top
                    if alto <= 0:
                        return
                    _wf_rect(state["slide"], x, top, widths[0], alto, fill_rgb=WF_WHITE_RGB,
                             line_rgb=WF_BORDER_RGB, line_pt=0.5)
                    add_text(state["slide"], x, top, widths[0], alto, estacion + (" (cont.)" if continua else ""),
                             size=9.5, bold=True, color=WF_TEXT_RGB, align=PP_ALIGN.CENTER)

                _ensure_space(titulo_continua, header_h + Cm(2.5))
                _encabezado()
                for g in grupos:
                    filas = g.get("filas") or []
                    if not filas:
                        continue
                    top = state["y"]
                    continua = False
                    for f in filas:
                        celdas = [f["descripcion"], f["control"]]
                        row_h = _pptx_fila_alto(celdas, widths[1:3], size)
                        if state["y"] + row_h > bottom_y:
                            _cerrar_grupo(g["estacion"], top, continua)
                            state["slide"], state["y"] = _new_slide(titulo_continua)
                            _encabezado()
                            top, continua = state["y"], True
                        cx = x + widths[0]
                        for texto, w in ((f["descripcion"], widths[1]), (f["control"], widths[2])):
                            _wf_rect(state["slide"], cx, state["y"], w, row_h, fill_rgb=WF_WHITE_RGB,
                                     line_rgb=WF_BORDER_RGB, line_pt=0.5)
                            add_text(state["slide"], cx, state["y"], w, row_h, texto, size=size, color=WF_TEXT_RGB)
                            cx += w
                        _wf_rect(state["slide"], cx, state["y"], widths[3], row_h, fill_rgb=WF_WHITE_RGB,
                                 line_rgb=WF_BORDER_RGB, line_pt=0.5)
                        add_text(state["slide"], cx, state["y"], widths[3], row_h, f"{f['avance']}%", size=size + 0.5,
                                 color=WF_TEXT_RGB, align=PP_ALIGN.CENTER)
                        state["y"] += row_h
                    _cerrar_grupo(g["estacion"], top, continua)
                state["y"] += Cm(0.3)

            def _draw_seguridad_indicadores_block(titulo_continua: str, block: dict) -> None:
                _ensure_space(titulo_continua, Cm(1.0))
                add_text(state["slide"], MARGIN_X, state["y"], content_w, Cm(0.8), (block.get("subtitulo") or "").upper(),
                         size=14, bold=True, color=MAROON_RGB)
                state["y"] += Cm(1.0)
                items = block.get("items") or []
                if not items:
                    _draw_empty("Sin acciones correctivas pendientes.")
                    return
                for text in items:
                    _ensure_space(titulo_continua, Cm(1.1))
                    add_text(state["slide"], MARGIN_X, state["y"], content_w, Cm(1.1), f"•  {text}",
                             size=11, color=WF_TEXT_RGB)
                    state["y"] += Cm(1.1)

            def _draw_estudios_avances_block(titulo_continua: str, block: dict) -> None:
                grupos = block.get("grupos") or []
                total_filas = sum(len(g.get("items") or []) for g in grupos)
                if total_filas == 0:
                    _draw_empty("Sin avances registrados en este período.")
                    return
                col_fracs = [0.22, 0.78]
                widths = [int(content_w * f) for f in col_fracs]
                _ensure_space(titulo_continua, Cm(0.9) * (total_filas + 2))
                _draw_bar(titulo_continua, "Avances", MAROON_RGB, text_rgb=WF_WHITE_RGB)
                x = MARGIN_X
                cy = state["y"]
                for g in grupos:
                    items = g.get("items") or []
                    if not items:
                        continue
                    group_top = cy
                    for text in items:
                        row_h = Cm(0.9)
                        _wf_rect(state["slide"], x + widths[0], cy, widths[1], row_h, fill_rgb=WF_WHITE_RGB,
                                 line_rgb=WF_BORDER_RGB, line_pt=0.5)
                        add_text(state["slide"], x + widths[0], cy, widths[1], row_h, f"•  {text}",
                                 size=8.5, color=WF_TEXT_RGB)
                        cy += row_h
                    group_h = cy - group_top
                    _wf_rect(state["slide"], x, group_top, widths[0], group_h, fill_rgb=WF_WHITE_RGB,
                             line_rgb=WF_BORDER_RGB, line_pt=0.5)
                    add_text(state["slide"], x, group_top, widths[0], group_h, g["disciplina"],
                             size=9.5, bold=True, color=WF_TEXT_RGB, align=PP_ALIGN.CENTER)
                state["y"] = cy + Cm(0.3)

            def _tr_label(v: dict) -> str:
                if v["no_aplica"]:
                    return "No Aplica"
                if v["valor"] is None:
                    return ""
                val = v["valor"]
                return f"{val:.0f}%" if float(val).is_integer() else f"{val:.2f}%"

            def _draw_tabla_resumen_matriz_block(titulo_continua: str, block: dict) -> None:
                """Tabla de avance acumulado — calcada de la diapositiva de
                referencia del informe diario: fila de título, encabezado
                ACTIVIDAD / EST 1 / E1-E2 … / Total, celdas sin color con
                borde gris, columna Total en negritas y filas de sección
                (ej. "INTER TRAMOS") a todo lo ancho."""
                columnas = block.get("columnas") or []
                filas = block.get("filas") or []
                if not columnas or not filas:
                    _draw_empty("Sin datos capturados en la Tabla Resumen.")
                    return
                GRIS_BORDE = (0xA6, 0xA6, 0xA6)
                GRIS_HEAD = (0xD9, 0xD9, 0xD9)
                act_w = Cm(4.4)
                total_w = Cm(1.8)
                min_col_w = Cm(1.25)
                avail = content_w - act_w - total_w
                max_cols = max(1, int(avail / min_col_w))
                chunks = [columnas[i:i + max_cols] for i in range(0, len(columnas), max_cols)]
                title_h = Cm(0.7)
                header_h = Cm(0.7)
                row_h = Cm(0.56)
                col_offset = 0
                for chunk_idx, chunk in enumerate(chunks):
                    is_last = chunk_idx == len(chunks) - 1
                    col_w = int(avail / len(chunk))
                    tbl_w = act_w + col_w * len(chunk) + (total_w if is_last else 0)

                    def _head() -> None:
                        _ensure_space(titulo_continua, title_h + header_h + row_h * 3)
                        sl = state["slide"]
                        y0 = state["y"]
                        _wf_rect(sl, MARGIN_X, y0, tbl_w, title_h, fill_rgb=GRIS_HEAD,
                                 line_rgb=GRIS_BORDE, line_pt=0.5)
                        add_text(sl, MARGIN_X, y0, tbl_w, title_h, "TABLA DE AVANCE ACUMULADO",
                                 size=10, bold=True, color=WF_TEXT_RGB, align=PP_ALIGN.CENTER)
                        y1 = y0 + title_h
                        _wf_rect(sl, MARGIN_X, y1, act_w, header_h, fill_rgb=GRIS_HEAD,
                                 line_rgb=GRIS_BORDE, line_pt=0.5)
                        add_text(sl, MARGIN_X, y1, act_w, header_h, "ACTIVIDAD",
                                 size=9, bold=True, color=WF_TEXT_RGB, align=PP_ALIGN.CENTER)
                        cx = MARGIN_X + act_w
                        for col in chunk:
                            _wf_rect(sl, cx, y1, col_w, header_h, fill_rgb=GRIS_HEAD,
                                     line_rgb=GRIS_BORDE, line_pt=0.5)
                            add_text(sl, cx, y1, col_w, header_h, col["label"],
                                     size=8, bold=True, color=WF_TEXT_RGB, align=PP_ALIGN.CENTER)
                            cx += col_w
                        if is_last:
                            _wf_rect(sl, cx, y1, total_w, header_h, fill_rgb=GRIS_HEAD,
                                     line_rgb=GRIS_BORDE, line_pt=0.5)
                            add_text(sl, cx, y1, total_w, header_h, "Total",
                                     size=8, bold=True, color=WF_TEXT_RGB, align=PP_ALIGN.CENTER)
                        state["y"] = y1 + header_h

                    _head()
                    for f in filas:
                        if state["y"] + row_h > bottom_y:
                            state["slide"], state["y"] = _new_slide(titulo_continua)
                            _head()
                        sl = state["slide"]
                        cy = state["y"]
                        if f.get("seccion"):
                            _wf_rect(sl, MARGIN_X, cy, tbl_w, row_h, fill_rgb=GRIS_HEAD,
                                     line_rgb=GRIS_BORDE, line_pt=0.5)
                            add_text(sl, MARGIN_X, cy, tbl_w, row_h, f["actividad"],
                                     size=8, bold=True, color=WF_TEXT_RGB, align=PP_ALIGN.CENTER)
                            state["y"] = cy + row_h
                            continue
                        _wf_rect(sl, MARGIN_X, cy, act_w, row_h, fill_rgb=WF_WHITE_RGB,
                                 line_rgb=GRIS_BORDE, line_pt=0.5)
                        add_text(sl, MARGIN_X, cy, act_w, row_h, f["actividad"],
                                 size=7.5, bold=True, color=WF_TEXT_RGB)
                        cx = MARGIN_X + act_w
                        for v in f["valores"][col_offset:col_offset + len(chunk)]:
                            _wf_rect(sl, cx, cy, col_w, row_h, fill_rgb=WF_WHITE_RGB,
                                     line_rgb=GRIS_BORDE, line_pt=0.5)
                            add_text(sl, cx, cy, col_w, row_h, _tr_label(v),
                                     size=7.5, color=WF_TEXT_RGB, align=PP_ALIGN.CENTER)
                            cx += col_w
                        if is_last:
                            t = f.get("total")
                            _wf_rect(sl, cx, cy, total_w, row_h, fill_rgb=WF_WHITE_RGB,
                                     line_rgb=GRIS_BORDE, line_pt=0.5)
                            add_text(sl, cx, cy, total_w, row_h, f"{t:.2f}%" if t is not None else "",
                                     size=7.5, bold=True, color=WF_TEXT_RGB, align=PP_ALIGN.CENTER)
                        state["y"] = cy + row_h
                    state["y"] += Cm(0.5)
                    col_offset += len(chunk)

            def _place_img(slide, b64_str, x, y, w, h) -> int:
                """Coloca la imagen dentro de la caja (x, y, w, h) SIN
                deformarla, centrada en horizontal; devuelve el y inferior
                real (o `y` si no se pudo leer)."""
                try:
                    from PIL import Image as _PI
                    raw = base64.b64decode(_strip_b64_prefix(b64_str))
                    iw, ih = _PI.open(io.BytesIO(raw)).size
                    sc = min(w / iw, h / ih)
                    pw, ph = int(iw * sc), int(ih * sc)
                    slide.shapes.add_picture(io.BytesIO(raw), int(x + (w - pw) / 2), int(y), width=pw, height=ph)
                    return int(y + ph)
                except Exception:
                    return int(y)

            def _draw_fotos_comparativa_block(titulo_continua: str, block: dict) -> None:
                """Una diapositiva por registro: foto ORIGINAL a la izquierda,
                foto ACTUAL a la derecha, cada una con su fecha de toma."""
                gap = Cm(1.0)
                col_w = int((content_w - gap) / 2)
                for idx, it in enumerate(block.get("items") or []):
                    if idx > 0 or state["y"] > top_y + Cm(2.6):
                        state["slide"], state["y"] = _new_slide(titulo_continua)
                    if it.get("titulo"):
                        _draw_heading(titulo_continua, it["titulo"])
                    y0 = state["y"]
                    if _foto_comp_desc(it, "original") or _foto_comp_desc(it, "actual"):
                        for col, key in enumerate(("original", "actual")):
                            x = MARGIN_X + col * (col_w + gap)
                            if it.get("desc_encabezado"):
                                add_text(state["slide"], x, y0, col_w, Cm(0.6), it["desc_encabezado"],
                                         size=11, bold=True, color=WF_TEXT_RGB)
                            add_text(state["slide"], x, y0 + Cm(0.6), col_w, Cm(1.8), _foto_comp_desc(it, key),
                                     size=11, color=WF_TEXT_RGB)
                        y0 += Cm(2.5)
                    img_h = int(bottom_y - y0 - (Cm(2.4) if block.get("leyenda") else Cm(1.6)))
                    y_end = y0
                    for col, (key, lbl, fkey) in enumerate((
                        ("original", "ORIGINAL", "fecha_original"), ("actual", "ACTUAL", "fecha_actual"),
                    )):
                        x = MARGIN_X + col * (col_w + gap)
                        if it.get(key):
                            y_end = max(y_end, _place_img(state["slide"], it[key], x, y0, col_w, img_h))
                        elif it.get("sin_placeholder"):
                            continue
                        else:
                            _wf_rect(state["slide"], x, y0, col_w, img_h, fill_rgb=(0xF1, 0xF5, 0xF9),
                                     line_rgb=WF_BORDER_RGB, line_pt=0.75)
                            add_text(state["slide"], x, y0, col_w, img_h, "Sin foto",
                                     size=14, italic=True, color=WF_MUTED_RGB, align=PP_ALIGN.CENTER)
                            y_end = max(y_end, y0 + img_h)
                    for col, (lbl, slot) in enumerate((("ORIGINAL", "original"), ("ACTUAL", "actual"))):
                        x = MARGIN_X + col * (col_w + gap)
                        _et = _foto_comp_etiqueta(it, slot, lbl)
                        if not _et:
                            continue
                        add_text(state["slide"], x, y_end + Cm(0.15), col_w, Cm(0.9), _et,
                                 size=13, bold=True, color=WF_TEXT_RGB, align=PP_ALIGN.CENTER)
                    if block.get("leyenda"):
                        lw = Cm(3.4) * len(block["leyenda"])
                        lx = MARGIN_X + int((content_w - lw) / 2)
                        ly = y_end + Cm(1.2)
                        for label, hexcolor in block["leyenda"]:
                            rgb = tuple(int(hexcolor[i:i + 2], 16) for i in (1, 3, 5))
                            _wf_oval(state["slide"], lx, ly + Cm(0.05), Cm(0.35), Cm(0.35), rgb)
                            add_text(state["slide"], lx + Cm(0.5), ly, Cm(2.8), Cm(0.5), label,
                                     size=10, color=WF_TEXT_RGB)
                            lx += Cm(3.4)
                    state["y"] = bottom_y

            def _draw_imagen_block(titulo_continua: str, block: dict) -> None:
                if state["y"] > top_y + Cm(2.6):
                    state["slide"], state["y"] = _new_slide(titulo_continua)
                if block.get("heading"):
                    _draw_heading(titulo_continua, block["heading"])
                img_h = int(bottom_y - state["y"] - Cm(2.0))
                y_end = _place_img(state["slide"], block["imagen"], MARGIN_X, state["y"], content_w, img_h)
                state["y"] = y_end + Cm(0.25)
                if block.get("caption"):
                    add_text(state["slide"], MARGIN_X, state["y"], content_w, Cm(0.8), block["caption"],
                             size=12, bold=True, color=WF_TEXT_RGB, align=PP_ALIGN.CENTER)
                    state["y"] += Cm(0.9)
                lx = MARGIN_X
                for label, hexcolor in (block.get("leyenda") or []):
                    rgb = tuple(int(hexcolor[i:i + 2], 16) for i in (1, 3, 5))
                    _wf_oval(state["slide"], lx, state["y"] + Cm(0.05), Cm(0.35), Cm(0.35), rgb)
                    add_text(state["slide"], lx + Cm(0.5), state["y"], Cm(2.6), Cm(0.5), label,
                             size=10, color=WF_TEXT_RGB)
                    lx += Cm(3.2)
                state["y"] += Cm(0.8)

            def _draw_seguridad_accidentes_block(titulo_continua: str, block: dict) -> None:
                """Registro de accidentes: Fecha, Mes, Trabajador, Contratista,
                Registro, Ubicación, Descripción, Foto y Seguimiento. Una tabla
                que pagina entre diapositivas repitiendo el encabezado."""
                if block.get("heading"):
                    _draw_heading(titulo_continua, block["heading"])
                rows = block.get("rows") or []
                if not rows:
                    _draw_empty("Sin registros de accidentes en este período.")
                    return
                headers = ["Fecha", "Mes", "Trabajador", "Contratista", "Registro", "Ubicación", "Descripción", "Foto", "Seguimiento"]
                fracs = (0.075, 0.07, 0.12, 0.09, 0.105, 0.11, 0.19, 0.10, 0.14)
                col_x = [int(content_w * sum(fracs[:i])) for i in range(len(fracs))]
                col_w = [int(content_w * f) for f in fracs]
                HEADER_H = Cm(0.9)
                PHOTO_H = Cm(2.2)
                FONT = 8
                LINE_H = Cm(0.36)

                def _lines(text: str, w_emu: int) -> int:
                    cpl = max(1, int((w_emu - Cm(0.2)) / max(1, int(Pt(FONT * 0.52)))))
                    return min(7, max(1, math.ceil(len(text or "—") / cpl)))

                def _header(slide, y):
                    _wf_rect(slide, MARGIN_X, y, content_w, HEADER_H, fill_rgb=BRAND_RGB)
                    for i, h in enumerate(headers):
                        add_text(slide, MARGIN_X + col_x[i], y, col_w[i], HEADER_H, h,
                                 size=9, bold=True, color=HEADER_TEXT_RGB, align=PP_ALIGN.CENTER)
                    return y + HEADER_H

                text_keys = ["fecha", "mes", "trabajador", "contratista", "registro", "ubicacion",
                             "descripcion", None, "seguimiento"]
                state["y"] = _header(state["slide"], state["y"])
                for r in rows:
                    row_h = max(
                        [Cm(0.6)] + [
                            _lines(str(r.get(k) or "—"), col_w[i]) * LINE_H + Cm(0.2)
                            for i, k in enumerate(text_keys) if k
                        ] + ([PHOTO_H + Cm(0.2)] if r.get("foto") else []),
                    )
                    if state["y"] + row_h > bottom_y:
                        state["slide"], state["y"] = _new_slide(titulo_continua)
                        state["y"] = _header(state["slide"], state["y"])
                    sl, ry = state["slide"], state["y"]
                    _wf_rect(sl, MARGIN_X, ry, content_w, row_h, fill_rgb=WF_WHITE_RGB,
                             line_rgb=WF_BORDER_RGB, line_pt=0.75)
                    for i, k in enumerate(text_keys):
                        if k is None:
                            if r.get("foto"):
                                _place_img(sl, r["foto"], MARGIN_X + col_x[i] + Cm(0.1), ry + Cm(0.1),
                                           col_w[i] - Cm(0.2), row_h - Cm(0.2))
                            else:
                                add_text(sl, MARGIN_X + col_x[i], ry, col_w[i], row_h, "—",
                                         size=FONT, color=WF_MUTED_RGB, align=PP_ALIGN.CENTER)
                            continue
                        add_text(sl, MARGIN_X + col_x[i] + Cm(0.1), ry + Cm(0.05), col_w[i] - Cm(0.2),
                                 row_h - Cm(0.1), str(r.get(k) or "—"), size=FONT, color=WF_TEXT_RGB)
                    state["y"] = ry + row_h
                state["y"] += Cm(0.4)

            _BLOCK_RENDERERS = {
                "summary": _draw_summary_block,
                "table": _draw_table_block,
                "list": _draw_list_block,
                "forestal_sheet": _draw_forestal_sheet_block,
                "riesgos_mapa": _draw_riesgos_mapa_block,
                "seguridad_indicadores": _draw_seguridad_indicadores_block,
                "seguridad_accidentes": _draw_seguridad_accidentes_block,
                "estudios_avances": _draw_estudios_avances_block,
                "tabla_resumen_matriz": _draw_tabla_resumen_matriz_block,
                "fotos_comparativa": _draw_fotos_comparativa_block,
                "imagen": _draw_imagen_block,
            }

            # (El resumen de actividades va al INICIO del PPTX, ver
            # `_emit_resumen_actividades_frente_slides`.)
            for _mod_key, _mod_data in (datos if datos is not None else modulos_data).items():
                if _mod_data is None:
                    continue
                titulo = _mod_data["titulo"]
                if datos is None:
                    _indice_mark(f"mod:{_mod_key}", titulo)
                sin_portada = _mod_key in _MODULOS_SIN_PORTADA
                state["slide"], state["y"] = _new_slide(None if sin_portada else titulo)
                titulo_continua = None if sin_portada else f"{titulo} (continúa)"
                for block in _mod_data["blocks"]:
                    _BLOCK_RENDERERS[block["type"]](titulo_continua, block)

        resumen_subtramos_emitidos: set = set()

        lidar_por_sub = _lidar_separar_por_estacion(modulos_data, nodes_by_id)

        def _emit_subtramo_summary_slide(subtramo_id: Optional[str], forzar: bool = False) -> None:
            """Slide de resumen de la estación y, justo después, su Vuelo LiDAR."""
            _emit_subtramo_summary_slide_core(subtramo_id, forzar)
            items = lidar_por_sub.pop(subtramo_id, None) if subtramo_id else None
            if items:
                nombre = (nodes_by_id.get(subtramo_id) or {}).get("name") or "Estación"
                _indice_mark(f"lidar:{subtramo_id}", f"Vuelo LiDAR · {nombre}")
                _emit_modulos_closing_slides({"fotos_lidar_estacion": _lidar_modulo_estacion(nombre, items)})

        def _emit_subtramo_summary_slide_core(subtramo_id: Optional[str], forzar: bool = False) -> None:
            """Emite (si hay datos) la slide de resumen del Subtramo
            `subtramo_id` para todo el período exportado — al final de la
            sección de ese subtramo. Con `forzar=True` la emite aunque no haya
            nada (frente sin reportes): las tablas dicen "Sin registros" y las
            actividades "Sin actividad", como en el reporte de referencia. Un
            subtramo ya impreso no se vuelve a emitir."""
            if not subtramo_id or subtramo_id in resumen_subtramos_emitidos:
                return
            subtramo_node = nodes_by_id.get(subtramo_id) or {}
            es_intertramo = subtramo_node.get("tipo_nodo") == "intertramo"
            # El turno nocturno solo parte la slide de ESTACIÓN; el Intertramo
            # conserva una sola slide con ambos turnos juntos.
            if es_intertramo:
                totals = resource_consolidated_by_subtramo.get(subtramo_id)
                _acts_base = (actividades_by_subtramo.get(subtramo_id) or []) + \
                    (actividades_noche_by_subtramo.get(subtramo_id) or [])
            else:
                totals = resource_consolidated_dia_by_subtramo.get(subtramo_id)
                _acts_base = actividades_by_subtramo.get(subtramo_id) or []
            _noche = None if es_intertramo else resource_consolidated_noche_by_subtramo.get(subtramo_id)
            # Nodo que realmente representa Acceso al Predio/Situación Social
            # para este Subtramo — respeta el toggle `acceso_predio_habilitado`
            # (a cualquier profundidad, ver hub). None si nada fue habilitado
            # para esta ubicación (antes se imprimía "Sin especificar" en
            # TODOS los subtramos sin importar el hub).
            acceso_node = _resolve_acceso_predio_node(subtramo_id, subtramo_node, nodes_by_subtramo)
            personal_rows = (totals or {}).get("personal") or []
            maquinaria_rows = (totals or {}).get("maquinaria") or []
            postes = sorted(
                (n for n in nodes_by_id.values() if n.get("parent_id") == subtramo_id),
                key=lambda n: (n.get("order", 0), n.get("name", "")),
            ) if es_intertramo else []
            # FIX: mismo caso que en el motor PDF (`_emit_subtramo_summary`)
            # — "Acceso al Predio" es estado persistente del nodo, no
            # derivado de reportes del período; un Subtramo sin
            # personal/maquinaria capturados en el período no debe perder
            # su slide de Acceso al Predio si el panel lo tiene configurado
            # (o, para Intertramo, sus postes definidos en el árbol).
            has_persistent_content = bool(
                (acceso_node and (acceso_node.get("acceso_predio") or "").strip())
                or (acceso_node and (acceso_node.get("situacion_social") or "").strip())
                or _acts_base
                or postes
            )
            _hay_dia = bool(forzar or personal_rows or maquinaria_rows or has_persistent_content)
            if not _hay_dia and not _noche:
                return
            resumen_subtramos_emitidos.add(subtramo_id)
            if _hay_dia:
                _acts_sub = _acts_base or (["Sin actividad"] if forzar else [])
                _indice_mark(f"sub:{subtramo_id}", f"Resumen · {subtramo_node.get('name') or 'Subtramo'}")
                if es_intertramo:
                    draw_intertramo_summary_slide(
                        subtramo_node, personal_rows, maquinaria_rows,
                        _acts_sub,
                        acceso_node.get("situacion_social") if acceso_node else None,
                        postes,
                        mostrar_situacion=acceso_node is not None,
                    )
                else:
                    _resto = draw_subtramo_summary_slide(
                        subtramo_node, personal_rows, maquinaria_rows,
                        _acts_sub,
                        acceso_node.get("situacion_social") if acceso_node else None,
                        acceso_node.get("acceso_predio") if acceso_node else None,
                        weather_by_subtramo.get(subtramo_id),
                        mostrar_acceso_predio=acceso_node is not None,
                        acceso_node_label=(acceso_node.get("name") if acceso_node else None),
                    )
                    while _resto:
                        _n_prev = len(_resto)
                        _resto = draw_subtramo_summary_slide(
                            subtramo_node, [], [], _resto, None, None, None,
                            mostrar_acceso_predio=False,
                            acceso_node_label=(acceso_node.get("name") if acceso_node else None),
                            continuacion=True,
                        )
                        if len(_resto) >= _n_prev:
                            break
            if _noche:
                # Misma estación (mismo "ESTACIÓN N.", mismo nombre), segunda
                # slide con SOLO lo capturado en el turno nocturno.
                _indice_mark(f"sub-noche:{subtramo_id}",
                             f"Resumen · {subtramo_node.get('name') or 'Subtramo'} · {TURNO_NOCTURNO_ETIQUETA.title()}")
                _resto = draw_subtramo_summary_slide(
                    subtramo_node, _noche.get("personal") or [], _noche.get("maquinaria") or [],
                    actividades_noche_by_subtramo.get(subtramo_id) or [],
                    acceso_node.get("situacion_social") if acceso_node else None,
                    acceso_node.get("acceso_predio") if acceso_node else None,
                    weather_by_subtramo.get(subtramo_id),
                    mostrar_acceso_predio=acceso_node is not None,
                    acceso_node_label=(acceso_node.get("name") if acceso_node else None),
                    turno_label=TURNO_NOCTURNO_ETIQUETA,
                )
                while _resto:
                    _n_prev = len(_resto)
                    _resto = draw_subtramo_summary_slide(
                        subtramo_node, [], [], _resto, None, None, None,
                        mostrar_acceso_predio=False,
                        acceso_node_label=(acceso_node.get("name") if acceso_node else None),
                        turno_label=TURNO_NOCTURNO_ETIQUETA, continuacion=True,
                    )
                    if len(_resto) >= _n_prev:
                        break

        # Frentes (Estación/Intertramo) SIN ningún reporte en el período: se
        # imprimen igual, con "Sin actividad", en su lugar del orden del árbol
        # (el reporte de referencia muestra siempre todos los frentes).
        _raices_orden = sorted((n for n in nodes_by_id.values() if n.get("depth") == 0),
                               key=lambda n: (n.get("order", 0), n.get("name", "")))
        _rank_raiz = {r["id"]: i for i, r in enumerate(_raices_orden)}
        frentes_orden = [f["id"] for f in sorted(
            (n for n in nodes_by_id.values() if n.get("depth") == 1),
            key=lambda n: (_rank_raiz.get(n.get("parent_id"), 10 ** 6), n.get("order", 0), n.get("name", "")),
        )]
        frentes_con_reportes = {
            _subtramo_id_for(n["id"], nodes_by_id) for n in leaf_nodes if workforce_reports_by_node.get(n["id"])
        }

        def _emit_frentes_sin_actividad(antes_de: Optional[str]) -> None:
            for sid in frentes_orden:
                if antes_de is not None and sid == antes_de:
                    break
                if sid not in frentes_con_reportes:
                    _emit_subtramo_summary_slide(sid, forzar=True)

        def _emit_actividades_area_slides(area_name: str, node_path: str, items: List[str]) -> None:
            """Slide(s) "RESUMEN DE ACTIVIDADES" insertadas justo después de
            la portadilla de Área — mismo contenido y misma fuente (curada
            del hub Actividades Generales) que `_emit_actividades_area` en
            el motor PDF, ver esa nota ahí. No-op si `items` viene vacío.
            Pagina igual que `_emit_recuento_general_slides` (nunca trunca
            con "+N más"). python-pptx no expone medición real de texto
            envuelto — la altura de fila se estima por conteo de caracteres,
            con margen generoso para minimizar el riesgo de texto cortado."""
            if not items:
                return

            MARGIN_X = Cm(1.8)
            content_w = SW - 2 * MARGIN_X
            HEADER_H = Cm(0.9)
            LINE_H = Cm(0.5)
            ROW_PAD = Cm(0.18)
            ROW_FONT = 11
            MAX_LINES_PER_ROW = 4

            def _estimate_lines(text: str, box_w_emu: int, font_pt: float) -> int:
                if not text:
                    return 1
                avg_char_w_emu = max(1, int(Pt(font_pt * 0.52)))
                chars_per_line = max(1, int(box_w_emu / avg_char_w_emu))
                return min(MAX_LINES_PER_ROW, max(1, math.ceil(len(text) / chars_per_line)))

            row_text_w = content_w - Cm(0.5)
            measured = [
                {"text": texto, "h": _estimate_lines(texto, row_text_w, ROW_FONT) * LINE_H + 2 * ROW_PAD}
                for texto in items
            ]
            n_total = len(measured)

            idx = 0
            page_in_area = 0
            while idx < n_total or page_in_area == 0:
                page_in_area += 1
                slide = _clone_membrete()
                y = TOP_MARGIN
                title = "RESUMEN DE ACTIVIDADES"
                if page_in_area > 1:
                    title += f"  (CONTINÚA · {page_in_area})"
                add_text(slide, MARGIN_X, y, content_w, Cm(0.9), title,
                         size=22, bold=True, color=READABLE_BRAND_RGB, align=PP_ALIGN.CENTER)
                y += Cm(1.0)
                add_text(slide, MARGIN_X, y, content_w, Cm(0.6), area_name.upper(),
                         size=15, bold=True, color=WF_TEXT_RGB, align=PP_ALIGN.CENTER)
                y += Cm(0.65)
                if node_path:
                    add_text(slide, MARGIN_X, y, content_w, Cm(0.5), node_path,
                             size=10, color=WF_MUTED_RGB, align=PP_ALIGN.CENTER)
                    y += Cm(0.55)

                _wf_rect(slide, MARGIN_X, y, content_w, HEADER_H, fill_rgb=BRAND_RGB)
                add_text(slide, MARGIN_X + Cm(0.2), y + Cm(0.15), content_w - Cm(0.4), HEADER_H - Cm(0.2),
                         "ACTIVIDADES", size=12, bold=True, color=HEADER_TEXT_RGB)
                yy = y + HEADER_H
                avail_h = (SH - BOTTOM_MARGIN) - yy

                cnt = 0
                h_acc = 0.0
                for i in range(idx, n_total):
                    rh = measured[i]["h"]
                    if cnt > 0 and h_acc + rh > avail_h:
                        break
                    h_acc += rh
                    cnt += 1
                cnt = max(cnt, 1)
                chunk_end = idx + cnt

                for i in range(idx, chunk_end):
                    row_h = measured[i]["h"]
                    if (i - idx) % 2 == 1:
                        _wf_rect(slide, MARGIN_X, yy, content_w, row_h, fill_rgb=WF_ZEBRA_TINT_RGB)
                    add_text(slide, MARGIN_X + Cm(0.25), yy + Cm(0.08), content_w - Cm(0.5), row_h - Cm(0.1),
                             f"•  {measured[i]['text']}", size=ROW_FONT, color=WF_TEXT_RGB)
                    _wf_rect(slide, MARGIN_X, yy + row_h - Pt(0.75), content_w, Pt(0.75), fill_rgb=WF_BORDER_RGB)
                    yy += row_h

                idx = chunk_end

        # Logo institucional: eliminado — la plantilla ya trae los logos
        # del membrete. Cualquier logo adicional programático producía
        # "ghost images" en las esquinas del reporte.
        # (Se conserva la resolución del blob por compatibilidad con otros
        # motores; no se inserta ninguna imagen adicional en PPTX.)
        logo_bytes = None  # noqa: F841

        def add_logo(slide, x, y, w_cm: float, h_cm: float):
            """DEPRECATED · no-op: no se insertan logos adicionales en PPTX."""
            return False

        def add_header_footer(slide):
            """DEPRECATED · no-op: el encabezado/pie institucional ahora
            proviene exclusivamente del membrete de la plantilla clonada
            por `_clone_membrete()`. Se mantiene para compatibilidad con
            invocaciones existentes."""
            return None

        # ==============================================================
        # COLORES PARAMETRIZABLES (documentados para futura configuración
        # por proyecto vía DB). Todos son tuples RGB (0..255).
        # ==============================================================
        # Portada principal: SOLO color_tema (nunca project_color/
        # color_institucional, que aquí ya no aplica — ver separación de
        # campos en ProjectIn). Antes blanco fijo; no se replica aquí la
        # técnica de contorno del motor PDF (python-pptx/add_text no la
        # soportan sin más obra) — limitación aceptada, ver commit.
        _cover_title_hex = _sanitize_color_hex(proj.get("color_tema")) or "#003366"
        _cover_title_ch = _cover_title_hex.lstrip("#")
        COVER_TEXT_COLOR = (int(_cover_title_ch[0:2], 16), int(_cover_title_ch[2:4], 16), int(_cover_title_ch[4:6], 16))
        AREA_TEXT_COLOR = (0xFF, 0xFF, 0xFF)      # Portadillas de Área: blanco
        NODE_TITLE_COLOR = (0x0F, 0x17, 0x2A)     # Título de nodo: azul oscuro
        PHOTO_CAPTION_COLOR = _sanitize_color_hex(proj.get("report_text_color")) or "#0F172A"
        # Convertir a tupla RGB para python-pptx
        _pcc = PHOTO_CAPTION_COLOR.lstrip("#")
        PHOTO_CAPTION_COLOR = (int(_pcc[0:2], 16), int(_pcc[2:4], 16), int(_pcc[4:6], 16))
        TEXT_MUTED = (0x64, 0x75, 0x8B)

        # ===== PORTADA PRINCIPAL (Slide 0 de la plantilla) =============
        # NOTA IMPORTANTE: los textos de la portada se inyectan AL FINAL
        # del render (después de todas las clonaciones de portadillas de
        # Área), para evitar que dichas portadillas hereden estos textos
        # al clonarse desde `tpl_cover_slide`. Aquí solo garantizamos que
        # existe la portada; los textos van al cierre del builder.
        if tpl_cover_slide is None and tpl_master_slide is None:
            # Sin plantilla: portada en blanco.
            prs.slides.add_slide(blank)

        # ===== SLIDES "ACTIVIDADES GENERALES" (resumen por frente) =============
        # Formato del reporte semanal de referencia: título "ACTIVIDADES
        # GENERALES", el nombre del Área debajo y dos columnas de texto (12 pt)
        # con un encabezado en negritas por Estación/Intertramo y sus
        # actividades con viñeta; los frentes sin actividad dicen "Sin
        # actividad". Va justo después de Datos Generales, antes del cuerpo por
        # nodo/área. Pagina de verdad (nunca trunca); la altura se estima con
        # `_pptx_texto_lineas`.
        def _emit_resumen_actividades_frente_slides() -> None:
            if not actividades_resumen_frente:
                return
            RF_MARGIN_X = Cm(1.5)
            RF_GUTTER = Cm(1.0)
            rf_content_w = SW - 2 * RF_MARGIN_X
            rf_col_w = int((rf_content_w - RF_GUTTER) / 2)
            RF_FONT = 12
            RF_LINE = int(RF_FONT * 1.2 * 12700)
            RF_GAP = int(Pt(4))
            RF_SPC_ANTES_H = int(Pt(6))
            RF_INDENT = int(Cm(0.6))
            col_top = TOP_MARGIN + Cm(1.3) + Cm(1.0)
            col_h = int((SH - BOTTOM_MARGIN) - col_top - Cm(0.2))

            for grp in actividades_resumen_frente:
                entradas: list = []
                for b in grp["bloques"]:
                    entradas.append(("h", b["titulo"], RF_LINE * _pptx_texto_lineas(b["titulo"], rf_col_w, RF_FONT) + RF_GAP + RF_SPC_ANTES_H))
                    for ln in b["lineas"]:
                        entradas.append(("b", ln, RF_LINE * _pptx_texto_lineas(ln, rf_col_w - RF_INDENT, RF_FONT) + RF_GAP))
                columnas: list = []
                cur: list = []
                usado = 0
                for i, (tipo, texto, h) in enumerate(entradas):
                    # Un encabezado nunca queda solo al final de la columna.
                    necesita = h + (entradas[i + 1][2] if tipo == "h" and i + 1 < len(entradas) else 0)
                    if cur and usado + necesita > col_h:
                        columnas.append(cur)
                        cur, usado = [], 0
                    cur.append((tipo, texto))
                    usado += h
                if cur:
                    columnas.append(cur)

                for pi in range(0, len(columnas), 2):
                    if pi == 0:
                        _indice_mark(f"actfrente:{grp['area']}", f"Resumen de actividades · {grp['area']}")
                    slide = _clone_membrete()
                    add_text(slide, RF_MARGIN_X, TOP_MARGIN, rf_content_w, Cm(1.3), "ACTIVIDADES GENERALES",
                             size=26, bold=True, color=READABLE_BRAND_RGB, align=PP_ALIGN.CENTER)
                    add_text(slide, RF_MARGIN_X, TOP_MARGIN + Cm(1.3), rf_content_w, Cm(0.9),
                             grp["area"].upper() + ("  (CONTINÚA)" if pi else ""),
                             size=18, bold=True, color=WF_TEXT_RGB)
                    for ci, col in enumerate(columnas[pi:pi + 2]):
                        tb = slide.shapes.add_textbox(RF_MARGIN_X + ci * (rf_col_w + RF_GUTTER), col_top, rf_col_w, col_h)
                        tf = tb.text_frame
                        tf.word_wrap = True
                        for k, (tipo, texto) in enumerate(col):
                            par = tf.paragraphs[0] if k == 0 else tf.add_paragraph()
                            run = par.add_run()
                            run.text = texto
                            run.font.size = Pt(RF_FONT)
                            run.font.bold = tipo == "h"
                            run.font.color.rgb = PRGBColor(*WF_TEXT_RGB)
                            par.space_after = Pt(4)
                            if tipo == "h" and k > 0:
                                par.space_before = Pt(6)
                            if tipo == "b":
                                pPr = par._p.get_or_add_pPr()
                                pPr.set("marL", str(RF_INDENT))
                                pPr.set("indent", str(-RF_INDENT))
                                _ET.SubElement(pPr, _qn("a:buChar")).set("char", "\u2022")

        # ===== SLIDE DATOS DE CONTRATO =====================================
        # Formato del informe diario de referencia: dos columnas (OBRA y
        # SUPERVISIÓN), cada una con objeto, empresa, contrato, ubicación y
        # una tabla Periodo / Monto / IVA / Monto con IVA / Anticipo. Todo
        # sale de los datos del proyecto (`datos_contrato` + campos base
        # como fallback); sin datos de supervisión, la obra ocupa todo el
        # ancho.
        def _emit_contrato_slide() -> None:
            bloques = _contrato_bloques(proj)
            if not bloques:
                return

            _indice_mark("contrato", "Datos de contrato")
            sl = _clone_membrete()
            k = min(1.0, SW / Cm(33.9))
            f_head = max(14.0, 18 * k)
            f_body = max(9.0, 14 * k)
            f_tbl = max(8.5, 12 * k)
            margin = Cm(1.5)
            gap = Cm(1.6)
            col_w = int((SW - 2 * margin - gap * (len(bloques) - 1)) / len(bloques))
            for bi, blq in enumerate(bloques):
                x = margin + bi * (col_w + gap)
                y = TOP_MARGIN
                add_text(sl, x, y, col_w, Cm(1.0), "DATOS DE CONTRATO", size=f_head, bold=True,
                         color=READABLE_BRAND_RGB)
                y += Cm(1.3)
                tb = sl.shapes.add_textbox(x, y, col_w, Cm(6.0))
                tf = tb.text_frame
                tf.word_wrap = True
                lineas = blq["lineas"]
                for li, (lbl, val) in enumerate(lineas):
                    par = tf.paragraphs[0] if li == 0 else tf.add_paragraph()
                    par.space_after = Pt(6)
                    r1 = par.add_run()
                    r1.text = lbl + " "
                    r1.font.size = Pt(f_body)
                    r1.font.bold = True
                    r1.font.color.rgb = PRGBColor(*WF_TEXT_RGB)
                    r2 = par.add_run()
                    r2.text = val
                    r2.font.size = Pt(f_body)
                    r2.font.color.rgb = PRGBColor(*WF_TEXT_RGB)
                filas = blq["filas"]
                if filas:
                    ty = y + Cm(6.6)
                    row_h = Cm(0.95)
                    lw = int(col_w * 0.42)
                    vw = int((col_w - lw) / 2)
                    _wf_rect(sl, x, ty, lw, row_h, fill_rgb=BRAND_RGB, line_rgb=BRAND_RGB, line_pt=0.5)
                    _wf_rect(sl, x + lw, ty, vw, row_h, fill_rgb=BRAND_RGB, line_rgb=BRAND_RGB, line_pt=0.5)
                    _wf_rect(sl, x + lw + vw, ty, vw, row_h, fill_rgb=BRAND_RGB, line_rgb=BRAND_RGB, line_pt=0.5)
                    add_text(sl, x + lw, ty, vw, row_h, "Inicio", size=f_tbl, bold=True,
                             color=HEADER_TEXT_RGB, align=PP_ALIGN.CENTER)
                    add_text(sl, x + lw + vw, ty, vw, row_h, "Fin", size=f_tbl, bold=True,
                             color=HEADER_TEXT_RGB, align=PP_ALIGN.CENTER)
                    ty += row_h
                    for lbl, v1, v2, unida in filas:
                        _wf_rect(sl, x, ty, lw, row_h, fill_rgb=BRAND_RGB, line_rgb=BRAND_RGB, line_pt=0.5)
                        add_text(sl, x, ty, lw, row_h, lbl, size=f_tbl, bold=True,
                                 color=HEADER_TEXT_RGB, align=PP_ALIGN.CENTER)
                        if unida:
                            _wf_rect(sl, x + lw, ty, vw * 2, row_h, fill_rgb=WF_WHITE_RGB,
                                     line_rgb=BRAND_RGB, line_pt=0.5)
                            add_text(sl, x + lw, ty, vw * 2, row_h, v1, size=f_tbl,
                                     color=WF_TEXT_RGB, align=PP_ALIGN.CENTER)
                        else:
                            _wf_rect(sl, x + lw, ty, vw, row_h, fill_rgb=WF_WHITE_RGB,
                                     line_rgb=BRAND_RGB, line_pt=0.5)
                            _wf_rect(sl, x + lw + vw, ty, vw, row_h, fill_rgb=WF_WHITE_RGB,
                                     line_rgb=BRAND_RGB, line_pt=0.5)
                            add_text(sl, x + lw, ty, vw, row_h, v1, size=f_tbl,
                                     color=WF_TEXT_RGB, align=PP_ALIGN.CENTER)
                            add_text(sl, x + lw + vw, ty, vw, row_h, v2, size=f_tbl,
                                     color=WF_TEXT_RGB, align=PP_ALIGN.CENTER)
                        ty += row_h

        # ===== SLIDE RESUMEN DE AVANCE (hasta arriba, tras la portada) =====
        # SOLO la tabla ACTIVIDAD / AVANCE con el % final (Total) de cada
        # fila de la Tabla de Avance Acumulado — sin título ni leyenda.
        def _emit_resumen_avance_slides() -> None:
            filas = ((modulos_data.get("tabla_resumen") or {}).get("blocks") or [{}])[0].get("filas") or []
            if not filas:
                return
            GRIS = (0xA6, 0xA6, 0xA6)
            x0 = Cm(1.5)
            tw_ = SW - 2 * x0
            act_w = int(tw_ * 0.78)
            val_w = tw_ - act_w
            head_h = Cm(0.9)
            base_h = Cm(0.7)
            top = TOP_MARGIN
            lim = SH - BOTTOM_MARGIN
            filas_h = []
            for f in filas:
                n = _pptx_texto_lineas(f["actividad"], act_w - Cm(0.4), 11)
                filas_h.append(max(base_h, int(Cm(0.35)) + int(n * Pt(11) * 1.2)))
            i = 0
            primera = True
            while i < len(filas):
                sl = _clone_membrete()
                if primera:
                    _indice_mark("resumen_avance", "Resumen de avance")
                    primera = False
                y = top
                _wf_rect(sl, x0, y, act_w, head_h, fill_rgb=BRAND_RGB, line_rgb=GRIS, line_pt=0.5)
                add_text(sl, x0, y, act_w, head_h, "ACTIVIDAD", size=13, bold=True,
                         color=HEADER_TEXT_RGB, align=PP_ALIGN.CENTER, tight=True)
                _wf_rect(sl, x0 + act_w, y, val_w, head_h, fill_rgb=BRAND_RGB, line_rgb=GRIS, line_pt=0.5)
                add_text(sl, x0 + act_w, y, val_w, head_h, "AVANCE", size=13, bold=True,
                         color=HEADER_TEXT_RGB, align=PP_ALIGN.CENTER, tight=True)
                y += head_h
                n_pag = 0
                while i < len(filas):
                    h = filas_h[i]
                    if y + h > lim and n_pag:
                        break
                    f = filas[i]
                    if f.get("seccion"):
                        _wf_rect(sl, x0, y, tw_, h, fill_rgb=(0xD9, 0xD9, 0xD9), line_rgb=GRIS, line_pt=0.5)
                        add_text(sl, x0 + Cm(0.2), y, tw_ - Cm(0.4), h, f["actividad"], size=11, bold=True,
                                 color=WF_TEXT_RGB, tight=True)
                    else:
                        t = f.get("total")
                        _wf_rect(sl, x0, y, act_w, h, fill_rgb=WF_WHITE_RGB, line_rgb=GRIS, line_pt=0.5)
                        add_text(sl, x0 + Cm(0.2), y, act_w - Cm(0.4), h, f["actividad"], size=11,
                                 color=WF_TEXT_RGB, tight=True)
                        _wf_rect(sl, x0 + act_w, y, val_w, h, fill_rgb=WF_WHITE_RGB, line_rgb=GRIS, line_pt=0.5)
                        add_text(sl, x0 + act_w, y, val_w, h, f"{t:.2f}%" if t is not None else "—",
                                 size=11, color=WF_TEXT_RGB, align=PP_ALIGN.CENTER, tight=True)
                    y += h
                    i += 1
                    n_pag += 1

        _emit_resumen_avance_slides()

        _emit_contrato_slide()

        # ===== SLIDES DATOS GENERALES (ex-Mapa: array de imágenes) =========
        # Cada imagen en `general_data_images` produce UNA slide dedicada
        # sobre el membrete institucional. Retro-compat: si el array está
        # vacío pero existe `template_map` (legacy), se emite ese archivo
        # como única slide. Si nada, slide con mensaje guía.
        _gd_images_p: List[str] = list(proj.get("general_data_images") or [])
        _legacy_map_pptx = _get_project_template(proj, "map") if not _gd_images_p else None

        def _emit_gd_slide_from_bytes(img_bytes: bytes) -> None:
            _sl = _clone_membrete()
            try:
                _map_x = Cm(1.0)
                _map_y = TOP_MARGIN
                _map_w = SW - Cm(2.0)
                _map_h = SH - _map_y - BOTTOM_MARGIN
                _sl.shapes.add_picture(
                    io.BytesIO(img_bytes),
                    _map_x, _map_y, width=_map_w, height=_map_h,
                )
            except Exception:
                pass

        _gd_names_p: List[str] = _gd_names_aligned(proj.get("general_data_names"), len(_gd_images_p))
        if _gd_images_p:
            for _gd_i, _b64 in enumerate(_gd_images_p):
                _indice_mark(
                    f"gd:{_gd_i}",
                    _gd_names_p[_gd_i] or (f"Datos generales {_gd_i + 1}" if len(_gd_images_p) > 1 else "Datos generales"),
                )
                try:
                    raw = base64.b64decode(_strip_b64_prefix(_b64))
                    _emit_gd_slide_from_bytes(raw)
                except Exception:
                    _emit_gd_slide_from_bytes(b"")
        elif _legacy_map_pptx:
            _indice_mark("gd", "Datos generales")
            try:
                _emit_gd_slide_from_bytes(Path(_legacy_map_pptx).read_bytes())
            except Exception:
                _emit_gd_slide_from_bytes(b"")
        else:
            _indice_mark("gd", "Datos generales")
            _empty = _clone_membrete()
            add_text(_empty, Cm(1.0), SH / 2 - Cm(0.6), SW - Cm(2.0), Cm(1.2),
                     "Sube imágenes de Datos Generales para el proyecto (presupuesto, programa, planos, mapa…).",
                     size=14, italic=True, color=TEXT_MUTED,
                     align=PP_ALIGN.CENTER)

        # El resumen de actividades va justo DESPUÉS de Datos Generales
        # (spec de producto) — antes del cuerpo principal por nodo/área.
        _emit_resumen_actividades_frente_slides()

        # ================================================================
        # Helper: emite una slide ejecutiva con hasta 2 FOTOS (foto + pie).
        # Cada foto es apaisada 13.37 × 10 cm; debajo va un cuadro de texto
        # con la descripción/observación del reporte al que pertenece
        # (máx 4 líneas). Un reporte con 4 fotos genera 2 slides.
        # ================================================================
        PHOTO_W = Cm(13.37)
        PHOTO_H = Cm(10.0)
        GAP_X = Cm(0.6)
        CAPTION_H = Cm(3.8)  # holgura para caption a 14pt (≈ 4 líneas)
        CAPTION_GAP = Cm(0.25)
        CAPTION_FONT_PT = 14

        def _pair_slide(photo_pair):
            """Emite una slide con hasta 2 fotos (foto + pie de texto).
            `photo_pair` es una lista de tuplas (b64_img|None, caption_str)."""
            slide = _clone_membrete()
            total_w = 2 * PHOTO_W + GAP_X
            x0 = (SW - total_w) // 2
            avail_top = TOP_MARGIN
            avail_h = SH - TOP_MARGIN - BOTTOM_MARGIN
            block_h = PHOTO_H + CAPTION_GAP + CAPTION_H
            y_photo = avail_top + (avail_h - block_h) // 2
            for idx, item in enumerate(photo_pair):
                if item is None:
                    continue
                b64_img, caption = item
                cx = x0 + idx * (PHOTO_W + GAP_X)
                if b64_img:
                    try:
                        raw = base64.b64decode(_strip_b64_prefix(b64_img))
                        slide.shapes.add_picture(
                            io.BytesIO(raw), cx, y_photo,
                            width=PHOTO_W, height=PHOTO_H,
                        )
                    except Exception:
                        pass
                # Pie de foto: descripción/observación del reporte
                caption_txt = (caption or "").strip() or "—"
                if len(caption_txt) > 320:
                    caption_txt = caption_txt[:317] + "…"
                add_text(
                    slide, cx, y_photo + PHOTO_H + CAPTION_GAP,
                    PHOTO_W, CAPTION_H,
                    caption_txt, size=CAPTION_FONT_PT, bold=False,
                    color=PHOTO_CAPTION_COLOR, align=PP_ALIGN.LEFT,
                )
            return slide

        any_data = False
        current_subtramo_id: Optional[str] = None
        # Ver nota equivalente en export_reports_pdf: buckets de Área que ya
        # recibieron su portadilla + resumen dentro de algún nodo.
        printed_area_buckets: set = set()
        for n in leaf_nodes:
            n_subtramo_id = _subtramo_id_for(n["id"], nodes_by_id)
            if current_subtramo_id is not None and n_subtramo_id != current_subtramo_id:
                _emit_subtramo_summary_slide(current_subtramo_id)
            current_subtramo_id = n_subtramo_id

            # Ver comentario equivalente en export_reports_pdf: `node_reps`
            # (severidad filtrada) SOLO alimenta fotos; `node_reps_all` (sin
            # filtro, mismo set que Fuerza de Trabajo) decide si el nodo
            # tiene algo que imprimir — antes se saltaba el nodo entero
            # cuando sus reportes eran todos "informativo", y sus
            # Actividades Generales curadas (que sí se ven en el hub) nunca
            # llegaban al PPTX.
            node_reps = reports_by_node.get(n["id"]) or []
            node_reps_all = workforce_reports_by_node.get(n["id"]) or []
            if not node_reps_all:
                continue
            _emit_frentes_sin_actividad(n_subtramo_id)
            any_data = True
            node_path = path_cache.get(n["id"]) or n.get("name", "")

            # SIN portadilla por nodo (a pedido del usuario, igual que en el PDF
            # desde 77b5000): el nodo ya no imprime su propia diapositiva de
            # título/imagen. La marca provisional del índice se completa con la
            # 1ª Área del nodo (abajo) y apunta a la primera diapositiva que
            # sigue, que es la portadilla de Área.
            _node_mark_i = len(_indice_marks)
            _indice_mark("area-pendiente", node_path)

            # === Sub-bucle por Área/Disciplina (bucket normalizado) ========
            # "Sub supervisores" → "OBRA CIVIL". Áreas con tildes/plurales
            # se colapsan al mismo bucket.
            def _bucket_key_for_report_slides(_r: dict) -> str:
                _aid_r = _r.get("area_id")
                if not _aid_r:
                    return "SIN ÁREA"
                return _normalize_area_name(
                    (areas_by_id.get(_aid_r) or {}).get("name"),
                    user_role=user.get("role"),
                    user_area=user.get("area"),
                )

            # Dos buckets paralelos, igual que en export_reports_pdf:
            # `reps_by_area` (narrativa, solo fotos) y `reps_by_area_all`
            # (decide qué Áreas existen y alimenta Actividades Generales).
            reps_by_area: dict = {}
            for r in node_reps:
                reps_by_area.setdefault(_bucket_key_for_report_slides(r), []).append(r)
            reps_by_area_all: dict = {}
            for r in node_reps_all:
                reps_by_area_all.setdefault(_bucket_key_for_report_slides(r), []).append(r)
            _sorted_area_ids = sorted(reps_by_area_all.keys(), key=lambda a: a.lower())
            for _area_i, bkey in enumerate(_sorted_area_ids):
                area_reps = reps_by_area.get(bkey) or []  # narrativa: puede venir vacía (sin fotos)
                area_reps_all = reps_by_area_all[bkey]
                area_name = bkey  # ya normalizado
                printed_area_buckets.add(area_name)
                _area_key, _area_title = f"area:{n['id']}:{area_name}", f"{node_path} · {area_name}"
                if _area_i == 0:
                    _indice_marks[_node_mark_i] = (_area_key, _area_title, _indice_marks[_node_mark_i][2])
                else:
                    _indice_mark(_area_key, _area_title)

                # --- Portadilla de Área (clon del fondo de la portada) ----
                # Título posicionado en la MISMA Y que "REPORTE X" en la
                # portada principal, para preservar consistencia visual.
                a_slide = _clone_cover_bg()
                _area_y = SH * 0.32  # equivalente a PH*0.32 en el PDF
                add_text(
                    a_slide, Cm(1.5), _area_y, SW - Cm(3.0), Cm(4.0),
                    area_name.upper(),
                    size=44, bold=True,
                    color=AREA_TEXT_COLOR, align=PP_ALIGN.CENTER,
                )

                # --- Resumen de Actividades Generales (curadas) del Área ---
                # Un bucket visual de Área puede colapsar varios area_id
                # (ver arriba) — se unen las actividades curadas de TODOS
                # los area_id presentes en este bucket, no solo uno.
                _area_ids_en_bucket = sorted({
                    _r.get("area_id") for _r in area_reps_all if _r.get("area_id")
                })
                _resumen_actividades = _actividades_resumen_para_bloque(
                    actividades_curadas_idx, n["id"], n_subtramo_id, _area_ids_en_bucket,
                )
                _emit_actividades_area_slides(area_name, node_path, _resumen_actividades)

                # --- Slides ejecutivas: 2 FOTOS por slide -----------------
                # TOPE ESTRICTO: cada reporte emite UNA sola slide con
                # máximo 2 fotos (las 2 primeras). Con captions individuales
                # por foto (`photo_captions[i]`), fallback a la observación
                # general si el caption individual está vacío.
                for _r in area_reps:
                    _indice_mark(f"rep:{_r.get('id')}", _indice_titulo_reporte(_r))
                    _all_imgs = _r.get("images") or []
                    _imgs = _all_imgs[:2]  # HARD-CAP: máximo 2 fotos
                    _general_obs = (
                        _r.get("observaciones") or _r.get("notes") or ""
                    ).strip() or (_r.get("incidencias") or "").strip() or "—"
                    _caps = _r.get("photo_captions") or []
                    def _cap_at(idx: int) -> str:
                        if idx < len(_caps):
                            _c = (_caps[idx] or "").strip()
                            if _c:
                                return _c
                        return _general_obs
                    if not _imgs:
                        # Reporte sin fotos → 1 slide con placeholder + obs.
                        _pair_slide([(None, _general_obs), None])
                        continue
                    _pair: list = []
                    for _i, _b64 in enumerate(_imgs):
                        _pair.append((_b64, _cap_at(_i)))
                    while len(_pair) < 2:
                        _pair.append(None)
                    _pair_slide(_pair)

        _emit_subtramo_summary_slide(current_subtramo_id)
        if any_data:
            _emit_frentes_sin_actividad(None)

        # === ÁREAS SIN REPORTES: ver nota equivalente en export_reports_pdf
        # — Actividades Generales curadas (hub) cuyo bucket de Área nunca
        # se imprimió arriba porque ningún reporte de campo cayó en esa
        # Área durante el período exportado. Se imprimen en una sección
        # final dedicada para que el hub y el PPTX nunca diverjan.
        _orphan_by_bucket: Dict[str, List[str]] = {}
        for _aid, _texts in (actividades_curadas_idx.get("general") or {}).items():
            if not _texts:
                continue
            _area = areas_by_id.get(_aid) or {}
            _bucket = _normalize_area_name(
                _area.get("name"), user_role=user.get("role"), user_area=user.get("area"),
            ) or "SIN ÁREA"
            if _bucket in printed_area_buckets:
                continue
            _dest = _orphan_by_bucket.setdefault(_bucket, [])
            for _t in _texts:
                if _t not in _dest:
                    _dest.append(_t)

        if _orphan_by_bucket:
            _indice_mark("orphan", "Actividades generales (áreas sin reportes)")
            _divider = _clone_membrete()
            add_text(
                _divider, Cm(1.0), SH / 2 - Cm(0.9), SW - Cm(2.0), Cm(1.2),
                "ACTIVIDADES GENERALES",
                size=24, bold=True, color=READABLE_BRAND_RGB, align=PP_ALIGN.CENTER,
            )
            add_text(
                _divider, Cm(1.0), SH / 2 + Cm(0.3), SW - Cm(2.0), Cm(1.0),
                "Áreas sin reportes de campo en el período exportado",
                size=13, italic=True, color=TEXT_MUTED, align=PP_ALIGN.CENTER,
            )

            for _bucket in sorted(_orphan_by_bucket.keys()):
                a_slide = _clone_cover_bg()
                _area_y = SH * 0.32
                add_text(
                    a_slide, Cm(1.5), _area_y, SW - Cm(3.0), Cm(4.0),
                    _bucket.upper(),
                    size=44, bold=True,
                    color=AREA_TEXT_COLOR, align=PP_ALIGN.CENTER,
                )
                _emit_actividades_area_slides(_bucket, "", _orphan_by_bucket[_bucket])

        # Slide(s) de cierre: RECUENTO GENERAL del período completo,
        # desglosado por Tramo y por puesto/descripción.
        _emit_recuento_general_slides()
        _emit_resumen_frentes_slides()

        # Sistema Multi-Proyecto Modular: Forestal y Arbolado / Seguridad e
        # Higiene, al final de todo — solo si están encendidos.
        _lidar_devolver_restantes(modulos_data, lidar_por_sub)
        _emit_modulos_closing_slides()

        # ==============================================================
        # TEXTOS DE PORTADA PRINCIPAL — se inyectan al FINAL para que las
        # clonaciones previas de `tpl_cover_slide` (portadillas de Área) no
        # arrastren estos textos como fondo residual.
        # ==============================================================
        if tpl_cover_slide is not None:
            _cx_left = Cm(1.5)
            _cy_top = Cm(6.0)
            _cw_full = SW - Cm(3.0)
            add_text(
                tpl_cover_slide, _cx_left, _cy_top, _cw_full, Cm(3.0),
                report_title, size=54, bold=True,
                color=COVER_TEXT_COLOR, align=PP_ALIGN.LEFT,
            )
            add_text(
                tpl_cover_slide, _cx_left, _cy_top + Cm(3.2), _cw_full, Cm(1.2),
                fechas_label, size=22, bold=True,
                color=COVER_TEXT_COLOR, align=PP_ALIGN.LEFT,
            )
            add_text(
                tpl_cover_slide, _cx_left, _cy_top + Cm(4.6), _cw_full, Cm(2.0),
                project_name, size=28, bold=True,
                color=COVER_TEXT_COLOR, align=PP_ALIGN.LEFT,
            )

        if not any_data:
            s2 = _clone_membrete()
            add_text(s2, Cm(1.5), SH / 2 - Cm(1.0), SW - Cm(3.0), Cm(2.0),
                     "Sin reportes en el período seleccionado.",
                     size=20, italic=True, color=TEXT_MUTED,
                     align=PP_ALIGN.CENTER)

        # Hoja final: tipo de reporte, periodo y superintendente de supervisión
        # (Datos de contrato > Supervisión). Sin nombre capturado no se imprime.
        if firma_cierre:
            _fs = _clone_membrete()
            _fw = SW - Cm(3.0)
            add_text(_fs, Cm(1.5), SH * 0.28, _fw, Cm(2.0), firma_cierre["titulo"],
                     size=44, bold=True, color=READABLE_BRAND_RGB, align=PP_ALIGN.CENTER)
            add_text(_fs, Cm(1.5), SH * 0.28 + Cm(2.3), _fw, Cm(1.2), firma_cierre["periodo"],
                     size=20, bold=True, color=WF_TEXT_RGB, align=PP_ALIGN.CENTER)
            add_text(_fs, Cm(1.5), SH * 0.28 + Cm(5.6), _fw, Cm(1.2), firma_cierre["nombre"],
                     size=24, bold=True, color=WF_TEXT_RGB, align=PP_ALIGN.CENTER)
            add_text(_fs, Cm(1.5), SH * 0.28 + Cm(6.9), _fw, Cm(1.0), firma_cierre["cargo"],
                     size=16, bold=True, color=WF_MUTED_RGB, align=PP_ALIGN.CENTER)

        # === [BLOQUE LEGACY PURGADO 2026-07-04] Layout viejo con tablas y 
        # 'Notas y noticias' eliminado tras refactor P0 → Layout Ejecutivo.


        # ================================================================
        # ÍNDICE EDITABLE + ORDEN DE SECCIONES (ver `_indice_plan`).
        #
        # También elimina la diapositiva de membrete original (índice 1)
        # para que no quede vacía en el PPTX final: borra la relación de la
        # Presentation-part y la purga del sldIdLst. Solo existe como
        # diapositiva aparte cuando la plantilla trae portada + membrete
        # (2+ slides); con plantilla de 1 slide o sin plantilla el índice 1
        # ya es contenido real y NO se borra.
        # ================================================================
        ROW_H = Cm(0.85)
        HEAD_H = Cm(2.0)
        IDX_MARGIN_X = Cm(2.0)
        idx_content_w = SW - 2 * IDX_MARGIN_X
        idx_num_w = Cm(2.0)
        usable_h = SH - TOP_MARGIN - BOTTOM_MARGIN
        idx_max_chars = max(10, int((idx_content_w - idx_num_w - Cm(0.4)) // Pt(14 * 0.52)))

        def _fill_index_slide(slide, chunk, is_first):
            y = TOP_MARGIN
            if is_first:
                add_text(slide, IDX_MARGIN_X, y, idx_content_w, Cm(1.1), indice_cfg["titulo"],
                         size=26, bold=True, color=READABLE_BRAND_RGB, align=PP_ALIGN.CENTER)
                add_text(slide, IDX_MARGIN_X, y + Cm(1.1), idx_content_w, Cm(0.7),
                         f"Reporte {indice_periodo} · {fechas_label}",
                         size=12, color=WF_MUTED_RGB, align=PP_ALIGN.CENTER)
                y += HEAD_H
            for text, page_no in chunk:
                text = _indice_truncate(text, lambda t: len(t) <= idx_max_chars)
                add_text(slide, IDX_MARGIN_X, y, idx_content_w - idx_num_w, ROW_H, text,
                         size=14, color=WF_TEXT_RGB)
                add_text(slide, IDX_MARGIN_X + idx_content_w - idx_num_w, y, idx_num_w, ROW_H,
                         str(page_no), size=14, bold=True, color=WF_TEXT_RGB, align=PP_ALIGN.RIGHT)
                _wf_rect(slide, IDX_MARGIN_X, y + ROW_H - Pt(0.75), idx_content_w, Pt(0.75),
                         fill_rgb=WF_BORDER_RGB)
                y += ROW_H

        try:
            _indice_estructura_out.extend(_pptx_apply_indice(
                prs, _indice_marks, indice_cfg,
                master_separate=(tpl_master_slide is not None and tpl_cover_slide is not None
                                 and tpl_master_slide is not tpl_cover_slide),
                clone_membrete=_clone_membrete, fill_index_slide=_fill_index_slide,
                first_cap=max(1, int((usable_h - HEAD_H) // ROW_H)),
                next_cap=max(1, int(usable_h // ROW_H)),
            ))
        except Exception as _e_idx:
            log.warning("[pptx] no se pudo aplicar el índice editable: %s", _e_idx)

        buf = io.BytesIO()
        prs.save(buf)
        return buf.getvalue()

    indice_periodo = _indice_periodo_key(period_type, period)
    indice_cfg = await _indice_load_config(pid, indice_periodo)
    _indice_estructura_out: List[dict] = []
    pptx_bytes = await asyncio.to_thread(_build_pptx_blocking)
    if _indice_estructura_out and user["role"] in (ROLE_COORD, ROLE_SUB) and not area_id and not scope_mine_only:
        await _indice_guardar_estructura(pid, indice_periodo, _indice_estructura_out)
    fname = _safe_export_filename(project_name, period, "pptx")
    return StreamingResponse(
        io.BytesIO(pptx_bytes),
        media_type="application/vnd.openxmlformats-officedocument.presentationml.presentation",
        headers={"Content-Disposition": f'attachment; filename="{fname}"'},
    )


# === DAILY GOALS (Metas del día por proyecto) ==============================
class DailyGoalIn(BaseModel):
    text: str


class DailyGoalPatch(BaseModel):
    text: Optional[str] = None
    is_completed: Optional[bool] = None


def _goal_out(doc: dict) -> dict:
    doc.pop("_id", None)
    return doc


@api.get("/projects/{pid}/daily_goals")
async def list_daily_goals(pid: str, user: dict = Depends(current_user)):
    await ensure_project_access(user, pid)
    cur = db.daily_goals.find({"project_id": pid}).sort("created_at", 1)
    out = []
    async for d in cur:
        out.append(_goal_out(d))
    return out


@api.post("/projects/{pid}/daily_goals")
async def create_daily_goal(pid: str, body: DailyGoalIn, user: dict = Depends(current_user)):
    if user["role"] not in (ROLE_COORD, ROLE_JEFE, ROLE_SUB):
        raise HTTPException(403, "Solo coord, jefe o sub-coordinador pueden crear metas")
    await ensure_project_access(user, pid)
    text = (body.text or "").strip()
    if not text:
        raise HTTPException(400, "El texto es obligatorio")
    gid = str(uuid.uuid4())
    doc = {
        "id": gid,
        "project_id": pid,
        "text": text,
        "is_completed": False,
        "created_at": datetime.now(timezone.utc),
        "created_by": user["id"],
        "created_by_name": user.get("name", ""),
    }
    await db.daily_goals.insert_one(doc)
    return _goal_out(doc)


@api.patch("/projects/{pid}/daily_goals/{gid}")
async def update_daily_goal(pid: str, gid: str, body: DailyGoalPatch, user: dict = Depends(current_user)):
    if user["role"] not in (ROLE_COORD, ROLE_JEFE, ROLE_SUB):
        raise HTTPException(403, "Solo coord, jefe o sub-coordinador pueden modificar metas")
    await ensure_project_access(user, pid)
    upd: dict = {}
    if body.text is not None:
        t = body.text.strip()
        if not t:
            raise HTTPException(400, "Texto inválido")
        upd["text"] = t
    if body.is_completed is not None:
        upd["is_completed"] = bool(body.is_completed)
    if upd:
        res = await db.daily_goals.update_one({"id": gid, "project_id": pid}, {"$set": upd})
        if res.matched_count == 0:
            raise HTTPException(404, "Meta no encontrada")
    out = await db.daily_goals.find_one({"id": gid, "project_id": pid})
    if not out:
        raise HTTPException(404, "Meta no encontrada")
    return _goal_out(out)


@api.delete("/projects/{pid}/daily_goals/{gid}")
async def delete_daily_goal(pid: str, gid: str, user: dict = Depends(current_user)):
    if user["role"] not in (ROLE_COORD, ROLE_JEFE, ROLE_SUB):
        raise HTTPException(403, "Solo coord, jefe o sub-coordinador pueden eliminar metas")
    await ensure_project_access(user, pid)
    res = await db.daily_goals.delete_one({"id": gid, "project_id": pid})
    if res.deleted_count == 0:
        raise HTTPException(404, "Meta no encontrada")
    return {"ok": True}


# === AI Summary (Resumen Ejecutivo con IA) ==================================
class AISummaryResponse(BaseModel):
    summary: str
    reports_count: int
    period_hours: int
    generated_at: datetime


# === A-11: entrada del Resumen con IA (pura, sin DB ni red) =================
RESUMEN_IA_MAX_AVANCES = 100
RESUMEN_IA_MAX_GASTOS = 50
RESUMEN_IA_MAX_EXCEPCIONES = 50

RESUMEN_IA_SIN_DATOS = (
    "• Avances: no disponible en los reportes (sin reportes en las últimas 24h).\n"
    "• Actividades: no disponible en los reportes.\n"
    "• Fuerza laboral: no disponible en los reportes.\n"
    "• Noticias: no hay noticias vigentes.\n"
    "• Excepciones y control de costos: sin excepciones ni gastos registrados."
)

