    cantidad: str
    precio_unitario: str
    meta: str
    periodicidad_meta: str
    activo: bool
    created_at: datetime
    # --- Calculados ---
    importe_contratado: str
    cantidad_ejecutada_acumulada: str = "0"
    # --- Etapa EVM (aditivo, None mientras el concepto no tenga datos EVM
