@api.post("/conceptos", response_model=ConceptoOut)
async def create_concepto(body: ConceptoIn, user: dict = Depends(require_role(ROLE_SUB, ROLE_COORD))):
    partida = await db.partidas.find_one({"id": body.partida_id})
    if not partida:
        raise HTTPException(404, "Partida no existe")
    project = await db.projects.find_one({"id": partida["project_id"]})
    _validar_unidad_para_proyecto(body.unidad, project or {})
    # C-05: la clave de un concepto es única en el proyecto (igual que en el importador).
    clave_nueva = body.clave.strip()
    if not clave_nueva or not body.descripcion.strip():
        raise HTTPException(400, "La clave y la descripción son obligatorias")
    if await db.conceptos.find_one({"project_id": partida["project_id"], "activo": True, "clave": clave_nueva}):
        c = nombres_nivel_proyecto(project)["concepto"]
        raise HTTPException(
            409, f"Ya existe {c['indefinido']} {c['minuscula']} con la clave '{clave_nueva}' en este proyecto",
        )
    # C-06: sin meta capturada, se calcula con la duración programada y la cadencia del
    # proyecto; sin programa (sin fechas) queda vacía.
    periodicidad_meta = body.periodicidad_meta or cadencia_de_proyecto(project)
    meta_inicial = body.meta or (
        meta_por_defecto(body.cantidad, body.fecha_inicio, body.fecha_fin, periodicidad_meta) or ""
    )
    cid = str(uuid.uuid4())
    doc = {
        "id": cid,
        "partida_id": body.partida_id,
        "project_id": partida["project_id"],
        "clave": body.clave.strip(),
        "descripcion": body.descripcion.strip(),
        "unidad": body.unidad,
        "cantidad": body.cantidad,
        "precio_unitario": body.precio_unitario,
        "meta": meta_inicial,
        "periodicidad_meta": periodicidad_meta,
        "activo": True,
        "created_at": datetime.now(timezone.utc),
        "created_by": user["id"],
        # Etapa EVM (aditivo) — casi siempre llegan vacíos aquí (el alta
        # manual de un concepto sigue siendo el flujo legado); se completan
        # después vía PATCH o el Importador Maestro (Tarea 2).
        "meta_cantidad": body.meta_cantidad,
        "importe_total_editable": body.importe_total_editable,
        "fecha_inicio": body.fecha_inicio,
        "fecha_fin": body.fecha_fin,
        # A-02: un concepto extraordinario nace con su P.U. pendiente de autorización.
        "extraordinario": bool(body.extraordinario),
        "pu_estatus": "pendiente_autorizacion" if body.extraordinario else None,
    }
    await db.conceptos.insert_one(doc)
    if body.extraordinario:
        await _log_bitacora(
            partida["project_id"], "concepto_extraordinario", "concepto", cid,
            "pu_estatus", None, "pendiente_autorizacion", user,
        )
    return await _concepto_out(doc)


@api.patch("/conceptos/{concepto_id}", response_model=ConceptoOut)
async def update_concepto(concepto_id: str, body: ConceptoPatch, user: dict = Depends(require_role(ROLE_SUB, ROLE_COORD))):
    concepto = await db.conceptos.find_one({"id": concepto_id})
    if not concepto:
        raise HTTPException(404, "Concepto no existe")
    upd: dict = {}
    if body.clave is not None:
        upd["clave"] = body.clave.strip()
    if body.descripcion is not None:
        upd["descripcion"] = body.descripcion.strip()
    if body.unidad is not None:
        project = await db.projects.find_one({"id": concepto["project_id"]})
        _validar_unidad_para_proyecto(body.unidad, project or {})
        upd["unidad"] = body.unidad
    if body.cantidad is not None:
        upd["cantidad"] = body.cantidad
    if body.periodicidad_meta is not None:
        upd["periodicidad_meta"] = body.periodicidad_meta
    if body.activo is not None:
        upd["activo"] = body.activo

    # PU y meta llevan bitácora explícita (valor anterior/nuevo/usuario/fecha)
    if body.precio_unitario is not None and body.precio_unitario != concepto["precio_unitario"]:
        await _log_bitacora(
            concepto["project_id"], "pu", "concepto", concepto_id,
            "precio_unitario", concepto["precio_unitario"], body.precio_unitario, user,
        )
        upd["precio_unitario"] = body.precio_unitario
    if body.meta is not None and body.meta != concepto.get("meta", ""):
        await _log_bitacora(
            concepto["project_id"], "meta", "concepto", concepto_id,
            "meta", concepto.get("meta", ""), body.meta, user,
        )
        upd["meta"] = body.meta

    # --- Etapa EVM (aditivo) --------------------------------------------
    # importe_total_editable lleva la MISMA bitácora que precio_unitario:
    # es lo que determina el precio_unitario_dinamico de aquí en adelante,
    # así que un cambio aquí es tan sensible como cambiar el PU a mano.
    if body.importe_total_editable is not None and body.importe_total_editable != concepto.get("importe_total_editable"):
        await _log_bitacora(
            concepto["project_id"], "pu", "concepto", concepto_id,
            "importe_total_editable", concepto.get("importe_total_editable"), body.importe_total_editable, user,
        )
        upd["importe_total_editable"] = body.importe_total_editable
    if body.meta_cantidad is not None and body.meta_cantidad != concepto.get("meta_cantidad"):
        if to_decimal(body.meta_cantidad) <= 0:
            raise HTTPException(400, "meta_cantidad debe ser mayor a 0 (se usa como divisor de precio_unitario)")
        await _log_bitacora(
            concepto["project_id"], "meta", "concepto", concepto_id,
            "meta_cantidad", concepto.get("meta_cantidad"), body.meta_cantidad, user,
        )
        upd["meta_cantidad"] = body.meta_cantidad
    # fecha_inicio/fecha_fin: la consistencia del rango se valida contra el
    # valor EFECTIVO (el que llega en este PATCH, o si no el ya guardado) —
    # un PATCH de un solo extremo no puede dejar el rango invertido en
    # silencio.
    if body.fecha_inicio is not None or body.fecha_fin is not None:
        nueva_inicio = body.fecha_inicio if body.fecha_inicio is not None else concepto.get("fecha_inicio")
        nueva_fin = body.fecha_fin if body.fecha_fin is not None else concepto.get("fecha_fin")
        if nueva_inicio and nueva_fin and date.fromisoformat(nueva_fin) < date.fromisoformat(nueva_inicio):
            raise HTTPException(400, "fecha_fin no puede ser anterior a fecha_inicio")
        if body.fecha_inicio is not None:
            upd["fecha_inicio"] = body.fecha_inicio
        if body.fecha_fin is not None:
            upd["fecha_fin"] = body.fecha_fin

    if upd:
        await db.conceptos.update_one({"id": concepto_id}, {"$set": upd})
    updated = await db.conceptos.find_one({"id": concepto_id})
    return await _concepto_out(updated)


@api.delete("/conceptos/{concepto_id}")
async def delete_concepto(concepto_id: str, user: dict = Depends(require_role(ROLE_SUB, ROLE_COORD))):
    """Borra un concepto — baja lógica (activo=false), sin bloquear aunque
    ya tenga avances registrados (preserva el historial, solo lo oculta del
    catálogo activo — a petición explícita del usuario, 2026-08-28)."""
    concepto = await db.conceptos.find_one({"id": concepto_id})
    if not concepto:
        raise HTTPException(404, "Concepto no existe")
    await db.conceptos.update_one({"id": concepto_id}, {"$set": {"activo": False}})
    return {"ok": True}


def filtrar_conceptos_busqueda(docs: list, q: Optional[str], limit: Optional[int] = None) -> list:
    """Filtra por subcadena (sin acentos ni mayúsculas) en clave o descripción y recorta a
    `limit`. Sin `q` devuelve todo (en el orden recibido). La búsqueda es por texto
    literal: "1.1." o "(a)" no son expresiones regulares y no rompen nada."""
    if q and q.strip():
        needle = _normalize_text(q)
        docs = [
            d for d in docs
            if needle in _normalize_text(d["clave"]) or needle in _normalize_text(d["descripcion"])
        ]
    if limit is not None:
        docs = docs[:limit]
    return docs


@api.get("/projects/{pid}/conceptos/search", response_model=List[dict])
async def search_conceptos(
    pid: str, q: Optional[str] = None, unidad: Optional[str] = None,
    limit: Optional[int] = Query(None, ge=1, le=500),
    user: dict = Depends(current_user),
):
    """Búsqueda global (atraviesa partidas) por clave o cualquier palabra de la
    descripción: parcial, sin distinguir acentos ni mayúsculas. Cada resultado
    indica a qué partida pertenece. Sin `q` lista los conceptos por clave; `limit`
    acota la lista (Registrar avance muestra los primeros por defecto)."""
    await ensure_project_access(user, pid)
    query: dict = {"project_id": pid, "activo": True}
    if unidad:
        query["unidad"] = unidad
    docs = await db.conceptos.find(query).to_list(length=100000)
    docs = filtrar_conceptos_busqueda(sort_by_clave(docs), q, limit)

    partida_ids = {d["partida_id"] for d in docs}
    partidas = await db.partidas.find({"id": {"$in": list(partida_ids)}}).to_list(length=10000)
    partida_by_id = {p["id"]: p for p in partidas}

    out = []
    for d in docs:
        concepto_out = await _concepto_out(d)
        p = partida_by_id.get(d["partida_id"])
        out.append({
            **concepto_out.model_dump(),
            "partida_clave": p["clave"] if p else None,
            "partida_nombre": p["nombre"] if p else None,
        })
    return out


@api.get("/conceptos/{concepto_id}/bitacora", response_model=List[BitacoraCambioOut])
async def concepto_bitacora(concepto_id: str, user: dict = Depends(current_user)):
    concepto = await db.conceptos.find_one({"id": concepto_id})
    if not concepto:
        raise HTTPException(404, "Concepto no existe")
    await ensure_project_access(user, concepto["project_id"])
    docs = await db.catalogo_bitacora.find({"entidad_tipo": "concepto", "entidad_id": concepto_id}).sort("fecha", -1).to_list(length=1000)
    return [BitacoraCambioOut(**d) for d in docs]


# === Importación desde Excel ===================================================
# Wizard de 4 pasos: (1) subir archivo → (2) elegir hoja + mapeo + partida
# destino + confirmar convención → (3) VALIDAR (todas las filas, una sola
# vez) → revisar vista previa paginada y corregir → (4) importar (commit).
#
# Los campos objetivo del mapeo y las palabras clave que usamos para proponer
# un mapeo automático a partir de los encabezados reales. "importe" es
# opcional: solo alimenta el chequeo informativo de 3.a, nunca se usa como
# fuente de verdad (el importe SIEMPRE se recalcula como cantidad × PU).
# === C-01 / C-03 Importador jerárquico ========================================
# La jerarquía se detecta por la CLAVE (1 -> 1.1 -> 1.1.1). Una fila sin cantidad ni
# P.U. es una PARTIDA (nodo del catálogo); una fila con cantidad y P.U. es un CONCEPTO
# que cuelga de la partida más cercana por prefijo de clave. La "partida destino" pasa
# a ser opcional: solo sirve para colgar el catálogo importado bajo un nodo existente.
# Los nombres de nivel salen de la configuración del proyecto, no de este código.
VALORES_MARCA_DEDUCTIVA = {"si", "s", "x", "1", "true", "verdadero", "yes", "y", "ded", "deductiva", "deductivo"}


def es_marca_deductiva(raw: Any) -> bool:
    """¿La celda de la columna "Deductiva" marca la fila como deductiva? (SI, X, 1, ...)"""
    if raw is None:
        return False
    if isinstance(raw, bool):
        return raw
    return _normalize_text(str(raw)) in VALORES_MARCA_DEDUCTIVA


def clave_a_texto(raw: Any) -> Optional[str]:
    """Clave de una celda como texto. Un número entero de Excel (1.0) vuelve a "1"."""
    if raw is None:
        return None
    if isinstance(raw, float) and raw.is_integer():
        return str(int(raw))
    t = str(raw).strip()
    return t or None


def ancestros_de_clave(clave: str) -> List[str]:
    """Prefijos de una clave, del más cercano al más lejano: "1.1.2" -> ["1.1", "1"]."""
    partes = (clave or "").split(".")
    return [".".join(partes[:i]) for i in range(len(partes) - 1, 0, -1)]


def profundidad_clave(clave: str) -> int:
    return (clave or "").count(".")


def padre_por_prefijo(clave: str, claves_partida: Any) -> Optional[str]:
    """Clave de la partida más cercana que es prefijo de `clave` (o None)."""
    for a in ancestros_de_clave(clave):
        if a in claves_partida:
            return a
    return None


def es_fila_partida(*valores: Any) -> bool:
    """Una fila es partida si TODAS las columnas numéricas del concepto vienen vacías."""
    return all(v is None or (isinstance(v, str) and not v.strip()) for v in valores)


def planificar_partidas(filas_partida: List[dict], existentes: Dict[str, str]) -> List[dict]:
    """Partidas que hay que CREAR (las de clave ya existente se reutilizan), de raíz a hoja,
    cada una con la clave de su padre (existente o creada en este mismo plan)."""
    conocidas = set(existentes) | {f["clave"] for f in filas_partida if f.get("clave")}
    ordenadas = sorted(enumerate(filas_partida), key=lambda t: (profundidad_clave(t[1]["clave"]), t[0]))
    nuevas: List[dict] = []
    vistas: set = set()
    for orden, f in ordenadas:
        c = f["clave"]
        if not c or c in existentes or c in vistas:
            continue
        vistas.add(c)
        nuevas.append({
            "clave": c, "nombre": (f.get("descripcion") or c), "orden": orden,
            "padre_clave": padre_por_prefijo(c, conocidas),
        })
    return nuevas


async def _crear_partidas_planificadas(
    partidas_col, pid: str, plan: List[dict], existentes: Dict[str, str], raiz_id: Optional[str],
    user: dict, registrar: Callable[..., Any],
) -> Dict[str, str]:
    """Crea las partidas del plan y devuelve el mapa clave -> id (existentes + creadas).
    `registrar` anota cada creación en el log de compensación ANTES de escribir."""
    mapa = dict(existentes)
    for pl in plan:
        padre_id = mapa.get(pl["padre_clave"]) if pl["padre_clave"] else raiz_id
        nuevo_id = str(uuid.uuid4())
        await registrar({"tipo": "partida_creada", "partida_id": nuevo_id, "valor_anterior": None})
        await partidas_col.insert_one({
            "id": nuevo_id, "project_id": pid, "clave": pl["clave"], "nombre": pl["nombre"],
            "orden": pl["orden"], "activo": True, "partida_padre_id": padre_id, "peso_manual": None,
            "created_at": datetime.now(timezone.utc), "created_by": user["id"],
        })
        mapa[pl["clave"]] = nuevo_id
    return mapa


async def _claves_partida_del_proyecto(pid: str) -> Dict[str, str]:
    return {p["clave"]: p["id"] async for p in db.partidas.find({"project_id": pid, "activo": True})}


_MAPPING_TARGETS = ["clave", "descripcion", "unidad", "cantidad", "precio_unitario", "importe", "deductiva"]
_MAPPING_KEYWORDS = {
    "clave": ["clave", "codigo", "código", "no.", "num", "item", "partida"],
    "descripcion": ["descripcion", "descripción", "concepto", "nombre", "actividad", "trabajo"],
    "unidad": ["unidad", "und", "um", "u.m.", "unidad de medida"],
    "cantidad": ["cantidad", "cant", "volumen", "vol"],
    "precio_unitario": ["precio unitario", "p.u.", "pu", "precio", "costo unitario", "costo"],
    "importe": ["importe", "total", "monto"],
    "deductiva": ["deductiva", "deductivo", "deduccion"],
}

# Umbral de tolerancia para el chequeo informativo "importe del archivo vs.
# cantidad × PU recalculado" — diferencias de redondeo de centavo no cuentan.
_TOLERANCIA_IMPORTE = Decimal("0.01")

# Orden de severidad para decidir el estado de una fila cuando aplican varios
# problemas a la vez (ver `_calcular_vista_filas`).
_TIPOS_ERROR = {"excel_error", "numero_ilegible", "numero_ambiguo", "campo_obligatorio_vacio", "cantidad_no_positiva", "sin_partida_destino", "clave_duplicada_sin_gemela_valida"}
_TIPOS_DUPLICADO = {"clave_duplicada_archivo", "clave_existente_proyecto"}
# C-07: unidad vacía y P.U. 0 avisan pero no bloquean. C-09: clave sin el prefijo de su partida padre.
_TIPOS_ADVERTENCIA = {"unidad_no_reconocida", "importe_no_coincide", "unidad_vacia", "precio_unitario_cero", "clave_sin_prefijo_padre"}


def _read_workbook_sheets(filename: str, content: bytes) -> dict:
    """Devuelve {sheet_name: [[celda,...], ...]} para .xlsx/.csv."""
    lower = filename.lower()
    if lower.endswith(".csv"):
        text = content.decode("utf-8-sig", errors="replace")
        rows = list(csv.reader(io.StringIO(text)))
        return {"CSV": rows}
    if lower.endswith(".xls"):
        raise HTTPException(
            400,
            "Formato .xls (Excel 97-2003) no soportado. Guarda el archivo como "
            ".xlsx o .csv desde Excel (Archivo > Guardar como) y vuelve a intentar.",
        )
    if not lower.endswith(".xlsx"):
        raise HTTPException(400, "Formato no soportado. Usa .xlsx o .csv")
    try:
        wb = openpyxl.load_workbook(io.BytesIO(content), data_only=True, read_only=True)
    except Exception as e:
        raise HTTPException(400, f"No se pudo leer el archivo: {e}")
    sheets = {}
    for name in wb.sheetnames:
        ws = wb[name]
        rows = [[cell for cell in row] for row in ws.iter_rows(values_only=True)]
        sheets[name] = rows
    return sheets


def _propose_mapping(headers: List[str]) -> dict:
    normalized = [_normalize_text(h) for h in headers]
    mapping: dict = {}
    used_idx: set = set()
    for target in _MAPPING_TARGETS:
        best_idx = None
        for idx, h in enumerate(normalized):
            if idx in used_idx or not h:
                continue
            if any(kw in h for kw in _MAPPING_KEYWORDS[target]):
                best_idx = idx
                break
        if best_idx is not None:
            mapping[target] = headers[best_idx]
            used_idx.add(best_idx)
    return mapping


def candidatos_numericos_de_hoja(rows: List[list], header_row_index: int, mapping: Any) -> List[object]:
    """C-13: celdas que pueden informar la convención decimal = las de las
    columnas numéricas mapeadas (cantidad, P.U., importe). Las claves ("1.1.1"),
    descripciones, fechas y demás columnas NO cuentan: un "1.1.1" tiene dos
    puntos pero es una clave, no un miles europeo, y antes votaba "coma decimal"
    para todo el archivo."""
    if not rows or header_row_index >= len(rows):
        return []
    headers = [str(c) if c is not None else "" for c in rows[header_row_index]]

    def _nombre(campo: str) -> Optional[str]:
        return mapping.get(campo) if isinstance(mapping, dict) else getattr(mapping, campo, None)

    indices = [
        headers.index(n) for n in (_nombre("cantidad"), _nombre("precio_unitario"), _nombre("importe"))
        if n and n in headers
    ]
    candidatos: List[object] = []
    for fila in rows[header_row_index + 1:]:
        for i in indices:
            if i < len(fila) and fila[i] is not None:
                candidatos.append(fila[i])
    return candidatos


def detectar_convencion_hoja(rows: List[list], header_row_index: int, mapping: Any) -> Optional[ConvencionDecimal]:
    return detectar_convencion(candidatos_numericos_de_hoja(rows, header_row_index, mapping))


def detectar_convencion_archivo(sheets: Dict[str, List[list]]) -> Optional[ConvencionDecimal]:
    """Convención propuesta al subir el archivo (todavía sin mapeo elegido): por hoja se
    toma la fila de encabezado y el mapeo propuestos y se mira solo lo numérico."""
    candidatos: List[object] = []
    for rows in sheets.values():
        if not rows:
            continue
        hdr = next((i for i, r in enumerate(rows[:15]) if _fila_parece_encabezado(r)), 0)
        headers = [str(c) if c is not None else "" for c in rows[hdr]]
        candidatos.extend(candidatos_numericos_de_hoja(rows, hdr, _propose_mapping(headers)))
    return detectar_convencion(candidatos)


def _validar_archivo_completo(
    rows: List[list],
    header_row_index: int,
    mapping: "ImportMappingIn",
    convencion: Optional[ConvencionDecimal],
    existing_by_clave: dict,
    unidades_personalizadas: Optional[List[str]] = None,
    partidas_existentes: Optional[Dict[str, str]] = None,
    niveles: Optional[dict] = None,
) -> List[dict]:
    """Procesa TODAS las filas de datos de la hoja UNA vez (3.a) — no una
    muestra. Cada fila queda con su interpretación (clave/descripción/
    unidad/cantidad/PU/importe) y la lista de `problemas` intrínsecos que
    encontró (celda de error de Excel, número ilegible/ambiguo, campo
    obligatorio vacío, unidad no reconocida, importe que no cuadra, clave ya
    existente en el proyecto). El resultado es inmutable una vez calculado:
    las correcciones del usuario NUNCA lo tocan, viven aparte como overlay
    (ver `_calcular_vista_filas`). No detecta claves duplicadas DENTRO del
    archivo aquí — eso depende de qué filas estén descartadas en cada
    momento, así que se recalcula dinámicamente en `_calcular_vista_filas`."""
    if len(rows) <= header_row_index:
        raise HTTPException(400, "header_row_index fuera de rango")
    nom_concepto = (niveles or nombres_nivel_proyecto(None))["concepto"]  # C-14: nombre y género configurados
    headers = [str(c) if c is not None else "" for c in rows[header_row_index]]
    data_rows = rows[header_row_index + 1:]

    def col(header_name: Optional[str]):
        if not header_name or header_name not in headers:
            return None
        return headers.index(header_name)

    idx = {
        "clave": col(mapping.clave), "descripcion": col(mapping.descripcion),
        "unidad": col(mapping.unidad), "cantidad": col(mapping.cantidad),
        "precio_unitario": col(mapping.precio_unitario), "importe": col(mapping.importe),
        "deductiva": col(getattr(mapping, "deductiva", None)),
    }
    if idx["clave"] is None or idx["descripcion"] is None or idx["cantidad"] is None or idx["precio_unitario"] is None:
        raise HTTPException(400, "El mapeo debe incluir al menos clave, descripción, cantidad y precio unitario")

    def celda(row: list, key: str):
        i = idx[key]
        if i is None or i >= len(row):
            return None
        return row[i]

    filas: List[dict] = []
    for i, row in enumerate(data_rows):
        clave_raw = celda(row, "clave")
        if clave_raw in (None, ""):
            continue  # fila vacía / de relleno, se ignora silenciosamente (igual que antes de Etapa 3)
        fila_num = header_row_index + 2 + i
        problemas: List[dict] = []

        clave = clave_a_texto(clave_raw)
        if not clave:
            problemas.append({"tipo": "campo_obligatorio_vacio", "campo": "clave", "motivo": "La clave está vacía"})

        descripcion_raw = celda(row, "descripcion")
        descripcion = (str(descripcion_raw).strip() if descripcion_raw is not None else "") or None
        if not descripcion:
            problemas.append({"tipo": "campo_obligatorio_vacio", "campo": "descripcion", "motivo": "La descripción está vacía"})

        # C-01: sin cantidad ni P.U. => es una PARTIDA (nodo del catálogo), no un concepto.
        if es_fila_partida(celda(row, "cantidad"), celda(row, "precio_unitario")):
            filas.append({
                "fila": fila_num, "tipo_fila": "partida", "clave": clave, "descripcion": descripcion,
                "unidad": None, "unidad_raw": None, "cantidad": None, "cantidad_raw": None,
                "precio_unitario": None, "precio_unitario_raw": None, "importe_archivo": None,
                "importe_calculado": None, "concepto_existente_id": None, "deductiva": False,
                "partida_existente_id": (partidas_existentes or {}).get(clave) if clave else None,
                "problemas": problemas,
            })
            continue

        unidad_raw = celda(row, "unidad")
        unidad, unidad_reconocida = _map_unidad_con_flag(
            str(unidad_raw) if unidad_raw is not None else None, unidades_personalizadas,
        )
        if idx["unidad"] is not None and not str(unidad_raw if unidad_raw is not None else "").strip():
            # C-07: unidad vacía -> se avisa (antes pasaba en silencio como UNIVERSAL).
            problemas.append({
                "tipo": "unidad_vacia", "campo": "unidad",
                "motivo": "La unidad está vacía; se usará UNIVERSAL si no se corrige",
            })
        elif not unidad_reconocida:
            problemas.append({
                "tipo": "unidad_no_reconocida", "campo": "unidad",
                "motivo": f"Unidad '{unidad_raw}' no reconocida; se usará UNIVERSAL si no se corrige",
            })

        def _parse_campo_numerico(raw_valor, nombre_campo: str) -> Optional[str]:
            try:
                return dec_to_str(_parse_celda_numerica(raw_valor, convencion))
            except CeldaErrorExcelError as e:
                problemas.append({"tipo": "excel_error", "campo": nombre_campo, "motivo": str(e)})
            except NumeroAmbiguoError as e:
                problemas.append({
                    "tipo": "numero_ambiguo", "campo": nombre_campo, "motivo": str(e),
                    "lectura_miles": dec_to_str(e.lectura_miles), "lectura_decimal": dec_to_str(e.lectura_decimal),
                })
            except ValueError as e:
                if raw_valor in (None, ""):
                    problemas.append({"tipo": "campo_obligatorio_vacio", "campo": nombre_campo, "motivo": f"El campo '{nombre_campo}' está vacío"})
                else:
                    problemas.append({"tipo": "numero_ilegible", "campo": nombre_campo, "motivo": str(e)})
            return None

        cantidad_raw = celda(row, "cantidad")
        cantidad = _parse_campo_numerico(cantidad_raw, "cantidad")
        pu_raw = celda(row, "precio_unitario")
        precio_unitario = _parse_campo_numerico(pu_raw, "precio_unitario")
        if precio_unitario is not None and to_decimal(precio_unitario) == 0:
            # C-07: un P.U. en 0 deja el importe del concepto en 0; se avisa sin bloquear.
            problemas.append({
                "tipo": "precio_unitario_cero", "campo": "precio_unitario",
                "motivo": f"El precio unitario es 0; el importe de {nom_concepto['demostrativo']} {nom_concepto['minuscula']} quedará en 0",
            })

        importe_archivo_raw = celda(row, "importe")
        importe_archivo = None
        if importe_archivo_raw not in (None, ""):
            try:
                importe_archivo = dec_to_str(_parse_celda_numerica(importe_archivo_raw, convencion))
            except Exception:
                importe_archivo = None  # el importe es solo informativo: si no parsea, se ignora sin bloquear

        importe_calculado = None
        if cantidad is not None and precio_unitario is not None:
            importe_calculado = dec_to_str(compute_importe(cantidad, precio_unitario))
            if importe_archivo is not None:
                diferencia = abs(to_decimal(importe_calculado) - to_decimal(importe_archivo))
                if diferencia > _TOLERANCIA_IMPORTE:
                    problemas.append({
                        "tipo": "importe_no_coincide", "campo": "importe",
                        "motivo": f"El importe del archivo ({importe_archivo}) difiere del recalculado ({importe_calculado}); se usará siempre el recalculado",
                    })

        concepto_existente_id = None
        if clave and clave in existing_by_clave:
            concepto_existente_id = existing_by_clave[clave]["id"]
            problemas.append({
                "tipo": "clave_existente_proyecto", "campo": None,
                "motivo": f"Ya existe {nom_concepto['indefinido']} {nom_concepto['minuscula']} con clave '{clave}' en este proyecto",
            })

        filas.append({
            "fila": fila_num,
            "tipo_fila": "concepto",
            "deductiva": es_marca_deductiva(celda(row, "deductiva")),
            "clave": clave,
            "descripcion": descripcion,
            "unidad": unidad,
            "unidad_raw": str(unidad_raw) if unidad_raw is not None else None,
            "cantidad": cantidad,
            "cantidad_raw": cantidad_raw,
            "precio_unitario": precio_unitario,
            "precio_unitario_raw": pu_raw,
            "importe_archivo": importe_archivo,
            "importe_calculado": importe_calculado,
            "concepto_existente_id": concepto_existente_id,
            "problemas": problemas,
        })

    return filas


def _calcular_vista_filas(validated_rows: List[dict], correcciones: dict, contexto: Optional[dict] = None) -> List[dict]:
    """Aplica el overlay de correcciones (disperso, por número de fila) sobre
    el resultado inmutable de `_validar_archivo_completo` y calcula el
    estado EFECTIVO de cada fila (ok | error | advertencia | duplicado |
    descartado). Se recalcula en cada lectura (preview, commit) — nunca se
    guarda un "estado" fijo en `validated_rows`, porque depende de
    correcciones y descartes que cambian entre lecturas."""
    # C-01: contexto de jerarquía. Sin contexto (pruebas, sesiones viejas) no se exige destino.
    contexto = contexto or {}
    tiene_destino = bool(contexto.get("tiene_destino", True))
    destino_clave = contexto.get("destino_clave")
    claves_partida = set(contexto.get("claves_partida_existentes") or [])
    for row in validated_rows:
        if row.get("tipo_fila") == "partida" and row.get("clave") and not (correcciones.get(str(row["fila"])) or {}).get("descartar"):
            claves_partida.add(row["clave"])

    # Pasada 1: problemas propios de cada fila (sin el chequeo de claves repetidas en el archivo).
    entradas: List[dict] = []
    for row in validated_rows:
        fila_key = str(row["fila"])
        correccion = correcciones.get(fila_key) or {}
        descartado = bool(correccion.get("descartar"))

        # Una corrección de cantidad/precio_unitario/unidad "resuelve" los
        # problemas intrínsecos de ESE campo (número ilegible/ambiguo,
        # unidad no reconocida). clave/descripción nunca son corregibles
        # (contrato aprobado) — sus problemas solo se resuelven descartando.
        campos_corregidos = {k for k in ("cantidad", "precio_unitario", "unidad") if correccion.get(k) is not None}
        problemas_activos = [p for p in row["problemas"] if p.get("campo") not in campos_corregidos]

        cantidad_efectiva = correccion.get("cantidad") or row["cantidad"]
        precio_unitario_efectivo = correccion.get("precio_unitario") or row["precio_unitario"]
        unidad_efectiva = correccion.get("unidad") or row["unidad"]

        if row.get("tipo_fila", "concepto") == "concepto" and not descartado:
            # C-03: cantidad <= 0 se rechaza, salvo que la fila lleve la marca deductiva.
            if cantidad_efectiva is not None and not row.get("deductiva"):
                try:
                    if to_decimal(cantidad_efectiva) <= 0:
                        problemas_activos = problemas_activos + [{
                            "tipo": "cantidad_no_positiva", "campo": "cantidad",
                            "motivo": "La cantidad debe ser mayor que cero (solo una fila deductiva puede ser cero o negativa)",
                        }]
                except (ValueError, TypeError, InvalidOperation):
                    pass
            # C-01: sin destino elegido, cada concepto necesita una partida ancestro por clave.
            padre = padre_por_prefijo(row["clave"], claves_partida) if row.get("clave") else None
            if not tiene_destino and row.get("clave") and padre is None:
                problemas_activos = problemas_activos + [{
                    "tipo": "sin_partida_destino", "campo": None,
                    "motivo": (
                        f"La clave '{row['clave']}' no tiene una partida padre en el archivo ni en el proyecto. "
                        "Incluye la fila de la partida o elige una partida destino."
                    ),
                }]
            # C-09: con partida destino, una clave jerárquica que no lleva el prefijo de su padre
            # (ej. "7.1" bajo la partida "3.3") se importa bajo el destino, pero se avisa.
            if tiene_destino and destino_clave and row.get("clave") and padre is None and profundidad_clave(row["clave"]) >= 1:
                problemas_activos = problemas_activos + [{
                    "tipo": "clave_sin_prefijo_padre", "campo": None,
                    "motivo": (
                        f"La clave '{row['clave']}' no empieza con la de su partida padre '{destino_clave}'; "
                        "se importará dentro de esa partida. Revisa que la clave sea la correcta."
                    ),
                }]

        entradas.append({
            "row": row, "correccion": correccion, "descartado": descartado, "problemas": problemas_activos,
            "cantidad": cantidad_efectiva, "pu": precio_unitario_efectivo, "unidad": unidad_efectiva,
        })

    # C-08: claves repetidas DENTRO del archivo (entre filas no descartadas). La primera fila
    # válida es la "gemela válida" y se conserva; las demás se omiten SOLO porque esa gemela
    # existe. Si ninguna fila con esa clave es válida no se omite nada en silencio: todas quedan
    # en error para que el usuario corrija una y descarte el resto.
    grupos: Dict[str, List[dict]] = {}
    for e in entradas:
        clave = e["row"].get("clave")
        if e["descartado"] or not clave:
            continue
        grupos.setdefault(clave, []).append(e)
    for clave, grupo in grupos.items():
        if len(grupo) < 2:
            continue
        validas = [e for e in grupo if not ({p["tipo"] for p in e["problemas"]} & _TIPOS_ERROR)]
        if validas:
            gemela = validas[0]
            for e in grupo:
                if e is gemela:
                    continue
                e["problemas"] = e["problemas"] + [{
                    "tipo": "clave_duplicada_archivo", "campo": None, "fila_gemela": gemela["row"]["fila"],
                    "motivo": (
                        f"La clave '{clave}' ya aparece en la fila {gemela['row']['fila']}, que es válida; "
                        "esta fila se omitirá"
                    ),
                }]
        else:
            for e in grupo:
                e["problemas"] = e["problemas"] + [{
                    "tipo": "clave_duplicada_sin_gemela_valida", "campo": None,
                    "motivo": (
                        f"La clave '{clave}' aparece {len(grupo)} veces y ninguna de esas filas es válida; "
                        "corrige una y descarta las demás"
                    ),
                }]

    vista: List[dict] = []
    for e in entradas:
        row = e["row"]
        problemas_activos = e["problemas"]
        if e["descartado"]:
            estado = "descartado"
        else:
            tipos_activos = {p["tipo"] for p in problemas_activos}
            if tipos_activos & _TIPOS_ERROR:
                estado = "error"
            elif tipos_activos & _TIPOS_DUPLICADO:
                estado = "duplicado"
            elif tipos_activos & _TIPOS_ADVERTENCIA:
                estado = "advertencia"
            else:
                estado = "ok"

        vista.append({
            **row,
            "cantidad_efectiva": e["cantidad"],
            "precio_unitario_efectivo": e["pu"],
            "unidad_efectiva": e["unidad"],
            "problemas_activos": problemas_activos,
            "correccion": e["correccion"] or None,
            "estado": estado,
        })
    return vista


def _resumen_de_vista(vista: List[dict]) -> dict:
    """Conteos del ARCHIVO COMPLETO (3.a) — se calcula sobre `vista` entera,
    nunca sobre la página que se vaya a devolver."""
    resumen = {"total": len(vista), "ok": 0, "advertencia": 0, "error": 0, "duplicado": 0, "descartado": 0}
    for row in vista:
        resumen[row["estado"]] = resumen.get(row["estado"], 0) + 1
    return resumen


@api.post("/projects/{pid}/conceptos/import/sheets")
async def import_upload_sheets(pid: str, file: UploadFile = File(...), user: dict = Depends(require_role(ROLE_SUB, ROLE_COORD))):
    """Paso 1: sube el archivo y devuelve las hojas disponibles.
    El archivo parseado se guarda temporalmente (Mongo, no disco local) para
    que los pasos siguientes no requieran volver a subirlo."""
    await ensure_project_access(user, pid)
    content = await file.read()
    if len(content) > 15 * 1024 * 1024:
        raise HTTPException(400, "Archivo demasiado grande (máx. 15MB)")
    sheets = _read_workbook_sheets(file.filename or "archivo.xlsx", content)

    # Detección de convención decimal (Etapa 2, diagnóstico 2.c): se hace
    # sobre TODAS las celdas de texto de TODAS las hojas (todavía no hay
    # mapeo de columnas elegido en este paso), buscando casos inequívocos.
    # Los números nativos (int/float) no aportan evidencia: no tienen
    # separador que desambiguar.
    convencion_detectada = detectar_convencion_archivo(sheets)

    import_id = str(uuid.uuid4())
    await db.catalogo_import_sessions.insert_one({
        "id": import_id,
        "project_id": pid,
        "user_id": user["id"],
        "filename": file.filename,
        "sheets": {name: rows for name, rows in sheets.items()},
        "convencion_decimal": convencion_detectada,
        "created_at": datetime.now(timezone.utc),
    })
    return {
        "import_id": import_id,
        "sheet_names": list(sheets.keys()),
        "requiere_seleccion_hoja": len(sheets) > 1,
        "convencion_detectada": convencion_detectada,
    }


@api.get("/projects/{pid}/conceptos/import/pendiente")
async def import_sesion_pendiente(pid: str, user: dict = Depends(require_role(ROLE_SUB, ROLE_COORD))):
    """Sesión de importación sin terminar más reciente DE ESTE USUARIO en
    este proyecto (si existe) — el modal la consulta al abrirse para
    ofrecer "Tienes una importación sin terminar de <archivo>. ¿Continuar o
    empezar de nuevo?". Se purga sola a las 24h por el índice TTL (ver
    startup_event en server.py); si expiró justo entre esta consulta y que
    el usuario elija "Continuar", las llamadas siguientes (headers/preview)
    devuelven 404 con el mismo "no existe o expiró" de siempre — el
    frontend lo muestra con claridad en vez de fallar en silencio."""
    await ensure_project_access(user, pid)
    session = await db.catalogo_import_sessions.find_one(
        {"project_id": pid, "user_id": user["id"]},
        sort=[("created_at", -1)],
    )
    if not session:
        return None
    return {
        "import_id": session["id"],
        "filename": session.get("filename"),
        "created_at": session["created_at"],
        "sheet_names": list(session.get("sheets", {}).keys()),
        "validado": session.get("validated_rows") is not None,
        "validated_sheet": session.get("validated_sheet"),
        "validated_header_row_index": session.get("validated_header_row_index"),
        "validated_mapping": session.get("validated_mapping"),
        "validated_partida_id": session.get("validated_partida_id"),
        "convencion_usada": session.get("convencion_usada") or session.get("convencion_decimal"),
    }


@api.delete("/projects/{pid}/conceptos/import/{import_id}")
async def import_descartar_sesion(pid: str, import_id: str, user: dict = Depends(require_role(ROLE_SUB, ROLE_COORD))):
    """"Empezar de nuevo": borra explícitamente una sesión de importación
    sin terminar, en vez de dejar que la encuentre el TTL 24h después.
    Idempotente: si ya no existe (el TTL ya la purgó, o ya se descartó),
    igual devuelve ok."""
    await ensure_project_access(user, pid)
    await db.catalogo_import_sessions.delete_one({"id": import_id, "project_id": pid})
    return {"ok": True}


def _fila_parece_encabezado(row: list) -> bool:
    """Heurística simple para proponer una fila de encabezado por defecto:
    la mayoría de las celdas no vacías son texto (no numéricas) — un
    encabezado real dice "Clave"/"Cantidad", una fila de logo/título suele
    tener 1-2 celdas con texto largo y el resto vacías."""
    no_vacias = [c for c in row if c not in (None, "")]
    if not no_vacias:
        return False
    textuales = [c for c in no_vacias if isinstance(c, str) and not re.fullmatch(r"[-+]?[0-9.,]+", c.strip())]
    return len(no_vacias) >= 3 and len(textuales) / len(no_vacias) >= 0.6


@api.get("/conceptos/import/{import_id}/headers")
async def import_headers(
    import_id: str,
    sheet: Optional[str] = None,
    header_row_index: Optional[int] = None,
    user: dict = Depends(require_role(ROLE_SUB, ROLE_COORD)),
):
    """Paso 2 (lectura ligera, sin validar): encabezados detectados de la
    hoja elegida + mapeo propuesto + una muestra de filas para que el
    usuario arme el mapeo antes de disparar la validación completa.

    `header_row_index` es OPCIONAL: si el archivo trae filas de logo/título
    antes del encabezado real (caso común en catálogos con membrete), el
    cliente puede pedir explícitamente cuál fila usar. Si no se manda, se
    propone una automáticamente con `_fila_parece_encabezado` (y de todos
    modos se devuelven las primeras filas crudas en `preview_rows` para que
    el usuario pueda corregir la propuesta con un toque, sin adivinar)."""
    session = await db.catalogo_import_sessions.find_one({"id": import_id})
    if not session:
        raise HTTPException(404, "Sesión de importación no existe o expiró")
    await ensure_project_access(user, session["project_id"])
    sheet_name = sheet or next(iter(session["sheets"].keys()))
    if sheet_name not in session["sheets"]:
        raise HTTPException(400, f"La hoja '{sheet_name}' no existe en este archivo")
    rows = session["sheets"][sheet_name]
    if not rows:
        raise HTTPException(400, "La hoja está vacía")

    if header_row_index is None:
        header_row_index = next((i for i, r in enumerate(rows[:15]) if _fila_parece_encabezado(r)), 0)
    if header_row_index >= len(rows):
        raise HTTPException(400, "header_row_index fuera de rango")

    headers = [str(c) if c is not None else "" for c in rows[header_row_index]]
    sample_rows = rows[header_row_index + 1: header_row_index + 6]
    return {
        "sheet": sheet_name,
        "header_row_index": header_row_index,
        "headers": headers,
        "suggested_mapping": _propose_mapping(headers),
        "sample_rows": sample_rows,
        "total_rows": max(len(rows) - header_row_index - 1, 0),
        "convencion_detectada": (
            detectar_convencion_hoja(rows, header_row_index, _propose_mapping(headers))
            or session.get("convencion_decimal")
        ),
        # Primeras filas TAL CUAL vienen en el archivo (sin importar cuál se
        # está usando como encabezado ahora) — para que el usuario elija.
        "preview_rows": rows[: min(len(rows), 15)],
    }


@api.post("/projects/{pid}/conceptos/import/{import_id}/validate")
async def import_validate(pid: str, import_id: str, body: ImportValidateIn, user: dict = Depends(require_role(ROLE_SUB, ROLE_COORD))):
    """Paso 3: valida TODAS las filas del archivo una sola vez (3.a) y
    guarda el resultado en la sesión de staging — la vista previa
    (import_preview) solo lee ese resultado ya calculado, paginado.

    Volver a llamar este endpoint (cambiar la convención decimal en el paso
    de confirmación, o "aplicar esta interpretación a todas las filas
    ambiguas" desde la vista previa) recalcula `validated_rows` desde cero,
    pero NUNCA toca `correcciones`: el overlay del usuario sigue aplicando
    sobre el resultado nuevo."""
    await ensure_project_access(user, pid)
    project = await db.projects.find_one({"id": pid})
    if body.partida_id:
        partida = await db.partidas.find_one({"id": body.partida_id, "project_id": pid})
        if not partida:
            raise HTTPException(404, "Partida no existe en este proyecto")
    session = await db.catalogo_import_sessions.find_one({"id": import_id, "project_id": pid})
    if not session:
        raise HTTPException(404, "Sesión de importación no existe o expiró")
    if body.sheet not in session["sheets"]:
        raise HTTPException(400, f"La hoja '{body.sheet}' no existe en este archivo")

    convencion: Optional[ConvencionDecimal] = (
        body.convencion
        or detectar_convencion_hoja(session["sheets"][body.sheet], body.header_row_index, body.mapping)
        or session.get("convencion_decimal")
    )

    # Consulta única de duplicados (Respuesta 2, aprobada): se trae UNA vez
    # todo el catálogo activo de la partida destino y se compara en
    # memoria — nada de una consulta por fila. A la escala esperada
    # (decenas a unos cientos de conceptos) esto es trivial.
    # C-01: los duplicados se buscan en TODO el proyecto (los conceptos ya no van todos a una
    # sola partida destino).
    existing = await db.conceptos.find({"project_id": pid, "activo": True}).to_list(length=100000)
    existing_by_clave = {c["clave"]: c for c in existing}

    partidas_proyecto = await _claves_partida_del_proyecto(pid)
    filas = _validar_archivo_completo(
        session["sheets"][body.sheet], body.header_row_index, body.mapping, convencion, existing_by_clave,
        unidades_personalizadas=(project or {}).get("unidades_personalizadas") or [],
        partidas_existentes=partidas_proyecto,
        niveles=nombres_nivel_proyecto(project),
    )
    contexto = {
        "tiene_destino": bool(body.partida_id),
        "destino_clave": partida["clave"] if body.partida_id else None,
        "claves_partida_existentes": sorted(partidas_proyecto),
    }

    update_fields = {
        "validated_rows": filas,
        "validated_sheet": body.sheet,
        "validated_header_row_index": body.header_row_index,
        "validated_mapping": body.mapping.model_dump(),
        "validated_partida_id": body.partida_id,
        "validated_contexto": contexto,
        "convencion_usada": convencion,
        "validated_at": datetime.now(timezone.utc),
    }
    if "correcciones" not in session:
        update_fields["correcciones"] = {}
        update_fields["duplicados_accion"] = "omitir"
    await db.catalogo_import_sessions.update_one({"id": import_id}, {"$set": update_fields})

    vista = _calcular_vista_filas(filas, session.get("correcciones") or {}, contexto=contexto)
    return {"resumen": _resumen_de_vista(vista), "convencion_usada": convencion}


@api.get("/conceptos/import/{import_id}/preview")
async def import_preview(import_id: str, page: int = 1, page_size: int = 50, user: dict = Depends(require_role(ROLE_SUB, ROLE_COORD))):
    """Lectura PAGINADA del resultado ya validado — no procesa nada aquí.
    El resumen de conteos es siempre del archivo completo (3.a), aunque
    `filas` solo traiga la página pedida."""
    session = await db.catalogo_import_sessions.find_one({"id": import_id})
    if not session:
        raise HTTPException(404, "Sesión de importación no existe o expiró")
    await ensure_project_access(user, session["project_id"])
    validated_rows = session.get("validated_rows")
    if validated_rows is None:
        raise HTTPException(400, "Todavía no se valida esta importación. Llama primero a /validate.")

    correcciones = session.get("correcciones") or {}
    vista = _calcular_vista_filas(validated_rows, correcciones, contexto=session.get("validated_contexto"))
    resumen = _resumen_de_vista(vista)

    page = max(page, 1)
    page_size = max(1, min(page_size, 200))
    start = (page - 1) * page_size
    pagina = vista[start:start + page_size]
    total_pages = max(1, (len(vista) + page_size - 1) // page_size)

    return {
        "resumen": resumen,
        "filas": pagina,
        "page": page,
        "page_size": page_size,
        "total_pages": total_pages,
        "total_rows": len(vista),
        "sheet": session.get("validated_sheet"),
        "partida_id": session.get("validated_partida_id"),
        "convencion_usada": session.get("convencion_usada"),
        "duplicados_accion": session.get("duplicados_accion", "omitir"),
    }


@api.put("/conceptos/import/{import_id}/rows/{fila}")
async def import_correct_row(import_id: str, fila: int, body: RowCorrectionIn, user: dict = Depends(require_role(ROLE_SUB, ROLE_COORD))):
    """3.b — corrección en línea de una fila con problema (o descartarla).
    Las correcciones de número ambiguo también pasan por aquí: el frontend
    ofrece las DOS lecturas ya calculadas (`problemas_activos[].lectura_*`)
    y el usuario elige una — nunca teclea el número de nuevo."""
    session = await db.catalogo_import_sessions.find_one({"id": import_id})
    if not session:
        raise HTTPException(404, "Sesión de importación no existe o expiró")
    await ensure_project_access(user, session["project_id"])
    validated_rows = session.get("validated_rows") or []
    if not any(r["fila"] == fila for r in validated_rows):
        raise HTTPException(404, f"Fila {fila} no existe en esta validación")

    entry: dict = {}
    if body.cantidad is not None:
        try:
            entry["cantidad"] = dec_to_str(to_decimal(body.cantidad))
        except Exception:
            raise HTTPException(400, "cantidad inválida")
    if body.precio_unitario is not None:
        try:
            entry["precio_unitario"] = dec_to_str(to_decimal(body.precio_unitario))
        except Exception:
            raise HTTPException(400, "precio_unitario inválido")
    if body.unidad is not None:
        proyecto_sesion = await db.projects.find_one({"id": session["project_id"]})
        _validar_unidad_para_proyecto(body.unidad, proyecto_sesion or {})
        entry["unidad"] = body.unidad
    if body.descartar:
        entry["descartar"] = True

    correcciones = session.get("correcciones") or {}
    if entry:
        correcciones[str(fila)] = entry
    else:
        correcciones.pop(str(fila), None)  # cuerpo vacío = revertir la fila a su valor original
    await db.catalogo_import_sessions.update_one({"id": import_id}, {"$set": {"correcciones": correcciones}})

    vista = _calcular_vista_filas(validated_rows, correcciones, contexto=session.get("validated_contexto"))
    fila_actualizada = next(r for r in vista if r["fila"] == fila)
    return {"fila": fila_actualizada, "resumen": _resumen_de_vista(vista)}


@api.delete("/conceptos/import/{import_id}/rows/{fila}")
async def import_revert_row(import_id: str, fila: int, user: dict = Depends(require_role(ROLE_SUB, ROLE_COORD))):
    """Revierte una fila a su valor original de `validated_rows` (borra su
    entrada del overlay de correcciones). Si el usuario se equivocó al
    corregir, este es el camino de vuelta."""
    session = await db.catalogo_import_sessions.find_one({"id": import_id})
    if not session:
        raise HTTPException(404, "Sesión de importación no existe o expiró")
    await ensure_project_access(user, session["project_id"])
    validated_rows = session.get("validated_rows") or []
    correcciones = session.get("correcciones") or {}
    correcciones.pop(str(fila), None)
    await db.catalogo_import_sessions.update_one({"id": import_id}, {"$set": {"correcciones": correcciones}})

    vista = _calcular_vista_filas(validated_rows, correcciones, contexto=session.get("validated_contexto"))
    fila_actualizada = next((r for r in vista if r["fila"] == fila), None)
    if fila_actualizada is None:
        raise HTTPException(404, f"Fila {fila} no existe en esta validación")
    return {"fila": fila_actualizada, "resumen": _resumen_de_vista(vista)}


@api.put("/conceptos/import/{import_id}/duplicados-accion")
async def import_set_duplicados_accion(import_id: str, body: DuplicadosAccionIn, user: dict = Depends(require_role(ROLE_SUB, ROLE_COORD))):
    """Opción por archivo (no por fila): qué hacer con claves que YA EXISTEN
    en el proyecto — "omitir" (no tocar lo existente) o "actualizar
    existentes" (upsert). Nunca duplica en silencio. No aplica a claves
    duplicadas DENTRO del mismo archivo — esas siempre requieren descarte
    manual porque no hay forma de saber cuál de las filas es la buena."""
    session = await db.catalogo_import_sessions.find_one({"id": import_id})
    if not session:
        raise HTTPException(404, "Sesión de importación no existe o expiró")
    await ensure_project_access(user, session["project_id"])
    await db.catalogo_import_sessions.update_one({"id": import_id}, {"$set": {"duplicados_accion": body.accion}})
    return {"duplicados_accion": body.accion}


async def _ejecutar_commit_con_compensacion(
    conceptos_col,
    sessions_col,
    log_bitacora: Callable[..., Any],
    pid: str,
    import_id: str,
    partida_id: Optional[str],
    vista: List[dict],
    duplicados_accion: str,
    user: dict,
    filename: Optional[str],
    partidas_col=None,
    cadencia: str = "MENSUAL",
) -> dict:
    """Núcleo del commit, separado de la ruta HTTP para poder probarlo con
    colecciones falsas (ver tests/test_import_commit_compensacion.py) sin
    depender de un Mongo real.

    LIMITACIÓN DOCUMENTADA (Respuesta 1 del diagnóstico): no se pudo
    determinar con certeza si el Mongo de producción de este proyecto corre
    en replica set — requisito de `session.start_transaction()` de Mongo, y
    no hay cadena de conexión de producción versionada en este repo. Por
    eso este commit usa COMPENSACIÓN MANUAL en vez de una transacción real:

      1. Antes de escribir CADA fila, se registra en
         `catalogo_import_sessions.compensacion_log` qué se está a punto de
         hacer (crear un id nuevo, o el valor ANTERIOR completo si se va a
         actualizar un concepto existente). El registro se persiste ANTES
         que la escritura real en `conceptos`.
      2. Si algo truena a mitad del loop, se recorre `compensacion_log` en
         reversa: los "creados" se borran, los "actualizados" recuperan su
         `valor_anterior`.

    El orden (registrar ANTES de escribir) es intencional: si el proceso
    muere entre el paso 1 y el paso 2, lo peor que pasa es "restaurar" algo
    que nunca se llegó a modificar — inocuo. Si fuera al revés (escribir y
    luego registrar), un crash justo ahí dejaría un cambio real sin ninguna
    forma de revertirlo.

    Esto NO es atomicidad real de Mongo: sigue habiendo una ventana angosta
    entre "registrar la compensación" y "ejecutar el write real" en la que,
    si el PROCESO ENTERO muere (no solo una excepción dentro de este
    request), ninguna compensación corre. Cuando se confirme que el Mongo de
    producción es replica set, esto debe reemplazarse por:

        async with await client.start_session() as s:
            async with s.start_transaction():
                ...  # los mismos writes, sin compensacion_log

    Importar NUNCA borra conceptos ni registros de avance existentes — como
    mucho, actualiza campos de un concepto ya existente (y siempre con su
    valor anterior guardado para poder revertir)."""
    import_batch_id = str(uuid.uuid4())
    creados, actualizados, omitidos = 0, 0, 0
    partidas_creadas, sin_partida = 0, 0
    log_local: List[dict] = []

    async def _registrar(entry: dict) -> None:
        log_local.append(entry)
        await sessions_col.update_one({"id": import_id}, {"$push": {"compensacion_log": entry}})

    async def _compensar() -> None:
        for entry in reversed(log_local):
            try:
                if entry["tipo"] == "creado":
                    await conceptos_col.delete_one({"id": entry["concepto_id"]})
                elif entry["tipo"] == "partida_creada":
                    await partidas_col.delete_one({"id": entry["partida_id"]})
                else:
                    await conceptos_col.update_one({"id": entry["concepto_id"]}, {"$set": entry["valor_anterior"]})
            except Exception as comp_err:
                log.error("[import_commit] fallo compensando %s: %s", entry, comp_err)

    try:
        # C-01: primero las PARTIDAS del archivo (filas sin cantidad ni P.U.), de raíz a hoja.
        mapa_partidas: Dict[str, str] = {}
        if partidas_col is not None:
            async for pdoc in partidas_col.find({"project_id": pid, "activo": True}):
                mapa_partidas[pdoc["clave"]] = pdoc["id"]
            filas_partida = [
                r for r in vista
                if r.get("tipo_fila") == "partida" and r["estado"] in ("ok", "advertencia") and r.get("clave")
            ]
            plan = planificar_partidas(filas_partida, mapa_partidas)
            n_antes = len(mapa_partidas)
            mapa_partidas = await _crear_partidas_planificadas(partidas_col, pid, plan, mapa_partidas, partida_id, user, _registrar)
            partidas_creadas = len(mapa_partidas) - n_antes
            for pl in plan:
                await log_bitacora(pid, "import", "partida", mapa_partidas[pl["clave"]], None, None, f"creada desde importación ({filename})", user)

        for row in vista:
            estado = row["estado"]
            if row.get("tipo_fila") == "partida":
                continue  # ya se procesó arriba
            if estado in ("error", "descartado"):
                continue
            if estado == "duplicado":
                tipos = {p["tipo"] for p in row["problemas_activos"]}
                if "clave_duplicada_archivo" in tipos:
                    # Ambiguo entre filas del propio archivo: nunca se
                    # autoresuelve, sin importar duplicados_accion.
                    omitidos += 1
                    continue
                if duplicados_accion == "omitir":
                    omitidos += 1
                    continue
                # duplicados_accion == "actualizar" y es solo
                # clave_existente_proyecto -> sigue como actualización abajo.

            clave = row["clave"]
            descripcion = row["descripcion"]
            unidad = row["unidad_efectiva"]
            cantidad = row["cantidad_efectiva"]
            precio_unitario = row["precio_unitario_efectivo"]

            existing_id = row.get("concepto_existente_id")
            existing_doc = None
            if existing_id:
                existing_doc = await conceptos_col.find_one({"id": existing_id})
                if not existing_doc:
                    existing_id = None  # se borró entre la validación y el commit: tratar como nuevo

            if existing_id and existing_doc:
                valor_anterior = {
                    "descripcion": existing_doc["descripcion"], "unidad": existing_doc["unidad"],
                    "precio_unitario": existing_doc["precio_unitario"], "cantidad": existing_doc["cantidad"],
                }
                entry = {"tipo": "actualizado", "concepto_id": existing_id, "valor_anterior": valor_anterior}
                log_local.append(entry)
                # Se registra la compensación ANTES del write real (ver docstring).
                await sessions_col.update_one({"id": import_id}, {"$push": {"compensacion_log": entry}})

                if existing_doc["precio_unitario"] != precio_unitario:
                    await log_bitacora(pid, "import", "concepto", existing_id, "precio_unitario", existing_doc["precio_unitario"], precio_unitario, user)
                if existing_doc["cantidad"] != cantidad:
                    await log_bitacora(pid, "import", "concepto", existing_id, "cantidad", existing_doc["cantidad"], cantidad, user)
                # La meta NUNCA se toca al actualizar (no se importa desde el
                # archivo) — si el concepto ya existía, conserva la meta que
                # ya tenía configurada.
                await conceptos_col.update_one(
                    {"id": existing_id},
                    {"$set": {
                        "descripcion": descripcion, "unidad": unidad,
                        "precio_unitario": precio_unitario, "cantidad": cantidad,
                        "import_batch_id": import_batch_id,
                    }},
                )
                actualizados += 1
            else:
                # C-01: el concepto cuelga de la partida más cercana por prefijo de su clave;
                # si no hay, de la partida destino (si se eligió).
                padre_clave = padre_por_prefijo(clave, mapa_partidas) if clave else None
                partida_destino = mapa_partidas[padre_clave] if padre_clave else partida_id
                if not partida_destino:
                    sin_partida += 1
                    continue
                cid = str(uuid.uuid4())
                entry = {"tipo": "creado", "concepto_id": cid, "valor_anterior": None}
                log_local.append(entry)
                await sessions_col.update_one({"id": import_id}, {"$push": {"compensacion_log": entry}})

                await conceptos_col.insert_one({
                    "id": cid, "partida_id": partida_destino, "project_id": pid,
                    "deductiva": bool(row.get("deductiva")),
                    "clave": clave, "descripcion": descripcion, "unidad": unidad,
                    "cantidad": cantidad, "precio_unitario": precio_unitario,
                    # C-06: este importador no trae fechas, así que no hay programa
                    # del que calcular un ritmo: la meta nace VACÍA (ya no es "toda
                    # la cantidad por semana") y se completa al programar el
                    # concepto. La periodicidad es la cadencia del proyecto.
                    "meta": "", "periodicidad_meta": cadencia, "activo": True,
                    "created_at": datetime.now(timezone.utc), "created_by": user["id"],
                    "import_batch_id": import_batch_id,
                })
                await log_bitacora(pid, "import", "concepto", cid, None, None, f"creado desde importación ({filename})", user)
                creados += 1
    except Exception as e:
        log.error("[import_commit] fallo a mitad del commit, compensando %d escrituras: %s", len(log_local), e)
        await _compensar()
        raise HTTPException(500, f"La importación falló a mitad de camino y se revirtió automáticamente (no se guardó nada): {e}")

    con_error = sum(1 for r in vista if r["estado"] == "error")
    descartados = sum(1 for r in vista if r["estado"] == "descartado")
    return {
        "creados": creados, "actualizados": actualizados, "omitidos": omitidos,
        "con_error": con_error, "descartados": descartados, "import_batch_id": import_batch_id,
        "partidas_creadas": partidas_creadas, "sin_partida": sin_partida,
    }


@api.post("/projects/{pid}/conceptos/import/{import_id}/commit")
async def import_commit(pid: str, import_id: str, user: dict = Depends(require_role(ROLE_SUB, ROLE_COORD))):
    """Paso 4: aplica el resultado ya validado (import_validate) + las
    correcciones del usuario. No recibe body — todo lo necesario ya quedó
    confirmado en la sesión de staging en los pasos anteriores."""
    proyecto_import = await ensure_project_access(user, pid)
    session = await db.catalogo_import_sessions.find_one({"id": import_id, "project_id": pid})
    if not session:
        raise HTTPException(404, "Sesión de importación no existe o expiró")
    validated_rows = session.get("validated_rows")
    if validated_rows is None:
        raise HTTPException(400, "Todavía no se valida esta importación. Llama primero a /validate.")
    partida_id = session.get("validated_partida_id")
    if partida_id:
        partida = await db.partidas.find_one({"id": partida_id, "project_id": pid})
        if not partida:
            raise HTTPException(404, "La partida validada ya no existe en este proyecto")

    correcciones = session.get("correcciones") or {}
    duplicados_accion = session.get("duplicados_accion", "omitir")
    vista = _calcular_vista_filas(validated_rows, correcciones, contexto=session.get("validated_contexto"))

    try:
        resultado = await _ejecutar_commit_con_compensacion(
            db.conceptos, db.catalogo_import_sessions, _log_bitacora,
            pid, import_id, partida_id, vista, duplicados_accion, user, session.get("filename"),
            partidas_col=db.partidas, cadencia=cadencia_de_proyecto(proyecto_import),
        )
    finally:
        # 3.d: SIEMPRE se limpia la sesión de staging al terminar el commit,
        # tanto en éxito como en falla-ya-compensada — no hay razón para
        # conservarla (si falló, la base ya quedó como estaba; el usuario
        # tendría que volver a subir/validar de todas formas).
        await db.catalogo_import_sessions.delete_one({"id": import_id})

    return resultado


# === Importador Maestro de Control de Obra (Etapa EVM) =======================
# Fusiona lo que antes eran dos wizards (Catálogo + Programa) en uno solo:
# un archivo, un mapeo (Clave/Descripción/Meta/Importe/Inicio/Fin), un commit.
# Vive en endpoints y colección de staging PROPIOS (evm_import_sessions,
# prefijo /conceptos/import_evm/...) en vez de reemplazar los del catálogo
# legado — así el wizard que hoy usan los coordinadores sigue funcionando
# mientras el catálogo migra concepto por concepto a los campos EVM (ver
# _concepto_tiene_datos_evm). Reutiliza toda la infraestructura de parseo ya
# probada (_read_workbook_sheets, detectar_convencion, _parse_celda_numerica,
# _fecha_excel_a_iso, _fila_parece_encabezado, _log_bitacora,
# _resumen_de_vista) — solo el mapeo de columnas y el commit son nuevos.

_MAPPING_TARGETS_EVM = ["clave", "descripcion", "meta", "importe", "inicio", "fin"]
_MAPPING_KEYWORDS_EVM = {
    "clave": ["clave", "codigo", "código", "no.", "num", "item", "partida"],
    "descripcion": ["descripcion", "descripción", "concepto", "nombre", "actividad", "trabajo"],
    "meta": ["meta", "cantidad", "cant", "volumen", "vol"],
    "importe": ["importe", "total", "monto", "importe contratado"],
    "inicio": ["inicio", "fecha inicio", "f. inicio", "start"],
    "fin": ["fin", "fecha fin", "f. fin", "termino", "término", "end"],
}

_TIPOS_ERROR_EVM = {"excel_error", "numero_ilegible", "numero_ambiguo", "campo_obligatorio_vacio", "fecha_ilegible", "rango_fecha_invalido", "sin_partida_destino"}
_TIPOS_DUPLICADO_EVM = {"clave_duplicada_archivo", "clave_existente_proyecto"}


@api.get("/conceptos/import_evm/plantilla.xlsx")
async def import_evm_plantilla(user: dict = Depends(current_user)):
    """Plantilla descargable con las columnas exactas que espera el
    Importador Maestro (Clave, Descripción, Meta, Importe, Inicio, Fin), una
    fila de ejemplo y una hoja de instrucciones. Inicio/Fin se escriben como
    celdas de fecha reales de Excel (no texto) — el único formato que
    _fecha_excel_a_iso acepta — para que el archivo del usuario nazca ya
    bien formateado en vez de tener que adivinarlo."""
    from openpyxl import Workbook
    from openpyxl.styles import Font, PatternFill, Alignment
    from openpyxl.utils import get_column_letter

    wb = Workbook()
    ws = wb.active
    ws.title = "Catálogo"

    headers = ["Clave", "Descripción", "Meta", "Importe", "Inicio", "Fin"]
    for col, h in enumerate(headers, start=1):
        cell = ws.cell(row=1, column=col, value=h)
        cell.font = Font(bold=True, color="FFFFFF")
        cell.fill = PatternFill("solid", fgColor="1E3A8A")
        cell.alignment = Alignment(horizontal="center")

    ejemplo = ["C-001", "Excavación a máquina en material tipo I", "150.00", "45000.00", date(2026, 1, 5), date(2026, 3, 20)]
    for col, v in enumerate(ejemplo, start=1):
        cell = ws.cell(row=2, column=col, value=v)
        if col in (5, 6):
            cell.number_format = "DD/MM/YYYY"

    for i, w in enumerate([14, 46, 12, 14, 14, 14], start=1):
        ws.column_dimensions[get_column_letter(i)].width = w
    ws.freeze_panes = "A2"

    ws2 = wb.create_sheet("Instrucciones")
    instrucciones = [
        "Cómo llenar esta plantilla para el Importador Maestro del catálogo de conceptos",
        "",
        "1. Clave: identificador único del concepto (ej. C-001). No se puede repetir dentro del mismo archivo.",
        "2. Descripción: nombre/descripción del concepto.",
        "3. Meta: cantidad meta del concepto (número, hasta 2 decimales).",
        "4. Importe: importe total contratado del concepto (número, hasta 2 decimales).",
        "5. Inicio: fecha de inicio del concepto. DEBE ser una celda con formato de FECHA de Excel, como en la fila de ejemplo de la hoja \"Catálogo\" — si Excel la trae como texto no se va a leer.",
        "6. Fin: fecha de fin del concepto. Mismo requisito que Inicio: debe ser una celda de fecha real, no texto.",
        "",
        "Estas dos fechas son las que se reflejan automáticamente en el Calendario del proyecto como \"Inicio de <clave>\" y \"Fin de <clave>\".",
        "",
        "Los 6 campos son obligatorios para poder validar el archivo. No borres la fila de encabezado (fila 1) de la hoja \"Catálogo\". La fila 2 es solo un ejemplo — bórrala o descártala durante la importación antes de confirmar.",
    ]
    for i, txt in enumerate(instrucciones, start=1):
        c = ws2.cell(row=i, column=1, value=txt)
        if i == 1:
            c.font = Font(bold=True, size=13, color="1E3A8A")
    ws2.column_dimensions["A"].width = 110

    buf = io.BytesIO()
    wb.save(buf)
    buf.seek(0)
    return StreamingResponse(
        buf,
        media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        headers={"Content-Disposition": 'attachment; filename="plantilla_catalogo_conceptos.xlsx"'},
    )


class ImportMappingEvmIn(BaseModel):
    clave: Optional[str] = None
    descripcion: Optional[str] = None
    meta: Optional[str] = None       # columna del Excel -> Concepto.meta_cantidad
    importe: Optional[str] = None    # columna del Excel -> Concepto.importe_total_editable
    inicio: Optional[str] = None     # columna del Excel -> Concepto.fecha_inicio
    fin: Optional[str] = None        # columna del Excel -> Concepto.fecha_fin


class ImportValidateEvmIn(BaseModel):
    sheet: str
    header_row_index: int = 0
    mapping: ImportMappingEvmIn
    partida_id: Optional[str] = None  # C-01: opcional (ver ImportValidateIn)
    convencion: Optional[ConvencionDecimal] = None


class RowCorrectionEvmIn(BaseModel):
    meta_cantidad: Optional[str] = None
    importe_total_editable: Optional[str] = None
    fecha_inicio: Optional[str] = None
    fecha_fin: Optional[str] = None
    descartar: bool = False


def _propose_mapping_evm(headers: List[str]) -> dict:
    normalized = [_normalize_text(h) for h in headers]
    mapping: dict = {}
    used_idx: set = set()
    for target in _MAPPING_TARGETS_EVM:
        best_idx = None
        for idx, h in enumerate(normalized):
            if idx in used_idx or not h:
                continue
            if any(kw in h for kw in _MAPPING_KEYWORDS_EVM[target]):
                best_idx = idx
                break
        if best_idx is not None:
            mapping[target] = headers[best_idx]
            used_idx.add(best_idx)
    return mapping


def _validar_archivo_completo_evm(
    rows: List[list],
    header_row_index: int,
    mapping: "ImportMappingEvmIn",
    convencion: Optional[ConvencionDecimal],
    existing_by_clave: dict,
    partidas_existentes: Optional[Dict[str, str]] = None,
    niveles: Optional[dict] = None,
) -> List[dict]:
    """Mismo contrato que _validar_archivo_completo (catálogo legado):
    procesa TODAS las filas una vez, resultado inmutable, correcciones
    viven aparte en _calcular_vista_filas_evm. A diferencia del importador
    de catálogo, aquí no hay unidad/cantidad/precio_unitario — el concepto
    EVM se define por meta_cantidad + importe_total_editable +
    fecha_inicio/fecha_fin (ver ConceptoIn). unidad se deja en "UNIVERSAL"
    por default al crear (mismo default que ConceptoIn.unidad) — este
    importador no trae columna de unidad, tal como se pidió."""
    if len(rows) <= header_row_index:
        raise HTTPException(400, "header_row_index fuera de rango")
    nom_concepto = (niveles or nombres_nivel_proyecto(None))["concepto"]  # C-14
    headers = [str(c) if c is not None else "" for c in rows[header_row_index]]
    data_rows = rows[header_row_index + 1:]

    def col(header_name: Optional[str]):
        if not header_name or header_name not in headers:
            return None
        return headers.index(header_name)

    idx = {k: col(getattr(mapping, k)) for k in ("clave", "descripcion", "meta", "importe", "inicio", "fin")}
    if any(idx[k] is None for k in ("clave", "descripcion", "meta", "importe", "inicio", "fin")):
        raise HTTPException(400, "El mapeo debe incluir clave, descripción, meta, importe, inicio y fin")

    def celda(row: list, key: str):
        i = idx[key]
        if i is None or i >= len(row):
            return None
        return row[i]

    filas: List[dict] = []
    for i, row in enumerate(data_rows):
        clave_raw = celda(row, "clave")
        if clave_raw in (None, ""):
            continue  # fila vacía / de relleno, se ignora silenciosamente (igual que el importador de catálogo)
        fila_num = header_row_index + 2 + i
        problemas: List[dict] = []

        clave = clave_a_texto(clave_raw)
        if not clave:
            problemas.append({"tipo": "campo_obligatorio_vacio", "campo": "clave", "motivo": "La clave está vacía"})

        descripcion_raw = celda(row, "descripcion")
        descripcion = (str(descripcion_raw).strip() if descripcion_raw is not None else "") or None
        if not descripcion:
            problemas.append({"tipo": "campo_obligatorio_vacio", "campo": "descripcion", "motivo": "La descripción está vacía"})

        # C-01: sin meta, importe ni fechas => es una PARTIDA (nodo del catálogo).
        if es_fila_partida(celda(row, "meta"), celda(row, "importe"), celda(row, "inicio"), celda(row, "fin")):
            filas.append({
                "fila": fila_num, "tipo_fila": "partida", "clave": clave, "descripcion": descripcion,
                "meta_cantidad": None, "importe_total_editable": None, "fecha_inicio": None, "fecha_fin": None,
                "concepto_existente_id": None,
                "partida_existente_id": (partidas_existentes or {}).get(clave) if clave else None,
                "problemas": problemas,
            })
            continue

        def _parse_campo_numerico(raw_valor, nombre_campo: str) -> Optional[str]:
            try:
                return dec_to_str(_parse_celda_numerica(raw_valor, convencion))
            except CeldaErrorExcelError as e:
                problemas.append({"tipo": "excel_error", "campo": nombre_campo, "motivo": str(e)})
            except NumeroAmbiguoError as e:
                problemas.append({
                    "tipo": "numero_ambiguo", "campo": nombre_campo, "motivo": str(e),
                    "lectura_miles": dec_to_str(e.lectura_miles), "lectura_decimal": dec_to_str(e.lectura_decimal),
                })
            except ValueError as e:
                if raw_valor in (None, ""):
                    problemas.append({"tipo": "campo_obligatorio_vacio", "campo": nombre_campo, "motivo": f"El campo '{nombre_campo}' está vacío"})
                else:
                    problemas.append({"tipo": "numero_ilegible", "campo": nombre_campo, "motivo": str(e)})
            return None

        meta_raw = celda(row, "meta")
        meta_cantidad = _parse_campo_numerico(meta_raw, "meta")
        if meta_cantidad is not None and to_decimal(meta_cantidad) <= 0:
            problemas.append({"tipo": "campo_obligatorio_vacio", "campo": "meta", "motivo": "meta debe ser mayor a 0 (se usa como divisor de precio_unitario)"})
            meta_cantidad = None

        importe_raw = celda(row, "importe")
        importe_total_editable = _parse_campo_numerico(importe_raw, "importe")

        # Fechas: SOLO se aceptan como celda de fecha real de Excel (mismo
        # criterio que el importador de Programa Desglosado, ver
        # _fecha_excel_a_iso) — nunca se adivina un texto "01/02/2026"
        # (¿día o mes primero?) como si fuera inequívoco.
        inicio_raw = celda(row, "inicio")
        fecha_inicio = _fecha_excel_a_iso(inicio_raw)
        if fecha_inicio is None:
            tipo = "campo_obligatorio_vacio" if inicio_raw in (None, "") else "fecha_ilegible"
            problemas.append({"tipo": tipo, "campo": "inicio", "motivo": f"Fecha de inicio inválida o no es una celda de fecha de Excel: {inicio_raw!r}"})

        fin_raw = celda(row, "fin")
        fecha_fin = _fecha_excel_a_iso(fin_raw)
        if fecha_fin is None:
            tipo = "campo_obligatorio_vacio" if fin_raw in (None, "") else "fecha_ilegible"
            problemas.append({"tipo": tipo, "campo": "fin", "motivo": f"Fecha de fin inválida o no es una celda de fecha de Excel: {fin_raw!r}"})

        if fecha_inicio and fecha_fin and date.fromisoformat(fecha_fin) < date.fromisoformat(fecha_inicio):
            problemas.append({"tipo": "rango_fecha_invalido", "campo": "fin", "motivo": f"La fecha de fin ({fecha_fin}) es anterior a la fecha de inicio ({fecha_inicio})."})

        concepto_existente_id = None
        if clave and clave in existing_by_clave:
            concepto_existente_id = existing_by_clave[clave]["id"]
            problemas.append({
                "tipo": "clave_existente_proyecto", "campo": None,
                "motivo": f"Ya existe {nom_concepto['indefinido']} {nom_concepto['minuscula']} con clave '{clave}' en este proyecto",
            })

        filas.append({
            "fila": fila_num, "tipo_fila": "concepto", "clave": clave, "descripcion": descripcion,
            "meta_cantidad": meta_cantidad, "importe_total_editable": importe_total_editable,
            "fecha_inicio": fecha_inicio, "fecha_fin": fecha_fin,
            "concepto_existente_id": concepto_existente_id, "problemas": problemas,
        })
    return filas


def _calcular_vista_filas_evm(validated_rows: List[dict], correcciones: dict, contexto: Optional[dict] = None) -> List[dict]:
    """Mismo contrato que _calcular_vista_filas (catálogo legado), sobre los
    campos EVM en vez de cantidad/precio_unitario/unidad."""
    conteo_claves: dict = {}
    for row in validated_rows:
        correccion = correcciones.get(str(row["fila"])) or {}
        if correccion.get("descartar") or not row["clave"]:
            continue
        conteo_claves[row["clave"]] = conteo_claves.get(row["clave"], 0) + 1
    claves_repetidas = {c for c, n in conteo_claves.items() if n > 1}

    contexto = contexto or {}
    tiene_destino = bool(contexto.get("tiene_destino", True))
    claves_partida = set(contexto.get("claves_partida_existentes") or [])
    for row in validated_rows:
        if row.get("tipo_fila") == "partida" and row.get("clave") and not (correcciones.get(str(row["fila"])) or {}).get("descartar"):
            claves_partida.add(row["clave"])

    vista: List[dict] = []
    for row in validated_rows:
        fila_key = str(row["fila"])
        correccion = correcciones.get(fila_key) or {}
        descartado = bool(correccion.get("descartar"))

        campos_corregidos = {k for k in ("meta_cantidad", "importe_total_editable", "fecha_inicio", "fecha_fin") if correccion.get(k) is not None}
        problemas_activos = [p for p in row["problemas"] if p.get("campo") not in campos_corregidos]

        if not descartado and row["clave"] in claves_repetidas:
            problemas_activos = problemas_activos + [{
                "tipo": "clave_duplicada_archivo", "campo": None,
                "motivo": f"La clave '{row['clave']}' aparece más de una vez en el archivo; descarta todas menos una",
            }]

        meta_cantidad_efectiva = correccion.get("meta_cantidad") or row["meta_cantidad"]
        importe_efectivo = correccion.get("importe_total_editable") or row["importe_total_editable"]
        fecha_inicio_efectiva = correccion.get("fecha_inicio") or row["fecha_inicio"]
        fecha_fin_efectiva = correccion.get("fecha_fin") or row["fecha_fin"]

        if row.get("tipo_fila", "concepto") == "concepto" and not descartado:
            if not tiene_destino and row.get("clave") and padre_por_prefijo(row["clave"], claves_partida) is None:
                problemas_activos = problemas_activos + [{
                    "tipo": "sin_partida_destino", "campo": None,
                    "motivo": (
                        f"La clave '{row['clave']}' no tiene una partida padre en el archivo ni en el proyecto. "
                        "Incluye la fila de la partida o elige una partida destino."
                    ),
                }]

        if descartado:
            estado = "descartado"
        else:
            tipos_activos = {p["tipo"] for p in problemas_activos}
            if tipos_activos & _TIPOS_ERROR_EVM:
                estado = "error"
            elif tipos_activos & _TIPOS_DUPLICADO_EVM:
                estado = "duplicado"
            else:
                estado = "ok"

        vista.append({
            **row,
            "meta_cantidad_efectiva": meta_cantidad_efectiva,
            "importe_total_editable_efectivo": importe_efectivo,
            "fecha_inicio_efectiva": fecha_inicio_efectiva,
            "fecha_fin_efectiva": fecha_fin_efectiva,
            "problemas_activos": problemas_activos,
            "correccion": correccion or None,
            "estado": estado,
        })
    return vista


async def _ejecutar_commit_evm_con_compensacion(
    conceptos_col,
    sessions_col,
    log_bitacora: Callable[..., Any],
    pid: str,
    import_id: str,
    partida_id: Optional[str],
    vista: List[dict],
    duplicados_accion: str,
    user: dict,
    filename: Optional[str],
    batch_size: int = 500,
    partidas_col=None,
    cadencia: str = "MENSUAL",
) -> dict:
    """Commit del Importador Maestro — mismo criterio de COMPENSACIÓN MANUAL
    que _ejecutar_commit_con_compensacion del catálogo legado (ver ese
    docstring para el porqué completo: no hay confirmación de que el Mongo
    de producción corra en replica set, así que no hay `start_transaction()`
    real disponible).

    Única diferencia real: los writes van en bulk_write POR LOTES de
    `batch_size` en vez de un insert_one/update_one por fila — con miles de
    conceptos (una curva de varios años) esa es la diferencia entre un
    commit de segundos y uno que tumba el proxy por timeout. La
    compensación se mantiene porque el lote COMPLETO se registra en
    compensacion_log ANTES de ejecutar su bulk_write (mismo orden
    "registrar antes de escribir"); si ese lote falla a mitad de camino
    (BulkWriteError con ordered=True), el índice del primer error dice
    cuántas operaciones SÍ se aplicaron — se recorta el log de ese lote a
    solo esas antes de compensar, para no fingir que se revierte algo que
    nunca llegó a escribirse.

    Igual que el importador legado: NUNCA reasigna el `id` de un concepto
    existente (upsert por clave, in-place) — eso es lo que garantiza que
    una cola de avances offline con un concepto_id viejo siga siendo válida
    sin importar cuántas reimportaciones hayan pasado mientras el
    dispositivo estaba desconectado."""
    import_batch_id = str(uuid.uuid4())
    log_local: List[dict] = []
    sin_partida = 0

    async def _registrar(entry: dict) -> None:
        log_local.append(entry)
        await sessions_col.update_one({"id": import_id}, {"$push": {"compensacion_log": entry}})

    async def _compensar() -> None:
        for entry in reversed(log_local):
            try:
                if entry["tipo"] == "creado":
                    await conceptos_col.delete_one({"id": entry["concepto_id"]})
                elif entry["tipo"] == "partida_creada":
                    await partidas_col.delete_one({"id": entry["partida_id"]})
                else:
                    await conceptos_col.update_one({"id": entry["concepto_id"]}, {"$set": entry["valor_anterior"]})
            except Exception as comp_err:
                log.error("[import_evm_commit] fallo compensando %s: %s", entry, comp_err)

    omitidos = 0
    filas_aplicables: List[dict] = []
    for row in vista:
        estado = row["estado"]
        if row.get("tipo_fila") == "partida":
            continue  # las partidas se crean aparte (C-01)
        if estado in ("error", "descartado"):
            continue
        if estado == "duplicado":
            tipos = {p["tipo"] for p in row["problemas_activos"]}
            if "clave_duplicada_archivo" in tipos:
                omitidos += 1
                continue  # ambiguo entre filas del propio archivo: nunca se autoresuelve
            if duplicados_accion == "omitir":
                omitidos += 1
                continue
        filas_aplicables.append(row)

    # Existentes se traen UNA vez (no una consulta por fila) para armar el
    # valor_anterior de compensación — mismo criterio que el importador de
    # catálogo.
    existing_ids = [r["concepto_existente_id"] for r in filas_aplicables if r.get("concepto_existente_id")]
    existing_docs: dict = {}
    if existing_ids:
        async for d in conceptos_col.find({"id": {"$in": existing_ids}}):
            existing_docs[d["id"]] = d

    try:
        # C-01: primero las PARTIDAS del archivo (filas sin meta ni importe), de raíz a hoja.
        mapa_partidas: Dict[str, str] = {}
        partidas_creadas = 0
        if partidas_col is not None:
            async for pdoc in partidas_col.find({"project_id": pid, "activo": True}):
                mapa_partidas[pdoc["clave"]] = pdoc["id"]
            filas_partida = [
                r for r in vista
                if r.get("tipo_fila") == "partida" and r["estado"] in ("ok", "advertencia") and r.get("clave")
            ]
            plan = planificar_partidas(filas_partida, mapa_partidas)
            n_antes = len(mapa_partidas)
            mapa_partidas = await _crear_partidas_planificadas(partidas_col, pid, plan, mapa_partidas, partida_id, user, _registrar)
            partidas_creadas = len(mapa_partidas) - n_antes

        for lote_inicio in range(0, len(filas_aplicables), batch_size):
            lote = filas_aplicables[lote_inicio: lote_inicio + batch_size]
            ops: List[Any] = []
            lote_log: List[dict] = []
            for row in lote:
                existing_id = row.get("concepto_existente_id")
                existing_doc = existing_docs.get(existing_id) if existing_id else None
                if existing_id and not existing_doc:
                    existing_id = None  # se borró entre validate y commit: tratar como nuevo

                if existing_id and existing_doc:
                    valor_anterior = {
                        "descripcion": existing_doc["descripcion"],
                        "meta_cantidad": existing_doc.get("meta_cantidad"),
                        "importe_total_editable": existing_doc.get("importe_total_editable"),
                        "fecha_inicio": existing_doc.get("fecha_inicio"),
                        "fecha_fin": existing_doc.get("fecha_fin"),
                    }
                    lote_log.append({"tipo": "actualizado", "concepto_id": existing_id, "valor_anterior": valor_anterior})
                    ops.append(UpdateOne(
                        {"id": existing_id},
                        {"$set": {
                            "descripcion": row["descripcion"],
                            "meta_cantidad": row["meta_cantidad_efectiva"],
                            "importe_total_editable": row["importe_total_editable_efectivo"],
                            "fecha_inicio": row["fecha_inicio_efectiva"],
                            "fecha_fin": row["fecha_fin_efectiva"],
                            "import_batch_id": import_batch_id,
                        }},
                    ))
                else:
                    padre_clave = padre_por_prefijo(row["clave"], mapa_partidas) if row.get("clave") else None
                    partida_destino = mapa_partidas[padre_clave] if padre_clave else partida_id
                    if not partida_destino:
                        sin_partida += 1
                        continue
                    cid = str(uuid.uuid4())
                    lote_log.append({"tipo": "creado", "concepto_id": cid, "valor_anterior": None})
                    ops.append(InsertOne({
                        "id": cid, "partida_id": partida_destino, "project_id": pid,
                        "clave": row["clave"], "descripcion": row["descripcion"], "unidad": "UNIVERSAL",
                        # Campos legado (cantidad/precio_unitario/meta) se dejan en
                        # blanco/derivados mínimos para que _concepto_out no truene
                        # al leer un concepto que NUNCA pasó por el alta manual
                        # legado — importe_contratado legado queda en "0" hasta que
                        # alguien lo edite a mano; el que manda para este concepto
                        # es precio_unitario_dinamico (ver _concepto_tiene_datos_evm).
                        "cantidad": row["meta_cantidad_efectiva"], "precio_unitario": "0",
                        # C-06: meta = cantidad ÷ duración (inicio-fin de la fila) en la
                        # cadencia del proyecto; sin fechas válidas queda vacía.
                        "meta": meta_por_defecto(
                            row["meta_cantidad_efectiva"], row["fecha_inicio_efectiva"], row["fecha_fin_efectiva"], cadencia,
                        ) or "",
                        "periodicidad_meta": cadencia,
                        "meta_cantidad": row["meta_cantidad_efectiva"],
                        "importe_total_editable": row["importe_total_editable_efectivo"],
                        "fecha_inicio": row["fecha_inicio_efectiva"], "fecha_fin": row["fecha_fin_efectiva"],
                        "activo": True, "created_at": datetime.now(timezone.utc), "created_by": user["id"],
                        "import_batch_id": import_batch_id,
                    }))

            # Registrar el lote ANTES de ejecutarlo (ver docstring).
            await sessions_col.update_one({"id": import_id}, {"$push": {"compensacion_log": {"$each": lote_log}}})
            log_local.extend(lote_log)

            try:
                await conceptos_col.bulk_write(ops, ordered=True)
            except BulkWriteError as bwe:
                write_errors = bwe.details.get("writeErrors", [])
                primer_error_idx = min((we["index"] for we in write_errors), default=0)
                # ordered=True: todo lo ANTES de primer_error_idx sí se aplicó
                # en este lote; lo de este lote desde ahí en adelante nunca se
                # escribió, así que se descarta del log antes de compensar.
                del log_local[len(log_local) - len(lote_log) + primer_error_idx:]
                raise
    except Exception as e:
        log.error("[import_evm_commit] fallo a mitad del commit, compensando %d escrituras: %s", len(log_local), e)
        await _compensar()
        raise HTTPException(500, f"La importación falló a mitad de camino y se revirtió automáticamente (no se guardó nada): {e}")

    creados = sum(1 for e in log_local if e["tipo"] == "creado")
    actualizados = sum(1 for e in log_local if e["tipo"] == "actualizado")
    for entry in log_local:
        if entry["tipo"] == "partida_creada":
            await log_bitacora(pid, "import_evm", "partida", entry["partida_id"], None, None, f"creada desde Importador Maestro ({filename})", user)
        elif entry["tipo"] == "creado":
            await log_bitacora(pid, "import_evm", "concepto", entry["concepto_id"], None, None, f"creado desde Importador Maestro ({filename})", user)
        else:
            await log_bitacora(pid, "import_evm", "concepto", entry["concepto_id"], "importe_total_editable/fechas", None, "actualizado desde Importador Maestro", user)

    con_error = sum(1 for r in vista if r["estado"] == "error")
    descartados = sum(1 for r in vista if r["estado"] == "descartado")
    return {
        "creados": creados, "actualizados": actualizados, "omitidos": omitidos,
        "con_error": con_error, "descartados": descartados, "import_batch_id": import_batch_id,
        "partidas_creadas": partidas_creadas, "sin_partida": sin_partida,
    }


@api.post("/projects/{pid}/conceptos/import_evm/sheets")
async def import_evm_upload_sheets(pid: str, file: UploadFile = File(...), user: dict = Depends(require_role(ROLE_SUB, ROLE_COORD))):
    """Paso 1 del Importador Maestro — mismo contrato que
    import_upload_sheets del catálogo legado, colección de staging propia."""
    await ensure_project_access(user, pid)
    content = await file.read()
    if len(content) > 15 * 1024 * 1024:
        raise HTTPException(400, "Archivo demasiado grande (máx. 15MB)")
    sheets = _read_workbook_sheets(file.filename or "archivo.xlsx", content)
    candidatos = [cell for rows in sheets.values() for row in rows for cell in row]
    convencion_detectada = detectar_convencion(candidatos)

    import_id = str(uuid.uuid4())
    await db.evm_import_sessions.insert_one({
        "id": import_id, "project_id": pid, "user_id": user["id"], "filename": file.filename,
        "sheets": {name: rows for name, rows in sheets.items()},
        "convencion_decimal": convencion_detectada, "created_at": datetime.now(timezone.utc),
    })
    return {
        "import_id": import_id, "sheet_names": list(sheets.keys()),
        "requiere_seleccion_hoja": len(sheets) > 1, "convencion_detectada": convencion_detectada,
    }


@api.get("/conceptos/import_evm/{import_id}/headers")
async def import_evm_headers(
    import_id: str,
    sheet: Optional[str] = None,
    header_row_index: Optional[int] = None,
    user: dict = Depends(require_role(ROLE_SUB, ROLE_COORD)),
):
    session = await db.evm_import_sessions.find_one({"id": import_id})
    if not session:
        raise HTTPException(404, "Sesión de importación no existe o expiró")
    await ensure_project_access(user, session["project_id"])
    sheet_name = sheet or next(iter(session["sheets"].keys()))
    if sheet_name not in session["sheets"]:
        raise HTTPException(400, f"La hoja '{sheet_name}' no existe en este archivo")
    rows = session["sheets"][sheet_name]
    if not rows:
        raise HTTPException(400, "La hoja está vacía")

    if header_row_index is None:
        header_row_index = next((i for i, r in enumerate(rows[:15]) if _fila_parece_encabezado(r)), 0)
    if header_row_index >= len(rows):
        raise HTTPException(400, "header_row_index fuera de rango")

    headers = [str(c) if c is not None else "" for c in rows[header_row_index]]
    sample_rows = rows[header_row_index + 1: header_row_index + 6]
    return {
        "sheet": sheet_name, "header_row_index": header_row_index, "headers": headers,
        "suggested_mapping": _propose_mapping_evm(headers), "sample_rows": sample_rows,
        "total_rows": max(len(rows) - header_row_index - 1, 0),
        "convencion_detectada": session.get("convencion_decimal"),
        "preview_rows": rows[: min(len(rows), 15)],
    }


@api.post("/projects/{pid}/conceptos/import_evm/{import_id}/validate")
async def import_evm_validate(pid: str, import_id: str, body: ImportValidateEvmIn, user: dict = Depends(require_role(ROLE_SUB, ROLE_COORD))):
    proyecto_evm = await ensure_project_access(user, pid)
    if body.partida_id:
        partida = await db.partidas.find_one({"id": body.partida_id, "project_id": pid})
        if not partida:
            raise HTTPException(404, "Partida no existe en este proyecto")
    session = await db.evm_import_sessions.find_one({"id": import_id, "project_id": pid})
    if not session:
        raise HTTPException(404, "Sesión de importación no existe o expiró")
    if body.sheet not in session["sheets"]:
        raise HTTPException(400, f"La hoja '{body.sheet}' no existe en este archivo")

    convencion: Optional[ConvencionDecimal] = body.convencion or session.get("convencion_decimal")
    # C-01: los duplicados se buscan en TODO el proyecto.
    existing = await db.conceptos.find({"project_id": pid, "activo": True}).to_list(length=100000)
    existing_by_clave = {c["clave"]: c for c in existing}

    partidas_proyecto = await _claves_partida_del_proyecto(pid)
    filas = _validar_archivo_completo_evm(
        session["sheets"][body.sheet], body.header_row_index, body.mapping, convencion, existing_by_clave,
        partidas_existentes=partidas_proyecto,
        niveles=nombres_nivel_proyecto(proyecto_evm if isinstance(proyecto_evm, dict) else None),
    )
    contexto = {"tiene_destino": bool(body.partida_id), "claves_partida_existentes": sorted(partidas_proyecto)}

    update_fields = {
        "validated_rows": filas, "validated_sheet": body.sheet,
        "validated_header_row_index": body.header_row_index, "validated_mapping": body.mapping.model_dump(),
        "validated_partida_id": body.partida_id, "validated_contexto": contexto, "convencion_usada": convencion,
        "validated_at": datetime.now(timezone.utc),
    }
    if "correcciones" not in session:
        update_fields["correcciones"] = {}
        update_fields["duplicados_accion"] = "omitir"
    await db.evm_import_sessions.update_one({"id": import_id}, {"$set": update_fields})

    vista = _calcular_vista_filas_evm(filas, session.get("correcciones") or {}, contexto=contexto)
    return {"resumen": _resumen_de_vista(vista), "convencion_usada": convencion}


@api.get("/conceptos/import_evm/{import_id}/preview")
async def import_evm_preview(import_id: str, page: int = 1, page_size: int = 50, user: dict = Depends(require_role(ROLE_SUB, ROLE_COORD))):
    session = await db.evm_import_sessions.find_one({"id": import_id})
    if not session:
        raise HTTPException(404, "Sesión de importación no existe o expiró")
    await ensure_project_access(user, session["project_id"])
    validated_rows = session.get("validated_rows")
    if validated_rows is None:
        raise HTTPException(400, "Todavía no se valida esta importación. Llama primero a /validate.")

    correcciones = session.get("correcciones") or {}
    vista = _calcular_vista_filas_evm(validated_rows, correcciones, contexto=session.get("validated_contexto"))
    resumen = _resumen_de_vista(vista)

    page = max(page, 1)
    page_size = max(1, min(page_size, 200))
    start = (page - 1) * page_size
    pagina = vista[start:start + page_size]
    total_pages = max(1, (len(vista) + page_size - 1) // page_size)

    return {
        "resumen": resumen, "filas": pagina, "page": page, "page_size": page_size,
        "total_pages": total_pages, "total_rows": len(vista),
        "sheet": session.get("validated_sheet"), "partida_id": session.get("validated_partida_id"),
        "convencion_usada": session.get("convencion_usada"), "duplicados_accion": session.get("duplicados_accion", "omitir"),
    }


@api.put("/conceptos/import_evm/{import_id}/rows/{fila}")
async def import_evm_correct_row(import_id: str, fila: int, body: RowCorrectionEvmIn, user: dict = Depends(require_role(ROLE_SUB, ROLE_COORD))):
    session = await db.evm_import_sessions.find_one({"id": import_id})
    if not session:
        raise HTTPException(404, "Sesión de importación no existe o expiró")
    await ensure_project_access(user, session["project_id"])
    validated_rows = session.get("validated_rows") or []
    if not any(r["fila"] == fila for r in validated_rows):
        raise HTTPException(404, f"Fila {fila} no existe en esta validación")

    entry: dict = {}
    if body.meta_cantidad is not None:
        try:
            valor = dec_to_str(to_decimal(body.meta_cantidad))
        except Exception:
            raise HTTPException(400, "meta inválida")
        if to_decimal(valor) <= 0:
            raise HTTPException(400, "meta debe ser mayor a 0")
        entry["meta_cantidad"] = valor
    if body.importe_total_editable is not None:
        try:
            entry["importe_total_editable"] = dec_to_str(to_decimal(body.importe_total_editable))
        except Exception:
            raise HTTPException(400, "importe inválido")
    if body.fecha_inicio is not None:
        try:
            date.fromisoformat(body.fecha_inicio)
        except ValueError:
            raise HTTPException(400, "fecha_inicio inválida, se espera YYYY-MM-DD")
        entry["fecha_inicio"] = body.fecha_inicio
    if body.fecha_fin is not None:
        try:
            date.fromisoformat(body.fecha_fin)
        except ValueError:
            raise HTTPException(400, "fecha_fin inválida, se espera YYYY-MM-DD")
        entry["fecha_fin"] = body.fecha_fin
    if body.descartar:
        entry["descartar"] = True

    correcciones = session.get("correcciones") or {}
    if entry:
        correcciones[str(fila)] = entry
    else:
        correcciones.pop(str(fila), None)
    await db.evm_import_sessions.update_one({"id": import_id}, {"$set": {"correcciones": correcciones}})

    vista = _calcular_vista_filas_evm(validated_rows, correcciones, contexto=session.get("validated_contexto"))
    fila_actualizada = next(r for r in vista if r["fila"] == fila)
    return {"fila": fila_actualizada, "resumen": _resumen_de_vista(vista)}


